// The turn-end policy in the loop, over the scripted server: what the loop
// types, through which verb, under which guard, and what it raises, under
// the owner's `[harness]` policy (every switch on) as the in-GUI host runs
// it. Each behaviour has its negative control. Included from `run.rs`'s
// tests (`mod turn_end`), so the `Mock` and the helpers there are in scope.

use crate::harness::login_latch::LoginLatches;
use crate::harness::repo_work::RepoWork;
use crate::supervise::policy::login::LoginShared;
use crate::supervise::policy::turn_end::{
    DONE_CHECK, FINISHED, LAND, LAND_NUDGE, RULE_CONTINUE, RULE_DONE_CHECK, RULE_LAND, RULE_LEFT,
    RULE_LOGIN, RULE_LOGIN_BACK, RULE_SUGGESTION, repo_work_suffix,
};
use std::sync::PoisonError;

#[path = "remembered_limit_tests.rs"]
mod remembered_limit;

#[path = "seed_matrix_tests.rs"]
mod seed_matrix;

/// The host's policy, every switch on (`SupervisorConfig::default()`) but
/// the answers: these scripts end on a request for a decision ([`STOP`]),
/// which `answer_questions = false` hands to a person, so each shows what the
/// loop typed before it, and the escalation after. (Full power answers it:
/// the policy's `a_question_in_prose_is_answered_by_the_priority_word`.)
fn hosted(max_s: u64) -> SuperviseOpts {
    SuperviseOpts {
        policy: SupervisorConfig {
            answer_questions: false,
            ..owners_policy()
        },
        ..auto(max_s)
    }
}

/// A turn that ended after 12 minutes of work (the done row's measure: a job,
/// past `EXCHANGE_WORK`, even where a person opened it), the worker's last
/// words `said`, at an empty composer in bypass mode.
fn ended(said: &str) -> Vec<String> {
    let mut r = rows(&[
        &format!("⏺ {said}"),
        "",
        "✻ Worked for 12m 2s · done 4:24 PM",
        "",
    ]);
    r.extend(composer("  ⏵⏵ bypass permissions on (shift+tab to cycle)"));
    r
}

/// [`ended`] with Claude Code's dim suggestion in the composer (`❯ keep
/// going`, the cursor left at column 2), or, `filled`, the suggestion
/// accepted into it (the cursor after it).
fn suggesting(said: &str) -> Vec<String> {
    let mut r = ended(said);
    let caret = r.iter().position(|row| row == "❯").expect("caret row");
    r[caret] = "❯ keep going".to_string();
    r
}

/// The worker asks for a decision: the point is escalated, never typed.
const STOP: &str = "I need your decision on the schema before I go on.";

fn ledger_at(tag: &str) -> (PathBuf, PathBuf) {
    let dir = crate::supervise::test_scratch_path("te-ledger", tag);
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).expect("tmp dir");
    let path = dir.join("s-1.jsonl");
    (dir, path)
}

/// The continue policy: a turn that ended after real work, with nothing
/// asked, is continued once (`keep going` typed through the guarded submit
/// `turn submit=guarded:^❯\skeep\x20going\s*$ …`, the session's program read
/// first, `CONTINUED` printed, a `typed` ledger row under `continue@v1`), and
/// the next turn, ending on a request for a decision, is escalated with the
/// worker's words, nothing typed. Negative control: the policy switched off
/// types nothing.
#[test]
fn a_turn_end_after_work_is_continued_once_and_a_stop_phrase_escalates() {
    let (dir, ledger) = ledger_at("continue");
    let mut m = Mock::new(vec![
        busy_screen(),
        ended("Fixed the parser; the suite is green."),
        busy_screen(),
        ended(STOP),
    ]);
    m.turn_releases = Some(1);
    m.vanish_after = Some(2);
    let (lines, _) = watch_lines_with(&mut m, &hosted(30), |s| {
        s.set_approval_ledger(Some(ledger.clone()));
    });
    assert_eq!(
        lines,
        [
            "EVENT idle seq=102 ⏺ Fixed the parser; the suite is green.".to_string(),
            "CONTINUED seq=102 rule=continue@v1 keep going".to_string(),
            format!("EVENT idle seq=104 ⏺ {STOP}"),
            "EXIT session gone (await seq 104 failed: aterm-ctl: ERR exited)".to_string(),
        ],
        "{:#?}",
        m.requests
    );
    let turn = continue_request("keep going");
    assert_eq!(
        turn,
        "turn submit=guarded:^❯\\skeep\\x20going\\s*$ idle=600 timeout=2500 yield=0.2 keep going"
    );
    let at = m
        .requests
        .iter()
        .position(|r| *r == turn)
        .expect("the turn");
    assert_eq!(m.requests[at - 1], "status");
    assert_eq!(count(&m, "turn"), 1, "{:#?}", m.requests);
    assert!(
        m.attention
            .as_deref()
            .is_some_and(|a| a.starts_with("claude idle: ")),
        "{:?}",
        m.attention
    );
    let rows = std::fs::read_to_string(&ledger).unwrap_or_default();
    assert!(
        rows.lines()
            .any(|l| l.contains("\"rule_id\":\"continue@v1\"")
                && l.contains("\"decision\":\"typed\"")
                && l.contains("\"command\":\"keep going\"")),
        "{rows}"
    );
    let _ = std::fs::remove_dir_all(&dir);

    // Negative control: the continue switch off.
    let mut m = Mock::new(vec![
        busy_screen(),
        ended("Fixed the parser; the suite is green."),
    ]);
    m.vanish_after = Some(2);
    let mut off = hosted(30);
    off.policy.continue_policy = false;
    let _ = watch_lines(&mut m, &off);
    assert_eq!(count(&m, "turn"), 0, "{:#?}", m.requests);
}

/// A worker that says it is done gets the done check where `keep going`
/// would be, and its answer `DONE` is a done claim again: the check is typed
/// again (FOREVER CRUISE), the task never ends, and the journal holds no
/// `DONE` — nor does Claude Code compacting the idle conversation under the
/// claim, its own housekeeping and no turn
/// ([`claude_codes_idle_compaction_is_no_turn`]), the back-off short so that
/// nothing but the reading holds an act. (Progress is continued with `keep
/// going`: the first test.)
#[test]
fn a_done_report_is_checked_and_a_done_reply_is_checked_again() {
    let (dir, journal) = journal_file("done-check");
    // The reply, its done row, then what the compaction appended under them.
    let mut compacted = rows(&[
        "⏺ DONE",
        "",
        "✻ Worked for 12m 2s · done 4:24 PM",
        "  ⎿  Skills restored (workflow-authoring)",
        "",
        "⏺ Compacted while idle, before the prompt cache expired",
        "",
    ]);
    compacted.extend(composer("  ⏵⏵ bypass permissions on (shift+tab to cycle)"));
    let mut m = Mock::new(vec![
        busy_screen(),
        ended("Fixed the parser; all done."),
        busy_screen(),
        ended("The task is complete. The parser fix is committed and all tests passed."),
        busy_screen(),
        compacted,
    ]);
    m.turn_releases = Some(1);
    m.vanish_after = Some(4);
    // A wait on the screen that sits passes the time it asks, on the run's
    // clock: an act a back-off holds comes inside the run.
    m.stall_sleep = Some(Duration::from_secs(20));
    let opts = SuperviseOpts {
        policy: owners_policy(),
        journal: Some(journal.clone()),
        ..auto(30)
    };
    let (lines, _) = watch_lines_with(&mut m, &opts, |s| {
        s.set_turn_end_timing(TurnEndTiming {
            short_backoff: Duration::from_millis(30),
            short_backoff_max: Duration::from_millis(60),
            ..TurnEndTiming::default()
        });
    });
    assert!(
        lines.contains(&format!(
            "CONTINUED seq=102 rule={RULE_DONE_CHECK} {}",
            clip(DONE_CHECK)
        )),
        "{lines:#?}"
    );
    let turns: Vec<&String> = m
        .requests
        .iter()
        .filter(|r| r.starts_with("turn "))
        .collect();
    assert!(
        turns.len() >= 2 && turns.iter().all(|r| **r == continue_request(DONE_CHECK)),
        "the check, and again: {:#?}",
        m.requests
    );
    let done: Vec<String> = journal_records(&journal)
        .0
        .into_iter()
        .map(|r| r.line)
        .filter(|l| l.starts_with("DONE "))
        .collect();
    assert!(done.is_empty(), "{done:#?}");
    let _ = std::fs::remove_dir_all(&dir);
}

/// A DONE CHECK ANSWERED FASTER THAN ANY READ IS JUDGED AT ITS ANSWER (the
/// lab's done-check scenario `d1l` on Claude Code 2.1.303): the worker's
/// every report is the idle line alone, and the check's answer — the same
/// line, in 41 ms — is drawn under the check's own `❯` row with no busy
/// screen between. The loop reads the act taken and answered there (the
/// screen's row over the last words, `TurnEndReading::answered`, against the
/// screen the check was typed at), with no wait for the act to be taken; the
/// short idle answer is a done claim, which ends nothing (FOREVER CRUISE).
/// FAILS WITHOUT THE FIX: `WAITING … the worker to take the
/// continue-done-check@v1 act`. NEGATIVE CONTROL: the same words drawn under
/// another prompt's row say nothing of the check: it is waited for to its
/// take window.
#[test]
fn a_check_answered_faster_than_any_read_is_judged_at_its_answer() {
    const IDLE: &str = "Both branches have landed and no lander is running.";
    let screen = |more: &[&str]| {
        let mut r = rows(&[
            "❯ land the two branches",
            "",
            &format!("⏺ {IDLE}"),
            "",
            "✻ Worked for 6s · done 10:54 PM",
            "",
        ]);
        r.extend(rows(more));
        r.extend(composer("  ⏵⏵ auto mode on (shift+tab to cycle)"));
        r
    };
    // The same words under another prompt's row: no sign the check was
    // taken (a person's question answered at once, the check's paste lost).
    let other = screen(&[
        "❯ what is left?",
        "",
        &format!("⏺ {IDLE}"),
        "",
        "✻ Baked for 0s · done 11:01 PM",
        "",
    ]);
    let check_row = format!("❯ {DONE_CHECK}");
    let answer_row = format!("⏺ {IDLE}");
    let answered = screen(&[
        &check_row,
        "",
        &answer_row,
        "",
        "✻ Cogitated for 0s · done 11:01 PM",
        "",
    ]);
    for (case, after, ends) in [("fast", answered, true), ("other", other, false)] {
        let (dir, journal) = journal_file(&format!("fast-answer-{case}"));
        let mut m = Mock::new(vec![busy_screen(), screen(&[]), after]);
        m.turn_releases = Some(1);
        m.vanish_after = Some(10);
        m.stall_sleep = Some(Duration::from_millis(20));
        let opts = SuperviseOpts {
            policy: owners_policy(),
            journal: Some(journal.clone()),
            ..auto(30)
        };
        let (lines, _) = watch_lines_with(&mut m, &opts, |s| {
            s.set_turn_end_timing(TurnEndTiming {
                short_backoff: Duration::from_millis(30),
                short_backoff_max: Duration::from_millis(60),
                take_within: Duration::from_millis(50),
                ..TurnEndTiming::default()
            });
        });
        let records: Vec<String> = journal_records(&journal)
            .0
            .into_iter()
            .map(|r| r.line)
            .collect();
        let _ = std::fs::remove_dir_all(&dir);
        assert!(
            lines.contains(&format!(
                "CONTINUED seq=102 rule={RULE_DONE_CHECK} {}",
                clip(DONE_CHECK)
            )),
            "{case}: {lines:#?}"
        );
        let done: Vec<&String> = records.iter().filter(|l| l.starts_with("DONE ")).collect();
        let waited = records
            .iter()
            .any(|l| l.contains("the worker to take the continue-done-check@v1 act"));
        assert!(done.is_empty(), "{case}: {records:#?}");
        assert_eq!(waited, !ends, "{case}: {records:#?}");
    }
}

/// A host whose conversation's record ends on the turn the loop's last act
/// opened once it typed one ([`IdleHost::act_taken`]), closed in 41 ms —
/// Claude Code's record of a prompt it answered at once — and on the
/// person's `land the two branches` before: recorded at `at_ms`, the
/// loop's fixed clock. Its finish says nothing (`Some(false)`), so only the
/// turn it ends on can tell the act's answer.
#[derive(Debug)]
struct TypedRecordHost {
    typed: std::sync::atomic::AtomicBool,
    at_ms: u64,
}

impl IdleHost for TypedRecordHost {
    fn wants(&self) -> bool {
        false
    }
    fn at_idle(&self) -> Option<HostStep> {
        None
    }
    fn owns_turn_end(&self) -> bool {
        false
    }
    fn finished(&self) -> Option<bool> {
        Some(false)
    }
    fn act_taken(&self, _: crate::harness::acts::Act) {
        self.typed.store(true, std::sync::atomic::Ordering::SeqCst);
    }
    fn last_turn(&self) -> Option<crate::harness::upgrade::LastTurn> {
        let (said, ended) = if self.typed.load(std::sync::atomic::Ordering::SeqCst) {
            (DONE_CHECK, Duration::from_millis(41))
        } else {
            ("land the two branches", Duration::from_secs(6))
        };
        Some(crate::harness::upgrade::LastTurn {
            opened: Some("prompt:fast".to_string()),
            opened_said: Some(crate::supervise::approvals::words_hash(said)),
            ended: Some(ended),
            opened_ms: Some(self.at_ms),
            ..Default::default()
        })
    }
}

/// THE RECORD TELLS A FAST ANSWER THE SCREEN DOES NOT: the check answered
/// at once with the idle line again, the screen drawing no prompt row over
/// it, and the conversation's record ending on the check's own prompt,
/// recorded since the act and closed in 41 ms — read while the check stands
/// untaken (`TurnEndState::reads_record`), handed to the policy as the turn
/// the record ends on (`TurnEndReading::record_turn`): the answer is judged
/// at that read, with no wait for the act to be taken — a done claim, which
/// ends nothing (FOREVER CRUISE). FAILS WITHOUT IT: the window. NEGATIVE
/// CONTROL: no host, and so no record — the act is waited for to its take
/// window.
#[test]
fn the_record_tells_a_check_answered_faster_than_any_read() {
    const IDLE: &str = "Both branches have landed and no lander is running.";
    let screen = |more: &[&str]| {
        let mut r = rows(&[
            "❯ land the two branches",
            "",
            &format!("⏺ {IDLE}"),
            "",
            "✻ Worked for 6s · done 10:54 PM",
            "",
        ]);
        r.extend(rows(more));
        r.extend(composer("  ⏵⏵ auto mode on (shift+tab to cycle)"));
        r
    };
    // The answer under the done row, its prompt row not drawn.
    let answer_row = format!("⏺ {IDLE}");
    let answered = screen(&[&answer_row, ""]);
    for (case, hosted, ends) in [("record", true, true), ("none", false, false)] {
        let host = Arc::new(TypedRecordHost {
            typed: std::sync::atomic::AtomicBool::new(false),
            at_ms: u64::try_from(TEST_NOW).expect("a time") * 1000,
        });
        let (dir, journal) = journal_file(&format!("fast-record-{case}"));
        let mut m = Mock::new(vec![busy_screen(), screen(&[]), answered.clone()]);
        m.turn_releases = Some(1);
        m.vanish_after = Some(10);
        m.stall_sleep = Some(Duration::from_millis(20));
        let opts = SuperviseOpts {
            policy: owners_policy(),
            journal: Some(journal.clone()),
            idle_host: hosted.then(|| Arc::clone(&host) as Arc<dyn IdleHost>),
            ..auto(30)
        };
        let (lines, _) = watch_lines_with(&mut m, &opts, |s| {
            s.set_clock(TEST_NOW, PDT);
            s.set_turn_end_timing(TurnEndTiming {
                short_backoff: Duration::from_millis(30),
                short_backoff_max: Duration::from_millis(60),
                take_within: Duration::from_millis(50),
                ..TurnEndTiming::default()
            });
        });
        let records: Vec<String> = journal_records(&journal)
            .0
            .into_iter()
            .map(|r| r.line)
            .collect();
        let _ = std::fs::remove_dir_all(&dir);
        assert!(
            lines.contains(&format!(
                "CONTINUED seq=102 rule={RULE_DONE_CHECK} {}",
                clip(DONE_CHECK)
            )),
            "{case}: {lines:#?}"
        );
        let done: Vec<&String> = records.iter().filter(|l| l.starts_with("DONE ")).collect();
        let waited = records
            .iter()
            .any(|l| l.contains("the worker to take the continue-done-check@v1 act"));
        assert!(done.is_empty(), "{case}: {records:#?}");
        assert_eq!(waited, !ends, "{case}: {records:#?}");
    }
}

/// The request after the write that starts `write` waits for the worker's
/// reaction with [`turn_end_loop::REACTION_WAIT`] (the screen moving) before
/// anything about the write is judged; never the approval press's 2 s
/// settle, which misjudges a worker merely slow to react.
fn assert_reaction_awaited(m: &Mock, write: &str) {
    let next = m
        .requests
        .iter()
        .skip_while(|r| !r.starts_with(write))
        .nth(1);
    let bound = format!(" timeout {}", turn_end_loop::REACTION_WAIT.as_millis());
    assert!(
        next.is_some_and(|r| r.starts_with("await seq ") && r.ends_with(&bound)),
        "after `{write}` the reaction is awaited{bound}: {:#?}",
        m.requests
    );
}

/// The worker's own suggestion, accepted by the vendor's accept key: `right`
/// fenced on the judged read's generation and guarded on the suggestion's
/// row, the screen read again, then Enter fenced on that read and guarded on
/// the filled row (`continue-suggestion@v1`, no `turn`). Negative control: a
/// host without the generation fence gets the same words typed through the
/// guarded submit instead, under the same rule.
#[test]
fn the_workers_suggestion_is_accepted_with_the_accept_key_and_a_fenced_enter() {
    let mut m = Mock::new(vec![
        busy_screen(),
        suggesting("Stage 1 is in."),
        suggesting("Stage 1 is in."),
        busy_screen(),
        ended(STOP),
    ]);
    m.gen_fence = true;
    m.sends_gen = true;
    m.help = "key [id=<key>] [if=<re>] [if-gen=<e.s>] <name>: send a named key\n".to_string();
    m.screen_cols.insert(2, 12);
    m.vanish_after = Some(2);
    let (lines, _) = watch_lines(&mut m, &hosted(30));
    assert!(
        lines.contains(&format!(
            "CONTINUED seq=102 rule={RULE_SUGGESTION} keep going"
        )),
        "{lines:#?}\n{:#?}",
        m.requests
    );
    let keys: Vec<&String> = m.presses();
    assert_eq!(
        keys,
        [
            "key if-gen=1.102 if=^❯\\x20keep\\x20going\\s*$ right",
            "key if-gen=1.103 if=^❯\\x20keep\\x20going\\s*$ enter",
        ],
        "{:#?}",
        m.requests
    );
    assert_eq!(count(&m, "turn"), 0, "{:#?}", m.requests);
    assert_reaction_awaited(&m, "key if-gen=1.102");

    // Negative control: no generation fence — the words, typed.
    let mut m = Mock::new(vec![
        busy_screen(),
        suggesting("Stage 1 is in."),
        ended(STOP),
    ]);
    m.turn_releases = Some(1);
    m.vanish_after = Some(2);
    let (lines, _) = watch_lines(&mut m, &hosted(30));
    assert!(
        lines.contains(&format!(
            "CONTINUED seq=102 rule={RULE_SUGGESTION} keep going"
        )),
        "{lines:#?}"
    );
    assert!(m.presses().is_empty(), "{:#?}", m.requests);
    assert!(m.requests.contains(&continue_request("keep going")));
}

/// The read after the accept key landed between the worker's clear and its redraw
/// (no caret row) and the loop returned with the suggestion filled: nothing pressed,
/// nothing journaled, nothing escalated. That read is taken again after one more
/// settle, and Enter goes fenced on the read that shows the fill. Negative control: a
/// composer still torn on the second read is not judged either, nothing more is
/// pressed, and it is journaled skipped.
#[test]
fn a_torn_read_after_the_accept_key_is_read_again() {
    let torn = {
        let mut rows = suggesting("Stage 1 is in.");
        let caret = rows
            .iter()
            .position(|row| row == "❯ keep going")
            .expect("caret row");
        rows[caret] = String::new();
        rows
    };
    let accepting = |screens: Vec<Vec<String>>, filled_at: Option<usize>| {
        let mut m = Mock::new(screens);
        m.gen_fence = true;
        m.sends_gen = true;
        m.help = "key [id=<key>] [if=<re>] [if-gen=<e.s>] <name>: send a named key\n".to_string();
        m.idle_never = true;
        if let Some(at) = filled_at {
            m.screen_cols.insert(at, 12);
        }
        m.vanish_after = Some(2);
        m
    };
    let mut m = accepting(
        vec![
            busy_screen(),
            suggesting("Stage 1 is in."),
            torn.clone(),
            suggesting("Stage 1 is in."),
            busy_screen(),
            ended(STOP),
        ],
        Some(3),
    );
    let (lines, _) = watch_lines(&mut m, &hosted(30));
    assert!(
        lines.contains(&format!(
            "CONTINUED seq=102 rule={RULE_SUGGESTION} keep going"
        )),
        "{lines:#?}\n{:#?}",
        m.requests
    );
    assert_eq!(
        m.presses(),
        [
            "key if-gen=1.102 if=^❯\\x20keep\\x20going\\s*$ right",
            "key if-gen=1.104 if=^❯\\x20keep\\x20going\\s*$ enter",
        ],
        "{:#?}",
        m.requests
    );
    assert_eq!(count(&m, "turn"), 0, "{:#?}", m.requests);
    // Between the two presses: the settle, the torn read, ONE MORE settle, then
    // the read Enter is fenced on. A read taken again with no settle before it
    // lands inside the same redraw. A read is one or two `text` requests (the
    // tail, then the whole screen when the tail decides nothing), so runs of
    // reads count once.
    let mut between: Vec<&str> = m
        .requests
        .iter()
        .skip_while(|r| !(verb_of(r) == "key" && r.ends_with(" right")))
        .skip(1)
        .take_while(|r| !(verb_of(r) == "key" && r.ends_with(" enter")))
        .filter_map(|r| {
            if r.starts_with("await idle ") {
                Some("settle")
            } else if verb_of(r) == "text" {
                Some("read")
            } else {
                None
            }
        })
        .collect();
    between.dedup();
    assert_eq!(
        between,
        ["settle", "read", "settle", "read"],
        "{:#?}",
        m.requests
    );

    // NEGATIVE CONTROL: still torn when read again — judged on neither read,
    // and journaled.
    let (dir, path) = journal_file("te-accept-torn");
    let mut m = accepting(
        vec![
            busy_screen(),
            suggesting("Stage 1 is in."),
            torn.clone(),
            torn,
        ],
        None,
    );
    let opts = SuperviseOpts {
        journal: Some(path.clone()),
        ..hosted(30)
    };
    let (lines, _) = watch_lines(&mut m, &opts);
    let (records, _) = journal_records(&path);
    let _ = std::fs::remove_dir_all(&dir);
    assert_eq!(
        m.presses(),
        ["key if-gen=1.102 if=^❯\\x20keep\\x20going\\s*$ right"],
        "{lines:#?}\n{:#?}",
        m.requests
    );
    assert_eq!(count(&m, "turn"), 0, "{:#?}", m.requests);
    assert!(
        records
            .iter()
            .any(|r| r.kind == "skipped" && r.seq == Some(102)),
        "{records:#?}"
    );
}

/// A PERSON'S DRAFT OVER A SELECTION DRAWN IN COLOUR ONLY (the review of ATERM-KI-1016-1's
/// "no pointer" item): `/config` standing over 2.1.268's slash menu at a turn end, the
/// text the same whichever entry is selected. The loop reads the `cell` of each entry's
/// first glyph, as MEASURED: as the menu opened (`/config` in `b1b9f9`) the draft is sent
/// with one fenced Enter, which opened the settings; after a person's `down`
/// (`/update-config` in `b1b9f9`), where Enter ran `/update-config`, nothing is pressed and
/// the point is escalated (`MENU_DIVERTS`). NEGATIVE CONTROL: with the cells unanswered
/// the selection is unknown, and nothing is pressed or escalated.
#[test]
fn a_draft_over_a_selection_drawn_in_colour_only_is_sent_only_onto_its_own_entry() {
    use aterm_phase::prompt::fixtures::{
        SLASH_MENU_CONFIG_2_1_268, SLASH_MENU_CONFIG_CELLS_2_1_268,
        SLASH_MENU_CONFIG_DOWN_CELLS_2_1_268, cells, screen,
    };
    let mut at_end = screen(SLASH_MENU_CONFIG_2_1_268);
    // The turn's end in the two blank rows over the frame: every row index kept.
    assert!(at_end[3].is_empty() && at_end[4].is_empty());
    at_end[3] = "⏺ Stage 1 is in.".to_string();
    at_end[4] = "✻ Worked for 12m 2s · done 4:24 PM".to_string();
    let caret = at_end
        .iter()
        .position(|r| r.starts_with('❯') && r.trim_end().ends_with("/config"))
        .expect("the caret row");
    for (what, measured, sent, unanswered) in [
        (
            "`/config` selected",
            SLASH_MENU_CONFIG_CELLS_2_1_268,
            true,
            false,
        ),
        (
            "`/update-config` selected",
            SLASH_MENU_CONFIG_DOWN_CELLS_2_1_268,
            false,
            false,
        ),
        (
            "the cells unanswered",
            SLASH_MENU_CONFIG_CELLS_2_1_268,
            false,
            true,
        ),
    ] {
        let mut m = fenced(vec![busy_screen(), at_end.clone()]);
        m.cursor_row = Some(caret);
        m.cursor_col = Some(2 + "/config".chars().count());
        m.cell_unreadable = unanswered;
        m.cells = cells(measured)
            .into_iter()
            .map(|(r, c, reply)| ((r, c), reply))
            .collect();
        m.vanish_after = Some(3);
        let mut opts = hosted(3);
        opts.policy.human_grace_s = 0;
        let (lines, _) = watch_lines(&mut m, &opts);
        assert!(
            m.requests.iter().any(|r| r.starts_with("cell 8 2")),
            "{what}: the entries' cells were read: {:#?}",
            m.requests
        );
        let enters = m
            .presses()
            .iter()
            .filter(|r| r.ends_with(" enter") && r.contains("if-gen="))
            .count();
        assert_eq!(
            (enters, count(&m, "turn") + count(&m, "send")),
            (usize::from(sent), 0),
            "{what}: {lines:#?}\n{:#?}",
            m.requests
        );
        // The badge carries the reason, cut to its room.
        let reason = &crate::supervise::policy::turn_end::MENU_DIVERTS[..60];
        let escalated = m
            .requests
            .iter()
            .any(|r| r.starts_with("meta set attention") && r.contains(reason));
        assert_eq!(
            escalated,
            !sent && !unanswered,
            "{what}: {lines:#?}\n{:#?}",
            m.requests
        );
    }
}

