/// [`login_expired`] with a person's local command said under its row
/// (`/model`, kept): the row is no longer the last thing said, and the
/// screen reads idle with no wall — the login not back.
fn login_left() -> Vec<String> {
    let mut r = login_expired();
    let at = r
        .iter()
        .position(|row| row.starts_with("⏺ Login expired"))
        .expect("the wall row");
    r.splice(
        at + 1..at + 1,
        rows(&["", "❯ /model", "  ⎿  Kept model as Opus 4.7"]),
    );
    r
}

/// A LOST LOGIN THAT ANSWERED THE LOOP'S OWN ACT AND LEFT THE SCREEN INSIDE
/// THE ACT'S TAKE WINDOW IS SIGNED IN (round 16's review, 2026-10-14): the
/// loop's `keep going` was answered at once by `⏺ Login expired · Please run
/// /login`, and a person's `/model` under it took the row off the screen
/// before the window's end. No point decided the wall, so the point after
/// the window does, as the wall it left: `/login` typed once under
/// `auth-login@v1`, and no badge beside it — the owner hears of the sign-in
/// from its notice where its dialog stands ([`super::policy::notice`]).
/// Measured before: the track the window's reading opened held the point
/// as a login already told of, and the loop sat silent with the login lost.
#[test]
fn a_lost_login_left_inside_the_own_acts_window_types_login() {
    let (dir, journal) = journal_file("te-takewin-login");
    let mut m = Mock::new(vec![
        busy_screen(),
        ended("Fixed the parser; the suite is green."),
        login_expired(),
        login_left(),
    ]);
    m.turn_gates = vec![1];
    m.vanish_after = Some(40);
    m.stall_sleep = Some(Duration::from_millis(100));
    // The run ends where the loop parks on the login it told of
    // (`Mock::end_when_parked`): a second `/login` would be due sooner.
    m.end_when_parked = true;
    let opts = SuperviseOpts {
        journal: Some(journal.clone()),
        ..hosted(30)
    };
    let (lines, _) = watch_lines_with(&mut m, &opts, |s| {
        s.set_turn_end_timing(TurnEndTiming {
            take_within: Duration::from_secs(1),
            short_backoff: Duration::from_millis(100),
            ..TurnEndTiming::default()
        });
    });
    let (records, _) = journal_records(&journal);
    let _ = std::fs::remove_dir_all(&dir);
    let decided: Vec<&String> = lines
        .iter()
        .filter(|l| l.starts_with("TYPED") || l.starts_with("CONTINUED"))
        .collect();
    assert_eq!(
        decided.len(),
        2,
        "the continuation, then `/login` once: {lines:#?}\n{:#?}",
        m.requests
    );
    assert_eq!(decided[0], "CONTINUED seq=102 rule=continue@v1 keep going");
    assert!(
        decided[1].starts_with("TYPED seq=") && decided[1].ends_with("rule=auth-login@v1 /login"),
        "{lines:#?}"
    );
    assert!(
        !m.requests
            .iter()
            .any(|r| r.starts_with("meta set attention")),
        "no badge beside the lost login's notice: {:#?}",
        m.requests
    );
    assert!(
        !records.iter().any(|r| r.kind == "escalated"),
        "{records:#?}"
    );
}

/// A weekly wall that says `resets 4pm`
/// and is met again by a continuation is placed afresh on each reprint's own
/// print. Tried at 16:02 and 16:12, the reprint at 16:13 is placed on 16:07 —
/// tomorrow's 16:00, a 23 hour wait for a lift that lagged by twelve minutes
/// (measured: -2 min, then +1427). A jump past the ladder's last
/// rung on the SAME words is held back four reprints — the ladder goes on, about
/// two hours — and then believed: the vendor prints a bare clock only for a reset
/// within a day ahead. NEGATIVE CONTROL: other words are a new wall, placed at
/// once.
#[test]
fn a_reprinted_wall_is_not_sent_to_tomorrow_at_once() {
    let at = |h: i64, m: i64| TEST_NOW + (h - 8) * 3600 + (m - 55) * 60;
    let four = "4pm (America/Los_Angeles)";
    let frame = |done: &str| {
        let mut r = rows(&[
            "⏺ Working.",
            "",
            &format!("✻ Worked for 3m 2s · done {done}"),
            "",
        ]);
        r.extend(composer("  ⏵⏵ bypass permissions on"));
        r
    };
    let mut m = Mock::new(vec![busy_screen()]);
    let mut s = session(&mut m, None);
    s.set_zone_lookup(test_zones);
    let reset_after = |s: &mut Session<'_, Mock>, h: i64, mi: i64, clock: &str, text: &str| {
        s.set_clock(at(h, mi), PDT);
        let _ = s.wall_reset_at(
            Some(text),
            aterm_phase::WallKind::UsageWeekly,
            false,
            true,
            false,
            false,
            &frame(clock),
        );
        let now = s.now_unix();
        s.wall_reset
            .as_ref()
            .and_then(|(_, u)| *u)
            .map(|u| (u - now) / 60)
    };
    // The first print (seen arriving, 16:02): the clock just passed.
    assert_eq!(reset_after(&mut s, 16, 3, "4:02 PM", four), Some(-3));
    // The reprints: the far placement is held back for the first four ...
    for (h, mi, done) in [
        (16, 13, "4:13 PM"),
        (16, 43, "4:43 PM"),
        (17, 13, "5:13 PM"),
        (17, 43, "5:43 PM"),
    ] {
        let got = reset_after(&mut s, h, mi, done, four).expect("a placement");
        assert!(
            got < 0,
            "{h}:{mi:02}: held at the first placement, {got} min from now"
        );
    }
    assert_eq!(s.reprint_jumps, super::turn_end_loop::REPRINT_JUMPS_MAX);
    // ... and believed at the fifth: tomorrow's 4pm.
    let got = reset_after(&mut s, 18, 13, "6:13 PM", four).expect("a placement");
    assert!(got > 21 * 60, "believed: {got} min");
    // CONTROL: other words are a new wall, placed at once (the counter starts over).
    let mut s = session(&mut m, None);
    s.set_zone_lookup(test_zones);
    assert_eq!(reset_after(&mut s, 16, 3, "4:02 PM", four), Some(-3));
    let got =
        reset_after(&mut s, 16, 13, "4:13 PM", "5pm (America/Los_Angeles)").expect("a placement");
    assert!(
        (45..=47).contains(&got),
        "a different clock is placed on its own print: {got}"
    );
}

/// A wall's placed reset is cached under its words, and the cache is dropped
/// once the worker has WORKED with no wall on the screen: the next wall of the
/// same words is a new reset, placed afresh. NEGATIVE CONTROL: a look at a
/// screen with no wall before the worker has worked keeps the cache.
#[test]
fn the_wall_cache_is_dropped_when_the_worker_has_worked() {
    let mut m = Mock::new(vec![busy_screen()]);
    let mut s = session(&mut m, None);
    s.set_zone_lookup(test_zones);
    let opts = hosted(30);
    let of = |rows: Vec<String>| Screen {
        rows,
        cursor_row: 0,
        cursor_col: 2,
        seq: 1,
        first: 0,
        generation: None,
        human: crate::supervise::screen::HumanInput::Unknown,
        human_seq: None,
        cols: None,
        pane_rows: None,
        launch: None,
    };
    let wall = of(memory_wall_in("3h"));
    let r = s.turn_end_reading(&wall, None, &opts);
    assert!(r.wall.is_some() && r.reset_at.is_some(), "the wall is read");
    assert!(s.wall_reset.is_some(), "and its reset is cached");
    let mut idle = rows(&["⏺ All done.", "", "✻ Worked for 3m 2s · done 8:00 PM", ""]);
    idle.extend(composer("  ⏵⏵ bypass permissions on (shift+tab to cycle)"));
    let gone = of(idle);
    let _ = s.turn_end_reading(&gone, None, &opts);
    assert!(
        s.wall_reset.is_some(),
        "no wall on the screen but no work either: the cache stays"
    );
    let _ = s.turn_end_reading(&gone, Some(Duration::from_secs(600)), &opts);
    assert!(s.wall_reset.is_none(), "the worker worked: dropped");
    assert_eq!(s.reprint_jumps, 0);
}

/// THE WAKE'S SETTLE IS SPREAD BY THE SESSION'S OWN SHARE, so the sessions
/// of one account do not all type in the same second when the Mac wakes: a
/// wait three hours ahead that the sleep carried past is decided again a
/// settle later, and 20 sessions land on several distinct seconds. (The
/// settle itself, where the wait sees the sleep:
/// [`a_sleep_between_two_steps_of_the_wait_is_seen_by_the_wait_itself`].)
#[test]
fn the_wakes_settle_is_spread_by_the_sessions_share() {
    let past = TEST_NOW + 8 * 3600;
    let mut seconds = std::collections::BTreeSet::new();
    for k in 0..20 {
        let mut m = Mock::new(vec![busy_screen()]);
        let mut s = session(&mut m, Some(format!("s-{k}")));
        s.set_clock(TEST_NOW, PDT);
        s.set_due(
            Instant::now() + Duration::from_secs(3 * 3600),
            "usage-weekly resets",
        );
        let before = Instant::now();
        s.settle_wake(past, Instant::now());
        s.woke(102, past, &mut super::super::Alone);
        let due = s.turn_end_due.expect("the settle's wait");
        assert_eq!(due.why, "the Mac woke");
        seconds.insert(due.at.saturating_duration_since(before).as_secs());
    }
    assert!(seconds.len() >= 8, "{seconds:?}");
}

/// Every line a step of the loop said or noted ([`Heard`]).
fn heard_lines(heard: &Heard) -> Vec<String> {
    heard.said.iter().chain(&heard.noted).cloned().collect()
}

/// THE SLEEP, WHERE IT IS WIRED. [`Session::wait_for_next`] marks the two
/// clocks and looks at them at every step; a wall clock that ran ahead of the
/// monotonic one by more than a minute between two steps is a Mac that slept,
/// and the wait it carried past is decided again a settle later. The test
/// stages the sleep in the session's own clock (a fixed clock that jumps 4
/// hours after the wait's first read, the monotonic one standing still) and
/// runs the real wait. NEGATIVE CONTROLS: a clock that only ticks an ordinary
/// step, and one stepped BACK, wake nothing; a wait with nothing standing is
/// left alone.
#[test]
fn a_sleep_between_two_steps_of_the_wait_is_seen_by_the_wait_itself() {
    use super::super::turn_end_loop::{WAKE_SETTLE, WAKE_SPREAD};
    let run = |step: i64, standing: bool| {
        let mut m = Mock::new(vec![busy_screen()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(TEST_NOW, PDT);
        if standing {
            s.set_due(
                Instant::now() + Duration::from_secs(3 * 3600),
                "usage-weekly resets",
            );
        }
        // The wait marks the clocks at its entry, the jump comes after.
        s.set_clock_jump(step);
        let seen = Turn {
            phase: Phase::Idle,
            screen: Screen {
                rows: ended("Stage done."),
                seq: 102,
                ..Screen::default()
            },
            timed_out: false,
        };
        let began = Instant::now();
        let mut deadline = began + Duration::from_millis(600);
        let mut review = Heard::default();
        let end = s.wait_for_next(seen, &hosted(30), &[], &mut deadline, &mut review);
        let took = began.elapsed();
        let lines = heard_lines(&review);
        // The scripted server answers the first wait with a moved screen: the
        // step ends, the loop looks again. What the step did to the wait is
        // what is asserted.
        assert!(end.is_ok(), "step {step}: {lines:#?}");
        let due = s
            .turn_end_due
            .clone()
            .map(|d| (d.at.saturating_duration_since(began), d.why));
        (lines, due, took)
    };
    // Four hours in one read: the Mac slept.
    let (lines, due, took) = run(4 * 3600, true);
    assert!(
        lines.iter().any(|l| l.starts_with("WAITING seq=102 until=")
            && l.ends_with("the Mac woke: deciding again")),
        "{lines:#?}"
    );
    let (after, why) = due.expect("a wait stands");
    assert_eq!(why, "the Mac woke");
    // The settle is placed from a read of the monotonic clock inside the
    // wait, so it lies between `began` and `began + took` past the settle and
    // the session's share (under WAKE_SPREAD): the wait's own measured time is
    // the slack, never a guess at the machine's load.
    assert!(
        after >= WAKE_SETTLE && after < WAKE_SETTLE + WAKE_SPREAD + took,
        "the far deadline is replaced by a settle: {after:?} (the wait took {took:?})"
    );
    // NEGATIVE CONTROLS.
    for step in [0, 20, -30] {
        let (lines, due, _) = run(step, true);
        assert!(
            !lines.iter().any(|l| l.contains("the Mac woke")),
            "step {step}: {lines:#?}"
        );
        assert!(due.expect("still standing").0 > Duration::from_secs(3 * 3600 - 5));
    }
    let (lines, due, _) = run(4 * 3600, false);
    assert!(lines.is_empty() && due.is_none(), "{lines:#?} {due:?}");
}

/// A WALL CLOCK STEPPED FORWARD IS NO SLEEP WHERE THE MACHINE COUNTS ITS
/// SLEEP ([`Session::watch_sleep`]): the wait of the test above, on a
/// machine that counts (`aterm_uds::process::asleep_since_boot`), its clock
/// jumping four hours between two steps. Counted as sleep, the jump is the
/// Mac's: the wait carried past is decided again a settle later, and the
/// sleep is in the loop's book between the two reads, which a turn's done
/// row is read against. Not counted — a clock a person or a time server set
/// on — it is no sleep: nothing woke, nothing is in the book, the wait
/// stands. NEGATIVE CONTROL: on a machine that keeps no count, the step
/// reads as a sleep, as before the count.
#[test]
fn a_clock_stepped_forward_is_no_sleep_where_the_machine_counts() {
    let run = |counts: bool, slept: bool| {
        let mut m = Mock::new(vec![busy_screen()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(TEST_NOW, PDT);
        if counts {
            s.count_sleeps(Duration::from_secs(600));
        }
        s.set_due(
            Instant::now() + Duration::from_secs(3 * 3600),
            "usage-weekly resets",
        );
        if slept {
            s.set_clock_jump(4 * 3600);
        } else {
            s.set_clock_step(4 * 3600);
        }
        let seen = Turn {
            phase: Phase::Idle,
            screen: Screen {
                rows: ended("Stage done."),
                seq: 102,
                ..Screen::default()
            },
            timed_out: false,
        };
        let mut deadline = Instant::now() + Duration::from_millis(600);
        let mut review = Heard::default();
        let end = s.wait_for_next(seen, &hosted(30), &[], &mut deadline, &mut review);
        assert!(end.is_ok(), "{:#?}", heard_lines(&review));
        let woke = heard_lines(&review)
            .iter()
            .any(|l| l.contains("the Mac woke"));
        let book: Vec<Duration> = s.sleep_book().sleeps().map(|z| z.len).collect();
        (woke, book)
    };
    let four = Duration::from_secs(4 * 3600);
    assert_eq!(run(true, true), (true, vec![four]), "a sleep, counted");
    assert_eq!(run(true, false), (false, Vec::new()), "a step, counted");
    assert_eq!(run(false, false), (true, vec![four]), "CONTROL: no count");
}

/// THE SLEEP UNDER A RECORDER: the staged sleep of the test above, its wait
/// run once unrecorded and once with the door recording, says the same lines
/// and leaves the same due — four hours in one read is the Mac's sleep
/// either way, an ordinary tick or a step back is none either way (the
/// recorder's stamps are peeks that never make the read a staged jump lands
/// at: pinned by `tape::core`'s
/// `a_stamp_never_makes_the_read_a_staged_jump_lands_at`). Each line's
/// `until=` is masked: it is placed from a monotonic read the two runs make at
/// their own moments.
#[test]
fn a_recorded_wait_sees_the_sleep_an_unrecorded_one_sees() {
    let run = |step: i64, recorded: bool| {
        let mut m = Mock::new(vec![busy_screen()]);
        let tape = memory_tape_clock();
        // Unrecorded: the door is the live one, a pass-through.
        let door = if recorded { tape.fx.clone() } else { Fx::os() };
        let mut taped = TapedCtl::new(&mut m, door, crate::supervise::tape::doors::CTL);
        let mut s = session(&mut taped, Some("@s-1".to_string()));
        if recorded {
            s.set_fx(tape.fx.clone());
        }
        s.set_clock(TEST_NOW, PDT);
        s.set_due(
            Instant::now() + Duration::from_secs(3 * 3600),
            "usage-weekly resets",
        );
        s.set_clock_jump(step);
        let seen = Turn {
            phase: Phase::Idle,
            screen: Screen {
                rows: ended("Stage done."),
                seq: 102,
                ..Screen::default()
            },
            timed_out: false,
        };
        let mut deadline = Instant::now() + Duration::from_millis(600);
        let mut review = Heard::default();
        let end = s.wait_for_next(seen, &hosted(30), &[], &mut deadline, &mut review);
        assert!(end.is_ok(), "step {step}");
        let due = s.turn_end_due.clone().map(|d| d.why);
        let lines: Vec<String> = heard_lines(&review)
            .into_iter()
            .map(|l| {
                l.split(' ')
                    .map(|w| {
                        if w.starts_with("until=") {
                            "until=…"
                        } else {
                            w
                        }
                    })
                    .collect::<Vec<_>>()
                    .join(" ")
            })
            .collect();
        drop(s);
        (lines, due)
    };
    for step in [4 * 3600, 0, 20, -30] {
        let (off_lines, off_due) = run(step, false);
        let (on_lines, on_due) = run(step, true);
        assert_eq!(on_lines, off_lines, "step {step}");
        assert_eq!(on_due, off_due, "step {step}");
        assert_eq!(
            on_due.as_deref() == Some("the Mac woke"),
            step == 4 * 3600,
            "step {step}: {on_lines:#?}"
        );
    }
}

/// A door recording into memory over a fixed clock not yet fixed — the
/// session's [`Session::set_clock`] fixes it through the door.
fn memory_tape_clock() -> MemoryTape {
    MemoryTape::over(&Fx::over(ClockSource::Scripted(Arc::default())))
}

/// A DUE THE SLEEP FELL SHORT OF FALLS AT ITS WALL TIME (the audit of
/// 2026-10-09: three tabs left 11.6-14.1 h past a weekly reset their
/// `Instant` waits had slept through). A wait set three hours ahead; the Mac
/// sleeps two of them — the wall clock jumps, the monotonic one stands still
/// — and wakes on a repaint (a new seq). The watch sees the sleep, but the
/// due is not one it carried past ([`Session::woke`] leaves it): it stands,
/// at its WALL time ([`Session::due_at`]) — an hour from the wake, not the
/// three its `Instant` still counts. (A due the sleep carried past waits for
/// the wake's settle instead:
/// [`a_reset_the_sleep_carried_past_waits_for_the_settle_though_a_repaint_wakes_the_loop`].)
/// NEGATIVE CONTROL: no sleep, three hours.
#[test]
fn a_due_the_sleep_fell_short_of_falls_at_its_wall_time() {
    let seen = |seq: u64| Turn {
        phase: Phase::Idle,
        screen: Screen {
            rows: ended("Stage done."),
            seq,
            ..Screen::default()
        },
        timed_out: false,
    };
    let run = |slept: i64| {
        let mut m = Mock::new(vec![busy_screen()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(TEST_NOW, PDT);
        s.set_due(
            Instant::now() + Duration::from_secs(3 * 3600),
            "usage-weekly resets",
        );
        let mut review = Heard::default();
        let mut deadline = Instant::now() + Duration::from_millis(600);
        let before = s.wait_for_next(seen(102), &hosted(30), &[], &mut deadline, &mut review);
        assert!(before.is_ok(), "{:#?}", heard_lines(&review));
        s.set_clock(TEST_NOW + slept, PDT);
        let mut deadline = Instant::now() + Duration::from_millis(600);
        let after = s.wait_for_next(seen(103), &hosted(30), &[], &mut deadline, &mut review);
        assert!(after.is_ok(), "{:#?}", heard_lines(&review));
        let left = s
            .due_at()
            .map(|t| t.saturating_duration_since(Instant::now()));
        (s.turn_end_due.clone().map(|d| d.why), left)
    };
    let (why, left) = run(2 * 3600);
    assert_eq!(why.as_deref(), Some("usage-weekly resets"));
    let left = left.expect("a due");
    assert!(
        left > Duration::from_secs(3600 - 60) && left <= Duration::from_secs(3600),
        "an hour from the wake: {left:?}"
    );
    // NEGATIVE CONTROL.
    let (why, left) = run(0);
    assert_eq!(why.as_deref(), Some("usage-weekly resets"));
    let left = left.expect("a due");
    assert!(left > Duration::from_secs(3 * 3600 - 60), "{left:?}");
}

/// What one wait of the loop's ([`Session::wait_for_next`]) said and left: the
/// lines heard, and the due standing after it (its reason).
struct Waited {
    lines: Vec<String>,
    due: Option<String>,
}

/// One wait on `point` (a 600 ms budget), into `heard`: what it said NEW, and
/// the due it left.
fn wait_once(
    s: &mut Session<'_, Mock>,
    point: &Turn,
    opts: &SuperviseOpts,
    heard: &mut Heard,
) -> Waited {
    let (said, noted) = (heard.said.len(), heard.noted.len());
    let mut deadline = Instant::now() + Duration::from_millis(600);
    let end = s.wait_for_next(point.clone(), opts, &[], &mut deadline, heard);
    assert!(end.is_ok(), "{:#?}", heard_lines(heard));
    Waited {
        lines: heard.said[said..]
            .iter()
            .chain(&heard.noted[noted..])
            .cloned()
            .collect(),
        due: s.turn_end_due.as_ref().map(|d| d.why.clone()),
    }
}

/// `rows` at `seq` as the session's own reader takes the point.
fn point_at(s: &Session<'_, Mock>, rows: Vec<String>, seq: u64) -> Turn {
    s.turn_of(Screen {
        rows,
        seq,
        ..Screen::default()
    })
}

/// Whether `lines` hold a continuation under `rule`.
fn continued(lines: &[String], rule: &str) -> bool {
    lines
        .iter()
        .any(|l| l.starts_with("CONTINUED seq=") && l.contains(&format!("rule={rule}")))
}

/// THE WAKE'S FIRST EVENT IS A REPAINT (the audit of 2026-10-09: `WAITING …
/// usage-weekly resets`, the Mac asleep 4.26 days across the reset, and no
/// `CONTINUED … rule=usage-resume@v1` until a person resumed three tabs
/// 11.6-14.1 h after it; and the handoff's residual (b) of the fix that
/// followed). A weekly limit is decided before its reset and waited for; the
/// Mac sleeps eleven hours past the reset, and what wakes the loop is Claude
/// Code repainting — the same point at a NEW seq. The reset the sleep carried
/// the wait past is decided after the wake's settle (the network is coming
/// back: a continuation typed into an API that cannot be reached is a wall of
/// its own), not at that first wait: nothing is typed there, the due stands
/// at the settle (`WAITING … the Mac woke`), and once the settle has passed
/// the point is continued, once — never held by the sleep. NEGATIVE CONTROL:
/// the same waits with no sleep type nothing and leave the reset's wait
/// standing.
#[test]
fn a_reset_the_sleep_carried_past_waits_for_the_settle_though_a_repaint_wakes_the_loop() {
    use crate::supervise::policy::turn_end::RULE_LIMIT_RESUME;
    let run = |slept: bool| {
        let mut m = Mock::new(vec![weekly_limited()]);
        let opts = hosted(30);
        let mut heard = Heard::default();
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(TEST_NOW, PDT);
        s.set_zone_lookup(test_zones);
        let at = |s: &Session<'_, Mock>, seq| point_at(s, weekly_limited(), seq);
        let first = at(&s, 102);
        let action = s
            .turn_end_at_point(&first, Some(Duration::from_secs(180)), &opts)
            .expect("a decision");
        s.turn_end_execute(&first, action, &opts, &[], &mut heard)
            .expect("the wait is set");
        let before = wait_once(&mut s, &first, &opts, &mut heard);
        assert!(
            !continued(&before.lines, RULE_LIMIT_RESUME),
            "{:#?}",
            before.lines
        );
        if slept {
            s.set_clock(AFTER_RESET + 11 * 3600, PDT);
        }
        let repainted = at(&s, 103);
        let woke = wait_once(&mut s, &repainted, &opts, &mut heard);
        s.pass_wake_settle();
        let again = at(&s, 104);
        let settled = wait_once(&mut s, &again, &opts, &mut heard);
        drop(s);
        let typed = count(&m, "@s-1 turn") + count(&m, "@s-1 send");
        (woke, settled, typed)
    };
    let (woke, settled, typed) = run(true);
    assert!(
        !continued(&woke.lines, RULE_LIMIT_RESUME),
        "nothing is typed at the wake's first wait: {:#?}",
        woke.lines
    );
    assert!(
        woke.lines
            .iter()
            .any(|l| l.starts_with("WAITING seq=103 until=")
                && l.ends_with("the Mac woke: deciding again")),
        "{:#?}",
        woke.lines
    );
    assert_eq!(woke.due.as_deref(), Some("the Mac woke"));
    assert!(
        continued(&settled.lines, RULE_LIMIT_RESUME),
        "continued once the settle has passed: {:#?}",
        settled.lines
    );
    assert_eq!(typed, 1);
    // NEGATIVE CONTROL.
    let (woke, settled, typed) = run(false);
    let lines: Vec<&String> = woke.lines.iter().chain(&settled.lines).collect();
    assert!(
        !lines
            .iter()
            .any(|l| l.contains("the Mac woke") || l.starts_with("CONTINUED")),
        "{lines:#?}"
    );
    assert_eq!(settled.due.as_deref(), Some("usage-weekly resets"));
    assert_eq!(typed, 0);
}

/// THE POLICY'S OWN BACK-OFF ACROSS A SLEEP (the handoff's residual (a) of
/// 2026-10-09). A 529 is waited out on a rung of an hour; the Mac sleeps
/// eight hours ten minutes into it and wakes on the same point (its seq
/// unchanged, so the wake is seen and its settle placed). Once the settle has
/// passed, the rung — counted on the wall clock, as every pause of the
/// policy's is — is long over: the retry is typed (`api-retry@v1`), not
/// another fifty minutes waited (the rung counted on `Instant`, which a sleep
/// stops). NEGATIVE CONTROL: no sleep, the rung still stands and nothing is
/// typed.
#[test]
fn a_back_off_the_mac_slept_through_is_over_once_the_wake_settles() {
    use crate::supervise::policy::turn_end::RULE_API_RETRY;
    let end_529 = || aterm_phase::prompt::fixtures::screen(aterm_phase::prompt::fixtures::END_529);
    let run = |slept: bool| {
        let mut m = Mock::new(vec![end_529()]);
        let opts = hosted(30);
        let mut heard = Heard::default();
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(TEST_NOW, PDT);
        s.set_turn_end_timing(TurnEndTiming {
            retry_backoff: vec![Duration::from_secs(3600)],
            ..TurnEndTiming::default()
        });
        let point = point_at(&s, end_529(), 102);
        let action = s
            .turn_end_at_point(&point, Some(Duration::from_secs(180)), &opts)
            .expect("a decision");
        assert!(
            matches!(&action, TurnEndAction::WaitUntil { why, .. } if why == "overloaded retry 1"),
            "{action:?}"
        );
        s.turn_end_execute(&point, action, &opts, &[], &mut heard)
            .expect("the wait is set");
        let _ = wait_once(&mut s, &point, &opts, &mut heard);
        if slept {
            s.set_clock(TEST_NOW + 8 * 3600, PDT);
        }
        let woke = wait_once(&mut s, &point, &opts, &mut heard);
        s.pass_wake_settle();
        let settled = wait_once(&mut s, &point, &opts, &mut heard);
        drop(s);
        let typed = count(&m, "@s-1 turn") + count(&m, "@s-1 send");
        (woke, settled, typed)
    };
    let (woke, settled, typed) = run(true);
    assert_eq!(
        woke.due.as_deref(),
        Some("the Mac woke"),
        "{:#?}",
        woke.lines
    );
    assert!(
        continued(&settled.lines, RULE_API_RETRY),
        "the rung slept through is over: {:#?}",
        settled.lines
    );
    assert_eq!(typed, 1, "{:#?}", settled.lines);
    // NEGATIVE CONTROL.
    let (_, settled, typed) = run(false);
    assert_eq!(settled.due.as_deref(), Some("overloaded retry 1"));
    assert_eq!(typed, 0, "{:#?}", settled.lines);
}

/// ANOTHER EVENT REACHES THE LOOP FIRST (residual (b): "whatever event
/// reaches the loop first"). At a network wall waited on a rung of an hour,
/// the Mac sleeps eight hours; at the wake the host's measure of the API
/// turns `Up` — an edge that decides the point at once, ahead of the due.
/// The wake is seen (the same seq) and the due placed at the settle, and the
/// edge still decides inside it: the try is typed before the network has
/// settled. It must wait for the settle like the due it overtook, and go
/// once the settle has passed (`api-back@v1`). NEGATIVE CONTROL: the same
/// edge with no sleep is acted on at once, as ever.
#[test]
fn an_edge_at_the_wake_types_nothing_before_the_settle() {
    use crate::supervise::policy::turn_end::RULE_API_BACK;
    let run = |slept: bool| {
        let host = ReachHost::scripted(&[Reach::Unknown]);
        let mut m = Mock::new(vec![enotfound()]);
        m.stall_sleep = Some(Duration::from_millis(5));
        let opts = SuperviseOpts {
            idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
            ..hosted(30)
        };
        let mut heard = Heard::default();
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(TEST_NOW, PDT);
        s.set_turn_end_timing(far_rungs());
        let point = point_at(&s, enotfound(), 102);
        let action = s
            .turn_end_at_point(&point, Some(Duration::from_secs(180)), &opts)
            .expect("a decision");
        assert!(
            matches!(&action, TurnEndAction::WaitUntil { .. }),
            "{action:?}"
        );
        s.turn_end_execute(&point, action, &opts, &[], &mut heard)
            .expect("the rung's wait");
        let _ = wait_once(&mut s, &point, &opts, &mut heard);
        host.script.lock().unwrap().push_back(Reach::Up {
            since: Instant::now(),
        });
        if slept {
            s.set_clock(TEST_NOW + 8 * 3600, PDT);
        }
        let woke = wait_once(&mut s, &point, &opts, &mut heard);
        s.pass_wake_settle();
        let settled = wait_once(&mut s, &point, &opts, &mut heard);
        drop(s);
        let typed = count(&m, "@s-1 turn") + count(&m, "@s-1 send");
        (woke, settled, typed)
    };
    let (woke, settled, typed) = run(true);
    assert!(
        !continued(&woke.lines, RULE_API_BACK),
        "the edge types nothing inside the settle: {:#?}",
        woke.lines
    );
    assert_eq!(
        woke.due.as_deref(),
        Some("the Mac woke"),
        "{:#?}",
        woke.lines
    );
    assert!(
        continued(&settled.lines, RULE_API_BACK),
        "the try goes once the settle has passed: {:#?}",
        settled.lines
    );
    assert_eq!(typed, 1);
    // NEGATIVE CONTROL.
    let (woke, _, typed) = run(false);
    assert!(continued(&woke.lines, RULE_API_BACK), "{:#?}", woke.lines);
    assert_eq!(typed, 1);
}

/// A host that asks for a point once told to (`wanting`) and takes it with a
/// step that TYPES into the agent — the live upgrade's carry-on — counted; it
/// keeps the words of the guards the loop said withheld a point
/// ([`IdleHost::withheld`]).
#[derive(Debug, Default)]
struct WakeHost {
    wanting: AtomicBool,
    steps: std::sync::atomic::AtomicUsize,
    withheld: std::sync::Mutex<Vec<&'static str>>,
}

impl IdleHost for WakeHost {
    fn wants(&self) -> bool {
        self.wanting.load(Ordering::SeqCst)
    }
    fn at_idle(&self) -> Option<HostStep> {
        self.steps.fetch_add(1, Ordering::SeqCst);
        self.wanting.store(false, Ordering::SeqCst);
        Some(HostStep {
            line: "upgrade step=carry-on".to_string(),
            moved: true,
            typed: Some(crate::supervise::policy::turn_end::HostTurn::CarryOn),
            repeat: false,
        })
    }
    fn owns_turn_end(&self) -> bool {
        false
    }
    fn withheld(&self, guard: crate::supervise::Guard) {
        self.withheld.lock().unwrap().push(guard.word());
    }
}

/// THE HOST'S STEP AT THE WAKE (the review of 2026-10-14, its probe D). The
/// wake's settle holds more than the turn-end policy's acts: the host's step
/// at an idle point — the live upgrade's notice or carry-on, a relaunched
/// agent's continuation — TYPES a turn into the agent too, into an API the
/// network may not reach yet. An idle point is waited on; the Mac sleeps
/// eight hours; at the wake the host asks for the point. Inside the settle
/// the point is withheld from it, and it is told why (`guard=wake-settle`);
/// once the settle has passed, its step goes. NEGATIVE CONTROL: the same ask
/// with no sleep is stepped at once.
#[test]
fn the_hosts_step_at_the_wake_waits_for_the_settle() {
    let run = |slept: bool| {
        let host = Arc::new(WakeHost::default());
        let mut m = Mock::new(vec![idle_screen()]);
        m.cursor_on_caret = true;
        let opts = SuperviseOpts {
            idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
            ..hosted(30)
        };
        let mut heard = Heard::default();
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(TEST_NOW, PDT);
        let screen = s.screen().expect("the point");
        let point = s.turn_of(screen);
        let _ = wait_once(&mut s, &point, &opts, &mut heard);
        if slept {
            s.set_clock(TEST_NOW + 8 * 3600, PDT);
        }
        host.wanting.store(true, Ordering::SeqCst);
        let woke = wait_once(&mut s, &point, &opts, &mut heard);
        let at_wake = host.steps.load(Ordering::SeqCst);
        s.pass_wake_settle();
        let _ = wait_once(&mut s, &point, &opts, &mut heard);
        let after = host.steps.load(Ordering::SeqCst);
        let withheld = host.withheld.lock().unwrap().clone();
        (woke.lines, at_wake, after, withheld)
    };
    let (lines, at_wake, after, withheld) = run(true);
    assert_eq!(at_wake, 0, "no step inside the settle: {lines:#?}");
    assert!(
        !lines.iter().any(|l| l.starts_with("HOST seq=")),
        "{lines:#?}"
    );
    assert_eq!(withheld, ["wake-settle"], "{lines:#?}");
    assert_eq!(after, 1, "the step goes once the settle has passed");
    // NEGATIVE CONTROL.
    let (lines, at_wake, _, withheld) = run(false);
    assert_eq!(at_wake, 1, "{lines:#?}");
    assert!(withheld.is_empty(), "{withheld:?}");
}

/// A WAIT INSIDE THE WAKE'S SETTLE STEPS TO ITS FALL: what the settle
/// withholds (the host's point) is offered at the top of the step that
/// follows, not a whole step later ([`Session::wait_for_next`]'s step cap, as
/// for [`IdleHost::wants_at`]). The settle falls 300 ms ahead under a
/// five-second budget: the wait's first request asks no longer than that.
/// NEGATIVE CONTROL: with no settle the step is the budget's.
#[test]
fn a_wait_inside_the_wakes_settle_steps_to_its_fall() {
    use super::super::turn_end_loop::WAKE_SETTLE;
    let run = |settling: bool| {
        let host = Arc::new(WakeHost::default());
        let mut m = Mock::new(vec![idle_screen()]);
        m.cursor_on_caret = true;
        // The wait's first request is its last: what it asked is the test.
        m.vanish_after = Some(0);
        let opts = SuperviseOpts {
            idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
            ..hosted(30)
        };
        let mut s = session(&mut m, None);
        s.set_clock(TEST_NOW, PDT);
        let screen = s.screen().expect("the point");
        let point = s.turn_of(screen);
        if settling {
            // No session id, no share: the settle alone, placed so it falls
            // 300 ms from now.
            let woke = Instant::now() + Duration::from_millis(300) - WAKE_SETTLE;
            s.settle_wake(TEST_NOW, woke);
        }
        let mut deadline = Instant::now() + Duration::from_secs(5);
        let _ = s.wait_for_next(point, &opts, &[], &mut deadline, &mut Heard::default());
        drop(s);
        m.requests
            .iter()
            .filter(|r| r.starts_with("await "))
            .find_map(|r| {
                let mut words = r.split(' ');
                words.find(|w| *w == "timeout")?;
                words.next()?.parse::<u64>().ok()
            })
            .expect("the wait's request")
    };
    let asked = run(true);
    assert!(asked <= 300, "stepped to the settle's fall: {asked} ms");
    // NEGATIVE CONTROL.
    let asked = run(false);
    assert!(asked > 300, "the budget's step: {asked} ms");
}

/// THE HOST'S BACKGROUND STEP AT THE WAKE, and the sleep seen by a REQUEST
/// (the review of 2026-10-14). A break in the agent's own background work is
/// offered to the host on a busy read ([`Session::host_steps_in_background`]):
/// the upgrade's notice typed there is a turn into the API like any other.
/// The Mac sleeps between two busy reads; only the read itself — a request
/// ([`Session::call`]) — can see the sleep, since no wait or decision runs
/// on a busy turn. Inside the settle the break is withheld
/// (`guard=wake-settle`); once it has passed, offered. NEGATIVE CONTROL: the
/// same reads with no sleep offer the break at once.
#[test]
fn the_hosts_background_step_at_the_wake_waits_for_the_settle() {
    let bg = || {
        let mut r = rows(&[
            "⏺ Waiting for the build.",
            "",
            "✻ Crunched for 9m 27s · done 11:07 AM · 1 shell still running",
            "",
        ]);
        r.extend(composer("  ⏵⏵ auto mode on · 1 shell · ← for agents"));
        r
    };
    let run = |slept: bool| {
        let host = Arc::new(BackgroundHost::default());
        let mut m = Mock::new(vec![bg()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(TEST_NOW, PDT);
        s.stall_host = Some(Arc::clone(&host) as Arc<dyn IdleHost>);
        s.setup.background_settle = Duration::ZERO;
        let _ = s.screen().expect("the busy read before the night");
        if slept {
            s.set_clock(TEST_NOW + 8 * 3600, PDT);
        }
        let screen = s.screen().expect("the busy read at the wake");
        let mut since = Some(Instant::now());
        s.host_steps_in_background(&screen, &mut since, None, &mut Alone);
        let at_wake = host.backgrounds.load(Ordering::SeqCst);
        s.pass_wake_settle();
        s.host_steps_in_background(&screen, &mut since, None, &mut Alone);
        let after = host.backgrounds.load(Ordering::SeqCst);
        let withheld: Vec<&str> = host
            .withheld
            .lock()
            .unwrap()
            .iter()
            .map(|g| g.word())
            .collect();
        (at_wake, after, withheld)
    };
    let (at_wake, after, withheld) = run(true);
    assert_eq!(at_wake, 0, "no notice inside the settle");
    assert_eq!(withheld, ["wake-settle"]);
    assert!(after >= 1, "offered once the settle has passed");
    // NEGATIVE CONTROL.
    let (at_wake, _, withheld) = run(false);
    assert_eq!(at_wake, 1);
    assert!(withheld.is_empty(), "{withheld:?}");
}

/// THE SETTLE COUNTS FROM THE WAKE, NOT FROM THE FIRST ACT AFTER IT (the
/// review of 2026-10-14, its probes A and B). The Mac sleeps through a
/// request of a busy turn — the request sees the sleep — and the turn ends
/// at a new point that the policy continues. Decided inside the settle, the
/// act is held at it (`WAITING … the Mac woke`) and nothing is typed: the
/// path of a sleep a request measured, through the act's own gate. Decided
/// after a busy turn that OUTLASTED the settle, it is typed at once and the
/// wake says nothing: the settle was placed when the sleep was measured, and
/// it has passed. NEGATIVE CONTROL: no sleep, typed at once.
#[test]
fn a_point_after_a_sleep_a_request_saw_is_held_only_until_the_wakes_settle() {
    use crate::supervise::policy::turn_end::RULE_CONTINUE;
    // `slept`: whether the Mac slept; `outlasted`: whether the busy turn ran
    // on past the settle before its point.
    let run = |slept: bool, outlasted: bool| {
        let mut m = Mock::new(vec![ended("Stage done.")]);
        let opts = hosted(30);
        let mut heard = Heard::default();
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(TEST_NOW, PDT);
        let _ = s.call(&["status"]).expect("a read before the night");
        if slept {
            s.set_clock(TEST_NOW + 8 * 3600, PDT);
        }
        let _ = s.call(&["status"]).expect("a read of the busy turn");
        if outlasted {
            s.pass_wake_settle();
        }
        let point = point_at(&s, ended("Stage done."), 102);
        let action = s
            .turn_end_at_point(&point, Some(Duration::from_secs(180)), &opts)
            .expect("a decision");
        s.turn_end_execute(&point, action, &opts, &[], &mut heard)
            .expect("carried out");
        let due = s.turn_end_due.as_ref().map(|d| d.why.clone());
        drop(s);
        let typed = count(&m, "@s-1 turn") + count(&m, "@s-1 send");
        (heard_lines(&heard), due, typed)
    };
    let (lines, due, typed) = run(true, false);
    assert_eq!(typed, 0, "held inside the settle: {lines:#?}");
    assert_eq!(due.as_deref(), Some("the Mac woke"), "{lines:#?}");
    assert!(
        lines.iter().any(|l| l.starts_with("WAITING seq=102 until=")
            && l.ends_with("the Mac woke: deciding again")),
        "{lines:#?}"
    );
    let (lines, _, typed) = run(true, true);
    assert!(continued(&lines, RULE_CONTINUE), "{lines:#?}");
    assert_eq!(typed, 1, "{lines:#?}");
    assert!(
        !lines.iter().any(|l| l.contains("the Mac woke")),
        "a settle long passed says nothing: {lines:#?}"
    );
    // NEGATIVE CONTROL.
    let (lines, _, typed) = run(false, false);
    assert!(continued(&lines, RULE_CONTINUE), "{lines:#?}");
    assert_eq!(typed, 1, "{lines:#?}");
}

/// A screen as the loop reads one.
fn read_screen(rows: Vec<String>) -> Screen {
    Screen {
        rows,
        cursor_row: 0,
        cursor_col: 2,
        seq: 1,
        first: 0,
        generation: None,
        human: crate::supervise::screen::HumanInput::Unknown,
        human_seq: None,
        cols: None,
        pane_rows: None,
        launch: None,
    }
}

/// THE HERD SPREAD (the accounts' sessions all reach the reset in the same
/// second and all type in it). A session's share of
/// [`TurnEndTiming::reset_jitter`] is FNV-1a of its id and the reset: the same
/// session waits the same on every reading (the policy stays a pure function of
/// what it is handed), less than the span, and 20 sessions land on many
/// distinct seconds. The loop hands the policy that share for the
/// walls a reset lifts, with a session id. NEGATIVE CONTROLS: no session id, and
/// a wall no reset lifts (a 529), get none.
#[test]
fn a_sessions_jitter_is_stable_bounded_and_spread() {
    use super::super::turn_end_loop::resume_jitter;
    let span = Duration::from_secs(60);
    // What the loop hands the policy.
    let read = |sid: Option<&str>, rows: Vec<String>| {
        let mut m = Mock::new(vec![busy_screen()]);
        let mut s = session(&mut m, sid.map(str::to_string));
        s.set_clock(TEST_NOW, PDT);
        s.set_zone_lookup(test_zones);
        let opts = hosted(30);
        let first = s.turn_end_reading(&read_screen(rows.clone()), None, &opts);
        let again = s.turn_end_reading(&read_screen(rows), None, &opts);
        assert_eq!(
            first.jitter, again.jitter,
            "the same session, the same share"
        );
        let unix = s.wall_reset.as_ref().and_then(|(_, u)| *u);
        (first.jitter, unix)
    };
    let mut shares = std::collections::BTreeSet::new();
    for k in 0..20 {
        let sid = format!("@s-{k}");
        let (jitter, unix) = read(Some(&sid), memory_wall_in("3h"));
        let unix = unix.expect("the placed reset");
        assert_eq!(jitter, resume_jitter(&sid, unix, span), "{sid}");
        assert!(jitter < span);
        shares.insert(jitter.as_secs());
    }
    assert!(
        shares.len() >= 8,
        "twenty sessions, several seconds: {shares:?}"
    );
    assert_eq!(
        read(None, memory_wall_in("3h")).0,
        Duration::ZERO,
        "no session"
    );
    let end_529 = aterm_phase::prompt::fixtures::screen(aterm_phase::prompt::fixtures::END_529);
    assert_eq!(
        read(Some("@s-3"), end_529).0,
        Duration::ZERO,
        "a 529 is no reset"
    );
}

/// A LIMIT A CANCEL LEFT THAT ONLY THE SCREEN READ IS NEVER A DAY'S WAIT
/// (round 17's residual (a)): with no transcript row to date its notice — a
/// conversation `/resume`d inside the act's window ends on its own older
/// cancelled limit, which draws the same — its bare clock is placed as an
/// answer's is (on the act's print, here: an act untaken) and then kept
/// within a session window: at the test's 08:55, `7:30am` (TOMORROW's on the
/// print) and `11:50pm` (fourteen hours ahead) are the day before's, PASSED;
/// `10:38am` (an hour and 43 minutes ahead) stands; a dated reset (`Oct 18 at
/// 7:30am`) and a span are what they name. NEGATIVE CONTROL: the same clocks
/// dated by a transcript row (`undated` false) — `7:30am` is tomorrow's, as
/// the print says.
#[test]
fn an_undated_cancelled_limit_is_placed_within_a_session_window() {
    let mut m = Mock::new(vec![busy_screen()]);
    let mut s = session(&mut m, None);
    s.set_zone_lookup(test_zones);
    let kind = aterm_phase::WallKind::UsageSession;
    let rows = auto_continue_cancelled();
    let mut placed = |text: &str, undated: bool| -> i64 {
        s.set_clock(TEST_NOW, PDT);
        s.wall_reset = None;
        let _ = s.wall_reset_at(Some(text), kind, false, false, true, undated, &rows);
        s.wall_reset
            .as_ref()
            .and_then(|(_, u)| *u)
            .expect("a placement")
            - TEST_NOW
    };
    let min = 60;
    let hour = 3600;
    // 08:55 PDT is 15:55Z.
    assert_eq!(placed("7:30am", true), -(hour + 25 * min), "passed");
    assert_eq!(
        placed("11:50pm", true),
        -(9 * hour + 5 * min),
        "yesterday's, passed"
    );
    assert_eq!(
        placed("10:38am", true),
        hour + 43 * min,
        "within the window"
    );
    assert_eq!(
        placed("Oct 18 at 7:30am", true),
        30 * 86_400 + 22 * hour + 35 * min,
        "a dated reset"
    );
    assert_eq!(placed("in 7h", true), 7 * hour, "a span");
    // NEGATIVE CONTROL: dated by a transcript row.
    assert_eq!(
        placed("7:30am", false),
        22 * hour + 35 * min,
        "tomorrow's on the print"
    );
    assert_eq!(placed("11:50pm", false), 14 * hour + 55 * min);
}

/// EVERY UNIX SECOND IS ITSELF, AT EVERY PHASE OF THE CLOCK. One placement
/// is one stamp, whatever part of a second each read fell in: a conversion
/// that carries its read's sub-second phase puts a reading made before a
/// second turns and a stamp made after it a second apart (`until=…:19Z`,
/// then `until=…:20Z`, for one wait). A FIXED clock stood at nine phases of
/// its second (no sleep, no running clock), and at each a unix second made
/// an `Instant` by `instant_of` reads back as itself through `unix_of`, and
/// one still ahead stamps as itself through `stamp_in`. A read-back that
/// drops its own read's phase can still round right just past a second's
/// turn; from 500 ms on it cannot. Each conversion put on whole seconds —
/// `instant_of`, `unix_of`, or `stamp_in` as `now_unix() + ahead` — fails
/// here.
#[test]
fn a_unix_second_reads_back_and_stamps_as_itself_at_any_phase_of_the_clock() {
    let mut m = Mock::new(vec![busy_screen()]);
    let mut s = session(&mut m, None);
    let mut bad = Vec::new();
    for phase in [0_i64, 1, 250, 499, 500, 501, 600, 750, 999] {
        s.set_clock_at_ms(TEST_NOW * 1000 + phase, PDT);
        for ahead in [-60_i64, -1, 0, 1, 2, 59, 600, 7200] {
            let u = TEST_NOW + ahead;
            let t = s.instant_of(u);
            let back = s.unix_of(t);
            if back != u {
                bad.push(format!(
                    "phase={phase} ahead={ahead}: unix_of={back}, want {u}"
                ));
            }
            if ahead >= 1 {
                let stamp = s.stamp_in(t);
                let want = utc_stamp(u64::try_from(u).expect("after 1970"));
                if stamp != want {
                    bad.push(format!(
                        "phase={phase} ahead={ahead}: stamp_in={stamp}, want {want}"
                    ));
                }
            }
        }
    }
    assert!(
        bad.is_empty(),
        "{} mismatches:\n{}",
        bad.len(),
        bad.join("\n")
    );
}

/// THE WALL IS WRITTEN DOWN, and its end. The loop that waits on a wall writes a
/// `wall-wait@v1` row with the reset as it placed it, for a loop that follows it
/// (a GUI replacement, a fault); a live turn drawn under the wall ends it with a
/// `wall-wait-end@v1` row, and the ledger then holds no open wall. Without
/// the row an update at that moment loses the wait for good.
/// NEGATIVE CONTROL: a run that never saw a wall writes neither row.
#[test]
fn the_wall_waited_on_is_written_to_the_ledger_and_its_end_too() {
    use crate::supervise::approvals;
    let run = |tag: &str, screens: Vec<Vec<String>>| {
        let dir = crate::supervise::test_scratch_path("wm-writes", tag);
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).expect("dir");
        let ledger = dir.join("s-1.jsonl");
        let before = crate::supervise::limit::unix_now();
        let (m, lines, _, jdir) = memory_run_for(tag, screens, 3, Some("@s-1"), |s| {
            s.set_approval_ledger(Some(ledger.clone()))
        });
        let after = crate::supervise::limit::unix_now();
        let _ = std::fs::remove_dir_all(&jdir);
        let rows = std::fs::read_to_string(&ledger).unwrap_or_default();
        let open = approvals::open_wall(&ledger, Some("@s-1"));
        let _ = std::fs::remove_dir_all(&dir);
        assert_eq!(m.turns, 0, "{lines:#?}\n{:#?}", m.requests);
        (rows, open, before, after)
    };
    let count_rule = |rows: &str, rule: &str| {
        rows.lines()
            .filter(|l| l.contains(&format!("\"rule_id\":\"{rule}\"")))
            .count()
    };
    // The wall, then the scrolled screen: the wall is written, once, with the
    // reset placed a minute from the print, and stands open.
    let (rows, open, before, after) = run(
        "wm-write",
        vec![
            busy_screen(),
            memory_wall_in("60s"),
            memory_scrolled_in("60s"),
        ],
    );
    assert_eq!(count_rule(&rows, approvals::RULE_WALL_WAIT), 1, "{rows}");
    assert_eq!(
        count_rule(&rows, approvals::RULE_WALL_WAIT_END),
        0,
        "{rows}"
    );
    let open = open.expect("an open wall");
    let reset = open.reset_unix.expect("the placed reset");
    assert!(
        reset >= before + 58 && reset <= after + 62,
        "reset {reset} not within [{before}, {after}] + a minute"
    );
    assert!(open.message.contains("weekly limit"), "{}", open.message);
    // A live turn under the wall ends it, and says so.
    let (rows, open, _, _) = run(
        "wm-end",
        vec![
            busy_screen(),
            memory_wall_in("60s"),
            memory_with_a_live_turn_in("60s"),
        ],
    );
    assert_eq!(count_rule(&rows, approvals::RULE_WALL_WAIT), 1, "{rows}");
    assert_eq!(
        count_rule(&rows, approvals::RULE_WALL_WAIT_END),
        1,
        "{rows}"
    );
    assert!(open.is_none(), "{open:?}");
    // NEGATIVE CONTROL: no wall, no rows of a wall's.
    let (rows, open, _, _) = run("wm-none", vec![busy_screen(), memory_scrolled_in("60s")]);
    assert_eq!(count_rule(&rows, approvals::RULE_WALL_WAIT), 0, "{rows}");
    assert_eq!(
        count_rule(&rows, approvals::RULE_WALL_WAIT_END),
        0,
        "{rows}"
    );
    assert!(open.is_none(), "{rows}");
}

/// AN IDLE SCREEN OR A QUESTION ENDS THE MEMORY once the policy has folded it
/// in ([`Session::observe_point`]) and waits on the wall no more: the worker
/// worked since, so the limit is over, and the point is the policy's own (it
/// continues, or asks for a person). The memory must not outlive it, or a
/// LATER screen that shows only background work would be read as the old wall
/// and answered with a spurious `keep going`. NEGATIVE CONTROLS: without the
/// idle screen between, the same scrolled screen IS read as the wall; and an
/// idle screen with no work since (Esc on the vendor's countdown, a person's
/// `/usage`) leaves the policy waiting on the reset the notice named, and the
/// memory with it — the wall it would end is standing still.
#[test]
fn an_idle_screen_or_a_question_ends_the_wall_memory() {
    let mut m = Mock::new(vec![busy_screen()]);
    let mut s = session(&mut m, None);
    s.set_clock(TEST_NOW, PDT);
    s.set_zone_lookup(test_zones);
    let opts = hosted(30);
    let wall = read_screen(memory_wall_in("3h"));
    let scrolled = read_screen(memory_scrolled_in("3h"));
    let quiet = |said: &str| {
        let mut idle = rows(&[
            &format!("⏺ {said}"),
            "",
            "✻ Worked for 3m 2s · done 8:00 PM",
            "",
        ]);
        idle.extend(composer("  ⏵⏵ bypass permissions on (shift+tab to cycle)"));
        read_screen(idle)
    };
    // A point as the loop folds it: read, then into the policy and the memory.
    let fold = |s: &mut Session<'_, Mock>, screen: &Screen, worked: Option<Duration>| {
        let r = s.turn_end_reading(screen, worked, &opts);
        s.observe_point(&r, Instant::now(), screen.seq);
        r
    };
    // CONTROL: the wall, then only its background work: read as the wall.
    let _ = fold(&mut s, &wall, None);
    assert!(s.wall_memory.is_some());
    let r = s.turn_end_reading(&scrolled, None, &opts);
    assert!(
        r.wall.is_some(),
        "the scrolled screen is the remembered wall"
    );
    for said in ["All done.", "Should I rename the module?"] {
        let _ = fold(&mut s, &wall, None);
        assert!(s.wall_memory.is_some(), "{said}");
        let _ = fold(&mut s, &quiet(said), Some(Duration::from_secs(182)));
        assert!(s.wall_memory.is_none(), "{said:?} ends the memory");
        let r = s.turn_end_reading(&scrolled, None, &opts);
        assert!(
            r.wall.is_none(),
            "{said:?}: a stale memory would be read here"
        );
    }
    // CONTROL: no work since the wall — the policy waits on its reset still.
    let _ = fold(&mut s, &wall, None);
    let _ = fold(&mut s, &quiet("All done."), None);
    assert!(s.turn_end.waits_on_named_reset());
    assert!(s.wall_memory.is_some(), "the wall stands: its memory too");
    let r = s.turn_end_reading(&scrolled, None, &opts);
    assert!(r.wall.is_some(), "the scrolled screen is the wall still");
}

/// AGY'S AND MUSE CODE'S OWN BACKGROUND WORK KEEPS THE REMEMBERED WALL, AS
/// CLAUDE CODE'S DOES (the verifier of the background reading: a busy read
/// of that work ended the memory as a live turn would, where Claude Code's
/// scrolled screen over its shell keeps it and reads limited). The loop folds
/// a limit each agent ended a turn on — Muse Code's usage wall, agy's per-day
/// 429 — and then a screen where the notice is gone and only the agent's own
/// work runs (Muse Code's backgrounded shell, agy's task in its panel): the
/// point is the wall still, read limited, and the memory stands, so the wait
/// for its reset goes on. NEGATIVE CONTROLS: with no wall remembered the same
/// screen is busy and wall-less; a live turn over the panel (Muse Code's
/// status row, agy's spinner) ends the memory, and the work's screen after it
/// is busy again.
#[test]
fn agy_and_muse_background_work_keeps_the_remembered_wall() {
    use aterm_phase::agy::fixtures::lab as a;
    use aterm_phase::muse::fixtures as u;
    use aterm_phase::prompt::fixtures::screen;
    for (name, wall, work, live) in [
        (
            "muse",
            u::USAGE_WALL,
            u::END_OF_TURN_BG_RUNNING,
            u::BUSY_WORK_RUNNING,
        ),
        ("agy", a::ERROR_429_LONG, a::BG_TASK, a::BG_BUSY),
    ] {
        let mut m = Mock::new(vec![busy_screen()]);
        let mut s = session(&mut m, None);
        s.set_clock(TEST_NOW, PDT);
        s.set_zone_lookup(test_zones);
        let opts = hosted(30);
        let (wall, work, live) = (
            read_screen(screen(wall)),
            read_screen(screen(work)),
            read_screen(screen(live)),
        );
        let fold = |s: &mut Session<'_, Mock>, screen: &Screen| {
            let r = s.turn_end_reading(screen, None, &opts);
            s.observe_point(&r, Instant::now(), screen.seq);
            r
        };
        // CONTROL: no wall remembered, the work is busy.
        let r = s.turn_end_reading(&work, None, &opts);
        assert_eq!((r.phase.clone(), r.wall), (Phase::Busy, None), "{name}");
        let r = fold(&mut s, &wall);
        assert!(matches!(r.phase, Phase::Limited { .. }), "{name}: {r:#?}");
        assert!(s.wall_memory.is_some(), "{name}");
        let kind = r.wall;
        let r = s.turn_end_reading(&work, None, &opts);
        assert!(matches!(r.phase, Phase::Limited { .. }), "{name}: {r:#?}");
        assert_eq!(r.wall, kind, "{name}: the remembered wall");
        assert!(s.wall_memory.is_some(), "{name}: the memory stands");
        // Read busy, the work is no live turn: it ends nothing.
        let reader = s.reader(&work.rows);
        s.end_memory_on_live_turn(reader, &work.rows, 103);
        assert!(s.wall_memory.is_some(), "{name}: no live turn");
        // CONTROL: a live turn ends it.
        let r = s.turn_end_reading(&live, None, &opts);
        assert_eq!((r.phase.clone(), r.wall), (Phase::Busy, None), "{name}");
        assert!(s.wall_memory.is_none(), "{name}: the live turn ended it");
        let r = s.turn_end_reading(&work, None, &opts);
        assert_eq!((r.phase.clone(), r.wall), (Phase::Busy, None), "{name}");
    }
}

/// TIER-1 FOR THE HIDING HALF OF `SupervisorUsageWall`
/// (`aterm_models_harness::supervisor_usage_wall_model`, dial `Hidden = 1`): the
/// wall's rows leave the screen while the agent's shell keeps the tab reading
/// busy (`WallHides`), and come back (`WallShows`); the loop's memory
/// ([`wall_memory`]) is what keeps the wall a wall meanwhile (`mem`). The
/// integration bind (`tests/supervise_conformance_usage_wall.rs`) drives the
/// reader and the decider with the dial off, since a `Session` is not theirs to
/// reach; this one drives the REAL `Session::turn_end_reading` along every
/// reachable state of the model, replaying the actions that reach it (the
/// wall's appearance and its being met again read the wall's screen, hiding
/// reads the scrolled one, an act taken reads an idle screen after work), and
/// at each state where the wall stands (`wall` 1, or 5 with the wall's rows out
/// of view) the real reading holds a wall exactly where the model enables the
/// act (`wall == 1 || wall == 5 && mem == 1`). NEGATIVE CONTROL: the `Buggy = 1`
/// model's `MemoryLost` (the loop forgets a wall when its rows leave) is not
/// the real code's move — with the real side left as it is, the bind disagrees
/// at the hidden wall the model says is forgotten.
#[test]
fn tier1_the_real_loop_remembers_a_hidden_wall_exactly_where_the_model_does() {
    use aterm_models_harness::supervisor_usage_wall_model;
    use std::collections::{BTreeMap, BTreeSet, VecDeque};
    type State = BTreeMap<&'static str, i64>;
    // The clock's range is shrunk (the memory does not read it); the dial is on.
    // A notice that leaves an idle screen is the decider's to wait out, and
    // bound in `tests/supervise_conformance_usage_wall.rs`: its dial is off;
    // so is the own act's take window (`OwnAct`), the decider's too.
    let hidden_model = aterm_spec::interp::with_consts(
        &supervisor_usage_wall_model(),
        &[
            ("Hidden", 1),
            ("Leaves", 0),
            ("OwnAct", 0),
            ("Cap", 5),
            ("Skew", 3),
        ],
    );
    let idle = || {
        let mut idle = rows(&["⏺ All done.", "", "✻ Worked for 3m 2s · done 8:00 PM", ""]);
        idle.extend(composer("  ⏵⏵ bypass permissions on (shift+tab to cycle)"));
        idle
    };
    // Replays `path` on a fresh loop, then says whether its reading of the
    // screen `st` stands for holds a wall.
    let real_wall = |path: &[&'static str], st: &State| -> bool {
        let mut m = Mock::new(vec![busy_screen()]);
        let mut s = session(&mut m, None);
        s.set_clock(TEST_NOW, PDT);
        s.set_zone_lookup(test_zones);
        let opts = hosted(30);
        // A point as the loop folds it: read, then into the policy and the
        // memory ([`Session::observe_point`]).
        let mut fold = |rows: Vec<String>, worked: Option<Duration>| {
            let screen = read_screen(rows);
            let r = s.turn_end_reading(&screen, worked, &opts);
            s.observe_point(&r, Instant::now(), screen.seq);
        };
        for action in path {
            match *action {
                "WallAppears" | "WallAppearsLate" | "WallShows" | "Met" => {
                    fold(memory_wall_in("3h"), Some(Duration::from_secs(600)));
                }
                // Found standing: read with no turn seen.
                "WallFoundSitting" => fold(memory_wall_in("3h"), None),
                "WallHides" => fold(memory_scrolled_in("3h"), None),
                "Taken" => fold(idle(), Some(Duration::from_secs(600))),
                // The world, the clock and the act: nothing the memory reads.
                // `MemoryLost` is the defect: the real loop makes no such move.
                _ => {}
            }
        }
        let screen = if st["wall"] == 5 {
            memory_scrolled_in("3h")
        } else {
            memory_wall_in("3h")
        };
        s.turn_end_reading(&read_screen(screen), None, &opts)
            .wall
            .is_some()
    };
    let walk = |m: &aterm_spec::derive::Model| {
        let mut seen: BTreeSet<State> = BTreeSet::new();
        let mut queue = VecDeque::from([(m.init_state(), Vec::<&'static str>::new())]);
        let (mut checked, mut hidden_checked, mut disagree) = (0, 0, Vec::new());
        while let Some((st, path)) = queue.pop_front() {
            if !seen.insert(st.clone()) {
                continue;
            }
            if st["wall"] == 1 || st["wall"] == 5 {
                let want = st["wall"] == 1 || st["mem"] == 1;
                let got = real_wall(&path, &st);
                checked += 1;
                hidden_checked += usize::from(st["wall"] == 5);
                if got != want {
                    disagree.push((st.clone(), got, want));
                }
            }
            for action in &m.actions {
                let mut next = st.clone();
                if m.fire(action.name, &mut next) {
                    let mut p = path.clone();
                    p.push(action.name);
                    queue.push_back((next, p));
                }
            }
        }
        (checked, hidden_checked, disagree)
    };
    let (checked, hidden_checked, disagree) = walk(&hidden_model);
    assert!(disagree.is_empty(), "{disagree:#?}");
    assert!(
        checked > 40 && hidden_checked > 10,
        "{checked} {hidden_checked}"
    );
    // NEGATIVE CONTROL.
    let buggy = aterm_spec::interp::with_buggy(&hidden_model, 1);
    let (_, _, off) = walk(&buggy);
    assert!(
        off.iter()
            .any(|(st, got, want)| st["wall"] == 5 && st["mem"] == 0 && *got && !*want),
        "the model that forgets the wall agrees with the real loop: {off:?}"
    );
}

/// ONE PLACEMENT OF A WALL'S RESET. The wait for a weekly wall's reset and the
/// budget stretched past it (`EXTEND`, which keeps a `supervise --max-s` from
/// timing out under the wall) read the same reset: the one the loop placed
/// (`place_reset`, by the wall's kind and its print). An evening weekly wall
/// that says `resets 9am` is tomorrow's 9am, 13 hours off; the session
/// window's rule (`limit::reset_at`: today's, tomorrow's only when it is under
/// five hours off) put it in the PAST for the stretch while the wait held for
/// tomorrow. NEGATIVE CONTROL: a wall no placement was made for falls back on
/// the session rule.
#[test]
fn the_budget_is_stretched_to_the_reset_the_wait_holds_for() {
    let mut m = Mock::new(vec![busy_screen()]);
    let mut s = session(&mut m, None);
    // 2026-09-28 20:00 PDT, the wall printed at 12:19 PM (the done row).
    let now = 1_790_650_800;
    s.set_clock(now, PDT);
    s.set_zone_lookup(test_zones);
    let rows: Vec<String> = memory_wall()
        .into_iter()
        .map(|r| r.replace("resets in 2s", "resets 9am (America/Los_Angeles)"))
        .collect();
    let text = "9am (America/Los_Angeles)";
    // No placement yet: the session rule, in the past.
    assert!(s.reset_unix(Some(text)).is_some_and(|at| at < now));
    let r = s.turn_end_reading(&read_screen(rows), None, &hosted(30));
    let waited = r.reset_at.expect("the wait");
    let unix = s.wall_reset.as_ref().and_then(|(_, u)| *u).expect("placed");
    assert!(
        unix > now + 12 * 3600 && unix < now + 14 * 3600,
        "{}",
        unix - now
    );
    assert!(waited > Instant::now() + Duration::from_secs(12 * 3600));
    assert_eq!(
        s.reset_unix(Some(text)),
        Some(unix),
        "the stretch reads it too"
    );
    // Other words are not the placed wall's.
    assert!(
        s.reset_unix(Some("10am (America/Los_Angeles)"))
            .is_some_and(|at| at < now)
    );
}

/// THE WAIT PLACES A RESET ACROSS A DAYLIGHT-SAVING CHANGE with the offset its
/// zone has where it falls ([`limit::place_reset_with`]), not the one it has
/// when the notice is read: the placement the continuation's wait is built on
/// (`reset_unix_for`), for a bare clock with and without a print to go by,
/// and a dated one. PDT until 2026-11-01 09:00Z, PST after.
#[test]
fn the_wait_places_a_reset_across_a_dst_change_with_the_offset_there() {
    fn la(zone: &str, unix: i64) -> Option<i64> {
        let pst = unix >= 1_793_523_600;
        (zone == "America/Los_Angeles").then_some(if pst { -8 * 3600 } else { PDT })
    }
    let mut m = Mock::new(vec![busy_screen()]);
    let mut s = session(&mut m, None);
    s.set_zone_lookup(la);
    // Read at 23:30 PDT on Oct 31, `3am` is 3am PST, 11:00Z: an hour later than
    // the PDT reading, 10:00Z, that the offset at the read says.
    s.set_clock(1_793_514_600, PDT);
    let three = Some("3am (America/Los_Angeles)");
    assert_eq!(
        s.reset_unix_for(three, false, true, false, &[]),
        Some(1_793_530_800)
    );
    // With a print to go by (`done 11:25 PM`) it is the first 3am after the print.
    let mut printed = rows(&["⏺ Working.", "", "✻ Worked for 3m 2s · done 11:25 PM", ""]);
    printed.extend(composer("  ⏵⏵ bypass permissions on"));
    assert_eq!(
        s.reset_unix_for(three, false, true, false, &printed),
        Some(1_793_530_800)
    );
    // A dated reset, read on Oct 30 at 12:00 PDT.
    s.set_clock(1_793_386_800, PDT);
    let nov_2 = Some("Nov 2 at 9am (America/Los_Angeles)");
    assert_eq!(
        s.reset_unix_for(nov_2, false, true, false, &[]),
        Some(1_793_638_800)
    );
}

/// A host that only listens for the canary's ladder, and answers its jobs
/// reading with `evidence` (`Unknown` by default: no reading), or with `then`
/// once it was told a call that made no progress.
#[derive(Debug, Default)]
struct LadderHost {
    told: std::sync::Mutex<Vec<String>>,
    evidence: crate::supervise::background::BackgroundEvidence,
    then: Option<crate::supervise::background::BackgroundEvidence>,
}

impl IdleHost for LadderHost {
    fn wants(&self) -> bool {
        false
    }
    fn at_idle(&self) -> Option<HostStep> {
        None
    }
    fn owns_turn_end(&self) -> bool {
        false
    }
    fn exception(&self, standing: Option<&crate::supervise::policy::exception::Exception>) {
        self.told.lock().unwrap().push(format!(
            "exception:{}",
            standing.map_or("none", |e| e.kind.word())
        ));
    }
    fn stall_unread(&self, stall: Option<StallSeen>) {
        self.told.lock().unwrap().push(match stall {
            None => "unread:none".to_string(),
            Some(StallSeen::Unread { .. }) => "unread:some".to_string(),
            Some(StallSeen::OwnWork { .. }) => "own-work:some".to_string(),
            Some(StallSeen::NoProgress { minutes, pid }) => {
                format!("no-progress:{pid}:{minutes}")
            }
        });
    }
    fn background_jobs(&self) -> crate::supervise::background::BackgroundEvidence {
        let told = self.told.lock().unwrap();
        match &self.then {
            Some(then) if told.iter().any(|t| t.starts_with("no-progress:")) => then.clone(),
            _ => self.evidence.clone(),
        }
    }
}

/// THE STALL'S END KEEPS THE POINT UNDER IT: the host has
/// one exception slot per tab, so when the raised stall ends while a point's
/// exception still stands, the host is told that point again, not `None`.
/// NEGATIVE CONTROL: with no point standing, the end is `exception:none`.
#[test]
fn a_stall_that_ends_tells_the_host_the_point_that_stood_under_it() {
    use crate::supervise::policy::outlook::ExceptionKind;
    let end = |standing: bool| {
        let host = Arc::new(LadderHost::default());
        let mut m = Mock::new(vec![busy_screen()]);
        let mut s = session(&mut m, None);
        s.stall_host = Some(Arc::clone(&host) as Arc<dyn IdleHost>);
        s.stuck_rung = super::super::wall_memory::StuckRung::Raised;
        s.stuck_raised = Some((Instant::now(), ExceptionKind::Stalled));
        if standing {
            let mut point = crate::supervise::policy::exception::Exception::stalled();
            point.kind = ExceptionKind::Futile;
            s.exception_open = Some((point, Instant::now()));
        }
        s.stuck_over(1, "the screen moved on", &mut Alone);
        host.told.lock().unwrap().clone()
    };
    assert_eq!(
        end(true),
        ["unread:none", "exception:futile"],
        "the point that stood under the stall is told again"
    );
    assert_eq!(end(false), ["unread:none", "exception:none"]);
}

/// THE CANARY FOR A SCREEN NO READER NAMES AND THE
/// LADDER ABOVE IT (design-exceptions 9.3). A screen that reads busy on the
/// agent's own background work alone, while the agent's OWN terminal title
/// rests on the idle glyph (`✳`; a working agent animates it), is one this
/// build does not read. Kept up:
/// `STUCK` (rung 1, the journal), `STALLED` and the host's record (rung 2,
/// three times as long), `EXCEPTION kind=stalled` and the host's exception (rung
/// 3, six times), each ONCE, and the loop's end withdraws both (`CLEARED
/// exception=stalled`, `unread:none`, `exception:none`). Nothing is typed. The
/// title is asked again at each rung: NEGATIVE CONTROLS, a title that animates,
/// a live spinner on the screen and a screen that shows no title climb no rung.
#[test]
fn a_stall_kept_up_climbs_to_a_record_and_then_an_exception_and_its_end_withdraws_both() {
    let scrolled = memory_scrolled();
    let run = |title: Option<&str>, screen: Vec<String>| {
        let (dir, path) = journal_file("stuck-ladder");
        let host = Arc::new(LadderHost::default());
        let mut m = Mock::new(vec![busy_screen(), screen]);
        m.title = title.map(str::to_string);
        m.vanish_after = Some(14);
        m.stall_sleep = Some(Duration::from_millis(25));
        let opts = SuperviseOpts {
            journal: Some(path.clone()),
            idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
            ..hosted(60)
        };
        // The unit is 30 ms: the rungs fall at 30, 90 and 180 ms at the
        // earliest, inside the run's 14 waits of at least 25 ms each; the run
        // ends on the mock's count of waits, never on a clock.
        let (lines, _) = watch_lines_with(&mut m, &opts, |s| {
            s.setup.stuck_after = Duration::from_millis(30);
        });
        let (records, _) = journal_records(&path);
        let _ = std::fs::remove_dir_all(&dir);
        let kind = |k: &str| -> Vec<String> {
            records
                .iter()
                .filter(|r| r.line.starts_with(k))
                .map(|r| r.line.clone())
                .collect()
        };
        (
            kind("STUCK"),
            kind("STALLED"),
            kind("EXCEPTION"),
            kind("CLEARED"),
            host.told.lock().unwrap().clone(),
            count(&m, "turn"),
            lines,
        )
    };
    let (stuck, stalled, exception, cleared, told, turns, lines) =
        run(Some("✳ Claude Code"), scrolled.clone());
    assert_eq!(stuck.len(), 1, "rung 1 once: {stuck:#?}\n{lines:#?}");
    assert_eq!(stalled.len(), 1, "rung 2 once: {stalled:#?}\n{lines:#?}");
    assert_eq!(
        exception.len(),
        1,
        "rung 3 once: {exception:#?}\n{lines:#?}"
    );
    assert!(
        exception[0].contains("kind=stalled when=later"),
        "{}",
        exception[0]
    );
    assert!(
        cleared
            .iter()
            .any(|l| l.contains("exception=stalled after=") && l.ends_with("the loop ended")),
        "{cleared:#?}"
    );
    assert_eq!(
        told,
        [
            "unread:some",
            "exception:stalled",
            "unread:none",
            "exception:none"
        ],
        "the host hears each rung once, and its end"
    );
    assert_eq!(turns, 0, "the ladder types nothing");
    // CONTROLS.
    for (name, title, screen) in [
        ("an animated title", Some("◐ Claude Code"), scrolled.clone()),
        (
            "a live spinner",
            Some("✳ Claude Code"),
            memory_with_a_live_turn(),
        ),
        ("no title", None, scrolled),
    ] {
        let (stuck, stalled, exception, _, told, _, lines) = run(title, screen);
        assert!(
            stuck.is_empty() && stalled.is_empty() && exception.is_empty() && told.is_empty(),
            "{name} climbs nothing: {stuck:#?} {stalled:#?} {told:#?}\n{lines:#?}"
        );
    }
}

/// THE CANARY NAMES A BACKGROUND CALL THAT MAKES NO PROGRESS (the hung-call
/// design's R1; system awareness §14.5). The stall of
/// `a_stall_kept_up_climbs_to_a_record_and_then_an_exception_and_its_end_withdraws_both`
/// — the screen busy on background work alone under Claude's resting title —
/// but the host's jobs reading names a call of the agent's own at no progress
/// (I4: a background `targo test` asleep on a mutex its own thread held, for
/// 26 h, while three EXCEPTIONs said "nothing here explains it"). The ladder
/// climbs as the design's `AllStuck` does: `STALLED` at once, with no `STUCK`
/// before it, naming the call's task id, pid, exe word, quiet age and its
/// unnamed wait; the host's record told it with the pid and age
/// (`StallSeen::NoProgress`); the `EXCEPTION` one unit later, its why the
/// same fact; each once, nothing typed, and the loop's end withdraws both.
/// A different call that becomes the worst after `STALLED` (the first ended,
/// another reads no progress) is named at `STALLED` in its turn, and the
/// exception names it a unit later: never a call no `STALLED` named.
/// NEGATIVE CONTROL: the very host answering `Unknown` climbs today's ladder
/// (`STUCK`, `STALLED`, `EXCEPTION`, the host's unread record), naming no
/// call. The run ends on the mock's count of waits, never on a clock.
#[test]
fn a_background_call_that_makes_no_progress_is_named_at_stalled_and_in_the_exception() {
    use crate::supervise::background::{BackgroundCall, BackgroundEvidence};
    let run = |evidence: BackgroundEvidence, then: Option<BackgroundEvidence>| {
        let (dir, path) = journal_file("stuck-kernel");
        let host = Arc::new(LadderHost {
            evidence,
            then,
            ..LadderHost::default()
        });
        let mut m = Mock::new(vec![busy_screen(), memory_scrolled()]);
        m.title = Some("✳ Claude Code".to_string());
        m.vanish_after = Some(14);
        m.stall_sleep = Some(Duration::from_millis(25));
        let opts = SuperviseOpts {
            journal: Some(path.clone()),
            idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
            ..hosted(60)
        };
        // The kernel is asked once the break has stood its settle: 30 ms
        // here, the ladder's unit.
        let (lines, _) = watch_lines_with(&mut m, &opts, |s| {
            s.setup.stuck_after = Duration::from_millis(30);
            s.setup.background_settle = Duration::from_millis(30);
        });
        let (records, _) = journal_records(&path);
        let _ = std::fs::remove_dir_all(&dir);
        let kind = |k: &str| -> Vec<String> {
            records
                .iter()
                .filter(|r| r.line.starts_with(k))
                .map(|r| r.line.clone())
                .collect()
        };
        (
            kind("STUCK"),
            kind("STALLED"),
            kind("EXCEPTION"),
            host.told.lock().unwrap().clone(),
            count(&m, "turn"),
            lines,
        )
    };
    let hung = BackgroundEvidence::NoProgress {
        worst: BackgroundCall {
            pid: 27098,
            pgid: 27090,
            exe: "aterm_gui-e0964a".to_string(),
            task: Some("bplle5dxj".to_string()),
            quiet_ms: 31 * 60_000 + 59_000,
            wait: None,
        },
    };
    let (stuck, stalled, exception, told, turns, lines) = run(hung.clone(), None);
    assert!(
        stuck.is_empty(),
        "the kernel explains the screen: no first rung: {stuck:#?}\n{lines:#?}"
    );
    assert_eq!(stalled.len(), 1, "rung 2 once: {stalled:#?}\n{lines:#?}");
    for said in ["bplle5dxj", "pid 27098", "31 min"] {
        assert!(stalled[0].contains(said), "{said:?} in {}", stalled[0]);
    }
    assert_eq!(
        exception.len(),
        1,
        "rung 3 once: {exception:#?}\n{lines:#?}"
    );
    assert!(
        exception[0].contains("kind=stalled when=later")
            && exception[0].contains("pid 27098")
            && exception[0].contains("31 min"),
        "{}",
        exception[0]
    );
    assert_eq!(
        told,
        [
            "no-progress:27098:31",
            "exception:stalled",
            "unread:none",
            "exception:none"
        ],
        "the host hears the call at rung 2, the exception at rung 3, and their end"
    );
    assert_eq!(turns, 0, "the ladder types nothing");
    // The first call ends and another becomes the worst after `STALLED`:
    // it is named in its turn, and the exception names it.
    let other = BackgroundEvidence::NoProgress {
        worst: BackgroundCall {
            pid: 31000,
            pgid: 31000,
            exe: "sleep".to_string(),
            task: None,
            quiet_ms: 20 * 60_000,
            wait: None,
        },
    };
    let (stuck, stalled, exception, told, _, lines) = run(hung, Some(other));
    assert!(stuck.is_empty(), "{stuck:#?}\n{lines:#?}");
    assert_eq!(
        (stalled.len(), exception.len()),
        (2, 1),
        "{stalled:#?} {exception:#?}\n{lines:#?}"
    );
    assert!(
        stalled[0].contains("pid 27098") && stalled[1].contains("pid 31000"),
        "{stalled:#?}"
    );
    assert!(exception[0].contains("pid 31000"), "{}", exception[0]);
    assert_eq!(
        told,
        [
            "no-progress:27098:31",
            "no-progress:31000:20",
            "exception:stalled",
            "unread:none",
            "exception:none"
        ],
        "the second call's record, then its exception"
    );
    // NEGATIVE CONTROL: no reading is today's ladder, naming no call.
    let (stuck, stalled, exception, told, _, lines) = run(BackgroundEvidence::Unknown, None);
    assert_eq!(
        (stuck.len(), stalled.len(), exception.len()),
        (1, 1, 1),
        "{stuck:#?} {stalled:#?} {exception:#?}\n{lines:#?}"
    );
    assert!(
        stalled
            .iter()
            .chain(&exception)
            .all(|l| !l.contains("pid 27098")),
        "{stalled:#?} {exception:#?}"
    );
    assert_eq!(
        told,
        [
            "unread:some",
            "exception:stalled",
            "unread:none",
            "exception:none"
        ]
    );
}

/// THE CANARY ON AGY'S AND MUSE CODE'S OWN BACKGROUND WORK THAT NEVER ENDS
/// (the review of the hard rule: their readers hold an ended turn, and a
/// question it ended on over a task or a shell, busy while that work runs,
/// and the canary climbed on Claude Code's screen alone, so a backgrounded
/// server held the question for ever with nothing typed and nothing said).
/// The turn ends asking `Should I deploy it now?` over agy's command task
/// and over Muse Code's backgrounded shell, or plainly over Muse Code's
/// shell, and the work never ends: `STUCK` naming the work, `STALLED` and
/// the host's record (both in the work's words, `StallSeen::OwnWork`: no
/// title was read and no screen went unread), `EXCEPTION kind=stalled` (the
/// work's own words) and the host's exception, each ONCE, and the loop's end
/// withdraws both.
/// Nothing is typed. The tab reports no title: theirs is unmeasured, and
/// their words standing still are the witness. The rungs' times are lower
/// bounds and the run ends on the mock's count of waits, never on a clock.
/// NEGATIVE CONTROLS: a live turn over the same panel (agy's spinner, Muse
/// Code's status row) climbs nothing; words that move are
/// `the_canarys_words_on_agy_or_muse_must_stand_still`'s.
#[test]
fn agy_or_muse_background_work_that_never_ends_climbs_the_canary() {
    use aterm_phase::agy::fixtures::lab as a;
    use aterm_phase::muse::fixtures as u;
    use aterm_phase::prompt::fixtures::screen;
    let asks = |rows: Vec<String>, head: &str, with: &str, blank_next: bool| {
        let mut rows = rows;
        let at = rows
            .iter()
            .rposition(|r| r.starts_with(head))
            .unwrap_or_else(|| panic!("a row starting {head:?}"));
        rows[at] = with.to_string();
        if blank_next {
            rows[at + 1] = String::new();
        }
        rows
    };
    let agy_asks = asks(
        screen(a::BG_TASK),
        "  Tool call done.",
        "  Should I deploy it now?",
        false,
    );
    let muse_asks = asks(
        screen(u::END_OF_TURN_BG_RUNNING),
        "◆ Tool call done.",
        "◆ Should I deploy it now?",
        true,
    );
    let run = |program: &str, busy: Vec<String>, work: Vec<String>| {
        let (dir, path) = journal_file("work-ladder");
        let host = Arc::new(LadderHost::default());
        let screens = vec![busy, work];
        let mut m = if program == "agy" {
            agy_mock(screens)
        } else {
            muse_mock(screens)
        };
        m.title = None;
        m.vanish_after = Some(14);
        m.stall_sleep = Some(Duration::from_millis(25));
        let opts = SuperviseOpts {
            journal: Some(path.clone()),
            idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
            ..hosted(60)
        };
        // The unit is 30 ms: the rungs fall at 30, 90 and 180 ms at the
        // earliest, inside the run's 14 waits of at least 25 ms each.
        let (lines, _) = watch_lines_with(&mut m, &opts, |s| {
            s.setup.stuck_after = Duration::from_millis(30);
        });
        let (records, _) = journal_records(&path);
        let _ = std::fs::remove_dir_all(&dir);
        let kind = |k: &str| -> Vec<String> {
            records
                .iter()
                .filter(|r| r.line.starts_with(k))
                .map(|r| r.line.clone())
                .collect()
        };
        let typed = m
            .requests
            .iter()
            .any(|r| r.starts_with("turn ") || r.starts_with("send ") || r.starts_with("key "));
        (
            [
                kind("STUCK"),
                kind("STALLED"),
                kind("EXCEPTION"),
                kind("CLEARED"),
            ],
            host.told.lock().unwrap().clone(),
            typed,
            lines,
        )
    };
    for (name, program, busy, work, what) in [
        (
            "agy's question over its task",
            "agy",
            screen(a::BUSY_THINKING),
            agy_asks,
            "a background task running",
        ),
        (
            "Muse Code's question over its shell",
            "muse",
            screen(u::BUSY_1_4_10),
            muse_asks,
            "background work running",
        ),
        (
            "Muse Code's plain end over its shell",
            "muse",
            screen(u::BUSY_1_4_10),
            screen(u::END_OF_TURN_BG_RUNNING),
            "background work running",
        ),
    ] {
        let ([stuck, stalled, exception, cleared], told, typed, lines) = run(program, busy, work);
        assert_eq!(
            stuck.len(),
            1,
            "{name}: rung 1 once: {stuck:#?}\n{lines:#?}"
        );
        assert!(stuck[0].contains(what), "{name}: {}", stuck[0]);
        assert_eq!(stalled.len(), 1, "{name}: rung 2 once: {stalled:#?}");
        assert!(
            stalled[0].contains("background work of the agent's own that has not ended"),
            "{name}: the work's words, no wait unclassified: {}",
            stalled[0]
        );
        assert_eq!(exception.len(), 1, "{name}: rung 3 once: {exception:#?}");
        assert!(
            exception[0].contains("kind=stalled when=later")
                && exception[0].contains("its own background work still runs"),
            "{name}: {}",
            exception[0]
        );
        assert!(
            cleared
                .iter()
                .any(|l| l.contains("exception=stalled after=") && l.ends_with("the loop ended")),
            "{name}: {cleared:#?}"
        );
        // The record is the work's, not an unread screen's: no title was
        // read, and the reader names the work.
        assert_eq!(
            told,
            [
                "own-work:some",
                "exception:stalled",
                "unread:none",
                "exception:none"
            ],
            "{name}: the host hears each rung once, and its end"
        );
        assert!(!typed, "{name}: the ladder types nothing\n{lines:#?}");
    }
    // CONTROLS: a live turn over the panel is no background work alone.
    for (name, program, busy, live) in [
        (
            "agy's spinner over its task",
            "agy",
            screen(a::BUSY_THINKING),
            screen(a::BG_BUSY),
        ),
        (
            "Muse Code's status row over its shell",
            "muse",
            screen(u::BUSY_1_4_10),
            screen(u::BUSY_WORK_RUNNING),
        ),
    ] {
        let ([stuck, stalled, exception, _], told, _, lines) = run(program, busy, live);
        assert!(
            stuck.is_empty() && stalled.is_empty() && exception.is_empty() && told.is_empty(),
            "{name} climbs nothing: {stuck:#?} {stalled:#?} {told:#?}\n{lines:#?}"
        );
    }
}

/// THE CANARY'S WORDS ON AGY AND MUSE CODE MUST STAND STILL: their title is
/// unmeasured, so what vouches that the agent does not work through the
/// unit is that the work named, the words above the composer and the draft
/// have not moved. Driven on a virtual clock, a unit apart: the same screen
/// read again climbs `STUCK` at the unit; a turn of the agent's own between
/// two reads (its reply another) starts the episode afresh, so the next
/// rung waits a whole unit from it; a clock's digits in the panel are no
/// change, and other work named there (a monitor in the shell's place) is
/// one. NEGATIVE CONTROLS: Codex's screen, whose reader names no
/// background work, never climbs, and the episode's end (a screen with the
/// work over) clears the words.
#[test]
fn the_canarys_words_on_agy_or_muse_must_stand_still() {
    use crate::supervise::fx::{ClockSource, Fx, VirtualClock};
    use aterm_phase::muse::fixtures as u;
    use aterm_phase::prompt::fixtures::screen;
    let unit = Duration::from_secs(30 * 60);
    let mut m = Mock::new(vec![busy_screen()]);
    m.program = "muse";
    let mut s = session(&mut m, None);
    s.program = Some("muse".to_string());
    s.set_fx(Fx::over(ClockSource::Virtual(Arc::new(VirtualClock::new(
        Instant::now(),
        1_790_000_000_000,
    )))));
    s.setup.stuck_after = unit;
    let read = |rows: Vec<String>| Screen {
        rows,
        ..Screen::default()
    };
    let work = screen(u::END_OF_TURN_BG_RUNNING);
    let reply_row = work
        .iter()
        .rposition(|r| r.starts_with("◆ Tool call done."))
        .expect("the reply");
    let mut other = work.clone();
    other[reply_row] = "◆ Started the server on port 3000.".to_string();
    other[reply_row + 1] = String::new();
    let branch = work
        .iter()
        .rposition(|r| r.starts_with("└ "))
        .expect("the branch");
    let mut ticked = work.clone();
    ticked[branch] = ticked[branch].replace("  2s", " 41m");
    assert_ne!(ticked, work, "the panel's clock ticked");
    let mut heard = Heard::default();
    let since = Some(s.fx.mono());
    let stuck = |heard: &Heard| {
        heard
            .noted
            .iter()
            .filter(|l| l.starts_with("STUCK"))
            .count()
    };
    s.stuck_busy_note(&read(work.clone()), since, &mut heard);
    assert!(s.stuck_still.is_some(), "the words start a clock");
    s.fx.sleep(unit / 2);
    // A turn of the agent's own between two reads: its words moved.
    s.stuck_busy_note(&read(other.clone()), since, &mut heard);
    s.fx.sleep(unit / 2 + Duration::from_secs(1));
    s.stuck_busy_note(&read(other.clone()), since, &mut heard);
    assert_eq!(
        stuck(&heard),
        0,
        "a unit from the words' move, not the episode's start"
    );
    s.fx.sleep(unit / 2);
    s.stuck_busy_note(&read(other.clone()), since, &mut heard);
    assert_eq!(
        stuck(&heard),
        1,
        "a unit of words that stood still: {:?}",
        heard.noted
    );
    assert!(
        heard.noted[0].contains("(background work running)"),
        "{:?}",
        heard.noted
    );
    // A clock in the panel is no move of the words.
    let mut ticking = other.clone();
    ticking[branch] = ticked[branch].clone();
    let held = s.stuck_still.clone();
    s.stuck_busy_note(&read(ticking), since, &mut heard);
    assert_eq!(
        s.stuck_still, held,
        "the panel's clock keeps the words' clock"
    );
    assert_eq!(
        s.stuck_rung,
        super::super::wall_memory::StuckRung::Said,
        "the ladder stands"
    );
    // Other work named, the rows above the composer as they were (a monitor
    // in the shell's place, under the bottom rule): the words moved, and the
    // ladder starts over.
    let mut monitor = other.clone();
    monitor[branch] = "└ ◇ Watch the lab socket  watching  14s".to_string();
    assert_eq!(
        s.reader(&monitor).background_wait(&monitor),
        Some("a monitor watching")
    );
    s.stuck_busy_note(&read(monitor), since, &mut heard);
    let words = |still: &Option<(String, Instant)>| still.as_ref().map(|(w, _)| w.clone());
    assert_ne!(
        words(&s.stuck_still),
        words(&held),
        "the work named is part of the words"
    );
    assert_eq!(
        s.stuck_rung,
        super::super::wall_memory::StuckRung::Quiet,
        "the ladder starts over"
    );
    // The work over: the episode ends, the words with it.
    let mut over = other.clone();
    over[branch] = format!(
        "└ ◆ Q3 background wait  ran 1s, exit 0{}1m 40s",
        " ".repeat(100)
    );
    s.stuck_busy_note(&read(over), since, &mut heard);
    assert_eq!(s.stuck_still, None);
    assert_eq!(s.stuck_rung, super::super::wall_memory::StuckRung::Quiet);
    // Codex names no background work of its own: nothing climbs.
    s.program = Some("codex".to_string());
    let mut codex = Heard::default();
    s.stuck_busy_note(&read(work.clone()), since, &mut codex);
    s.fx.sleep(unit * 7);
    s.stuck_busy_note(&read(work), since, &mut codex);
    assert!(codex.noted.is_empty(), "{:?}", codex.noted);
    assert_eq!(s.stuck_still, None);
}

/// THE CANARY'S WORDS MOVING AFTER ITS EXCEPTION END IT (the review of
/// 6b820169e8: nothing tested a move once a rung was reached). On a virtual
/// clock, Muse Code's turn ends over its backgrounded shell and the screen
/// is read a unit, three and six units on: `STUCK`, then `STALLED` in the
/// work's words with the host's record of the work (no wait unclassified,
/// no title read), then `EXCEPTION kind=stalled` with the host's exception.
/// Then a draft is typed into the composer and nothing else on the screen
/// moves: the exception CLEARS (`the agent's words moved`), the host is told
/// the record and the exception are over, the ladder is quiet, and it climbs
/// again only a whole unit from the move. NEGATIVE CONTROL: the drafted
/// screen read a second short of that unit says nothing.
#[test]
fn the_canarys_words_moving_after_its_exception_clear_it() {
    use super::super::wall_memory::StuckRung;
    use crate::supervise::fx::{ClockSource, Fx, VirtualClock};
    use aterm_phase::muse::fixtures as u;
    use aterm_phase::prompt::fixtures::screen;
    let unit = Duration::from_secs(30 * 60);
    let host = Arc::new(LadderHost::default());
    let mut m = Mock::new(vec![busy_screen()]);
    m.program = "muse";
    let mut s = session(&mut m, None);
    s.program = Some("muse".to_string());
    s.stall_host = Some(Arc::clone(&host) as Arc<dyn IdleHost>);
    s.set_fx(Fx::over(ClockSource::Virtual(Arc::new(VirtualClock::new(
        Instant::now(),
        1_790_000_000_000,
    )))));
    s.setup.stuck_after = unit;
    let read = |rows: Vec<String>| Screen {
        rows,
        ..Screen::default()
    };
    let work = screen(u::END_OF_TURN_BG_RUNNING);
    let caret = work
        .iter()
        .rposition(|r| r.trim_end() == "❯")
        .expect("the empty caret row");
    let mut drafted = work.clone();
    drafted[caret] = "❯ deploy it now".to_string();
    assert_eq!(
        s.reader(&drafted).composer(&drafted).map(|(_, d)| d),
        Some(vec!["deploy it now".to_string()]),
        "the draft is read"
    );
    assert_eq!(
        s.reader(&drafted).background_wait(&drafted),
        Some("background work running"),
        "the work still runs under the draft"
    );
    let lines = |heard: &Heard, head: &str| -> Vec<String> {
        heard
            .noted
            .iter()
            .filter(|l| l.starts_with(head))
            .cloned()
            .collect()
    };
    let mut heard = Heard::default();
    let since = Some(s.fx.mono());
    s.stuck_busy_note(&read(work.clone()), since, &mut heard);
    for (after, rung) in [
        (unit, StuckRung::Said),
        (unit * 2, StuckRung::Told),
        (unit * 3, StuckRung::Raised),
    ] {
        s.fx.sleep(after);
        s.stuck_busy_note(&read(work.clone()), since, &mut heard);
        assert_eq!(s.stuck_rung, rung, "{:#?}", heard.noted);
    }
    let stalled = lines(&heard, "STALLED");
    assert_eq!(stalled.len(), 1, "{:#?}", heard.noted);
    assert!(
        stalled[0].contains("background work of the agent's own that has not ended")
            && !stalled[0].contains("does not classify"),
        "the work's words: {}",
        stalled[0]
    );
    let exception = lines(&heard, "EXCEPTION");
    assert!(
        exception.len() == 1
            && exception[0].contains("kind=stalled when=later")
            && exception[0].contains("its own background work still runs"),
        "{exception:#?}"
    );
    assert_eq!(
        *host.told.lock().unwrap(),
        ["own-work:some", "exception:stalled"],
        "the record is the work's"
    );
    // A draft typed: the words moved, and what the ladder raised ends.
    s.fx.sleep(Duration::from_secs(60));
    s.stuck_busy_note(&read(drafted.clone()), since, &mut heard);
    let cleared = lines(&heard, "CLEARED");
    assert!(
        cleared.len() == 1
            && cleared[0].contains("exception=stalled after=60s")
            && cleared[0].ends_with("the agent's words moved"),
        "{cleared:#?}"
    );
    assert_eq!(
        *host.told.lock().unwrap(),
        [
            "own-work:some",
            "exception:stalled",
            "unread:none",
            "exception:none"
        ],
        "the host hears the record and the exception end"
    );
    assert_eq!(s.stuck_rung, StuckRung::Quiet);
    // The ladder climbs again from the move, a whole unit on.
    s.fx.sleep(unit - Duration::from_secs(1));
    s.stuck_busy_note(&read(drafted.clone()), since, &mut heard);
    assert_eq!(lines(&heard, "STUCK").len(), 1, "short of the unit");
    assert_eq!(s.stuck_rung, StuckRung::Quiet);
    s.fx.sleep(Duration::from_secs(1));
    s.stuck_busy_note(&read(drafted), since, &mut heard);
    assert_eq!(
        lines(&heard, "STUCK").len(),
        2,
        "a unit from the move: {:#?}",
        heard.noted
    );
    assert_eq!(s.stuck_rung, StuckRung::Said);
}

/// THE CANARY'S SECOND FLAVOUR: A DIALOG NO READER NAMES (measured 2026-10-06
/// on Claude Code 2.1.292: the classifier-billing notice, `Enter to continue ·
/// Esc to cancel`, no options, no composer — silent for as long as it stood).
/// The screen reads `idle` with no evidence, its words stand still, and the
/// agent's own title rests: `STUCK` (rung 1) with the rows that teach a reader,
/// `STALLED` and the host's record (rung 2), `EXCEPTION kind=dialog` and the
/// host's exception (rung 3), each ONCE, from the clock the first sight starts
/// (a third of the busy flavour's), and the loop's end withdraws both. The
/// rungs' times are lower bounds and the run ends on the mock's count of
/// waits, never on a clock. Nothing is typed. Run twice: a screen that holds still
/// (the wait's step reaches the clock) and one that never does (a footer that
/// ticks: the read of the wait for the turn reaches it, the wait never does).
/// NEGATIVE CONTROLS: a title that animates, the same words over an idle
/// composer, and a tab whose program is a shell under a stale title say
/// nothing. The words stand still through a ticking countdown and a blinked
/// glyph, and move for a sentence added: `seq` alone is no change.
#[test]
fn a_dialog_no_reader_names_climbs_to_a_record_and_a_line_and_its_end_withdraws_both() {
    // The notice as Claude Code 2.1.292 drew it, measured: no composer frame
    // (one rule over four paragraphs and the footer), the pending tool row above.
    let notice = crate::supervise::prompt::fixtures::screen(
        crate::supervise::prompt::fixtures::AUTO_CLASSIFIER_BILLING_NOTICE_MEASURED,
    );
    let run = |title: &str, program: &'static str, screen: Vec<String>, never_still: bool| {
        let (dir, path) = journal_file("dialog-ladder");
        let host = Arc::new(LadderHost::default());
        let mut m = Mock::new(vec![busy_screen(), screen]);
        m.title = Some(title.to_string());
        m.program = program;
        m.vanish_after = Some(14);
        m.stall_sleep = Some(Duration::from_millis(25));
        m.idle_never = never_still;
        let opts = SuperviseOpts {
            journal: Some(path.clone()),
            idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
            ..hosted(60)
        };
        // The unit is 30 ms: the rungs fall at 30, 90 and 180 ms at the earliest.
        let (lines, _) = watch_lines_with(&mut m, &opts, |s| {
            s.setup.stuck_after = Duration::from_millis(90);
        });
        let (records, _) = journal_records(&path);
        let _ = std::fs::remove_dir_all(&dir);
        let kind = |k: &str| -> Vec<String> {
            records
                .iter()
                .filter(|r| r.line.starts_with(k))
                .map(|r| r.line.clone())
                .collect()
        };
        (
            kind("STUCK"),
            kind("STALLED"),
            kind("EXCEPTION"),
            kind("CLEARED"),
            host.told.lock().unwrap().clone(),
            count(&m, "turn"),
            lines,
        )
    };
    for never_still in [false, true] {
        let (stuck, stalled, exception, cleared, told, turns, lines) =
            run("✳ Claude Code", "claude", notice.clone(), never_still);
        let said = format!("never_still={never_still}\n{lines:#?}");
        assert_eq!(stuck.len(), 1, "rung 1 once: {stuck:#?}\n{said}");
        assert!(
            stuck[0].ends_with("Enter to continue · Esc to cancel"),
            "the rows that teach a reader: {}",
            stuck[0]
        );
        assert_eq!(stalled.len(), 1, "rung 2 once: {stalled:#?}\n{said}");
        assert_eq!(exception.len(), 1, "rung 3 once: {exception:#?}\n{said}");
        assert!(
            exception[0].contains("kind=dialog when=later"),
            "{}",
            exception[0]
        );
        assert!(
            cleared
                .iter()
                .any(|l| l.contains("exception=dialog after=") && l.ends_with("the loop ended")),
            "{cleared:#?}"
        );
        assert_eq!(
            told,
            [
                "unread:some",
                "exception:dialog",
                "unread:none",
                "exception:none"
            ],
            "the host hears each rung once, and its end\n{said}"
        );
        assert_eq!(turns, 0, "the canary types nothing");
    }
    // CONTROLS.
    for (name, title, program, over_a_composer) in [
        ("an animated title", "◐ Claude Code", "claude", false),
        ("an idle composer", "✳ Claude Code", "claude", true),
        ("a shell under a stale title", "✳ Claude Code", "zsh", false),
    ] {
        let mut screen = notice.clone();
        if over_a_composer {
            screen.extend(composer("  ? for shortcuts"));
        }
        let (stuck, stalled, exception, _, told, _, lines) = run(title, program, screen, false);
        assert!(
            stuck.is_empty() && stalled.is_empty() && exception.is_empty() && told.is_empty(),
            "{name}: {stuck:#?} {stalled:#?} {exception:#?} {told:#?}\n{lines:#?}"
        );
    }
    // THE WORDS: what stands still is the words, never the seq, a countdown or a
    // glyph, and the clock they keep follows them.
    let mut m = Mock::new(vec![busy_screen()]);
    let mut s = session(&mut m, None);
    let screen = |rows: Vec<String>| Screen {
        rows,
        ..Screen::default()
    };
    let at = |rows: &[String], what: &str| {
        rows.iter()
            .position(|r| r.contains(what))
            .unwrap_or_else(|| panic!("{what}"))
    };
    let shown = |glyph: &str, secs: &str| {
        let mut r = notice.clone();
        let (tool, line) = (at(&r, "⏺ Bash"), at(&r, "Nothing breaks"));
        r[tool] = r[tool].replacen('⏺', glyph, 1);
        r[line].push_str(&format!(" ({secs}s)"));
        r
    };
    let mut longer = notice.clone();
    longer.insert(
        at(&notice, "Enter to continue"),
        "One more thing: it needs a login.".to_string(),
    );
    let still = s.dialog_words(&screen(shown("⏺", "12")));
    assert!(still.is_some(), "the notice has words");
    assert_eq!(still, s.dialog_words(&screen(shown("·", "13"))));
    assert_ne!(still, s.dialog_words(&screen(longer.clone())));
    assert_eq!(s.dialog_words(&screen(idle_screen())), None);
    assert_eq!(s.dialog_words(&screen(busy_screen())), None);
    let mut heard = Heard::default();
    s.stuck_rung = super::super::wall_memory::StuckRung::Said;
    s.dialog_note(&screen(shown("⏺", "12")), &mut heard);
    let began = s.stuck_dialog.clone().expect("the notice starts a clock");
    assert_eq!(
        s.stuck_rung,
        super::super::wall_memory::StuckRung::Quiet,
        "what the busy flavour's ladder held ends at a dialog's first sight"
    );
    std::thread::sleep(Duration::from_millis(2));
    s.dialog_note(&screen(shown("·", "13")), &mut heard);
    assert_eq!(
        s.stuck_dialog,
        Some(began.clone()),
        "a tick keeps the clock"
    );
    s.dialog_note(&screen(longer), &mut heard);
    assert!(
        s.stuck_dialog.as_ref().is_some_and(|(_, at)| *at > began.1),
        "other words start it afresh"
    );
    s.stuck_busy_note(&screen(memory_scrolled()), Some(Instant::now()), &mut heard);
    assert_eq!(
        s.stuck_dialog, None,
        "a busy read ends it, background work alone too"
    );
    s.dialog_note(&screen(shown("⏺", "12")), &mut heard);
    s.dialog_note(&screen(idle_screen()), &mut heard);
    assert_eq!(s.stuck_dialog, None, "a screen with no words ends it");
    assert!(
        heard.said.is_empty() && heard.noted.is_empty(),
        "{:?}",
        heard.noted
    );
}

/// A host whose probe of the session's repository answers from a script
/// ([`IdleHost::repo_work`]): each ask takes the next answer, the last one
/// standing; how often it was asked is counted.
#[derive(Debug)]
struct RepoHost {
    found: std::sync::Mutex<VecDeque<Option<RepoWork>>>,
    asked: std::sync::atomic::AtomicUsize,
}

impl RepoHost {
    fn new(found: Vec<Option<RepoWork>>) -> Self {
        Self {
            found: std::sync::Mutex::new(found.into()),
            asked: std::sync::atomic::AtomicUsize::new(0),
        }
    }
}

impl IdleHost for RepoHost {
    fn wants(&self) -> bool {
        false
    }
    fn at_idle(&self) -> Option<HostStep> {
        None
    }
    fn owns_turn_end(&self) -> bool {
        false
    }
    fn repo_work(&self) -> Option<RepoWork> {
        self.asked.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
        let mut found = self.found.lock().unwrap_or_else(PoisonError::into_inner);
        if found.len() > 1 {
            found.pop_front().flatten()
        } else {
            found.front().cloned().flatten()
        }
    }
}

/// A DONE CLAIM OVER WORK NO REMOTE MAIN HAS through the real supervisor and
/// its host (FOREVER CRUISE, the repository's suffix): a done report while
/// the host's probe of the session's repository finds an uncommitted file
/// gets the done check with [`repo_work_suffix`] after it — naming the
/// repository, its counts and the path — and no `DONE`. The probe is asked
/// only where the worker's words say done. NEGATIVE CONTROLS: the same
/// report over a clean repository gets the plain check, and no `DONE`
/// either; progress words over a dirty repository never ask the probe and
/// are continued.
#[test]
fn a_claim_over_uncommitted_work_gets_the_repo_suffix_through_the_loop() {
    let report = |lines: &[&str]| {
        let mut r = vec![format!("⏺ {}", lines[0])];
        r.extend(lines[1..].iter().map(|l| format!("  {l}")));
        r.extend(rows(&["", "✻ Worked for 12m 2s · done 4:24 PM", ""]));
        r.extend(composer("  ⏵⏵ bypass permissions on (shift+tab to cycle)"));
        r
    };
    let claim = report(&["Built, tested and landed the parser. All done; nothing left to do."]);
    let dirty = RepoWork {
        repo: "/Users//a/Developer/parser".to_string(),
        changed: 1,
        paths: vec!["src/lexer.rs".to_string()],
        ..RepoWork::default()
    };
    let run = |tag: &str, screens: Vec<Vec<String>>, found: Vec<Option<RepoWork>>| {
        let (dir, journal) = journal_file(tag);
        let host = Arc::new(RepoHost::new(found));
        let mut m = Mock::new(screens);
        m.turn_releases = Some(1);
        m.vanish_after = Some(2);
        let opts = SuperviseOpts {
            policy: SupervisorConfig::default(),
            journal: Some(journal.clone()),
            idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
            ..auto(30)
        };
        let (lines, _) = watch_lines(&mut m, &opts);
        let done: Vec<String> = journal_records(&journal)
            .0
            .into_iter()
            .map(|r| r.line)
            .filter(|l| l.starts_with("DONE "))
            .collect();
        let _ = std::fs::remove_dir_all(&dir);
        let asked = host.asked.load(std::sync::atomic::Ordering::SeqCst);
        let turns: Vec<String> = m
            .requests
            .iter()
            .filter(|r| r.starts_with("turn "))
            .cloned()
            .collect();
        (turns, lines, done, asked)
    };
    let suffix = repo_work_suffix(&dirty);
    assert!(
        suffix.contains("/Users//a/Developer/parser: 1 changed (src/lexer.rs)"),
        "{suffix}"
    );
    let (turns, lines, done, asked) = run(
        "claim-dirty",
        vec![busy_screen(), claim.clone()],
        vec![Some(dirty.clone())],
    );
    assert_eq!(
        turns.first(),
        Some(&continue_request(&format!("{DONE_CHECK} {suffix}"))),
        "the check with the repository's suffix: {lines:#?}"
    );
    assert!(asked >= 1, "the probe was asked at the claim");
    assert!(done.is_empty(), "{done:#?}");
    // NEGATIVE CONTROLS: a clean repository, and words that say no done.
    let (turns, lines, done, asked) = run("claim-clean", vec![busy_screen(), claim], vec![None]);
    assert_eq!(
        turns.first(),
        Some(&continue_request(DONE_CHECK)),
        "the plain check: {lines:#?}"
    );
    assert!(asked >= 1, "the probe was asked at the claim");
    assert!(done.is_empty(), "{done:#?}");
    let progress = report(&["Stage 2 landed; the parser is next."]);
    let (turns, lines, done, asked) = run(
        "claim-progress",
        vec![busy_screen(), progress],
        vec![Some(dirty)],
    );
    assert_eq!(asked, 0, "no done said, no probe: {lines:#?}");
    assert!(done.is_empty(), "{done:#?}");
    assert!(
        !turns.is_empty() && turns.iter().all(|t| !t.contains(&suffix)),
        "continued, no suffix: {turns:#?}"
    );
    assert!(
        lines
            .iter()
            .any(|l| l.contains(&format!("rule={RULE_CONTINUE} "))),
        "{lines:#?}"
    );
}
/// A PERSON'S GREETING LEFT TO THEM STAYS THEIRS IN THE NEXT LOOP (the
/// review's RR3-TE-2): the loop that left it ledgers the turn it left (a
/// `skipped` row under `left-to-person@v1`, keyed by the screen's last words
/// where no host reads the transcript), and a new loop on the same ledger
/// and the same screen, with no person's stamp of its own, types nothing.
/// NEGATIVE CONTROLS, the done check as before the row: the same new loop
/// over a ledger whose row a typed act closed, and over none.
#[test]
fn a_persons_greeting_left_to_them_stays_theirs_in_the_next_loop() {
    let greeting = "Hi! What would you like me to work on?";
    let quick = |said: &str| {
        let mut r = rows(&[&format!("⏺ {said}"), ""]);
        r.extend(composer("  ⏵⏵ bypass permissions on (shift+tab to cycle)"));
        r
    };
    let opts = SuperviseOpts {
        policy: SupervisorConfig {
            human_grace_s: 0,
            ..owners_policy()
        },
        ..auto(1)
    };
    let run = |ledger: &std::path::Path, person: bool| {
        let mut m = Mock::new(vec![busy_screen(), quick(greeting)]);
        m.turn_releases = Some(1);
        m.vanish_after = Some(8);
        if person {
            m.human = vec!["2000"];
        }
        let (lines, _) = watch_lines_with(&mut m, &opts, |s| {
            s.set_turn_end_timing(TurnEndTiming {
                short_backoff: Duration::from_millis(30),
                short_backoff_max: Duration::from_millis(60),
                ..TurnEndTiming::default()
            });
            s.set_approval_ledger(Some(ledger.to_path_buf()));
        });
        (count(&m, "turn"), lines)
    };
    let (dir, ledger) = ledger_at("left-next-loop");
    let (turns, lines) = run(&ledger, true);
    assert_eq!(turns, 0, "{lines:#?}");
    let body = std::fs::read_to_string(&ledger).unwrap_or_default();
    let left: Vec<&str> = body
        .lines()
        .filter(|l| l.contains(&format!("\"rule_id\":\"{RULE_LEFT}\"")))
        .collect();
    assert_eq!(left.len(), 1, "{body}");
    assert!(left[0].contains("\"decision\":\"skipped\""), "{body}");
    let (turns, lines) = run(&ledger, false);
    assert_eq!(turns, 0, "the next loop: {lines:#?}");
    assert!(
        !lines
            .iter()
            .any(|l| l.contains(&format!("rule={RULE_DONE_CHECK} "))),
        "{lines:#?}"
    );
    // NEGATIVE CONTROLS.
    let closed = format!(
        "{}\n{}\n",
        body.trim_end(),
        approvals::Row {
            rule_id: RULE_CONTINUE,
            outcome: approvals::Outcome::Typed,
            command: "keep going",
            reason: "the turn-end policy",
            box_seq: 1,
        }
        .to_json(i64::MAX / 2, None)
    );
    std::fs::write(&ledger, closed).expect("ledger");
    let (_, lines) = run(&ledger, false);
    assert!(
        lines
            .iter()
            .any(|l| l.contains(&format!("rule={RULE_DONE_CHECK} "))),
        "a typed act closed it: {lines:#?}"
    );
    std::fs::write(&ledger, "").expect("ledger");
    let (_, lines) = run(&ledger, false);
    assert!(
        lines
            .iter()
            .any(|l| l.contains(&format!("rule={RULE_DONE_CHECK} "))),
        "no row: {lines:#?}"
    );
    let _ = std::fs::remove_dir_all(&dir);
}

/// A host whose transcript LAGS the screen at a decision's first read
/// ([`IdleHost::transcript_tail`]: `fresh`) and has caught up when read
/// again for that lag ([`IdleHost::transcript_tail_again`]: `again`).
#[derive(Debug)]
struct LagHost {
    fresh: String,
    again: String,
}

impl IdleHost for LagHost {
    fn wants(&self) -> bool {
        false
    }
    fn at_idle(&self) -> Option<HostStep> {
        None
    }
    fn owns_turn_end(&self) -> bool {
        false
    }
    fn transcript_tail(&self) -> Option<String> {
        Some(self.fresh.clone())
    }
    fn transcript_tail_again(&self) -> Option<String> {
        Some(self.again.clone())
    }
}

/// A PERSON'S EXCHANGE IS LEFT UNDER ITS PROMPT'S KEY, HOWEVER LATE THE
/// TRANSCRIPT (the review's RR4-TE-3, ATERM-KI-1016-1): the loop decides the
/// moment the busy row leaves, and the reply's rows reach the transcript a
/// flush or more later. Keyed by the tail's last row, a tail that still
/// ended on the person's prompt (`u-1`), or on a tool's call (`a-0`) before
/// the reply's last words, keyed a row no later reading named (each names
/// the reply's last row, `a-1`), and the next loop typed the done check
/// into the greeting; re-reading the tail for a second covered only a lag
/// shorter than that. Keyed by the prompt that opened the exchange, every
/// tail ledgers `prompt:u-1` — the prompt alone, a tool's call after it,
/// the whole reply — and the next loop, the record caught up, types
/// nothing; so too over a row an earlier build keyed by the reply's last
/// row (`answer:a-1`). And a command the person ran in Claude Code after
/// the exchange, which the model answers not (`/config` as 2.1.294 records
/// it), leaves it theirs; a prompt command's exchange (`/init`), the tail
/// holding its command and expansion but no answer yet, is left under the
/// command's key, which the record caught up names (the review's
/// KR-P5-CMD). NEGATIVE CONTROLS, the done check typed: a row keyed by
/// another prompt, and the same row where a `/loop`'s wake (a row Claude
/// Code numbered anew) was answered after the exchange.
#[test]
fn a_persons_exchange_is_left_under_its_prompts_key() {
    let greeting = "Hi! What would you like me to work on?";
    let prompt = r#"{"isSidechain":false,"type":"user","uuid":"u-1","promptId":"p-1","message":{"role":"user","content":"hi"},"origin":{"kind":"human"},"promptSource":"typed"}"#;
    let call = r#"{"isSidechain":false,"type":"assistant","uuid":"a-0","message":{"model":"claude-opus-5-5","role":"assistant","content":[{"type":"tool_use","id":"t-1","name":"Read","input":{"file_path":"/p/README.md"}}]}}"#;
    let result = r#"{"isSidechain":false,"type":"user","uuid":"r-1","promptId":"p-1","message":{"role":"user","content":[{"type":"tool_result","tool_use_id":"t-1","content":"ok"}]}}"#;
    let answer = format!(
        r#"{{"isSidechain":false,"type":"assistant","uuid":"a-1","message":{{"model":"claude-opus-5-5","role":"assistant","content":[{{"type":"text","text":"{greeting}"}}]}}}}"#
    );
    let full = format!("{prompt}\n{call}\n{result}\n{answer}\n");
    let quick = || {
        let mut r = rows(&[&format!("⏺ {greeting}"), ""]);
        r.extend(composer("  ⏵⏵ bypass permissions on (shift+tab to cycle)"));
        r
    };
    let run = |ledger: &std::path::Path, host: LagHost, person: bool| {
        let mut m = Mock::new(vec![busy_screen(), quick()]);
        m.turn_releases = Some(1);
        m.vanish_after = Some(8);
        if person {
            m.human = vec!["2000"];
        }
        let opts = SuperviseOpts {
            policy: SupervisorConfig {
                human_grace_s: 0,
                ..owners_policy()
            },
            idle_host: Some(Arc::new(host) as Arc<dyn IdleHost>),
            ..auto(1)
        };
        let (lines, _) = watch_lines_with(&mut m, &opts, |s| {
            s.set_turn_end_timing(TurnEndTiming {
                short_backoff: Duration::from_millis(30),
                short_backoff_max: Duration::from_millis(60),
                ..TurnEndTiming::default()
            });
            s.set_approval_ledger(Some(ledger.to_path_buf()));
        });
        (count(&m, "turn"), lines)
    };
    let left_keys = |ledger: &std::path::Path| -> Vec<String> {
        std::fs::read_to_string(ledger)
            .unwrap_or_default()
            .lines()
            .filter(|l| l.contains(&format!("\"rule_id\":\"{RULE_LEFT}\"")))
            .filter_map(|l| aterm_json::from_str::<aterm_json::Value>(l).ok())
            .filter_map(|v| v.get("command").and_then(|c| c.as_str()).map(str::to_owned))
            .collect()
    };
    let host = |tail: &str| LagHost {
        fresh: tail.to_string(),
        again: tail.to_string(),
    };
    let checked = |lines: &[String]| {
        lines
            .iter()
            .any(|l| l.contains(&format!("rule={RULE_DONE_CHECK} ")))
    };
    let (dir, ledger) = ledger_at("left-under-prompt");
    for (what, tail) in [
        ("the prompt alone, re-read alike", format!("{prompt}\n")),
        (
            "a tool's call after it",
            format!("{prompt}\n{call}\n{result}\n"),
        ),
        ("caught up", full.clone()),
    ] {
        std::fs::write(&ledger, "").expect("ledger");
        let (turns, lines) = run(&ledger, host(&tail), true);
        assert_eq!(turns, 0, "{what}: {lines:#?}");
        assert_eq!(left_keys(&ledger), ["prompt:u-1"], "{what}: {lines:#?}");
        let (turns, lines) = run(&ledger, host(&full), false);
        assert_eq!(turns, 0, "{what}, the next loop: {lines:#?}");
        assert!(!checked(&lines), "{what}, the next loop: {lines:#?}");
    }
    let row = |key: &str| {
        approvals::Row {
            rule_id: RULE_LEFT,
            outcome: approvals::Outcome::Skipped,
            command: key,
            reason: approvals::LEFT_REASON,
            box_seq: 1,
        }
        .to_json(i64::MAX / 2, None)
            + "\n"
    };
    std::fs::write(&ledger, row("answer:a-1")).expect("ledger");
    let (turns, lines) = run(&ledger, host(&full), false);
    assert_eq!(turns, 0, "an earlier build's row: {lines:#?}");
    assert!(!checked(&lines), "an earlier build's row: {lines:#?}");
    // NEGATIVE CONTROLS.
    std::fs::write(&ledger, row("prompt:u-0")).expect("ledger");
    let (_, lines) = run(&ledger, host(&full), false);
    assert!(checked(&lines), "another prompt's row: {lines:#?}");
    let wake = r#"{"isSidechain":false,"type":"user","uuid":"w-1","promptId":"p-wake","isMeta":true,"promptSource":"system","scheduledTaskId":"t1","message":{"role":"user","content":"check the build"}}"#;
    let woke = format!(
        "{full}{wake}\n{}\n",
        answer.replace(r#""uuid":"a-1""#, r#""uuid":"a-2""#)
    );
    std::fs::write(&ledger, row("prompt:u-1")).expect("ledger");
    let (_, lines) = run(&ledger, host(&woke), false);
    assert!(checked(&lines), "a wake answered since: {lines:#?}");
    // A command of the person's after the exchange, no answer to it.
    let caveat = r#"{"isSidechain":false,"type":"user","uuid":"c-0","promptId":"p-2","isMeta":true,"message":{"role":"user","content":"<local-command-caveat>Caveat: The messages below were generated by the user while running local commands. DO NOT respond to these messages or otherwise consider them in your response unless the user explicitly asks you to.</local-command-caveat>"}}"#;
    let config = r#"{"isSidechain":false,"type":"user","uuid":"c-1","promptId":"p-2","message":{"role":"user","content":"<command-name>/config</command-name>\n            <command-message>config</command-message>\n            <command-args></command-args>"}}"#;
    let config_out = r#"{"isSidechain":false,"type":"user","uuid":"c-2","promptId":"p-2","message":{"role":"user","content":"<local-command-stdout>Disabled auto-compact</local-command-stdout>"}}"#;
    let configured = format!("{full}{caveat}\n{config}\n{config_out}\n");
    std::fs::write(&ledger, row("prompt:u-1")).expect("ledger");
    let (turns, lines) = run(&ledger, host(&configured), false);
    assert_eq!(turns, 0, "/config after the exchange: {lines:#?}");
    assert!(!checked(&lines), "/config after the exchange: {lines:#?}");
    // A prompt command's exchange, its answer not on the record yet.
    let init = r#"{"isSidechain":false,"type":"user","uuid":"i-1","promptId":"p-5","message":{"role":"user","content":"<command-message>init is analyzing your codebase…</command-message>\n<command-name>/init</command-name>"},"origin":{"kind":"human"}}"#;
    let expansion = r#"{"isSidechain":false,"type":"user","uuid":"i-2","promptId":"p-5","isMeta":true,"message":{"role":"user","content":[{"type":"text","text":"Please analyze this codebase and create a CLAUDE.md file"}]}}"#;
    let asked = format!("{init}\n{expansion}\n");
    std::fs::write(&ledger, "").expect("ledger");
    let (turns, lines) = run(&ledger, host(&asked), true);
    assert_eq!(turns, 0, "/init, unanswered on the record: {lines:#?}");
    assert_eq!(left_keys(&ledger), ["prompt:i-1"], "/init: {lines:#?}");
    let (turns, lines) = run(&ledger, host(&format!("{asked}{answer}\n")), false);
    assert_eq!(turns, 0, "/init, the next loop: {lines:#?}");
    assert!(!checked(&lines), "/init, the next loop: {lines:#?}");
    let _ = std::fs::remove_dir_all(&dir);
}

/// A PERSON'S EXCHANGE AN OLDER BUILD NOTED LEFT STAYS THEIRS IN THE NEXT
/// LOOP (ATERM-KI-1016-1, done-5): a build through 0.105.0 journals `LEFT
/// seq=<n> rule=left-to-person@v1 …` and writes no row naming the turn it
/// left, so the first loop after the update typed the done check into the
/// person's greeting. The note's time names the turn: the transcript's last
/// turn opened by a prompt recorded at or before it is the one that build
/// left (`approvals::LEFT_BEFORE`), and the new loop, no person's stamp of
/// its own, types nothing. NEGATIVE CONTROLS, the done check typed: a prompt
/// recorded after the note (a turn opened since), an act journaled after it
/// (`CONTINUED`, which closes it as its row would), a task's end journaled
/// after it, a prompt row with no time, no journal (a build's books with
/// nothing that says it), and a journal whose last note is the task's end
/// before the exchange (that build notes no `LEFT` after a `DONE`, and
/// nothing on disk tells its exchange from an orchestrator's new task:
/// ATERM-KI-1016-1, done-7).
#[test]
fn a_persons_exchange_an_older_build_noted_left_stays_theirs_in_the_next_loop() {
    use crate::supervise::journal::JournalRecord;
    let greeting = "Hi! What would you like me to work on?";
    // 2026-10-01T12:00:00Z, and the note 3 min after it.
    let opened_s: i64 = 1_790_856_000;
    let noted_ms = (opened_s + 180) * 1000;
    let prompt = |stamp: Option<&str>| {
        let at = stamp.map_or_else(String::new, |t| format!(r#","timestamp":"{t}""#));
        format!(
            r#"{{"isSidechain":false,"type":"user","uuid":"u-1","promptId":"p-1"{at},"message":{{"role":"user","content":"hi"}},"origin":{{"kind":"human"}},"promptSource":"typed"}}"#
        )
    };
    let answer = format!(
        r#"{{"isSidechain":false,"type":"assistant","uuid":"a-1","message":{{"model":"claude-opus-5-5","role":"assistant","content":[{{"type":"text","text":"{greeting}"}}]}}}}"#
    );
    let tail = |stamp: Option<&str>| format!("{}\n{answer}\n", prompt(stamp));
    let quick = || {
        let mut r = rows(&[&format!("⏺ {greeting}"), ""]);
        r.extend(composer("  ⏵⏵ bypass permissions on (shift+tab to cycle)"));
        r
    };
    let run = |ledger: &std::path::Path, tail: String| {
        let mut m = Mock::new(vec![busy_screen(), quick()]);
        m.turn_releases = Some(1);
        m.vanish_after = Some(8);
        let opts = SuperviseOpts {
            policy: SupervisorConfig {
                human_grace_s: 0,
                ..owners_policy()
            },
            idle_host: Some(Arc::new(LagHost {
                fresh: tail.clone(),
                again: tail,
            }) as Arc<dyn IdleHost>),
            ..auto(1)
        };
        let (lines, _) = watch_lines_with(&mut m, &opts, |s| {
            s.set_turn_end_timing(TurnEndTiming {
                short_backoff: Duration::from_millis(30),
                short_backoff_max: Duration::from_millis(60),
                ..TurnEndTiming::default()
            });
            s.set_approval_ledger(Some(ledger.to_path_buf()));
        });
        (count(&m, "turn"), lines)
    };
    let checked = |lines: &[String]| {
        lines
            .iter()
            .any(|l| l.contains(&format!("rule={RULE_DONE_CHECK} ")))
    };
    let note = |at: i64, line: &str| JournalRecord::of_line(at, None, line, None).to_json() + "\n";
    let left = note(
        noted_ms,
        &format!(
            "LEFT seq=7 rule={RULE_LEFT} a person's own exchange (their message, answered \
             within 10 min): nothing is typed until the next turn ends"
        ),
    );
    let (dir, ledger) = ledger_at("left-older-note");
    let journal = approvals::journal_beside(&ledger);
    std::fs::write(&ledger, "").expect("ledger");
    std::fs::write(&journal, &left).expect("journal");
    let (turns, lines) = run(&ledger, tail(Some("2026-10-01T12:00:00.000Z")));
    assert_eq!(turns, 0, "{lines:#?}");
    assert!(!checked(&lines), "{lines:#?}");
    // NEGATIVE CONTROLS.
    let fresh = |journal_text: Option<&str>| {
        std::fs::write(&ledger, "").expect("ledger");
        let _ = std::fs::remove_file(&journal);
        if let Some(text) = journal_text {
            std::fs::write(&journal, text).expect("journal");
        }
    };
    fresh(Some(&left));
    let (_, lines) = run(&ledger, tail(Some("2026-10-01T12:04:00.000Z")));
    assert!(checked(&lines), "a turn opened since: {lines:#?}");
    let acted = format!(
        "{left}{}",
        note(
            noted_ms + 60_000,
            "CONTINUED seq=9 rule=continue@v1 keep going"
        )
    );
    fresh(Some(&acted));
    let (_, lines) = run(&ledger, tail(Some("2026-10-01T12:00:00.000Z")));
    assert!(checked(&lines), "an act since: {lines:#?}");
    let ended = format!(
        "{left}{}",
        note(
            noted_ms + 60_000,
            "DONE seq=9 rule=continue-done-check@v1 the worker said it is done after the done \
             check: nothing more is typed until a person or an orchestrator types"
        )
    );
    fresh(Some(&ended));
    let (_, lines) = run(&ledger, tail(Some("2026-10-01T12:00:00.000Z")));
    assert!(checked(&lines), "a task's end since: {lines:#?}");
    fresh(Some(&left));
    let (_, lines) = run(&ledger, tail(None));
    assert!(checked(&lines), "a prompt with no time: {lines:#?}");
    fresh(None);
    let (_, lines) = run(&ledger, tail(Some("2026-10-01T12:00:00.000Z")));
    assert!(checked(&lines), "no journal: {lines:#?}");
    // …and a task's end noted before the exchange (the review's DR-2, what
    // stays of done-7): that build notes `LEFT` only where the task's end is
    // first said, so a person's exchange after its `DONE` has no note, and
    // its `EVENT` with no act after it is also what an act the live
    // upgrade's own step took the point from leaves. Continued once.
    let done_before = note(
        (opened_s - 300) * 1000,
        "DONE seq=5 rule=finished@v1 the worker reported ATERM-TASK-DONE: its task is \
         finished; nothing more is typed until a person or an orchestrator types",
    );
    fresh(Some(&done_before));
    let (_, lines) = run(&ledger, tail(Some("2026-10-01T12:00:00.000Z")));
    assert!(checked(&lines), "a task's end noted before: {lines:#?}");
    let _ = std::fs::remove_dir_all(&dir);
}

/// A PERSON'S OWN EXCHANGE AT A WALL STAYS THEIRS IN THE NEXT LOOP (the
/// review's RR4-TE-2): a person's quick message met a 529 (Claude Code
/// 2.1.294's measured transcript: the prompt `lag-e5`, the overload's
/// notice, its `turn_duration`), and the loop that saw it was gone before
/// its retry. That loop ledgered the exchange at the wall (a `skipped` row
/// under `left-to-person@v1`, its key the person's prompt marked the
/// wall's, and the exchange's work so far); the next loop, whose first point
/// is the same wall, types the retry, and nothing into the greeting that
/// answers it — so too from a row that names no work. A row whose work before
/// the wall was 10 min is a job's: its answer is the policy's (the merge
/// review's F3, main's 7fffc8156). NEGATIVE CONTROL:
/// the same next loop over no row types the retry and then `Nobody is here
/// to answer…` into the greeting (what the review measured).
#[test]
fn a_persons_exchange_at_a_wall_stays_theirs_in_the_next_loop() {
    use crate::supervise::policy::turn_end::{RULE_ANSWER, RULE_API_RETRY};
    let tail = include_str!("fixtures/claude-2.1.294-transcript-529.jsonl");
    let greeting = "Hello! How can I help?";
    let answer = format!(
        r#"{{"isSidechain":false,"type":"assistant","uuid":"a-9","message":{{"model":"claude-opus-5-5","role":"assistant","content":[{{"type":"text","text":"{greeting}"}}]}}}}"#
    );
    let answered = format!("{tail}{answer}\n");
    let wall = || {
        let mut r = rows(&[
            "❯ lag-e5",
            "  ⎿  API Error: Repeated 529 Overloaded errors. The API is at capacity — this is \
             usually temporary. Try again in a moment. If it persists, check your inference \
             gateway (127.0.0.1:61336).",
            "",
            "✻ Churned for 3s · done 9:59 AM",
            "",
        ]);
        r.extend(composer("  ⏵⏵ bypass permissions on (shift+tab to cycle)"));
        r
    };
    let quick = || {
        let mut r = rows(&[&format!("⏺ {greeting}"), ""]);
        r.extend(composer("  ⏵⏵ bypass permissions on (shift+tab to cycle)"));
        r
    };
    let run = |ledger: &std::path::Path, m: &mut Mock, backoff: Duration| {
        let opts = SuperviseOpts {
            policy: SupervisorConfig {
                human_grace_s: 0,
                ..owners_policy()
            },
            idle_host: Some(Arc::new(LagHost {
                fresh: tail.to_string(),
                again: answered.clone(),
            }) as Arc<dyn IdleHost>),
            ..auto(1)
        };
        let (lines, _) = watch_lines_with(m, &opts, |s| {
            s.set_turn_end_timing(TurnEndTiming {
                retry_backoff: vec![backoff; 3],
                short_backoff: Duration::from_millis(30),
                short_backoff_max: Duration::from_millis(60),
                ..TurnEndTiming::default()
            });
            s.set_approval_ledger(Some(ledger.to_path_buf()));
        });
        lines
    };
    let (dir, ledger) = ledger_at("left-at-wall");
    // The loop that saw the person's turn meet the wall, gone before its
    // retry.
    let mut m = Mock::new(vec![busy_screen(), wall()]);
    m.vanish_after = Some(3);
    m.human = vec!["2000"];
    let lines = run(&ledger, &mut m, Duration::from_secs(600));
    assert_eq!(count(&m, "turn"), 0, "{lines:#?}");
    let body = std::fs::read_to_string(&ledger).unwrap_or_default();
    let walled: Vec<&str> = body
        .lines()
        .filter(|l| l.contains(&format!("\"rule_id\":\"{RULE_LEFT}\"")))
        .collect();
    assert_eq!(walled.len(), 1, "{body}\n{lines:#?}");
    // Its key the prompt's, marked the wall's, and the exchange's work so far
    // in whole seconds (F3 of the merge review).
    const PROMPT: &str = "prompt:6277d654-73c7-45e4-9dac-9971bc9c1e8e";
    let head = format!("\"command\":\"{}{PROMPT}@", approvals::LEFT_AT_WALL);
    let at = walled[0].find(&head).expect(body.as_str()) + head.len() - 1;
    let end = at + walled[0][at..].find('"').expect("the key's end");
    assert!(
        walled[0][at + 1..end].parse::<u64>().is_ok(),
        "the work in seconds: {body}"
    );
    // The row as written, its work replaced by `work` (`""`: as a row
    // written before the work was carried).
    let row = walled[0].to_string();
    let carrying = |work: &str| format!("{}{work}{}\n", &row[..at], &row[end..]);
    // The next loop: its first point the same wall.
    let next = |ledger: &std::path::Path| {
        let mut m = Mock::new(vec![wall(), busy_screen(), quick()]);
        m.turn_releases = Some(0);
        m.vanish_after = Some(20);
        m.stall_sleep = Some(Duration::from_millis(20));
        let lines = run(ledger, &mut m, Duration::from_millis(50));
        (count(&m, "turn"), lines)
    };
    let typed =
        |lines: &[String], rule: &str| lines.iter().any(|l| l.contains(&format!("rule={rule} ")));
    let (turns, lines) = next(&ledger);
    assert_eq!(turns, 1, "the retry alone: {lines:#?}");
    assert!(typed(&lines, RULE_API_RETRY), "{lines:#?}");
    assert!(!typed(&lines, RULE_ANSWER), "{lines:#?}");
    // A row written before the work was carried: the same.
    std::fs::write(&ledger, carrying("")).expect("ledger");
    let (turns, lines) = next(&ledger);
    assert_eq!(turns, 1, "the retry alone: {lines:#?}");
    // The work the row carries reaches the policy: 10 min of it before the
    // wall makes the turn a job (`EXCHANGE_WORK`), whose retry's answer is
    // the policy's, as with no row.
    std::fs::write(&ledger, carrying("@600")).expect("ledger");
    let (turns, lines) = next(&ledger);
    assert_eq!(turns, 2, "{lines:#?}");
    assert!(typed(&lines, RULE_ANSWER), "{lines:#?}");
    // NEGATIVE CONTROL: no row.
    std::fs::write(&ledger, "").expect("ledger");
    let (turns, lines) = next(&ledger);
    assert_eq!(turns, 2, "{lines:#?}");
    assert!(typed(&lines, RULE_API_RETRY), "{lines:#?}");
    assert!(typed(&lines, RULE_ANSWER), "{lines:#?}");
    let _ = std::fs::remove_dir_all(&dir);
}

/// A PERSON'S EXCHANGE RETRIED AT A WALL STAYS THEIRS IN THE NEXT LOOP
/// (ATERM-KI-1016-1): a person's quick message met a 529 (Claude Code
/// 2.1.294's measured transcript), the loop that saw it ledgered the
/// exchange at the wall, typed the retry, and was gone before the retry's
/// answer. The retry's row closed the wall's, and the next loop, whose first
/// point is the greeting that answers the retry, typed into it; the row stays
/// open as the retry's ([`approvals::left_after_typed`]), and that next loop
/// types nothing and leaves the exchange to the person under the retry's
/// prompt (`prompt:r-9`). NEGATIVE CONTROLS, typed: the retry's answer a job past
/// the exchange's bound by its `turn_duration`, and a continuation typed
/// after the retry.
#[test]
fn a_persons_exchange_retried_at_a_wall_stays_theirs_in_the_next_loop() {
    use crate::supervise::policy::turn_end::RULE_API_RETRY;
    let tail = include_str!("fixtures/claude-2.1.294-transcript-529.jsonl");
    let greeting = "Hello! How can I help?";
    let wall = || {
        let mut r = rows(&[
            "❯ lag-e5",
            "  ⎿  API Error: Repeated 529 Overloaded errors. The API is at capacity — this is \
             usually temporary. Try again in a moment. If it persists, check your inference \
             gateway (127.0.0.1:61336).",
            "",
            "✻ Churned for 3s · done 9:59 AM",
            "",
        ]);
        r.extend(composer("  ⏵⏵ bypass permissions on (shift+tab to cycle)"));
        r
    };
    let quick = || {
        let mut r = rows(&[&format!("⏺ {greeting}"), ""]);
        r.extend(composer("  ⏵⏵ bypass permissions on (shift+tab to cycle)"));
        r
    };
    let run = |ledger: &std::path::Path, m: &mut Mock, tail: &str| {
        let opts = SuperviseOpts {
            policy: SupervisorConfig {
                human_grace_s: 0,
                ..owners_policy()
            },
            idle_host: Some(Arc::new(LagHost {
                fresh: tail.to_string(),
                again: tail.to_string(),
            }) as Arc<dyn IdleHost>),
            ..auto(60)
        };
        let (lines, _) = watch_lines_with(m, &opts, |s| {
            s.set_turn_end_timing(TurnEndTiming {
                retry_backoff: vec![Duration::from_millis(50); 3],
                short_backoff: Duration::from_millis(30),
                short_backoff_max: Duration::from_millis(60),
                // The retry's take window cut to 50 ms, so the next loop's
                // first point, which awaits the retry the loop before typed
                // (`TurnEndState::seed_awaited`), is judged inside the run.
                take_within: Duration::from_millis(50),
                ..TurnEndTiming::default()
            });
            s.set_approval_ledger(Some(ledger.to_path_buf()));
        });
        lines
    };
    let (dir, ledger) = ledger_at("retried-at-wall");
    // The loop that saw the person's turn meet the wall: it types the retry
    // and is gone.
    let mut m = Mock::new(vec![busy_screen(), wall()]);
    m.human = vec!["2000"];
    m.exit_when = Some(|m| m.turns > 0);
    let lines = run(&ledger, &mut m, tail);
    assert_eq!(count(&m, "turn"), 1, "{lines:#?}");
    let body = std::fs::read_to_string(&ledger).unwrap_or_default();
    let retry = body
        .lines()
        .filter(|l| l.contains(&format!("\"rule_id\":\"{RULE_API_RETRY}\"")))
        .filter_map(|l| aterm_json::from_str::<aterm_json::Value>(l).ok())
        .find_map(|v| v.get("command").and_then(|c| c.as_str()).map(str::to_owned))
        .expect(body.as_str());
    let open = approvals::open_left_in(&body, None).expect(body.as_str());
    assert!(open.starts_with(approvals::LEFT_RETRIED), "{open}");
    // The retry's turn as Claude Code records it: the typed retry, the
    // greeting, the turn's `turn_duration`.
    let answered = |ms: u64| {
        format!(
            "{tail}{}\n{}\n{}\n",
            aterm_json::json!({
                "isSidechain": false, "type": "user", "uuid": "r-9", "promptId": "p-9",
                "message": {"role": "user", "content": retry},
            }),
            aterm_json::json!({
                "isSidechain": false, "type": "assistant", "uuid": "a-9",
                "message": {"model": "claude-opus-5-5", "role": "assistant",
                            "content": [{"type": "text", "text": greeting}]},
            }),
            aterm_json::json!({
                "isSidechain": false, "type": "system", "subtype": "turn_duration",
                "durationMs": ms,
            }),
        )
    };
    // The next loop: its first point the retry's answer, over the ledger
    // `rows` (`body`: as the loop before it left it).
    let next = |rows: &str, record: &str, typed: bool| {
        std::fs::write(&ledger, rows).expect("ledger");
        let mut m = Mock::new(vec![quick()]);
        // Each wait sleeps, so the take window has run out long before the
        // session goes (40 waits of at least 5 ms, past its 50 ms).
        m.stall_sleep = Some(Duration::from_millis(5));
        if typed {
            m.exit_when = Some(|m| m.turns > 0);
        } else {
            m.vanish_after = Some(40);
        }
        let lines = run(&ledger, &mut m, record);
        (count(&m, "turn"), lines)
    };
    let (turns, lines) = next(&body, &answered(4_000), false);
    assert_eq!(turns, 0, "the retry's answer is the person's: {lines:#?}");
    // …as that loop judged it: the exchange left to the person under the
    // retry's prompt, as the loop that typed the retry leaves it.
    let after = std::fs::read_to_string(&ledger).unwrap_or_default();
    assert_eq!(
        approvals::open_left_in(&after, None).as_deref(),
        Some("prompt:r-9"),
        "{after}\n{lines:#?}"
    );
    // NEGATIVE CONTROLS.
    let (turns, lines) = next(&body, &answered(11 * 60 * 1000), true);
    assert_eq!(turns, 1, "CONTROL: a job past the bound: {lines:#?}");
    let closed = format!(
        "{body}{}\n",
        approvals::Row {
            rule_id: "continue@v1",
            outcome: approvals::Outcome::Typed,
            command: "keep going",
            reason: "",
            box_seq: 1,
        }
        .to_json(i64::MAX / 2, None)
    );
    let (turns, lines) = next(&closed, &answered(4_000), true);
    assert_eq!(
        turns, 1,
        "CONTROL: a continuation after the retry: {lines:#?}"
    );
    let _ = std::fs::remove_dir_all(&dir);
}

/// A PERSON'S QUESTION IS THEIRS THOUGH ITS ANSWER TAKES MINUTES, through the
/// real supervisor (the owner, 2026-10-15: "these auto prompts are for
/// continuously running jobs"): their question, then a three-minute answer
/// that looked things up, gets nothing typed, and the journal says once why.
/// Negative control: a turn they opened that works past `EXCHANGE_WORK` is a
/// job, and is continued.
#[test]
fn a_persons_question_answered_at_length_is_left_to_them() {
    let answered = |worked: &str| {
        let mut r = rows(&[
            "❯ what do you think?",
            "",
            "  Ran 2 shell commands",
            "",
            "⏺ Keep the token: it costs nothing and survives a restart.",
            "",
            &format!("✻ Worked for {worked} · done 4:24 PM"),
            "",
        ]);
        r.extend(composer("  ⏵⏵ bypass permissions on (shift+tab to cycle)"));
        r
    };
    // Their keystroke sent the question, just before the turn's work.
    for (screen, human, typed) in [
        (answered("3m 2s"), "185000", false),
        (answered("12m 2s"), "725000", true),
    ] {
        let (dir, journal) = journal_file("persons-question");
        let mut m = Mock::new(vec![busy_screen(), screen]);
        m.turn_releases = Some(1);
        m.human = vec![human];
        // An act that must come ends the watch, a minute its hang detector;
        // one that must not is looked for for a second.
        let max = if typed {
            m.exit_when = Some(|m| m.turns > 0);
            60
        } else {
            m.vanish_after = Some(8);
            1
        };
        let opts = SuperviseOpts {
            policy: SupervisorConfig {
                human_grace_s: 0,
                ..owners_policy()
            },
            journal: Some(journal.clone()),
            ..auto(max)
        };
        let (lines, _) = watch_lines_with(&mut m, &opts, |s| {
            s.set_turn_end_timing(TurnEndTiming {
                short_backoff: Duration::from_millis(30),
                short_backoff_max: Duration::from_millis(60),
                ..TurnEndTiming::default()
            });
        });
        assert_eq!(count(&m, "turn") > 0, typed, "{typed}: {lines:#?}");
        let left = journal_records(&journal)
            .0
            .into_iter()
            .filter(|r| r.line.starts_with("LEFT "))
            .count();
        assert_eq!(left, usize::from(!typed), "{typed}");
        let _ = std::fs::remove_dir_all(&dir);
    }
}

/// CLAUDE CODE'S OWN HOUSEKEEPING IS NO TURN (2026-10-15, two of the owner's
/// tabs typed `keep going` an hour after their finished reports): a spinner,
/// then a screen whose last thing said is `⏺ Compacted while idle, before the
/// prompt cache expired`. Nothing is typed where the last turn left nothing
/// to type: after a person's own exchange (their greeting, answered in
/// seconds), and at a question held for a person with answers off. The
/// person's grace is off and the back-off short, so nothing but the reading
/// holds an act. Negative controls, each typed: a message of the worker's in
/// the notice's place (a turn that ended); and an attach (a seamless update,
/// a fault) after a report ending in the retired `ATERM-TASK-DONE` (the
/// MEASURED screen, 2.1.302's notice with the `·` hint it appends, and so
/// under Claude Code's own `keep going` suggestion) — a done claim read
/// through the compaction, which gets the done check (FOREVER CRUISE) — or
/// after a report that did not finish.
#[test]
fn claude_codes_idle_compaction_is_no_turn() {
    use aterm_phase::prompt::fixtures::{
        IDLE_COMPACTED_HINT_MEASURED, IDLE_COMPACTED_MEASURED, screen,
    };
    let measured = screen(IDLE_COMPACTED_MEASURED);
    let hinted = screen(IDLE_COMPACTED_HINT_MEASURED);
    let swap = |rows: &[String], from: &str, to: &str| -> Vec<String> {
        let at = rows.iter().position(|r| r.starts_with(from)).expect(from);
        let mut out = rows.to_vec();
        out[at] = to.to_string();
        out
    };
    // Claude Code's dim suggestion, where the composer's caret was.
    let suggested = |rows: &[String]| swap(rows, "❯", "❯ keep going");
    let notice = "⏺ Compacted while idle";
    let worker = "⏺ Compacted the build logs into one file.";
    let ask = "Shall I drop the old table?";
    let greeting = "Hi! What would you like me to work on?";
    let framed = |body: &[&str]| {
        let mut r = rows(body);
        r.extend(composer("  ⏵⏵ bypass permissions on (shift+tab to cycle)"));
        r
    };
    let greeted = framed(&[&format!("⏺ {greeting}"), ""]);
    // The worker's words, then what the compaction appended under them.
    let compacted = |said: &str| {
        framed(&[
            &format!("⏺ {said}"),
            "",
            "  ⎿  Skills restored (workflow-authoring)",
            "",
            "⏺ Compacted while idle, before the prompt cache expired",
            "",
        ])
    };
    let (left, held) = (compacted(greeting), compacted(ask));
    let run = |screens: Vec<Vec<String>>| {
        vec![
            busy_screen(),
            screens[0].clone(),
            busy_screen(),
            screens[1].clone(),
        ]
    };
    let arms = [
        ("attached", vec![measured.clone()], true, true),
        // 2.1.302's notice, its `·` hint after it.
        ("attached, 2.1.302", vec![hinted.clone()], true, true),
        // The same under a `keep going` suggestion.
        (
            "attached, 2.1.302, a suggestion",
            vec![suggested(&hinted)],
            true,
            true,
        ),
        (
            "attached, unfinished",
            vec![swap(
                &measured,
                "  ATERM-TASK-DONE",
                "  Next I port the reader.",
            )],
            true,
            true,
        ),
        (
            "left",
            run(vec![greeted.clone(), left.clone()]),
            true,
            false,
        ),
        (
            "left, a worker's turn",
            run(vec![greeted.clone(), swap(&left, notice, worker)]),
            true,
            true,
        ),
        ("held", run(vec![ended(ask), held.clone()]), false, false),
        (
            "held, a worker's turn",
            run(vec![ended(ask), swap(&held, notice, worker)]),
            false,
            true,
        ),
    ];
    let mut wrong = Vec::new();
    for (arm, screens, answers, typed) in arms {
        let last = screens.len() - 1;
        let mut m = Mock::new(screens);
        m.turn_releases = Some(last);
        // The greeting's turn was opened by a person's keystroke.
        if arm.starts_with("left") {
            m.human = vec!["2000"];
        }
        // An act that must come ends the watch, a minute its hang detector;
        // one that must not is looked for until the session goes.
        let max = if typed {
            m.exit_when = Some(|m| m.turns > 0);
            60
        } else {
            m.vanish_after = Some(8);
            1
        };
        let opts = SuperviseOpts {
            policy: SupervisorConfig {
                human_grace_s: 0,
                answer_questions: answers,
                ..owners_policy()
            },
            ..auto(max)
        };
        let (lines, _) = watch_lines_with(&mut m, &opts, |s| {
            s.set_turn_end_timing(TurnEndTiming {
                short_backoff: Duration::from_millis(30),
                short_backoff_max: Duration::from_millis(60),
                ..TurnEndTiming::default()
            });
        });
        if (count(&m, "turn") > 0) != typed {
            wrong.push(format!("{arm}: typed={}: {lines:#?}", !typed));
        }
    }
    assert!(wrong.is_empty(), "{wrong:#?}");
}

/// A host whose conversation's record runs on past the 256 KiB tail it
/// reads for a wall ([`IdleHost::transcript_tail`]: `tail`): its finish read
/// folds the whole record, `full` ([`IdleHost::finished`]), and names the
/// turn it ends on by that fold ([`IdleHost::last_turn`]) where
/// `record_key`, as the window host's memo does.
#[derive(Debug)]
struct RecordHost {
    full: String,
    tail: String,
    record_key: bool,
}

impl IdleHost for RecordHost {
    fn wants(&self) -> bool {
        false
    }
    fn at_idle(&self) -> Option<HostStep> {
        None
    }
    fn owns_turn_end(&self) -> bool {
        false
    }
    fn transcript_tail(&self) -> Option<String> {
        Some(self.tail.clone())
    }
    fn finished(&self) -> Option<bool> {
        Some(crate::harness::upgrade::transcript_finished(
            &self.full,
            &[],
        ))
    }
    fn last_turn(&self) -> Option<crate::harness::upgrade::LastTurn> {
        let mut scan = crate::harness::upgrade::FinishedScan::default();
        for line in self.full.lines() {
            scan.line(line);
        }
        self.record_key.then(|| scan.last_turn())
    }
}

/// A PERSON'S EXCHANGE LEFT TO THEM STAYS THEIRS UNDER AN IDLE COMPACTION
/// (the merge review's XR-1, against main's a4a25f634): the greeting left to
/// its person (`left-to-person@v1`, keyed `answer:a-1`), then Claude Code
/// compacted the idle conversation by itself, and a new loop (a seamless
/// update, a fault) attaches there. The compaction's block — its summary,
/// restored files and skills — fills the 256 KiB tail the loop keyed the
/// turn by, which then names no turn; keyed by the screen's words instead,
/// the row matched nothing and the loop typed into the person's exchange.
/// Keyed by the record its finish was read from, the row is read: nothing is
/// typed. NEGATIVE CONTROL: a host that names no turn by its record (the
/// tail alone) types.
#[test]
fn a_persons_exchange_stays_theirs_under_an_idle_compaction() {
    let greeting = "Hi! What would you like me to work on?";
    let exchange = format!(
        "{}\n{}\n",
        r#"{"isSidechain":false,"type":"user","uuid":"u-1","message":{"role":"user","content":"hi"},"origin":{"kind":"human"},"promptSource":"typed"}"#,
        format_args!(
            r#"{{"isSidechain":false,"type":"assistant","uuid":"a-1","message":{{"model":"claude-opus-5-5","role":"assistant","content":[{{"type":"text","text":"{greeting}"}}]}}}}"#
        )
    );
    let block = [
        r#"{"type":"system","subtype":"compact_boundary","isSidechain":false,"compactMetadata":{"trigger":"idle"}}"#,
        r#"{"type":"user","uuid":"s-1","isSidechain":false,"isCompactSummary":true,"isVisibleInTranscriptOnly":true,"message":{"role":"user","content":"This session is being continued from a previous conversation."}}"#,
        r#"{"type":"attachment","isSidechain":false,"attachment":{"type":"file","filename":"/tmp/f0.rs","content":"fn main() {}"}}"#,
        r#"{"type":"system","subtype":"informational","isSidechain":false,"content":"Compacted while idle, before the prompt cache expired"}"#,
    ]
    .join("\n")
        + "\n";
    let compacted = {
        let mut r = rows(&[
            &format!("⏺ {greeting}"),
            "",
            "  ⎿  Skills restored (workflow-authoring)",
            "",
            "⏺ Compacted while idle, before the prompt cache expired",
            "",
        ]);
        r.extend(composer("  ⏵⏵ bypass permissions on (shift+tab to cycle)"));
        r
    };
    let (dir, ledger) = ledger_at("left-under-compaction");
    for record_key in [true, false] {
        let row = approvals::Row {
            rule_id: RULE_LEFT,
            outcome: approvals::Outcome::Skipped,
            command: "answer:a-1",
            reason: approvals::LEFT_REASON,
            box_seq: 1,
        }
        .to_json(i64::MAX / 2, None);
        std::fs::write(&ledger, row + "\n").expect("ledger");
        let typed = !record_key;
        let mut m = Mock::new(vec![compacted.clone()]);
        // An act that must come ends the watch, a minute its hang detector;
        // one that must not is looked for until the session goes, the point
        // decided first (its `LEFT` said).
        let max = if typed {
            m.exit_when = Some(|m| m.turns > 0);
            60
        } else {
            m.vanish_after = Some(8);
            1
        };
        let (jdir, journal) = journal_file("left-under-compaction");
        let opts = SuperviseOpts {
            policy: SupervisorConfig {
                human_grace_s: 0,
                ..owners_policy()
            },
            journal: Some(journal.clone()),
            idle_host: Some(Arc::new(RecordHost {
                full: format!("{exchange}{block}"),
                tail: block.clone(),
                record_key,
            }) as Arc<dyn IdleHost>),
            ..auto(max)
        };
        let (lines, _) = watch_lines_with(&mut m, &opts, |s| {
            s.set_turn_end_timing(TurnEndTiming {
                short_backoff: Duration::from_millis(30),
                short_backoff_max: Duration::from_millis(60),
                ..TurnEndTiming::default()
            });
            s.set_approval_ledger(Some(ledger.clone()));
        });
        assert_eq!(
            count(&m, "turn") > 0,
            typed,
            "record_key={record_key}: {lines:#?}"
        );
        let left = journal_records(&journal)
            .0
            .into_iter()
            .filter(|r| r.line.starts_with("LEFT "))
            .count();
        assert_eq!(
            left,
            usize::from(!typed),
            "record_key={record_key}: {lines:#?}"
        );
        let _ = std::fs::remove_dir_all(&jdir);
    }
    let _ = std::fs::remove_dir_all(&dir);
}

/// A host whose conversation's record is `full`, folded as the window host
/// folds it: with the texts the session's supervisor typed, `ours`, read
/// first ([`IdleHost::finished`]).
#[derive(Debug)]
struct LedgeredRecordHost {
    full: String,
    ours: Vec<approvals::Typed>,
}

impl LedgeredRecordHost {
    fn scan(&self) -> crate::harness::upgrade::FinishedScan {
        let mut scan = crate::harness::upgrade::FinishedScan::default();
        scan.supervisor_typed(&self.ours);
        for line in self.full.lines() {
            scan.line(line);
        }
        scan
    }
}

impl IdleHost for LedgeredRecordHost {
    fn wants(&self) -> bool {
        false
    }
    fn at_idle(&self) -> Option<HostStep> {
        None
    }
    fn owns_turn_end(&self) -> bool {
        false
    }
    fn finished(&self) -> Option<bool> {
        Some(self.scan().finished())
    }
}

/// A NEW LOOP TYPES NOTHING INTO A LANDING A WALL-CUT LAND ACT'S RETRY
/// LANDED (the merge review's M5-R1): Land's instruction typed, a 529 cut
/// its turn, the wall's retry typed by the loop (its ledger) and answered
/// with a clean defense (`Nothing left: …`) — where the previous loop's
/// policy landed the task. A new loop (a seamless update, a policy reload,
/// Off lifted) attaches at that point; its host's record reads the retry's
/// answer as the land act's, and nothing is typed. FAILS WITHOUT THE FIX:
/// the record read the retry as the harness's own line and its answer as a
/// first done report, and the loop typed LAND again. Under Cruise the same
/// shape with the done check and `All done.` is a claim at the check's
/// yield, and the check is typed (FOREVER CRUISE). NEGATIVE CONTROL: the
/// same record with no ledger (the retry someone's words) gets the check
/// (Land's instruction under Land), never `keep going`.
#[test]
fn a_new_loop_types_nothing_where_a_wall_cut_land_acts_retry_landed() {
    use crate::supervise::policy::turn_end::{LAND, RULE_API_RETRY, RULE_LAND, wall_retry_text};
    let json = |text: &str| aterm_json::to_string(&aterm_json::Value::from(text)).expect("json");
    let user = |text: &str| {
        format!(
            r#"{{"isSidechain":false,"type":"user","timestamp":"1970-01-01T00:00:01.000Z","message":{{"role":"user","content":{}}},"origin":{{"kind":"human"}},"promptSource":"typed","version":"2.1.300"}}"#,
            json(text)
        )
    };
    let model = |text: &str| {
        format!(
            r#"{{"isSidechain":false,"type":"assistant","message":{{"model":"claude-opus-5-5","role":"assistant","content":[{{"type":"text","text":{}}}],"stop_reason":"end_turn"}},"version":"2.1.300"}}"#,
            json(text)
        )
    };
    let wall = r#"{"isSidechain":false,"type":"assistant","message":{"model":"<synthetic>","content":[{"type":"text","text":"API Error: 529 Overloaded"}]},"isApiErrorMessage":true,"error":"unknown"}"#;
    let closed = r#"{"isSidechain":false,"type":"system","subtype":"turn_duration","durationMs":180000,"messageCount":4,"isMeta":false}"#;
    let retry = wall_retry_text(
        RULE_API_RETRY,
        aterm_phase::WallKind::Overloaded,
        aterm_phase::Program::Claude,
    );
    for (word, asked, check, reply) in [
        (
            "cruise",
            DONE_CHECK,
            RULE_DONE_CHECK,
            "All done. Nothing left to do.",
        ),
        (
            "land",
            LAND,
            RULE_LAND,
            "Nothing left: all of it is merged into the remote main branch.",
        ),
    ] {
        let full = [
            user("Fix the lexer and land it."),
            model("Stage 1 landed."),
            user(asked),
            wall.to_string(),
            user(&retry),
            model(reply),
            closed.to_string(),
        ]
        .join("\n");
        for ledgered in [true, false] {
            let ours = if ledgered {
                vec![approvals::Typed {
                    at_ms: 1_000,
                    text: retry.clone(),
                    rule: RULE_API_RETRY.to_string(),
                }]
            } else {
                Vec::new()
            };
            let typed = !ledgered || word == "cruise";
            let mut m = Mock::new(vec![ended(reply)]);
            m.autopilot = Some(word);
            // An act that must come ends the watch, a minute its hang
            // detector; one that must not is looked for until the session
            // goes, the point decided first (its `DONE` said).
            let max = if typed {
                m.exit_when = Some(|m| m.turns > 0);
                60
            } else {
                m.vanish_after = Some(8);
                1
            };
            let (jdir, journal) = journal_file(&format!("cut-check-{word}-{ledgered}"));
            let opts = SuperviseOpts {
                policy: SupervisorConfig {
                    human_grace_s: 0,
                    ..owners_policy()
                },
                journal: Some(journal.clone()),
                idle_host: Some(Arc::new(LedgeredRecordHost {
                    full: full.clone(),
                    ours,
                }) as Arc<dyn IdleHost>),
                ..auto(max)
            };
            let (lines, _) = watch_lines_with(&mut m, &opts, |s| {
                s.set_turn_end_timing(TurnEndTiming {
                    short_backoff: Duration::from_millis(30),
                    short_backoff_max: Duration::from_millis(60),
                    ..TurnEndTiming::default()
                });
            });
            let what = format!("{word} ledgered={ledgered}: {lines:#?}");
            assert_eq!(count(&m, "turn") > 0, typed, "{what}");
            if typed {
                assert!(continued(&lines, check), "the check: {what}");
            }
            let _ = std::fs::remove_dir_all(&jdir);
        }
    }
}

// ------------------------------------------------------------------------
// Another account in the loop (`docs/DESIGN-claude-accounts-2026-10-01.md`
// §6): the host's advice, its relaunch, the tells. Labels are the design's.
// ------------------------------------------------------------------------

use crate::supervise::policy::turn_end::{AccountAt, RULE_ACCOUNT, Restart};

/// A host that keeps a roster, as a test drives it: what it advises
/// ([`IdleHost::account`]) and what its relaunch answers
/// ([`IdleHost::restart`]) are scripted — each ask takes the next entry, the
/// last for ever after — and everything the loop asked or told it is kept,
/// IN ORDER. It owns no turn end, and takes no step of its own but the
/// relaunch's last one, where a test owes it (`carry`).
#[derive(Debug, Default)]
struct AccountHost {
    advice: std::sync::Mutex<VecDeque<Option<AccountAdvice>>>,
    advised: std::sync::Mutex<Option<AccountAdvice>>,
    answers: std::sync::Mutex<VecDeque<&'static str>>,
    answered: std::sync::Mutex<Option<&'static str>>,
    said: std::sync::Mutex<Vec<String>>,
    /// [`IdleHost::account_stamp`], as a test moves it.
    stamp: std::sync::atomic::AtomicU64,
    /// The stamp moves by itself right after the FIRST ask for advice: news
    /// that lands while the session waits on that advice.
    news_after_first_ask: std::sync::atomic::AtomicBool,
    /// A relaunched agent's last step is owed: the host asks for the next
    /// idle point and takes it there ([`IdleHost::at_idle`]), once.
    carry: std::sync::atomic::AtomicBool,
    /// The word that step answers; `None`: `done:resumed`, what the relaunch
    /// of an account move answers (`relaunch::carried_quietly`: nothing
    /// typed). `continued` is a carry-on typed, what it answered before.
    step: std::sync::Mutex<Option<&'static str>>,
    /// The step is owed once a relaunch answers `adopted`, as a window's
    /// host parks it (`account_move`). Off, a test owes it by hand.
    parks: std::sync::atomic::AtomicBool,
    /// What the loop told of its exceptions ([`IdleHost::exception`]), in
    /// order, each with how many entries [`Self::said`] held then:
    /// `exception:<kind>:<when>`, `:escalated` where the loop's own
    /// escalation carries it, or `exception:none`.
    told: std::sync::Mutex<Vec<(String, usize)>>,
    /// The limit row the agent's transcript stands at
    /// ([`IdleHost::standing_limit`]: `None` too for one the host moved the
    /// conversation off), and how often it was asked.
    standing: std::sync::Mutex<Option<crate::harness::upgrade::StandingLimit>>,
    standing_asks: std::sync::atomic::AtomicUsize,
    /// The agent's process ([`IdleHost::agent_pid`]), when it started
    /// ([`IdleHost::agent_started`], unix seconds), and the conversation it
    /// holds ([`IdleHost::agent_conversation`]).
    pid: std::sync::Mutex<Option<u32>>,
    started: std::sync::Mutex<Option<i64>>,
    conversation: std::sync::Mutex<Option<String>>,
    /// The conversation the host names once it is asked for the standing
    /// limit: its ask reads the agent again, as the GUI's refreshes its
    /// snapshot.
    named_on_ask: std::sync::Mutex<Option<String>>,
    /// The process the host names once it is asked for the standing limit:
    /// a snapshot kept from before a relaunch, refreshed by the ask.
    pid_on_ask: std::sync::Mutex<Option<u32>>,
    /// [`IdleHost::login_label`]: the session's renewable login, as a test
    /// sets it.
    login_label: std::sync::Mutex<Option<String>>,
    /// [`IdleHost::transcript_tail`]: the agent's transcript, as a test sets
    /// it (`None`: none this host can read).
    tail: std::sync::Mutex<Option<String>>,
    /// [`IdleHost::login_superseded`], as a test sets it; and how many
    /// times the loop asked it.
    login_superseded: std::sync::atomic::AtomicBool,
    superseded_asked: std::sync::atomic::AtomicUsize,
    /// The renewal lands right after the host's next answer that the
    /// process holds its row's own login, before the loop reads anything
    /// else: the stamp moves, and the process is on the login it replaced.
    renews_after_answer: std::sync::atomic::AtomicBool,
    /// [`IdleHost::login_method`]: the method the session's login already
    /// is, as a test sets it.
    login_method: std::sync::Mutex<Option<aterm_phase::LoginMethod>>,
    /// [`IdleHost::roster_word`], as a test sets it; and how many times the
    /// loop asked it.
    roster: std::sync::Mutex<Option<crate::supervise::policy::turn_end::RosterWord>>,
    roster_asked: std::sync::atomic::AtomicUsize,
    /// The owner's `[harness] relaunch = false`, as a window's host reads it
    /// live ([`IdleHost::relaunch_off`]: and then no restart can be asked,
    /// [`IdleHost::can_restart`]); and how many times the loop asked it.
    relaunch_off: std::sync::atomic::AtomicBool,
    relaunch_off_asked: std::sync::atomic::AtomicUsize,
}

impl AccountHost {
    fn scripted(advice: &[Option<AccountAdvice>], answers: &[&'static str]) -> Arc<Self> {
        Arc::new(Self {
            advice: std::sync::Mutex::new(advice.iter().cloned().collect()),
            answers: std::sync::Mutex::new(answers.iter().copied().collect()),
            ..Self::default()
        })
    }

    /// The host advises a move to `to` at every point, and its relaunch
    /// answers `answer`.
    fn moving(to: &str, answer: &'static str) -> Arc<Self> {
        Self::scripted(
            &[Some(AccountAdvice::Move { to: to.to_string() })],
            &[answer],
        )
    }

    /// Everything said to it that starts with `prefix`, in order.
    fn said(&self, prefix: &str) -> Vec<String> {
        self.said
            .lock()
            .unwrap()
            .iter()
            .filter(|s| s.starts_with(prefix))
            .cloned()
            .collect()
    }

    fn all(&self) -> Vec<String> {
        self.said.lock().unwrap().clone()
    }

    /// What the loop told of its exceptions, in order, without the counts.
    fn told(&self) -> Vec<String> {
        self.told
            .lock()
            .unwrap()
            .iter()
            .map(|(word, _)| word.clone())
            .collect()
    }
}

impl IdleHost for AccountHost {
    fn wants(&self) -> bool {
        self.carry.load(Ordering::SeqCst)
    }
    fn at_idle(&self) -> Option<HostStep> {
        if !self.carry.swap(false, Ordering::SeqCst) {
            return None;
        }
        self.said.lock().unwrap().push("carry-on".to_string());
        let step = self.step.lock().unwrap().unwrap_or("done:resumed");
        Some(HostStep {
            line: format!("carry-on step={step}"),
            moved: crate::harness::upgrade_drive::moved(step),
            typed: crate::harness::upgrade_drive::host_turn(step),
            repeat: false,
        })
    }
    fn owns_turn_end(&self) -> bool {
        false
    }
    fn can_restart(&self) -> bool {
        !self.relaunch_off.load(Ordering::SeqCst)
    }
    fn relaunch_off(&self) -> bool {
        self.relaunch_off_asked.fetch_add(1, Ordering::SeqCst);
        self.relaunch_off.load(Ordering::SeqCst)
    }
    fn restart(&self, why: &Restart) -> Option<String> {
        let what = match why {
            Restart::Account { to, .. } => format!("restart:{}:{to}", why.word()),
            other => format!("restart:{}", other.word()),
        };
        self.said.lock().unwrap().push(what);
        let mut last = self.answered.lock().unwrap();
        if let Some(next) = self.answers.lock().unwrap().pop_front() {
            *last = Some(next);
        }
        if *last == Some("adopted") && self.parks.load(Ordering::SeqCst) {
            self.carry.store(true, Ordering::SeqCst);
        }
        last.map(str::to_string)
    }
    fn account(&self, point: AccountPoint) -> Option<AccountAdvice> {
        let at = match point {
            AccountPoint::Wall { kind } => format!("account:wall:{}", kind.name()),
            AccountPoint::LoginEnded => "account:login-ended".to_string(),
            AccountPoint::TurnEnd => "account:turn-end".to_string(),
        };
        self.said.lock().unwrap().push(at);
        let mut last = self.advised.lock().unwrap();
        if let Some(next) = self.advice.lock().unwrap().pop_front() {
            *last = next;
        }
        if self.news_after_first_ask.swap(false, Ordering::SeqCst) {
            self.stamp.fetch_add(1, Ordering::SeqCst);
        }
        last.clone()
    }
    fn account_stamp(&self) -> u64 {
        self.stamp.load(Ordering::SeqCst)
    }
    fn login_label(&self) -> Option<String> {
        self.login_label.lock().unwrap().clone()
    }
    fn login_method(&self) -> Option<aterm_phase::LoginMethod> {
        *self.login_method.lock().unwrap()
    }
    fn roster_word(&self) -> Option<crate::supervise::policy::turn_end::RosterWord> {
        self.roster_asked.fetch_add(1, Ordering::SeqCst);
        self.roster.lock().unwrap().clone()
    }
    fn transcript_tail(&self) -> Option<String> {
        self.tail.lock().unwrap().clone()
    }
    fn login_superseded(&self) -> bool {
        self.superseded_asked.fetch_add(1, Ordering::SeqCst);
        let superseded = self.login_superseded.load(Ordering::SeqCst);
        if !superseded && self.renews_after_answer.swap(false, Ordering::SeqCst) {
            self.login_superseded.store(true, Ordering::SeqCst);
            self.stamp.fetch_add(1, Ordering::SeqCst);
        }
        superseded
    }
    fn login_notice(&self, days: u32) {
        self.said.lock().unwrap().push(format!("notice:{days}"));
    }
    fn exception(&self, standing: Option<&crate::supervise::policy::exception::Exception>) {
        let word = standing.map_or_else(
            || "exception:none".to_string(),
            |e| {
                format!(
                    "exception:{}:{}{}",
                    e.kind.word(),
                    e.when.word(),
                    if e.escalated { ":escalated" } else { "" }
                )
            },
        );
        let at = self.said.lock().unwrap().len();
        self.told.lock().unwrap().push((word, at));
    }
    fn standing_limit(&self) -> Option<crate::harness::upgrade::StandingLimit> {
        self.standing_asks.fetch_add(1, Ordering::SeqCst);
        if let Some(named) = self.named_on_ask.lock().unwrap().take() {
            *self.conversation.lock().unwrap() = Some(named);
        }
        if let Some(pid) = self.pid_on_ask.lock().unwrap().take() {
            *self.pid.lock().unwrap() = Some(pid);
        }
        self.standing.lock().unwrap().clone()
    }
    fn agent_pid(&self) -> Option<u32> {
        *self.pid.lock().unwrap()
    }
    fn agent_started(&self) -> Option<i64> {
        *self.started.lock().unwrap()
    }
    fn agent_conversation(&self) -> Option<String> {
        self.conversation.lock().unwrap().clone()
    }
    fn account_served(&self) {
        self.said.lock().unwrap().push("served".to_string());
    }
    fn account_answered(&self, bad: AccountBad) {
        self.said.lock().unwrap().push(
            match bad {
                AccountBad::Wall => "answered:wall",
                AccountBad::SignedOut => "answered:signed-out",
            }
            .to_string(),
        );
    }
}

/// 2026-09-17T17:05:00-07:00: three minutes after [`limited_screen`]'s done
/// row, its `7:30pm` reset still ahead.
const ACCOUNT_NOW: i64 = TEST_NOW + 8 * 3600 + 10 * 60;

/// One watch over `screens` under `host`, its approval ledger at `ledger`:
/// the lines, the server's record and the journal's lines.
fn account_run(
    tag: &str,
    screens: Vec<Vec<String>>,
    host: &Arc<AccountHost>,
    ledger: &Path,
) -> (Vec<String>, Mock, Vec<String>) {
    account_run_with(tag, screens, host, ledger, |_| {})
}

/// [`account_run`] over a server `setup` changes further.
fn account_run_with(
    tag: &str,
    screens: Vec<Vec<String>>,
    host: &Arc<AccountHost>,
    ledger: &Path,
    setup: impl FnOnce(&mut Mock),
) -> (Vec<String>, Mock, Vec<String>) {
    let (dir, path) = journal_file(tag);
    let mut m = Mock::new(screens);
    m.vanish_after = Some(2);
    m.stall_sleep = Some(Duration::from_millis(5));
    setup(&mut m);
    let opts = SuperviseOpts {
        idle_host: Some(Arc::clone(host) as Arc<dyn IdleHost>),
        journal: Some(path.clone()),
        ..hosted(3)
    };
    let (lines, _) = watch_lines_with(&mut m, &opts, |s| {
        s.set_clock(ACCOUNT_NOW, PDT);
        s.set_approval_ledger(Some(ledger.to_path_buf()));
    });
    let (records, _) = journal_records(&path);
    let _ = std::fs::remove_dir_all(&dir);
    (lines, m, records.into_iter().map(|r| r.line).collect())
}

/// AT A WALL the host's advice to move is ITS RELAUNCH: asked once, the label
/// its only name — `RESTARTED seq=<n> rule=account-rotate@v1 relaunch under
/// account work-2 (…)`, a `typed` ledger row a later loop reads back as a
/// move made and still to be answered — and nothing is typed into the agent
/// at the wall. A relaunch that must wait (`wait:changed`: the agent's own
/// jobs) HOLDS the point, `WAITING … restart:account waits: …`, nothing
/// typed. One that can never be made (`refused:line`) is written down
/// (`skipped`), not asked again, and the wall is waited out as it would be.
/// (A host that advises nothing is asked for no relaunch:
/// [`news_of_the_accounts_ends_a_sessions_wait_at_its_limit`]'s control.)
#[test]
fn a_wall_with_an_account_to_move_to_is_the_hosts_relaunch() {
    use crate::supervise::approvals::{account_moves, open_account_move, open_wall};
    let wall = || vec![busy_screen(), limited_screen()];

    // Made.
    let (dir, ledger) = ledger_at("account-made");
    let host = AccountHost::moving("work-2", "adopted");
    let (lines, m, _) = account_run("te-account-made", wall(), &host, &ledger);
    assert_eq!(
        host.said("restart"),
        ["restart:account:work-2"],
        "{lines:#?}"
    );
    assert!(
        lines.iter().any(|l| l.starts_with("RESTARTED seq=")
            && l.contains(" rule=account-rotate@v1 relaunch under account work-2 ")),
        "{lines:#?}"
    );
    assert_eq!(
        count(&m, "turn"),
        0,
        "nothing typed at the wall: {:#?}",
        m.requests
    );
    assert_eq!(count(&m, "meta set attention"), 0, "{:#?}", m.requests);
    let moves = account_moves(&ledger, None);
    assert_eq!(moves.made_ms.len(), 1, "{moves:?}");
    assert!(!moves.unmade);
    let open = open_account_move(&ledger, None).expect("the move, still to be answered");
    assert_eq!((open.to.as_str(), open.at), ("work-2", AccountAt::Wall));
    assert_eq!(
        open_wall(&ledger, None),
        None,
        "the session left that wall's account: its wait is over"
    );
    let text = std::fs::read_to_string(&ledger).expect("the ledger");
    assert!(
        text.contains("\"rule_id\":\"account-rotate@v1\",\"decision\":\"typed\"")
            && text.contains("(account move: to=work-2 at=wall)"),
        "{text}"
    );
    let _ = std::fs::remove_dir_all(&dir);

    // Not yet: the point is held.
    let (dir, ledger) = ledger_at("account-waits");
    let host = AccountHost::moving("work-2", "wait:changed");
    let (lines, m, journal) = account_run("te-account-waits", wall(), &host, &ledger);
    assert!(
        journal
            .iter()
            .any(|l| l.starts_with("WAITING ") && l.contains("restart:account waits: wait:changed")),
        "{journal:#?}"
    );
    assert_eq!(count(&m, "turn"), 0, "{:#?}", m.requests);
    assert!(
        !lines.iter().any(|l| l.starts_with("RESTARTED")),
        "{lines:#?}"
    );
    assert_eq!(
        account_moves(&ledger, None),
        Default::default(),
        "nothing made, nothing refused"
    );
    let _ = std::fs::remove_dir_all(&dir);

    // Never: written down, the wall waited out.
    let (dir, ledger) = ledger_at("account-refused");
    let host = AccountHost::moving("work-2", "refused:line");
    let (lines, m, journal) = account_run("te-account-refused", wall(), &host, &ledger);
    assert_eq!(
        host.said("restart"),
        ["restart:account:work-2"],
        "asked once: {lines:#?}"
    );
    assert!(
        !lines.iter().any(|l| l.starts_with("RESTARTED")),
        "{lines:#?}"
    );
    assert_eq!(count(&m, "turn"), 0, "{:#?}", m.requests);
    let moves = account_moves(&ledger, None);
    assert!(
        moves.unmade && moves.made_ms.is_empty() && moves.open.is_none(),
        "{moves:?}"
    );
    assert!(
        open_wall(&ledger, None).is_some(),
        "the wall still stands, and is still waited on"
    );
    let waited: Vec<&String> = journal
        .iter()
        .filter(|l| l.starts_with("WAITING ") && l.contains("usage-session resets"))
        .collect();
    assert_eq!(waited.len(), 1, "{journal:#?}");
    let _ = std::fs::remove_dir_all(&dir);
}

/// A MOVE AHEAD OF A WALL THE HOST CANNOT MAKE YET (`wait:changed`: the
/// agent's own background work runs, and the relaunch would end it) NEVER
/// HOLDS THE POINT: it is deferred as the model's return is — the turn's own
/// continuation is typed, `DEFERRED … restart:account-ahead` journaled, and
/// the move is asked again at the next idle point. Held, as a move AT a wall
/// is ([`a_wall_with_an_account_to_move_to_is_the_hosts_relaunch`]), a tab
/// that always has a job running would never be continued again. NEGATIVE
/// CONTROL: a move the host makes types nothing at the point it was made —
/// the relaunched agent's first point is the next decision
/// ([`a_move_ahead_of_a_wall_types_nothing_and_its_point_is_decided_as_with_no_move`]).
#[test]
fn a_move_ahead_the_host_defers_never_holds_the_continuation() {
    let end = || vec![busy_screen(), ended("Stage 3 done; the suite is green.")];
    let (dir, ledger) = ledger_at("account-ahead-waits");
    let host = AccountHost::moving("work-2", "wait:changed");
    let (lines, m, journal) = account_run("te-account-ahead-waits", end(), &host, &ledger);
    assert_eq!(
        host.said("restart"),
        ["restart:account-ahead:work-2"],
        "{lines:#?}"
    );
    assert!(
        m.requests.contains(&continue_request("keep going")),
        "the continuation goes ahead: {:#?}",
        m.requests
    );
    assert_eq!(
        lines.iter().filter(|l| l.starts_with("CONTINUED")).count(),
        1,
        "{lines:#?}"
    );
    assert!(
        journal.iter().any(|l| l.starts_with("DEFERRED ")
            && l.contains("restart:account-ahead")
            && l.contains("wait:changed")),
        "{journal:#?}"
    );
    let _ = std::fs::remove_dir_all(&dir);

    let (dir, ledger) = ledger_at("account-ahead-made");
    let host = AccountHost::moving("work-2", "adopted");
    let (lines, m, _) = account_run("te-account-ahead-made", end(), &host, &ledger);
    assert_eq!(host.said("restart"), ["restart:account-ahead:work-2"]);
    assert!(
        lines.iter().any(|l| l.starts_with("RESTARTED seq=")
            && l.contains(" rule=account-rotate@v1 relaunch under account work-2 ")),
        "{lines:#?}"
    );
    assert_eq!(count(&m, "turn"), 0, "{:#?}", m.requests);
    assert_eq!(
        crate::supervise::approvals::open_account_move(&ledger, None).map(|o| o.at),
        Some(AccountAt::Ahead)
    );
    let _ = std::fs::remove_dir_all(&dir);
}

/// A MOVE AHEAD OF A WALL TYPES NOTHING, AND ITS POINT IS DECIDED AS WITH NO
/// MOVE (the accounts design v2, §3.5): the relaunch of an account move
/// answers `done:resumed` at the relaunched agent's first idle point
/// (`relaunch::carried_quietly`), a step that moves nothing, so the loop
/// decides that point itself — and what it types is exactly what the same
/// session was typed with no roster at all: the same decision, typed once.
/// NEGATIVE CONTROL: the same moved run whose host step TYPES (`continued`,
/// the relaunch's carry-on before 2026-10-15) takes the point, and what the
/// session is typed is no longer the decision it had with no move.
#[test]
fn a_move_ahead_of_a_wall_types_nothing_and_its_point_is_decided_as_with_no_move() {
    let done = "Stage 3 done; the suite is green.";
    // The third screen is the relaunched agent at its prompt, its
    // conversation repainted.
    let screens = || vec![busy_screen(), ended(done), ended(done)];
    let turns = |m: &Mock| -> Vec<String> {
        m.requests
            .iter()
            .filter(|r| r.starts_with("turn"))
            .cloned()
            .collect()
    };
    let run = |tag: &str, host: &Arc<AccountHost>| {
        let (dir, ledger) = ledger_at(tag);
        // The cursor at the caret, as a real agent parks it: the reader
        // vouches for the idle prompt the host's step is taken at.
        let (lines, m, journal) =
            account_run_with(&format!("te-{tag}"), screens(), host, &ledger, |m| {
                m.vanish_after = Some(4);
                m.cursor_on_caret = true;
            });
        let _ = std::fs::remove_dir_all(&dir);
        (turns(&m), format!("{lines:#?}\n{journal:#?}"), journal)
    };
    let moving = |step: Option<&'static str>| {
        let host = AccountHost::moving("work-2", "adopted");
        host.parks.store(true, Ordering::SeqCst);
        *host.step.lock().unwrap() = step;
        host
    };

    // No roster's advice: the turn's own continuation.
    let baseline = AccountHost::scripted(&[None], &["adopted"]);
    let (unmoved, log, _) = run("account-ahead-baseline", &baseline);
    assert!(baseline.said("restart").is_empty(), "{log}");
    assert_eq!(unmoved, [continue_request("keep going")], "{log}");

    // The move: made, its last step taken at the relaunched prompt with
    // nothing typed, and the point decided as with no move.
    let host = moving(None);
    let (moved, log, journal) = run("account-ahead-quiet", &host);
    assert_eq!(
        host.said("restart"),
        ["restart:account-ahead:work-2"],
        "{log}"
    );
    assert_eq!(host.said("carry-on"), ["carry-on"], "{log}");
    assert!(
        journal
            .iter()
            .any(|l| l.starts_with("HOST seq=") && l.ends_with(" carry-on step=done:resumed")),
        "{log}"
    );
    assert!(
        journal.iter().any(|l| l.starts_with("RESTARTED seq=")
            && l.ends_with("(at a turn end; the same conversation)")),
        "{log}"
    );
    assert_eq!(moved, unmoved, "the same decision, typed once: {log}");

    // NEGATIVE CONTROL: a host step that types takes the point.
    let host = moving(Some("continued"));
    let (carried, log, _) = run("account-ahead-carried", &host);
    assert_eq!(host.said("carry-on"), ["carry-on"], "{log}");
    assert!(carried.is_empty(), "the host's turn took the point: {log}");
    assert_ne!(carried, unmoved, "{log}");
}

/// A session at `rows`, its point, and the options a hosted loop has under
/// `host`.
fn account_point_of(rows: Vec<String>, phase: Phase) -> Turn {
    Turn {
        phase,
        screen: Screen {
            rows,
            seq: 102,
            cursor_col: 2,
            ..Screen::default()
        },
        timed_out: false,
    }
}

fn account_opts(host: &Arc<AccountHost>) -> SuperviseOpts {
    SuperviseOpts {
        idle_host: Some(Arc::clone(host) as Arc<dyn IdleHost>),
        ..SuperviseOpts::hosted_with(&owners_policy())
    }
}

/// THE HOST IS ASKED FOR ITS ADVICE ONCE A DECISION, however many times the
/// reading of the point is built: the decision reads it, a relaunch that
/// could not be made reads it again, and so does the act typed in its place
/// — one ask (a host that reads its roster and state file is not asked six
/// times). A point decided AGAIN asks again: that is how a session waiting
/// on every account learns one is usable. NEGATIVE CONTROL: the relaunch is
/// asked of the host as often as the decision is made, so the single ask is
/// not a decision that was skipped.
#[test]
fn the_host_is_asked_for_its_advice_once_a_decision() {
    let host = AccountHost::scripted(
        &[Some(AccountAdvice::Move {
            to: "work-2".to_string(),
        })],
        &["wait:changed"],
    );
    let opts = account_opts(&host);
    let rows = limited_screen();
    let mut m = Mock::new(vec![rows.clone()]);
    let mut s = session(&mut m, Some("@s-1".to_string()));
    s.set_clock(ACCOUNT_NOW, PDT);
    s.set_zone_lookup(test_zones);
    let point = account_point_of(
        rows,
        Phase::Limited {
            message: String::new(),
            reset: None,
        },
    );
    for round in 1..=3 {
        let action = s
            .turn_end_at_point(
                &point,
                (round == 1).then_some(Duration::from_secs(180)),
                &opts,
            )
            .expect("a decision");
        assert!(
            matches!(
                &action,
                TurnEndAction::Restart { why: Restart::Account { to, at: AccountAt::Wall }, rule_id, .. }
                    if to == "work-2" && *rule_id == RULE_ACCOUNT
            ),
            "{action:?}"
        );
        s.turn_end_execute(&point, action, &opts, &[], &mut Alone)
            .expect("the relaunch waits, it does not fail");
        assert_eq!(host.said("account").len(), round, "{:?}", host.all());
        assert_eq!(host.said("restart").len(), round, "{:?}", host.all());
    }
    assert!(
        s.turn_end_due.is_some(),
        "the point is held on the back-off"
    );
}

/// A WAIT THAT STANDS ON THE HOST'S ADVICE IS DECIDED AGAIN WHEN THE HOST'S
/// STAMP MOVES ([`IdleHost::account_stamp`], [`Session::account_edge`]; the
/// accounts design §6: the owner's `accounts use`, an account proven or
/// struck by another session — none of which moves this session's screen). A
/// session whose host advised nothing waits its wall out; the stamp moving is
/// an edge, ONCE, and the point decided again asks the host again — whose
/// advice is now the move. NEGATIVE CONTROLS: the stamp as it stood when the
/// advice was asked is no edge however often it is read; nor is a moved stamp
/// with no wait standing (an escalated point has nothing to decide again).
#[test]
fn a_wait_on_the_hosts_advice_is_decided_again_when_its_stamp_moves() {
    let host = AccountHost::scripted(
        &[
            None,
            Some(AccountAdvice::Move {
                to: "work-2".to_string(),
            }),
        ],
        &["adopted"],
    );
    let opts = account_opts(&host);
    let rows = limited_screen();
    let mut m = Mock::new(vec![rows.clone()]);
    let mut s = session(&mut m, Some("@s-1".to_string()));
    s.set_clock(ACCOUNT_NOW, PDT);
    s.set_zone_lookup(test_zones);
    let point = account_point_of(
        rows,
        Phase::Limited {
            message: String::new(),
            reset: None,
        },
    );
    host.stamp.store(7, Ordering::SeqCst);
    // Decided once: no advice, so the wall's own wait.
    let action = s
        .turn_end_at_point(&point, Some(Duration::from_secs(180)), &opts)
        .expect("a decision");
    assert!(
        matches!(action, TurnEndAction::WaitUntil { .. }),
        "{action:?}"
    );
    s.turn_end_execute(&point, action, &opts, &[], &mut Alone)
        .expect("the wait is set");
    assert!(s.turn_end_due.is_some(), "the wall is waited out");
    assert_eq!(host.said("account").len(), 1, "{:?}", host.all());
    // NEGATIVE CONTROL: the stamp as the advice was asked is no edge.
    assert!(!s.account_edge(&opts));
    assert!(!s.account_edge(&opts));

    // The accounts moved: an edge, once.
    host.stamp.store(8, Ordering::SeqCst);
    assert!(s.account_edge(&opts), "the stamp moved under a wait");
    assert!(!s.account_edge(&opts), "the same stamp is no second edge");
    // …and the point decided again asks again: the move.
    let again = s
        .turn_end_at_point(&point, None, &opts)
        .expect("a decision");
    assert!(
        matches!(
            &again,
            TurnEndAction::Restart { why: Restart::Account { to, at: AccountAt::Wall }, .. }
                if to == "work-2"
        ),
        "{again:?}"
    );
    assert_eq!(host.said("account").len(), 2, "{:?}", host.all());

    // NEGATIVE CONTROL: a moved stamp with no wait standing decides nothing.
    host.stamp.store(9, Ordering::SeqCst);
    s.turn_end_due = None;
    assert!(!s.account_edge(&opts), "nothing is waited on");
}

/// THE SEAT OF THAT EDGE IS THE LOOP'S WAIT ([`Session::wait_for_next`]): a
/// session at a usage limit whose host advised nothing, and whose stamp moves
/// while it waits, is decided again INSIDE the wait — the host is asked a
/// second time and its relaunch is made, long before the limit's reset.
/// NEGATIVE CONTROL: the same host with no news is asked once and makes no
/// relaunch (the wall is waited out, as with no roster).
#[test]
fn news_of_the_accounts_ends_a_sessions_wait_at_its_limit() {
    let wall = || vec![busy_screen(), limited_screen()];
    let script = || {
        AccountHost::scripted(
            &[
                None,
                Some(AccountAdvice::Move {
                    to: "work-2".to_string(),
                }),
            ],
            &["adopted"],
        )
    };

    let (dir, ledger) = ledger_at("account-news");
    let host = script();
    host.news_after_first_ask.store(true, Ordering::SeqCst);
    let (lines, _, journal) = account_run("te-account-news", wall(), &host, &ledger);
    assert_eq!(
        host.said("account").len(),
        2,
        "asked again inside the wait: {:?}\n{journal:#?}",
        host.all()
    );
    assert_eq!(
        host.said("restart"),
        ["restart:account:work-2"],
        "{lines:#?}"
    );
    assert!(
        lines.iter().any(|l| l.starts_with("RESTARTED seq=")),
        "{lines:#?}"
    );
    let _ = std::fs::remove_dir_all(&dir);

    // NEGATIVE CONTROL: no news, no second ask, no relaunch.
    let (dir, ledger) = ledger_at("account-no-news");
    let host = script();
    let (lines, _, _) = account_run("te-account-no-news", wall(), &host, &ledger);
    assert_eq!(host.said("account").len(), 1, "{:?}", host.all());
    assert!(host.said("restart").is_empty(), "{lines:#?}");
    let _ = std::fs::remove_dir_all(&dir);
}

/// A LOST LOGIN WITH NO ACCOUNT LEFT IS SIGNED IN WHERE IT STANDS (the
/// owner's ruling of 2026-10-19, after v0.106.0 waited at it and told
/// nobody): the session's own move to `pool-a` met a lost login, the host
/// struck it and advises nothing at all, so no move will come — the loop
/// types `/login` ONCE and, where its hand-off to the browser stands, tells
/// its host the owner is needed NOW (the notice, with no badge beside it),
/// so the window asks for the sign-in on the glass; the ask ends when the
/// agent works again. News after `/login` moves nothing: the
/// wall's act shut the move. NEGATIVE CONTROL: a session with no move
/// behind it is told the same, and its host is never asked about the
/// login. (A host that advises a wait with an end raises nothing Now-class:
/// the policy's
/// `a_lost_login_with_no_account_to_wait_for_is_signed_in_where_it_stands`.)
#[test]
fn a_lost_login_with_no_account_left_types_login_and_asks_its_sign_in_now() {
    use crate::supervise::approvals::{ACCOUNT_MOVE_COMMAND, Outcome, Row, account_switch_reason};
    let mut login = rows(&[
        "⏺ Carrying on.",
        "  ⎿  Not logged in · Please run /login",
        "",
    ]);
    login.extend(composer("  ? for shortcuts"));
    // The relaunched agent's resumed conversation: its last row is the old
    // process's notice, and it sits there until the resume is typed.
    let mut resumed = rows(&[
        "⏺ Resumed: carrying on.",
        "  ⎿  Not logged in · Please run /login",
        "",
    ]);
    resumed.extend(composer("  ? for shortcuts"));
    // The turn asked under `pool-a` meets the lost login (read again where
    // the news decides it again), the frame before the dialog draws, the
    // hand-off to the browser, the agent back at work.
    let screens = || {
        vec![
            busy_screen(),
            login.clone(),
            login.clone(),
            resumed.clone(),
            handoff(),
            handoff(),
            busy_screen(),
            ended("Carried on: stage 3 is done."),
        ]
    };
    let moved = || {
        let now_ms = crate::supervise::journal::unix_ms();
        Row {
            rule_id: RULE_ACCOUNT,
            outcome: Outcome::Typed,
            command: &format!("{ACCOUNT_MOVE_COMMAND}pool-a"),
            reason: &account_switch_reason("pool-a", AccountAt::Wall),
            box_seq: 90,
        }
        .to_json(now_ms - 60_000, None)
    };
    // The turn asked under `pool-a`, before this loop: the wall's resume.
    let resumed = || {
        let now_ms = crate::supervise::journal::unix_ms();
        Row {
            rule_id: crate::supervise::policy::turn_end::RULE_LIMIT_RESUME,
            outcome: Outcome::Typed,
            command: "keep going",
            reason: "the turn-end policy",
            box_seq: 91,
        }
        .to_json(now_ms - 50_000, None)
    };
    let run = |tag: &str, seeded: bool, host: &Arc<AccountHost>| {
        let (dir, ledger) = ledger_at(tag);
        if seeded {
            std::fs::write(&ledger, moved() + "\n" + &resumed() + "\n").expect("the ledger");
        }
        let (lines, m, journal) =
            account_run_with(&format!("te-{tag}"), screens(), host, &ledger, |m| {
                m.vanish_after = Some(4);
                m.cursor_on_caret = true;
                m.turn_releases = Some(3);
            });
        let _ = std::fs::remove_dir_all(&dir);
        let log = format!(
            "{lines:#?}\n{journal:#?}\n{:?}\n{:?}\n{:#?}",
            host.all(),
            host.told(),
            m.requests
        );
        (lines, m, journal, log)
    };

    // Stuck: `/login` once, the owner asked now, the ask withdrawn at work.
    // (The host's news after `/login` advises the move back: moved nothing.)
    let host = AccountHost::scripted(
        &[
            None,
            Some(AccountAdvice::Move {
                to: "pool-a".to_string(),
            }),
            None,
        ],
        &["adopted"],
    );
    host.news_after_first_ask.store(true, Ordering::SeqCst);
    let (lines, m, journal, log) = run("account-stuck-login", true, &host);
    let logins = |lines: &[String]| {
        lines
            .iter()
            .filter(|l| l.ends_with(" rule=auth-login@v1 /login"))
            .count()
    };
    assert_eq!(logins(&lines), 1, "`/login` once: {log}");
    assert_eq!(
        host.told(),
        ["exception:login:now", "exception:none"],
        "told once, withdrawn once: {log}"
    );
    assert!(
        journal.iter().any(|l| l.starts_with("EXCEPTION ")
            && l.contains("kind=login when=now notice=login-")),
        "{log}"
    );
    assert!(host.said("restart").is_empty(), "{log}");
    assert!(
        !m.requests
            .iter()
            .any(|r| r.starts_with("meta set attention")),
        "no badge beside the notice: {log}"
    );

    // NEGATIVE CONTROL: no move behind the session — the same.
    let host = AccountHost::scripted(&[None], &["adopted"]);
    let (lines, _, _, log) = run("account-stuck-login-none", false, &host);
    assert_eq!(logins(&lines), 1, "{log}");
    assert_eq!(
        host.told(),
        ["exception:login:now", "exception:none"],
        "{log}"
    );
    assert!(
        !host
            .said("account")
            .iter()
            .any(|s| s == "account:wall:auth"),
        "no host is asked about the login the person lost: {log}"
    );
}

/// A ONE-LOGIN MACHINE'S LOGIN ENDS (accounts v2 S7, REVERSED BY THE
/// OWNER'S RULING OF 2026-10-19 — v0.106.0's very configuration: one roster
/// row with an email, `accounts = "off"`, `logins` on): there is no move
/// behind it and the host advises none, so the loop types `/login` ONCE and,
/// where its hand-off to the browser stands, tells its host the owner is
/// needed NOW (no badge beside it) to finish the sign-in in the browser —
/// never a renewal. The ask ends when the agent
/// works again. Claude Code's expiry notice on a screen is told to the host
/// once. NEGATIVE CONTROL: `logins = "off"` is the same `/login`, and asks
/// the host nothing.
#[test]
fn a_one_login_machine_types_login_once_and_asks_its_sign_in_now() {
    let mut login = rows(&[
        "⏺ Carrying on.",
        "  ⎿  Not logged in · Please run /login",
        "",
    ]);
    login.extend(composer("  ? for shortcuts"));
    // Claude Code's notice where it parks a notification, at the end.
    let mut noticed = rows(&[
        "⏺ Carried on: stage 3 is done.",
        "",
        "✻ Worked for 3m 2s · done 4:24 PM",
        &format!(
            "{:>118}",
            "\u{26a0} Your login expires in 2 days \u{b7} run /login to renew"
        ),
    ]);
    noticed.extend(composer("  ? for shortcuts"));
    let mut resumed = rows(&[
        "⏺ Resumed: carrying on.",
        "  ⎿  Not logged in · Please run /login",
        "",
    ]);
    resumed.extend(composer("  ? for shortcuts"));
    let screens = || {
        vec![
            busy_screen(),
            login.clone(),
            login.clone(),
            resumed.clone(),
            handoff(),
            handoff(),
            busy_screen(),
            noticed.clone(),
        ]
    };
    let run = |tag: &str, host: &Arc<AccountHost>, logins: bool| {
        let (dir, ledger) = ledger_at(tag);
        let (journal_dir, path) = journal_file(&format!("te-{tag}"));
        let mut m = Mock::new(screens());
        m.vanish_after = Some(4);
        m.stall_sleep = Some(Duration::from_millis(5));
        m.cursor_on_caret = true;
        m.turn_releases = Some(3);
        let mut opts = SuperviseOpts {
            idle_host: Some(Arc::clone(host) as Arc<dyn IdleHost>),
            journal: Some(path.clone()),
            ..hosted(3)
        };
        opts.policy.accounts = crate::harness::accounts::Mode::Off;
        opts.policy.logins = logins;
        let (lines, _) = watch_lines_with(&mut m, &opts, |s| {
            s.set_clock(ACCOUNT_NOW, PDT);
            s.set_approval_ledger(Some(ledger.clone()));
        });
        let (records, _) = journal_records(&path);
        let journal: Vec<String> = records.into_iter().map(|r| r.line).collect();
        let _ = std::fs::remove_dir_all(&dir);
        let _ = std::fs::remove_dir_all(&journal_dir);
        let log = format!(
            "{lines:#?}\n{journal:#?}\n{:?}\n{:?}\n{:#?}",
            host.all(),
            host.told(),
            m.requests
        );
        (lines, m, journal, log)
    };
    let logins = |lines: &[String]| {
        lines
            .iter()
            .filter(|l| l.ends_with(" rule=auth-login@v1 /login"))
            .count()
    };
    let host = AccountHost::scripted(&[None], &["adopted"]);
    *host.login_label.lock().unwrap() = Some("m7-a".to_string());
    let (lines, m, journal, log) = run("one-login-renew", &host, true);
    assert_eq!(logins(&lines), 1, "`/login` once: {log}");
    assert_eq!(host.said("notice"), ["notice:2"], "told once: {log}");
    assert_eq!(
        host.told(),
        ["exception:login:now", "exception:none"],
        "{log}"
    );
    assert!(
        journal.iter().any(|l| l.starts_with("EXCEPTION ")
            && l.contains("kind=login when=now notice=login-")),
        "{log}"
    );
    assert!(
        !journal.iter().any(|l| l.contains("accounts renew")),
        "no renewal asked: {log}"
    );
    assert!(host.said("restart").is_empty(), "{log}");
    assert!(
        !m.requests
            .iter()
            .any(|r| r.starts_with("meta set attention")),
        "no badge beside the notice: {log}"
    );

    // NEGATIVE CONTROL: the logins' lifecycle off — the same `/login`.
    let host = AccountHost::scripted(&[None], &["adopted"]);
    *host.login_label.lock().unwrap() = Some("m7-a".to_string());
    let (lines, _, _, log) = run("one-login-off", &host, false);
    assert_eq!(logins(&lines), 1, "{log}");
    assert!(host.said("account").is_empty(), "nothing asked: {log}");
}

/// THE SIGN-IN'S NOTICE OUTLASTS ITS DIALOG'S BUSY READS (the review's F6,
/// `run.rs`'s busy read, [`crate::supervise::policy::login::dialog_stands`]):
/// once `/login`'s hand-off stands and its notice is told, a read of the
/// dialog's own spinner (`Opening browser to sign in…`, which reads busy) is
/// no agent working: the notice stands, and ends only with the loop. MEASURED
/// before in the real-Claude lab: read as the agent working, the hand-off
/// took the owner's notice down while its URL and paste field stood.
/// NEGATIVE CONTROL: the agent's own busy read in its place ends it, "the
/// agent working".
#[test]
fn the_sign_ins_notice_outlasts_its_dialogs_busy_reads() {
    let mut login = rows(&[
        "⏺ Carrying on.",
        "  ⎿  Not logged in · Please run /login",
        "",
    ]);
    login.extend(composer("  ? for shortcuts"));
    // The dialog's spinner as Claude Code draws it while the browser opens,
    // with its busy footer: a busy read of the dialog.
    let mut spinning =
        aterm_phase::prompt::fixtures::screen(aterm_phase::prompt::fixtures::LOGIN_OPENING);
    for row in &mut spinning {
        if row.contains("Opening browser to sign in") {
            *row = "  ✻ Opening browser to sign in… (3s · esc to interrupt)".to_string();
        }
    }
    assert!(crate::supervise::policy::login::dialog_stands(&spinning));
    let run = |tag: &str, busy: Vec<String>| {
        let (dir, path) = journal_file(tag);
        let mut m = Mock::new(vec![
            busy_screen(),
            login.clone(),
            login.clone(),
            login.clone(),
            handoff(),
            handoff(),
            busy,
            handoff(),
        ]);
        m.vanish_after = Some(3);
        m.cursor_on_caret = true;
        m.turn_releases = Some(3);
        let opts = SuperviseOpts {
            journal: Some(path.clone()),
            ..hosted(3)
        };
        let (lines, _) = watch_lines(&mut m, &opts);
        let (records, _) = journal_records(&path);
        let _ = std::fs::remove_dir_all(&dir);
        let journal: Vec<String> = records.into_iter().map(|r| r.line).collect();
        let log = format!("{lines:#?}\n{journal:#?}\n{:#?}", m.requests);
        (journal, log)
    };
    let raised = |journal: &[String]| {
        journal
            .iter()
            .filter(|l| {
                l.starts_with("EXCEPTION ") && l.contains("kind=login when=now notice=login-")
            })
            .count()
    };
    let working = |journal: &[String]| {
        journal
            .iter()
            .any(|l| l.starts_with("CLEARED ") && l.ends_with(" the agent working"))
    };
    let (journal, log) = run("te-signin-busy", spinning);
    assert_eq!(raised(&journal), 1, "told once: {log}");
    assert!(!working(&journal), "the dialog's spinner is no work: {log}");
    // NEGATIVE CONTROL: the agent's own busy read ends it.
    let (journal, log) = run("te-signin-work", busy_screen());
    assert!(raised(&journal) >= 1, "{log}");
    assert!(working(&journal), "{log}");
}

/// `/login`'s SUCCESS GETS ITS ENTER ONCE, AT SESSION LEVEL (the review's F8,
/// [`Session::confirm_dialog`]): the loop's own `/login` signed in, Claude
/// Code's `Login successful. Press Enter to continue…` is pressed once —
/// fenced on the read's generation and person count and on the success row
/// — booked `TYPED … rule=login-done@v1`. NEGATIVE CONTROL: a person's key
/// between the read and the press skips it, and nothing is booked.
#[test]
fn the_login_success_gets_one_fenced_enter() {
    let mut login = rows(&[
        "⏺ Carrying on.",
        "  ⎿  Not logged in · Please run /login",
        "",
    ]);
    login.extend(composer("  ? for shortcuts"));
    let success =
        aterm_phase::prompt::fixtures::screen(aterm_phase::prompt::fixtures::LOGIN_SUCCESS);
    let run = |tag: &str, person_at_key: usize| {
        let (dir, path) = journal_file(tag);
        let mut m = Mock::new(vec![
            busy_screen(),
            login.clone(),
            login.clone(),
            login.clone(),
            success.clone(),
            success.clone(),
        ]);
        m.vanish_after = Some(3);
        m.cursor_on_caret = true;
        m.turn_releases = Some(3);
        m.sends_gen = true;
        m.gen_fence = true;
        m.human_seq = Some(3);
        m.person_at_key = person_at_key;
        let opts = SuperviseOpts {
            journal: Some(path.clone()),
            ..hosted(3)
        };
        let (lines, _) = watch_lines(&mut m, &opts);
        let (records, _) = journal_records(&path);
        let _ = std::fs::remove_dir_all(&dir);
        let journal: Vec<String> = records.into_iter().map(|r| r.line).collect();
        let log = format!("{lines:#?}\n{journal:#?}\n{:#?}", m.requests);
        (lines, journal, m, log)
    };
    let enters = |m: &Mock| -> Vec<String> {
        m.requests
            .iter()
            .filter(|r| r.starts_with("key ") && r.ends_with(" enter"))
            .cloned()
            .collect()
    };
    let done = |lines: &[String]| {
        lines
            .iter()
            .filter(|l| l.starts_with("TYPED ") && l.contains(" rule=login-done@v1 enter at "))
            .count()
    };
    let (lines, _, m, log) = run("te-login-done", 0);
    let pressed = enters(&m);
    assert_eq!(pressed.len(), 1, "one Enter: {log}");
    assert!(
        pressed[0].contains("if-human=3 ")
            && pressed[0].contains(" if-gen=")
            && pressed[0].contains(" if=^\\x20{2}Login\\x20successful"),
        "fenced on the read and its row: {log}"
    );
    assert_eq!(done(&lines), 1, "{log}");
    // NEGATIVE CONTROL: a person keyed before the press.
    let (lines, journal, _, log) = run("te-login-done-person", 1);
    assert_eq!(done(&lines), 0, "{log}");
    assert!(
        journal
            .iter()
            .any(|l| l.starts_with("SKIPPED ") && l.contains(" rule=login-done@v1 enter: ")),
        "{log}"
    );
    // Direct entry controls the execution boundary, not the policy's decision.
    // Heard is unattended: Alone would bypass the stall guard.
    let direct = |program: &str, stalled: bool, counted: bool, generated: bool| {
        let mut m = fenced(vec![success.clone()]);
        let mut heard = Heard::default();
        {
            let mut s = session(&mut m, None);
            s.set_clock(TEST_NOW, PDT);
            s.set_zone_lookup(test_zones);
            s.program = Some(program.to_string());
            let read = s.screen().expect("the captured success screen");
            let mut point = point_at(&s, read.rows.clone(), read.seq);
            point.screen = read;
            if !counted {
                point.screen.human_seq = None;
            }
            if !generated {
                point.screen.generation = None;
            }
            s.stall_suspect = stalled;
            let row = success
                .iter()
                .find(|row| row.contains("Login successful"))
                .unwrap()
                .clone();
            s.turn_end_execute(
                &point,
                TurnEndAction::Confirm {
                    rule_id: crate::supervise::policy::login::RULE_LOGIN_DONE,
                    row,
                },
                &hosted(3),
                &[],
                &mut heard,
            )
            .expect("the captured action is handled");
        }
        (enters(&m), heard)
    };
    let (pressed, heard) = direct("claude", false, true, true);
    assert_eq!(pressed.len(), 1, "ordinary guarded execution");
    assert!(pressed[0].contains("if-human=7 ") && pressed[0].contains(" if-gen="));
    assert_eq!(done(&heard.said), 1);
    for (program, stalled, counted, generated) in [
        ("zsh", false, true, true),
        ("claude", true, true, true),
        ("claude", false, false, true),
        ("claude", false, true, false),
    ] {
        let (pressed, heard) = direct(program, stalled, counted, generated);
        assert!(
            pressed.is_empty(),
            "{program} {stalled} {counted} {generated}"
        );
        assert_eq!(done(&heard.said), 0);
    }
}

/// THE PICKER OF THE LOOP'S OWN `/login` IS ANSWERED WITH THE METHOD THE
/// LOGIN ALREADY IS, AT SESSION LEVEL (the review's F8, the approval loop's
/// [`crate::supervise::policy::login::RULE_LOGIN_METHOD`]): the host says the
/// session's login is a subscription ([`IdleHost::login_method`]), so the
/// picker its `/login` opened gets that row — its keys fenced on the read's
/// person count. NEGATIVE CONTROLS: a host that says nothing leaves the
/// picker to the owner, no key pressed; and the read with no person count
/// to fence a key on presses nothing.
#[test]
fn the_picker_of_its_own_login_gets_the_method_the_login_is() {
    let mut login = rows(&[
        "⏺ Carrying on.",
        "  ⎿  Not logged in · Please run /login",
        "",
    ]);
    login.extend(composer("  ? for shortcuts"));
    let picker = aterm_phase::prompt::fixtures::screen(aterm_phase::prompt::fixtures::LOGIN_PICKER);
    let run = |tag: &str, method: Option<aterm_phase::LoginMethod>, counted: bool| {
        let (dir, path) = journal_file(tag);
        let mut m = fenced(vec![
            busy_screen(),
            login.clone(),
            login.clone(),
            login.clone(),
            picker.clone(),
            handoff(),
        ]);
        m.vanish_after = Some(3);
        m.cursor_on_caret = true;
        m.turn_releases = Some(3);
        m.key_releases = Some(4);
        if !counted {
            m.human_seq = None;
        }
        let host = AccountHost::scripted(&[None], &["adopted"]);
        *host.login_method.lock().unwrap() = method;
        let opts = SuperviseOpts {
            idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
            journal: Some(path.clone()),
            ..hosted(3)
        };
        let (lines, _) = watch_lines(&mut m, &opts);
        let (records, _) = journal_records(&path);
        let _ = std::fs::remove_dir_all(&dir);
        let journal: Vec<String> = records.into_iter().map(|r| r.line).collect();
        let log = format!("{lines:#?}\n{journal:#?}\n{:#?}", m.requests);
        (m, log)
    };
    let keys = |m: &Mock| -> Vec<String> {
        m.requests
            .iter()
            .filter(|r| r.starts_with("key "))
            .cloned()
            .collect()
    };
    let subscription = Some(aterm_phase::LoginMethod::Subscription);
    let (m, log) = run("te-picker", subscription, true);
    let pressed = keys(&m);
    assert_eq!(
        pressed.len(),
        1,
        "the focused subscription row's Enter: {log}"
    );
    assert!(
        pressed[0].starts_with("key if-human=7 ")
            && pressed[0].contains("Claude\\x20account\\x20with\\x20subscription")
            && pressed[0].ends_with(" enter"),
        "fenced on the person and its row: {log}"
    );
    // NEGATIVE CONTROLS: nothing says the method; no person count.
    let (m, log) = run("te-picker-unsaid", None, true);
    assert!(keys(&m).is_empty(), "the owner's pick: {log}");
    let (m, log) = run("te-picker-uncounted", subscription, false);
    assert!(keys(&m).is_empty(), "no key without its fence: {log}");
}

/// A RENEWED LOGIN THAT NOTHING RELAUNCHES THE TAB ONTO (accounts v2 S7,
/// `relaunch = false`): the session's process is still on the login the
/// renewal replaced, as its host says at the lost login
/// ([`IdleHost::login_superseded`]), so no renewal reaches it. The loop
/// types no `/login` and asks no renewal again: the notice it tells names
/// the step by hand (`/login` in the tab), and its own escalation stands
/// down for it — one surface.
/// NEGATIVE CONTROL: the same wall with the process on its row's own login
/// is signed in where it stands: `/login` (the owner's ruling of
/// 2026-10-19), never the renewal.
#[test]
fn a_renewed_login_nothing_relaunches_the_tab_onto_is_never_renewed_again() {
    let mut login = rows(&[
        "⏺ Carrying on.",
        "  ⎿  Not logged in · Please run /login",
        "",
    ]);
    login.extend(composer("  ? for shortcuts"));
    let run = |tag: &str, superseded: bool| {
        let (dir, ledger) = ledger_at(tag);
        let (journal_dir, path) = journal_file(&format!("te-{tag}"));
        // A `/login` typed opens its hand-off to the browser.
        let mut screens = vec![busy_screen(), login.clone(), login.clone()];
        if !superseded {
            screens.push(handoff());
        }
        let mut m = Mock::new(screens);
        m.vanish_after = Some(3);
        m.cursor_on_caret = true;
        m.turn_releases = Some(1);
        let host = AccountHost::scripted(&[None], &["adopted"]);
        *host.login_label.lock().unwrap() = Some("m7-a".to_string());
        host.login_superseded.store(superseded, Ordering::SeqCst);
        let mut opts = SuperviseOpts {
            idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
            journal: Some(path.clone()),
            ..hosted(3)
        };
        opts.policy.accounts = crate::harness::accounts::Mode::Off;
        opts.policy.relaunch = false;
        let (lines, _) = watch_lines_with(&mut m, &opts, |s| {
            s.set_clock(ACCOUNT_NOW, PDT);
            s.set_approval_ledger(Some(ledger.clone()));
        });
        let (records, _) = journal_records(&path);
        let journal: Vec<String> = records.into_iter().map(|r| r.line).collect();
        let _ = std::fs::remove_dir_all(&dir);
        let _ = std::fs::remove_dir_all(&journal_dir);
        let log = format!(
            "{lines:#?}\n{journal:#?}\n{:?}\n{:?}\n{:#?}",
            host.all(),
            host.told(),
            m.requests
        );
        (m, journal, host, log)
    };
    let (m, journal, host, log) = run("renewed-by-hand", true);
    assert!(
        host.superseded_asked.load(Ordering::SeqCst) > 0,
        "asked at the lost login: {log}"
    );
    let by_hand = crate::supervise::policy::notice::RENEWED_BY_HAND.id;
    assert!(
        journal.iter().any(|l| l.starts_with("EXCEPTION ")
            && l.contains(&format!("kind=login when=now notice={by_hand}"))),
        "{log}"
    );
    assert!(
        !m.requests
            .iter()
            .any(|r| r.starts_with("meta set attention")),
        "the notice is the one surface: no badge beside it: {log}"
    );
    assert!(
        journal.iter().any(|l| l.starts_with("NOT ESCALATED ")
            && l.contains(&format!("the notice {by_hand} stands"))),
        "the loop's escalation stands down for the notice: {log}"
    );
    assert!(
        !journal.iter().any(|l| l.contains("accounts renew m7-a")),
        "no renewal asked again: {log}"
    );
    assert!(
        !m.requests
            .iter()
            .any(|r| !r.starts_with("meta ") && r.contains("/login")),
        "no /login: {log}"
    );
    assert!(host.said("restart").is_empty(), "nothing relaunched: {log}");

    // NEGATIVE CONTROL: on its row's own login, signed in where it stands.
    let (m, journal, _, log) = run("renew-by-hand", false);
    assert!(
        journal.iter().any(|l| l.starts_with("EXCEPTION ")
            && l.contains("kind=login when=now notice=login-")),
        "{log}"
    );
    assert!(
        m.requests
            .iter()
            .any(|r| r.starts_with("turn ") && r.ends_with(" /login")),
        "{log}"
    );
    assert!(
        !journal.iter().any(|l| l.contains("accounts renew m7-a")),
        "{log}"
    );
}

/// THE RENEWAL'S EDGE KEEPS WHAT THE DECISION READ (accounts v2 S7): the
/// host's stamp is read before it answers whether the process holds a login
/// a renewal replaced, so a renewal that lands right after that answer, before
/// the loop reads anything else, is news to the point decided on it; and a
/// read for the loop's books after the decision (its own answer the
/// renewal's) leaves the decision's mark alone, so the wait's edge still
/// decides the point again, once. NEGATIVE CONTROLS: while the stamp stands
/// still the host is not asked again, however many steps the wait takes;
/// news of something else asks it once and keeps the point.
#[test]
fn the_renewal_edge_keeps_what_the_decision_read() {
    let mut login = rows(&[
        "⏺ Carrying on.",
        "  ⎿  Not logged in · Please run /login",
        "",
    ]);
    login.extend(composer("  ? for shortcuts"));
    let screen = Screen {
        rows: login.clone(),
        seq: 102,
        cursor_col: 2,
        ..Screen::default()
    };
    let host = AccountHost::scripted(&[None], &["adopted"]);
    *host.login_label.lock().unwrap() = Some("m7-a".to_string());
    let mut opts = account_opts(&host);
    opts.policy.accounts = crate::harness::accounts::Mode::Off;
    opts.policy.relaunch = false;
    let mut m = Mock::new(vec![login]);
    let mut s = session(&mut m, Some("@s-1".to_string()));
    s.set_clock(ACCOUNT_NOW, PDT);
    let asked = || host.superseded_asked.load(Ordering::SeqCst);
    let r = s.turn_end_reading(&screen, None, &opts);
    assert_eq!(r.login_label.as_deref(), Some("m7-a"));
    assert!(!r.login_superseded);
    assert_eq!(asked(), 1);
    // NEGATIVE CONTROL: no news, no ask.
    for _ in 0..3 {
        assert!(!s.account_edge(&opts));
    }
    assert_eq!(asked(), 1);
    // NEGATIVE CONTROL: news of something else, asked once; the point kept.
    host.stamp.fetch_add(1, Ordering::SeqCst);
    assert!(!s.account_edge(&opts));
    assert!(!s.account_edge(&opts));
    assert_eq!(asked(), 2);
    // The renewal lands right after the decision's answer.
    host.renews_after_answer.store(true, Ordering::SeqCst);
    let r = s.turn_end_reading(&screen, None, &opts);
    assert!(!r.login_superseded);
    let books = s.turn_end_reread(&screen, &opts);
    assert!(books.login_superseded);
    assert!(s.account_edge(&opts), "the renewal decides the point again");
    assert!(!s.account_edge(&opts), "once");
}

/// THE HOST IS TOLD ONCE WHAT ANSWERED THE MOVE, and of a bad answer BEFORE
/// the same point asks its advice — so a host that strikes the account there
/// advises the next one in its very next answer. Served: the first turn
/// asked after the relaunch ran and ended with no wall. A usage limit: only
/// once a turn was asked under the new login. A lost login: likewise, only
/// once a turn was asked under the new login. NEGATIVE CONTROLS: a session
/// that made no move is told nothing; a limit on the resumed screen before
/// any turn was asked is told as nothing and asked about as nothing (it is
/// the old account's notice: the wall's resume is owed there); and a lost
/// login before any turn was asked is told nothing and asks the host nothing
/// (the old process's notice).
/// THE ROSTER'S WORD ON THE SESSION'S LOGIN IS ASKED AT A WEEKLY LIMIT
/// (the review's acct-1, acct-7): once a decision, onto the reading the
/// owner's notice is chosen on, before the host is asked for its advice.
/// NEGATIVE CONTROLS: a session limit, and a plain turn end, ask nothing and
/// carry no word.
#[test]
fn the_rosters_word_is_asked_at_a_weekly_limit_alone() {
    use crate::supervise::policy::turn_end::{RosterWord, TurnEndReading};
    let host = Arc::new(AccountHost {
        roster: std::sync::Mutex::new(Some(RosterWord::Unread)),
        ..AccountHost::default()
    });
    let opts = SuperviseOpts {
        idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
        ..hosted(30)
    };
    let walled = |message: &str| {
        let mut r = rows(&["⏺ Carrying on.", &format!("  ⎿  {message}"), ""]);
        r.extend(composer("  ? for shortcuts"));
        TurnEndReading::of(
            &aterm_phase::ClaudeReader.read(&r, Some(2)),
            &r,
            false,
            None,
            None,
            None,
        )
    };
    let mut m = Mock::new(vec![busy_screen()]);
    let mut s = session(&mut m, None);
    let mut weekly =
        walled("You've hit your weekly limit · resets Oct 23 at 8am (America/Los_Angeles)");
    assert_eq!(weekly.wall, Some(aterm_phase::WallKind::UsageWeekly));
    s.account_advise(&mut weekly, 7, &opts);
    assert_eq!(weekly.roster, Some(RosterWord::Unread));
    assert_eq!(host.roster_asked.load(Ordering::SeqCst), 1);
    // NEGATIVE CONTROLS.
    for message in [
        "You've hit your session limit · resets 3pm (America/Los_Angeles)",
        "",
    ] {
        let mut r = walled(message);
        assert_ne!(
            r.wall,
            Some(aterm_phase::WallKind::UsageWeekly),
            "{message}"
        );
        s.account_advise(&mut r, 8, &opts);
        assert_eq!(r.roster, None, "{message}");
    }
    assert_eq!(host.roster_asked.load(Ordering::SeqCst), 1);
}

/// A `/login` LEFT AT A WEEKLY LIMIT ASKS THE ROSTER'S WORD TOO (the review
/// of the login carry, acct3-1): `❯ /login` / `⎿  Login interrupted` draws
/// over the limit's row, the reader gives no wall there, and asked at the
/// row alone the loop handed the notice no word — the owner was told to type
/// `/login` in the tab, which writes whatever account the browser signs in
/// into the roster row's own login. With the limit's track standing, the word
/// is asked there and the notice is the roster's step. NEGATIVE CONTROL: a
/// login no row names is still told to sign in in the tab — to another
/// account, the limit's own notice (r5h-4: signed in again, the same
/// account's limit stands).
#[test]
fn a_login_left_at_a_weekly_limit_asks_the_rosters_word() {
    use crate::supervise::policy::exception::exception_for;
    use crate::supervise::policy::turn_end::{RosterWord, SignInNext, TurnEndReading};
    use aterm_phase::prompt::fixtures::{LOGIN_EXPIRED, screen};
    let weekly_row = "⏺ You've hit your weekly limit · resets Oct 23 at 8am (America/Los_Angeles)";
    let with_tail = |tail: &[&str]| {
        let mut r = screen(LOGIN_EXPIRED);
        let at = r
            .iter()
            .position(|row| row.starts_with("⏺ Login expired"))
            .expect("the wall row");
        r.splice(at..=at, tail.iter().map(|s| (*s).to_string()));
        r
    };
    let read = |rows: &[String], worked: Option<Duration>| {
        TurnEndReading::of(
            &aterm_phase::ClaudeReader.read(rows, Some(2)),
            rows,
            false,
            worked,
            None,
            None,
        )
    };
    let next = RosterWord::Row {
        next: Some(SignInNext {
            label: "m8-2".to_string(),
            renew: true,
        }),
        ready: None,
        held: None,
    };
    for (word, id) in [
        (next, "limit-renew"),
        // NEGATIVE CONTROL.
        (RosterWord::Unlisted, "limit-sign-in"),
    ] {
        let host = Arc::new(AccountHost {
            roster: std::sync::Mutex::new(Some(word.clone())),
            ..AccountHost::default()
        });
        let opts = account_opts(&host);
        let mut m = Mock::new(vec![busy_screen()]);
        let mut s = session(&mut m, None);
        let t = Instant::now();
        let mut weekly = read(&with_tail(&[weekly_row]), Some(Duration::from_secs(180)));
        assert_eq!(weekly.wall, Some(aterm_phase::WallKind::UsageWeekly));
        s.turn_end.observe(&weekly, t);
        s.account_advise(&mut weekly, 7, &opts);
        let asked = host.roster_asked.load(Ordering::SeqCst);
        assert_eq!(asked, 1, "{word:?}");
        let rows = with_tail(&[weekly_row, "", "❯ /login", "  ⎿  Login interrupted"]);
        // The host relaunches the tab (`AccountHost::can_restart`), as the
        // loop's own reading says: a renewal's switch can follow (r3h-2).
        let mut left = TurnEndReading {
            person: Some(Duration::from_secs(5)),
            restartable: opts.idle_host.as_ref().is_some_and(|h| h.can_restart()),
            ..read(&rows, Some(Duration::from_secs(20)))
        };
        assert_eq!(left.wall, None, "the row drawn over");
        assert!(left.login_interrupted);
        let now = t + Duration::from_secs(90);
        s.turn_end.observe(&left, now);
        s.account_advise(&mut left, 8, &opts);
        assert_eq!(
            host.roster_asked.load(Ordering::SeqCst),
            asked + 1,
            "{word:?}"
        );
        assert_eq!(left.roster.as_ref(), Some(&word));
        let e = exception_for(&s.turn_end, &left, &opts.policy, now).expect("told");
        assert_eq!(e.notice.as_ref().map(|n| n.id), Some(id), "{word:?}: {e:?}");
    }
}

/// THE OWNER'S `relaunch = false` IS NAMED AT A WEEKLY LIMIT (the review of
/// the login carry, r4h-1): a window's host masks the key out of the loop's
/// config, so the policy read `relaunch` on whatever the owner set, and a
/// tab beside a ready row was told no listed account could take over. The
/// loop asks the host for it where the roster's word is read, and the notice
/// names the line that lets the tab switch. NEGATIVE CONTROLS: with the
/// relaunch on, the same limit is the ready row's `accounts use`; a session
/// limit, whose roster word is not read, asks the host nothing of it.
#[test]
fn a_relaunch_the_host_switched_off_is_named_at_a_weekly_limit() {
    use crate::supervise::policy::exception::exception_for;
    use crate::supervise::policy::turn_end::{HeldBy, Ready, RosterWord, TurnEndReading};
    let walled = |message: &str, host: &AccountHost| {
        let mut r = rows(&["⏺ Carrying on.", &format!("  ⎿  {message}"), ""]);
        r.extend(composer("  ? for shortcuts"));
        TurnEndReading {
            // As the loop sets it ([`IdleHost::can_restart`]).
            restartable: host.can_restart(),
            ..TurnEndReading::of(
                &aterm_phase::ClaudeReader.read(&r, Some(2)),
                &r,
                false,
                None,
                None,
                None,
            )
        }
    };
    let word = RosterWord::Row {
        next: None,
        ready: Some(Ready {
            label: "m8-3".to_string(),
        }),
        held: Some(HeldBy::Earlier),
    };
    // The ready row is one the roster holds the tab off (the limit came
    // before this Claude Code): with the relaunch on, the next step is named.
    for (off, id, step) in [
        (true, "limit-stay-held", "relaunch = true"),
        // NEGATIVE CONTROL.
        (false, "limit-use", "aterm harness accounts use m8-3"),
    ] {
        let host = Arc::new(AccountHost {
            roster: std::sync::Mutex::new(Some(word.clone())),
            relaunch_off: std::sync::atomic::AtomicBool::new(off),
            ..AccountHost::default()
        });
        let opts = account_opts(&host);
        assert!(opts.policy.relaunch, "the host's config never says it off");
        let mut m = Mock::new(vec![busy_screen()]);
        let mut s = session(&mut m, None);
        let t = Instant::now();
        let mut weekly = walled(
            "You've hit your weekly limit · resets Oct 23 at 8am (America/Los_Angeles)",
            &host,
        );
        assert_eq!(weekly.wall, Some(aterm_phase::WallKind::UsageWeekly));
        weekly.reset_at = Some(t + Duration::from_secs(6 * 24 * 3600));
        s.turn_end.observe(&weekly, t);
        s.account_advise(&mut weekly, 7, &opts);
        assert_eq!(weekly.relaunch_off, off);
        assert_eq!(host.relaunch_off_asked.load(Ordering::SeqCst), 1, "{off}");
        let e = exception_for(&s.turn_end, &weekly, &opts.policy, t).expect("told");
        assert_eq!(e.notice.as_ref().map(|n| n.id), Some(id), "{off}: {e:?}");
        assert!(e.action.contains(step), "{off}: {e:?}");
        // NEGATIVE CONTROL: a session limit reads no roster word, and asks
        // nothing of the relaunch.
        let mut session_limit = walled(
            "You've hit your session limit · resets 3pm (America/Los_Angeles)",
            &host,
        );
        s.account_advise(&mut session_limit, 8, &opts);
        assert!(!session_limit.relaunch_off, "{off}");
        assert_eq!(host.relaunch_off_asked.load(Ordering::SeqCst), 1, "{off}");
    }
}

/// A RELAUNCH THE OWNER SWITCHES ON REACHES A TAB WAITING AT ITS WEEKLY LIMIT
/// (the review of the login carry, r5h-1): with the host's `relaunch` off no
/// advice is asked there — no move could follow — so the decision kept none,
/// and the stamp the host moves at the owner's edit (`relaunch` is masked
/// out of the loop's config and hands no worker over) was news to nothing:
/// the tab waited the week out under a notice naming `relaunch = true`, a
/// line already set. The decision read the roster's word, and that is enough
/// to hear the news: an edge, once, and the point decided again asks the
/// host, whose move is made. NEGATIVE CONTROLS: the stamp as it stood is no
/// edge; a session limit, whose roster word is not read, waits on.
#[test]
fn a_relaunch_switched_on_reaches_a_tab_waiting_at_its_weekly_limit() {
    use crate::supervise::policy::turn_end::{Ready, RosterWord};
    let wait_at = |message: &str| {
        let host = AccountHost::moving("m8-3", "adopted");
        *host.roster.lock().unwrap() = Some(RosterWord::Row {
            next: None,
            ready: Some(Ready {
                label: "m8-3".to_string(),
            }),
            held: None,
        });
        host.relaunch_off.store(true, Ordering::SeqCst);
        host.stamp.store(7, Ordering::SeqCst);
        let rows: Vec<String> = limited_screen()
            .into_iter()
            .map(|r| {
                r.replace(
                    "You've hit your session limit · resets 7:30pm (America/Los_Angeles)",
                    message,
                )
            })
            .collect();
        (host, rows)
    };
    let weekly = "You've hit your weekly limit · resets Sep 23 at 8am (America/Los_Angeles)";
    let session_limit = "You've hit your session limit · resets 7:30pm (America/Los_Angeles)";
    for (message, edge) in [
        (weekly, true),
        // NEGATIVE CONTROL: a session limit reads no roster word.
        (session_limit, false),
    ] {
        let (host, rows) = wait_at(message);
        let opts = account_opts(&host);
        let mut m = Mock::new(vec![rows.clone()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(ACCOUNT_NOW, PDT);
        s.set_zone_lookup(test_zones);
        let point = account_point_of(
            rows,
            Phase::Limited {
                message: String::new(),
                reset: None,
            },
        );
        let action = s
            .turn_end_at_point(&point, Some(Duration::from_secs(180)), &opts)
            .expect("a decision");
        assert!(
            matches!(action, TurnEndAction::WaitUntil { .. }),
            "{message}: {action:?}"
        );
        s.turn_end_execute(&point, action, &opts, &[], &mut Alone)
            .expect("the wait is set");
        assert!(
            s.turn_end_due.is_some(),
            "{message}: the limit is waited out"
        );
        assert!(host.said("account").is_empty(), "{:?}", host.all());
        assert_eq!(
            host.roster_asked.load(Ordering::SeqCst),
            usize::from(edge),
            "{message}"
        );
        // NEGATIVE CONTROL: the stamp as it stood is no edge.
        assert!(!s.account_edge(&opts), "{message}");
        // The owner sets `relaunch = true`: the host's stamp moves.
        host.relaunch_off.store(false, Ordering::SeqCst);
        host.stamp.store(8, Ordering::SeqCst);
        assert_eq!(s.account_edge(&opts), edge, "{message}");
        assert!(!s.account_edge(&opts), "{message}: once");
        if !edge {
            continue;
        }
        let again = s
            .turn_end_at_point(&point, None, &opts)
            .expect("a decision");
        assert!(
            matches!(
                &again,
                TurnEndAction::Restart { why: Restart::Account { to, at: AccountAt::Wall }, .. }
                    if to == "m8-3"
            ),
            "{again:?}"
        );
        assert_eq!(host.said("account"), ["account:wall:usage-weekly"]);
    }
}

/// A MOVE ANSWERED BY A LOST LOGIN IS NOT SERVED BY ITS `/login` DIALOG (the
/// review of the login carry, acct3-2): the dialog's spinner reads busy, and
/// at its `Login interrupted` the told move was said served — the host proved
/// the dead login and marked it `ok`, a rotation candidate other sessions
/// were moved onto. Told the lost login, `/login` typed, the dialog read busy
/// and then left: the host hears nothing served, and the move still stands
/// for the turn that is. NEGATIVE CONTROL: the same `/login` signed in
/// (`Login successful`) and a turn served after it: told served, once, and
/// the move is over.
#[test]
fn a_moves_lost_login_is_not_served_by_its_login_dialog() {
    use crate::supervise::policy::turn_end::{TurnEndReading, decide_turn_end};
    use aterm_phase::prompt::fixtures::{LOGIN_HANDOFF, LOGIN_INTERRUPTED, LOGIN_SUCCESS, screen};
    let mut login = rows(&[
        "⏺ Carrying on.",
        "  ⎿  Not logged in · Please run /login",
        "",
    ]);
    login.extend(composer("  ? for shortcuts"));
    let run = |after: &[(Vec<String>, Option<Duration>)]| {
        let host = AccountHost::scripted(&[None], &["adopted"]);
        let opts = account_opts(&host);
        let mut m = Mock::new(vec![login.clone()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(ACCOUNT_NOW, PDT);
        let idle = ended("Carried on: stage 3 is done.");
        let r = TurnEndReading::of(
            &aterm_phase::ClaudeReader.read(&idle, Some(2)),
            &idle,
            false,
            None,
            None,
            None,
        );
        let t = Instant::now();
        s.turn_end.restarted(
            &Restart::Account {
                to: "work-2".to_string(),
                at: AccountAt::Wall,
            },
            true,
            &r,
            t,
        );
        s.turn_end
            .host_typed(t, crate::supervise::policy::turn_end::HostTurn::CarryOn);
        let point = |rows: &[String], seq: u64| Screen {
            rows: rows.to_vec(),
            seq,
            cursor_col: 2,
            ..Screen::default()
        };
        // The lost login after a turn asked under the move: told.
        let lost = point(&login, 102);
        let mut first = s.turn_end_reading(&lost, Some(Duration::from_secs(180)), &opts);
        s.fold_point(&mut first, t, lost.seq, &opts);
        assert_eq!(host.said("answered:"), ["answered:signed-out"]);
        // `/login` typed into it.
        let mut at = t;
        let mut a = decide_turn_end(&s.turn_end, &first, &opts.policy, at);
        for _ in 0..4 {
            if let TurnEndAction::WaitUntil { until, .. } = a {
                at = until;
                a = decide_turn_end(&s.turn_end, &first, &opts.policy, at);
            }
        }
        assert_eq!(a.rule_id(), Some(RULE_LOGIN), "{a:?}");
        s.turn_end.acted(&a, &first, at);
        s.turn_end.took();
        for (k, (rows, worked)) in after.iter().enumerate() {
            let seq = 103 + k as u64;
            let shown = point(rows, seq);
            let now = at + Duration::from_secs(30 * (k as u64 + 1));
            let mut r = s.turn_end_reading(&shown, *worked, &opts);
            s.fold_point(&mut r, now, seq, &opts);
        }
        (
            host.said("served").len(),
            s.turn_end.account_move().is_some(),
        )
    };
    let busy = Some(Duration::from_secs(4));
    let left = run(&[
        (screen(LOGIN_HANDOFF), busy),
        (screen(LOGIN_INTERRUPTED), busy),
        (screen(LOGIN_INTERRUPTED), busy),
    ]);
    assert_eq!(left, (0, true), "the dialog served nothing");
    // NEGATIVE CONTROL.
    let served = run(&[
        (screen(LOGIN_HANDOFF), busy),
        (screen(LOGIN_SUCCESS), busy),
        (ended("Carried on: stage 4 is done."), busy),
    ]);
    assert_eq!(served, (1, false), "signed in, then served: once");
}

#[test]
fn the_host_is_told_once_what_answered_the_move() {
    let wall = limited_screen();
    let idle = ended("Carried on: stage 3 is done.");
    let mut login = rows(&[
        "⏺ Carrying on.",
        "  ⎿  Not logged in · Please run /login",
        "",
    ]);
    login.extend(composer("  ? for shortcuts"));
    let moved_to = |s: &mut Session<'_, Mock>, asked: bool| {
        let r = crate::supervise::policy::turn_end::TurnEndReading::of(
            &aterm_phase::ClaudeReader.read(&idle, Some(2)),
            &idle,
            false,
            None,
            None,
            None,
        );
        s.turn_end.restarted(
            &Restart::Account {
                to: "work-2".to_string(),
                at: AccountAt::Wall,
            },
            true,
            &r,
            Instant::now(),
        );
        if asked {
            s.turn_end.host_typed(
                Instant::now(),
                crate::supervise::policy::turn_end::HostTurn::CarryOn,
            );
        }
    };
    let told = |rows: &[String], moved: Option<bool>, worked: Option<Duration>| {
        let host = AccountHost::moving("pool-a", "adopted");
        let opts = account_opts(&host);
        let mut m = Mock::new(vec![rows.to_vec()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(ACCOUNT_NOW, PDT);
        s.set_zone_lookup(test_zones);
        if let Some(asked) = moved {
            moved_to(&mut s, asked);
        }
        let screen = Screen {
            rows: rows.to_vec(),
            seq: 102,
            cursor_col: 2,
            ..Screen::default()
        };
        // The loop's order: the tells off the reading, the point folded
        // in, then the host's advice.
        let mut first = s.turn_end_reading(&screen, worked, &opts);
        s.fold_point(&mut first, Instant::now(), screen.seq, &opts);
        // The reading of the same point, built again: nothing is told twice
        // and the host is not asked twice.
        let again = s.turn_end_reading(&screen, None, &opts);
        assert_eq!(first.account, again.account);
        (host.all(), first.account)
    };
    let work = Some(Duration::from_secs(180));
    let next = Some(AccountAdvice::Move {
        to: "pool-a".to_string(),
    });
    // A usage limit after a turn asked under the new login: struck, THEN
    // advised.
    assert_eq!(
        told(&wall, Some(true), work),
        (
            vec![
                "answered:wall".to_string(),
                "account:wall:usage-session".to_string()
            ],
            next.clone()
        )
    );
    // A lost login after a turn asked under the new login: struck, THEN
    // advised. (Rewritten for F11/F12: it was told at once, no turn asked.)
    assert_eq!(
        told(&login, Some(true), work),
        (
            vec![
                "answered:signed-out".to_string(),
                "account:wall:auth".to_string()
            ],
            next.clone()
        )
    );
    // Served: told, and the point is then a plain turn end like any other.
    assert_eq!(
        told(&idle, Some(true), work),
        (
            vec!["served".to_string(), "account:turn-end".to_string()],
            next.clone()
        )
    );
    // NEGATIVE CONTROLS.
    assert_eq!(
        told(&wall, None, work).0,
        ["account:wall:usage-session"],
        "no move was made: nothing to tell"
    );
    assert_eq!(
        told(&wall, Some(false), work).0,
        Vec::<String>::new(),
        "no turn was asked under the new login: the limit is the old account's notice, and \
         the wall's resume is what the point gets"
    );
    assert_eq!(
        told(&idle, Some(false), work).0,
        Vec::<String>::new(),
        "nobody asked that turn — and with the move unanswered, no move ahead is asked for"
    );
    assert_eq!(
        told(&login, Some(false), None),
        (Vec::<String>::new(), None),
        "no turn was asked under the new login: the lost login is the old process's notice, \
         nothing is struck and no host is asked"
    );
    assert_eq!(
        told(&login, None, None).0,
        Vec::<String>::new(),
        "a login the person lost: the login rule's, and no host is asked"
    );
}

/// R10/R5: A LOST LOGIN AFTER A TURN ASKED UNDER THE LOGIN THE MOVE CHOSE IS
/// TOLD — STRUCK ON THAT LOGIN — BEFORE ANY ADVICE FOR THAT POINT IS ASKED,
/// though no read saw that turn busy. The session was moved to `work-2` at
/// main's limit and the wall's resume typed there; `work-2` answers it with
/// `Not logged in` inside one read. Inside the act's take window the point
/// waits for it and the host is asked nothing (no login is struck yet); the
/// fold that judges the act tells the lost login, THEN the host is asked, so
/// the move it advises is made from a struck `work-2` — and the point read
/// again once that relaunch is made tells nothing more (the host judges the
/// process under `pool-a` by then). Asked first, the host advised with
/// `work-2` unstruck (the next account, or the move back onto `work-2` on
/// the `ok` it had before), and the strike landed after the relaunch, on
/// `pool-a`. So too where the row has LEFT the screen by the point that
/// judges the act (T8: a person's `/status` drawn over it inside the
/// window): the host is asked about the lost login the track holds, and it
/// is told there first. (The same lost login read with the turn's work is
/// told before the fold, as ever, in the same order:
/// [`the_host_is_told_once_what_answered_the_move`].) NEGATIVE CONTROL:
/// `Login successful` drawn over it is no lost login, told or asked.
#[test]
fn a_lost_login_no_read_saw_busy_is_struck_before_the_host_is_asked() {
    use crate::supervise::policy::turn_end::RULE_LIMIT_RESUME;
    let mut login = rows(&[
        "⏺ Resumed: carrying on.",
        "  ⎿  Not logged in · Please run /login",
        "",
    ]);
    login.extend(composer("  ? for shortcuts"));
    let wall = limited_screen();
    // Each point: its screen, the act's take window there and the work read.
    let run = |points: &[(&[String], Duration, Option<Duration>)]| {
        let host = AccountHost::moving("pool-a", "adopted");
        let opts = account_opts(&host);
        let mut m = Mock::new(points.iter().map(|p| p.0.to_vec()).collect());
        let action = {
            let mut s = session(&mut m, Some("@s-1".to_string()));
            s.set_clock(ACCOUNT_NOW, PDT);
            s.set_zone_lookup(test_zones);
            let r = crate::supervise::policy::turn_end::TurnEndReading::of(
                &aterm_phase::ClaudeReader.read(&wall, Some(2)),
                &wall,
                false,
                None,
                None,
                None,
            );
            let now = Instant::now();
            s.turn_end.restarted(
                &Restart::Account {
                    to: "work-2".to_string(),
                    at: AccountAt::Wall,
                },
                true,
                &r,
                now,
            );
            s.turn_end.acted(
                &TurnEndAction::Type {
                    text: "keep going".to_string(),
                    rule_id: RULE_LIMIT_RESUME,
                },
                &r,
                now,
            );
            let mut action = None;
            for (seq, (rows, take_within, worked)) in (102..).zip(points) {
                s.turn_end.timing.take_within = *take_within;
                let point = point_at(&s, rows.to_vec(), seq);
                let decided = s
                    .turn_end_at_point(&point, *worked, &opts)
                    .expect("a decision");
                if matches!(decided, TurnEndAction::Restart { .. }) {
                    s.turn_end_execute(&point, decided.clone(), &opts, &[], &mut Alone)
                        .expect("carried out");
                }
                action = Some(decided);
            }
            action.expect("a point")
        };
        (action, host.all())
    };
    let window = TurnEndTiming::default().take_within;
    let moved = [
        "answered:signed-out",
        "account:wall:auth",
        "restart:account:pool-a",
    ];
    let to_pool_a = Restart::Account {
        to: "pool-a".to_string(),
        at: AccountAt::Wall,
    };
    // Inside the take window: nothing told, nothing asked.
    let (action, said) = run(&[(&login, window, None)]);
    assert!(
        matches!(&action, TurnEndAction::WaitUntil { why, .. } if why.starts_with("the worker to take")),
        "{action:?}"
    );
    assert!(
        said.is_empty(),
        "no advice for a login nobody struck: {said:?}"
    );
    // Judged at its deadline (a window of nothing): struck, THEN asked.
    let (action, said) = run(&[(&login, Duration::ZERO, None)]);
    assert!(
        matches!(&action, TurnEndAction::Restart { why, .. } if *why == to_pool_a),
        "{action:?}"
    );
    assert_eq!(said, moved, "struck on work-2 before the advice");
    // T8: THE ROW GONE BY THE POINT THAT JUDGES THE ACT — a person's
    // `/status` drawn over it inside the window: the lost login the track
    // holds is the point's, told there and struck on work-2, THEN asked
    // about. Asked first, the host advised with work-2 unstruck, and nothing
    // ever told it.
    let mut status = rows(&[
        "⏺ Resumed: carrying on.",
        "  ⎿  Not logged in · Please run /login",
        "",
        "❯ /status",
        "  ⎿  Status dialog dismissed",
        "",
    ]);
    status.extend(composer("  ? for shortcuts"));
    let (action, said) = run(&[(&login, window, None), (&status, Duration::ZERO, None)]);
    assert!(
        matches!(&action, TurnEndAction::Restart { why, .. } if *why == to_pool_a),
        "{action:?}"
    );
    assert_eq!(said, moved, "struck on work-2 before the advice");
    // NEGATIVE CONTROL: the login back (`Login successful`) instead —
    // nothing told, and no lost login asked about.
    let mut back = rows(&[
        "⏺ Resumed: carrying on.",
        "  ⎿  Not logged in · Please run /login",
        "",
        "❯ /login",
        "  ⎿  Login successful",
        "",
    ]);
    back.extend(composer("  ? for shortcuts"));
    let (_, said) = run(&[(&login, window, None), (&back, Duration::ZERO, None)]);
    assert!(
        !said
            .iter()
            .any(|s| s == "answered:signed-out" || s == "account:wall:auth"),
        "{said:?}"
    );
}

/// T1/T6: A LOOP STARTED ON A TOLD MOVE AN HOUR AND MORE OLD HOLDS IT: the
/// session was moved to `pool-a`, whose lost login was told (its row says
/// `until=served`), and ninety minutes on its agent is relaunched under that
/// login. The loop that takes it reads the move back from the ledger —
/// every field of the row through to the policy's seed — and waits at the
/// lost login, asking the host about it, for the instant the host names:
/// `/login` is not typed while a move is to come. (What the policy does with each
/// seed is `a_told_move_is_held_by_a_later_loop_whatever_its_age`'s.)
/// NEGATIVE CONTROL: the same move told by an older build, whose row says
/// no `until=served` (it closed told moves silently, so its ledger holds
/// every one open), is history at that age: `/login` typed.
#[test]
fn a_loop_started_on_an_old_told_move_waits_at_its_lost_login() {
    use crate::supervise::approvals::{
        ACCOUNT_MOVE_COMMAND, Outcome, Row, account_answer_reason, account_switch_reason,
    };
    use crate::supervise::policy::turn_end::{AccountAnswer, AccountBad};
    let mut login = rows(&[
        "⏺ Resumed: carrying on.",
        "  ⎿  Not logged in · Please run /login",
        "",
    ]);
    login.extend(composer("  ? for shortcuts"));
    let run = |tag: &str, told: String, screens: Vec<Vec<String>>| {
        let (dir, ledger) = ledger_at(tag);
        let now_ms = crate::supervise::journal::unix_ms();
        let command = format!("{ACCOUNT_MOVE_COMMAND}pool-a");
        let row = |outcome, reason: &str, box_seq, ago_min: i64| {
            Row {
                rule_id: RULE_ACCOUNT,
                outcome,
                command: &command,
                reason,
                box_seq,
            }
            .to_json(now_ms - ago_min * 60_000, None)
        };
        let written = [
            row(
                Outcome::Typed,
                &account_switch_reason("pool-a", AccountAt::Wall),
                90,
                90,
            ),
            row(Outcome::Waiting, &told, 91, 89),
        ];
        std::fs::write(&ledger, written.join("\n") + "\n").expect("the ledger");
        // The host names the instant another account opens.
        let host = AccountHost::scripted(
            &[Some(AccountAdvice::Wait {
                until: Instant::now() + Duration::from_secs(3600),
            })],
            &[],
        );
        let (lines, m, journal) =
            account_run_with(&format!("te-{tag}"), screens, &host, &ledger, |_| {});
        let _ = std::fs::remove_dir_all(&dir);
        let log = format!(
            "{lines:#?}\n{journal:#?}\n{:?}\n{:?}\n{:#?}",
            host.all(),
            host.told(),
            m.requests
        );
        (lines, m, host, log)
    };
    let by = AccountAnswer::Bad(AccountBad::SignedOut);
    let marked = account_answer_reason("pool-a", by);
    let at_login = || vec![login.clone(), login.clone()];
    let (_, m, host, log) = run("account-old-told", marked, at_login());
    assert!(
        !m.requests.iter().any(|r| r.contains("/login")),
        "no /login: {log}"
    );
    assert!(
        host.said("account")
            .iter()
            .any(|s| s == "account:wall:auth"),
        "the host is asked about the lost login: {log}"
    );
    assert!(
        !host.told().iter().any(|t| t == "exception:login:now"),
        "a wait with an end asks nothing: {log}"
    );
    // NEGATIVE CONTROL: told by an older build, the move is history.
    let older = "the turn-end policy (account move answered: to=pool-a by=signed-out)";
    let (lines, _, _, log) = run("account-old-told-older", older.to_string(), at_login());
    assert!(
        lines
            .iter()
            .any(|l| l.ends_with(" rule=auth-login@v1 /login")),
        "{log}"
    );
}

/// R10's hardening: THE POINT READ AGAIN ONCE AN ACCOUNT MOVE'S RELAUNCH IS
/// MADE TELLS NOTHING. Its screen is the old process's, but the host judges
/// the one its tab runs now, under the login moved to. A person's turn under
/// `work-2` runs into `work-2`'s usage limit — a turn the fold, not the tell
/// before it, marks asked — and the host advises the move to `pool-a`: once
/// that relaunch is made nothing is told (told, the limit was charged to
/// `pool-a`'s new process). NEGATIVE CONTROL: the same point where the
/// relaunch is refused (`refused:line`) tells the limit at the reread — the
/// process there is still `work-2`'s.
#[test]
fn the_point_read_again_after_an_account_relaunch_tells_nothing() {
    let wall = limited_screen();
    let started = ended("Resumed: stage 2.");
    let run = |answer: &'static str| {
        let host = AccountHost::moving("pool-a", answer);
        let opts = account_opts(&host);
        let mut m = Mock::new(vec![wall.clone()]);
        {
            let (mut s, point) = account_session(&mut m);
            let r = crate::supervise::policy::turn_end::TurnEndReading::of(
                &aterm_phase::ClaudeReader.read(&started, Some(2)),
                &started,
                false,
                Some(Duration::from_secs(1)),
                None,
                None,
            );
            let now = Instant::now();
            s.turn_end.restarted(
                &Restart::Account {
                    to: "work-2".to_string(),
                    at: AccountAt::Ahead,
                },
                true,
                &r,
                now,
            );
            // The relaunch's own start-up, its first point.
            s.turn_end.observe(&r, now);
            let action = s
                .turn_end_at_point(&point, Some(Duration::from_secs(180)), &opts)
                .expect("a decision");
            assert!(
                matches!(&action, TurnEndAction::Restart { why: Restart::Account { to, .. }, .. } if to == "pool-a"),
                "{action:?}"
            );
            s.turn_end_execute(&point, action, &opts, &[], &mut Alone)
                .expect("carried out");
        }
        host.all()
    };
    assert_eq!(
        run("adopted"),
        ["account:wall:usage-session", "restart:account:pool-a"],
        "nothing told of the old screen once the relaunch is made"
    );
    // NEGATIVE CONTROL.
    assert_eq!(
        run("refused:line"),
        [
            "account:wall:usage-session",
            "restart:account:pool-a",
            "answered:wall"
        ],
        "no relaunch: the process is still work-2's"
    );
}

/// A LOOP THAT STARTS AT A WALL AFTER ANOTHER KEEPS WHAT THAT ONE LEFT IN THE
/// LEDGER (each seamless update and each fault starts a new loop): four
/// moves made within the hour are the bound spent — the host's relaunch is
/// not asked, and the wall is waited out, said to be a breaker — and a move
/// that could not be made at the wall is not asked again there. NEGATIVE
/// CONTROL: the same wall and the same advice over an empty ledger ask the
/// relaunch at once.
#[test]
fn a_loop_that_starts_after_another_keeps_its_bound_and_its_latch() {
    use crate::supervise::approvals::{
        ACCOUNT_MOVE_COMMAND, Outcome, Row, account_switch_reason, account_unmade_reason,
    };
    let wall = || vec![busy_screen(), limited_screen()];
    let now_ms = crate::supervise::journal::unix_ms();
    let row = |outcome: Outcome, reason: &str, ago_min: i64| {
        Row {
            rule_id: RULE_ACCOUNT,
            outcome,
            command: &format!("{ACCOUNT_MOVE_COMMAND}pool-a"),
            reason,
            box_seq: 90,
        }
        .to_json(now_ms - ago_min * 60_000, None)
    };
    let run = |tag: &str, rows: &[String]| {
        let (dir, ledger) = ledger_at(tag);
        if !rows.is_empty() {
            std::fs::write(&ledger, rows.join("\n") + "\n").expect("the ledger");
        }
        let host = AccountHost::moving("work-2", "adopted");
        let (lines, _, journal) = account_run(&format!("te-{tag}"), wall(), &host, &ledger);
        let _ = std::fs::remove_dir_all(&dir);
        (host.said("restart"), lines, journal)
    };
    // The bound, spent by the loops before this one — the last move's wall's
    // resume typed under it, so the limit this loop finds is that account's
    // own, no notice its relaunch repainted.
    let made = account_switch_reason("pool-a", AccountAt::Wall);
    let resumed = Row {
        rule_id: crate::supervise::policy::turn_end::RULE_LIMIT_RESUME,
        outcome: Outcome::Typed,
        command: "keep going",
        reason: "the turn-end policy",
        box_seq: 91,
    }
    .to_json(now_ms - 5 * 60_000, None);
    let four: Vec<String> = (1..=4)
        .rev()
        .map(|ago| row(Outcome::Typed, &made, 10 * ago))
        .chain(std::iter::once(resumed))
        .collect();
    let (asked, lines, journal) = run("account-seeded-bound", &four);
    assert!(asked.is_empty(), "{lines:#?}");
    assert!(
        journal
            .iter()
            .any(|l| l.starts_with("WAITING ") && l.contains("a breaker")),
        "{journal:#?}"
    );
    // The latch: refused at this wall by the loop before.
    let unmade = account_unmade_reason("pool-a", AccountAt::Wall, Some("refused:line"));
    let (asked, lines, journal) = run("account-seeded-latch", &[row(Outcome::Skipped, &unmade, 5)]);
    assert!(asked.is_empty(), "{lines:#?}");
    assert!(
        journal
            .iter()
            .any(|l| l.starts_with("WAITING ") && l.contains("usage-session resets")),
        "{journal:#?}"
    );
    // NEGATIVE CONTROLS: nothing on the ledger, and moves made long ago.
    let (asked, lines, _) = run("account-seeded-none", &[]);
    assert_eq!(asked, ["restart:account:work-2"], "{lines:#?}");
    let old: Vec<String> = (1..=4)
        .map(|ago| row(Outcome::Typed, &made, 120 * ago))
        .collect();
    let (asked, lines, _) = run("account-seeded-old", &old);
    assert_eq!(asked, ["restart:account:work-2"], "{lines:#?}");
}

/// THE LATCH A LOOP LEAVES IN THE LEDGER IS ITS WALL'S: a move that could
/// not be made AT A WALL latches (a loop that starts after it does not ask it
/// again there) until the end of that wall is written (`wall-wait-end@v1`).
/// (The moves made, their answers and the turns asked under them, read back
/// by the loops that follow: [`a_loop_that_starts_after_another_keeps_its_bound_and_its_latch`],
/// [`a_move_seeded_from_the_ledger_is_answered_once_across_loops`],
/// [`a_loop_started_on_an_old_told_move_waits_at_its_lost_login`].)
/// NEGATIVE CONTROLS: another session's move, a draft submitted under the
/// rule, a refusal AHEAD of a wall and a missing ledger read as nothing.
#[test]
fn the_ledger_reads_a_sessions_account_moves_back() {
    use crate::supervise::approvals::{
        ACCOUNT_MOVE_COMMAND, AccountMoves, Outcome, RULE_WALL_WAIT_END, Row, account_moves,
        account_switch_reason, account_unmade_reason,
    };
    let (dir, ledger) = ledger_at("account-ledger");
    let row = |rule: &str, outcome: Outcome, command: &str, reason: &str, ts: i64, sid| {
        Row {
            rule_id: rule,
            outcome,
            command,
            reason,
            box_seq: 1,
        }
        .to_json(ts, sid)
    };
    let to = format!("{ACCOUNT_MOVE_COMMAND}work-2");
    let write = |rows: &[String]| std::fs::write(&ledger, rows.join("\n") + "\n").expect("ledger");
    let me = Some("s-1");
    let unmade = |at, ts| {
        row(
            RULE_ACCOUNT,
            Outcome::Skipped,
            &to,
            &account_unmade_reason("work-2", at, Some("refused:line")),
            ts,
            me,
        )
    };
    write(&[unmade(AccountAt::Wall, 1_000)]);
    assert!(account_moves(&ledger, Some("@s-1")).unmade);
    write(&[
        unmade(AccountAt::Wall, 1_000),
        row(
            RULE_WALL_WAIT_END,
            Outcome::Waiting,
            "",
            "the wall left the screen",
            2_000,
            me,
        ),
    ]);
    assert!(
        !account_moves(&ledger, Some("@s-1")).unmade,
        "the wall is over"
    );
    // NEGATIVE CONTROLS.
    write(&[
        row(
            RULE_ACCOUNT,
            Outcome::Typed,
            &to,
            &account_switch_reason("work-2", AccountAt::Wall),
            1_000,
            Some("s-2"),
        ),
        row(
            RULE_ACCOUNT,
            Outcome::Typed,
            "my own words",
            "the turn-end policy",
            2_000,
            me,
        ),
        unmade(AccountAt::Ahead, 3_000),
    ]);
    assert_eq!(
        account_moves(&ledger, Some("@s-1")),
        AccountMoves::default()
    );
    assert_eq!(
        account_moves(&dir.join("absent.jsonl"), me),
        AccountMoves::default()
    );
    let _ = std::fs::remove_dir_all(&dir);
}

/// A MODEL SWITCH A MADE ACCOUNT MOVE LET GO IS NOT CARRIED ON BY THE LOOP
/// AFTER IT. The move relaunches the session on the model the fallback
/// replaced and the policy forgets the switch (`TurnEndState::restarted`):
/// its return was owed at the OLD account's bucket's reset. The ledger must
/// say the same, or every loop that starts afterwards (each seamless update,
/// each fault) reads the switch back as open and relaunches the session once
/// more at that reset — onto the model it already runs. NEGATIVE CONTROLS:
/// the switch alone is open; a move that could NOT be made, another
/// session's move, and a draft submitted under the rule leave it open; a
/// switch made AFTER the move is open.
#[test]
fn an_account_move_made_closes_the_model_switch_for_the_loop_after_it() {
    use crate::supervise::approvals::{
        ACCOUNT_MOVE_COMMAND, Outcome, Row, account_switch_reason, account_unmade_reason,
        model_switch_reason, open_model_switch,
    };
    use crate::supervise::policy::turn_end::RULE_MODEL_FALLBACK;
    let (dir, ledger) = ledger_at("account-closes-switch");
    let me = Some("s-1");
    let back_at = 1_789_700_000;
    let row = |rule: &str, outcome: Outcome, command: &str, reason: &str, ts: i64, sid| {
        Row {
            rule_id: rule,
            outcome,
            command,
            reason,
            box_seq: 1,
        }
        .to_json(ts, sid)
    };
    let switch = |ts: i64| {
        row(
            RULE_MODEL_FALLBACK,
            Outcome::Typed,
            "relaunch --model opus",
            &model_switch_reason(Some("fable"), Some(back_at), 1),
            ts,
            me,
        )
    };
    let to = format!("{ACCOUNT_MOVE_COMMAND}work-2");
    let moved = |ts: i64, sid| {
        row(
            RULE_ACCOUNT,
            Outcome::Typed,
            &to,
            &account_switch_reason("work-2", AccountAt::Wall),
            ts,
            sid,
        )
    };
    let write = |rows: &[String]| std::fs::write(&ledger, rows.join("\n") + "\n").expect("ledger");
    let open = || open_model_switch(&ledger, Some("@s-1")).map(|o| (o.to, o.back_at_unix));
    let standing = Some(("opus".to_string(), Some(back_at)));
    // NEGATIVE CONTROL: the switch alone is open.
    write(&[switch(1_000)]);
    assert_eq!(open(), standing);
    // The move made after it: no return is owed.
    write(&[switch(1_000), moved(2_000, me)]);
    assert_eq!(open(), None, "the move let the switch go");
    // NEGATIVE CONTROLS: none of these is this session's move made.
    let unmade = row(
        RULE_ACCOUNT,
        Outcome::Skipped,
        &to,
        &account_unmade_reason("work-2", AccountAt::Wall, Some("refused:line")),
        2_000,
        me,
    );
    let draft = row(
        RULE_ACCOUNT,
        Outcome::Typed,
        "my own words",
        "the turn-end policy",
        2_000,
        me,
    );
    for (what, after) in [
        ("a move not made", unmade),
        ("another session's move", moved(2_000, Some("s-2"))),
        ("a draft under the rule", draft),
    ] {
        write(&[switch(1_000), after]);
        assert_eq!(open(), standing, "{what}");
    }
    // A switch made AFTER the move is the new account's own, and open.
    write(&[switch(1_000), moved(2_000, me), switch(3_000)]);
    assert_eq!(open(), standing);
    let _ = std::fs::remove_dir_all(&dir);
}

/// A TASK THAT LANDED, OPENED AGAIN BY SOMEONE'S TURN THAT ENDS ON A USAGE
/// LIMIT, IS ASKED ABOUT AT THAT LIMIT. The host is asked for its
/// advice BEFORE the point is folded into the policy's memory, and it is the
/// fold that opens the task again (a turn of work that a prompt in the
/// conversation's record asked — here no record is read, and the screen's
/// rule takes the turn for one): judged on the memory as it stood, the
/// session read as done, the host was asked nothing, and the wall was waited
/// out to its reset beside an account that could be run on — with nothing to
/// decide it again (a wait stands on the host's stamp only where the host
/// was asked). NEGATIVE CONTROL: the same limit read with NO turn run since
/// the task landed is a done session's — nothing asked, nothing decided.
#[test]
fn a_finished_task_opened_again_is_asked_about_at_the_limit_its_turn_ends_on() {
    let limited = || Phase::Limited {
        message: String::new(),
        reset: None,
    };
    let run = |worked: Option<Duration>| {
        let host = AccountHost::moving("work-2", "wait:changed");
        let mut opts = account_opts(&host);
        opts.policy.autopilot = crate::supervise::config::Autopilot::Land;
        let mut m = Mock::new(vec![limited_screen()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(ACCOUNT_NOW, PDT);
        s.set_zone_lookup(test_zones);
        // The worker's point, and its task landed (as a loop before this one
        // left it): nothing is typed from here.
        let done = account_point_of(ended("All landed."), Phase::Idle);
        let _ = s
            .turn_end_at_point(&done, Some(Duration::from_secs(300)), &opts)
            .expect("a decision");
        assert!(s.turn_end.seed_task_done());
        // Then the session's screen shows a session limit.
        let wall = account_point_of(limited_screen(), limited());
        let action = s
            .turn_end_at_point(&wall, worked, &opts)
            .expect("a decision");
        (action, host.said("account:wall"))
    };
    // Someone's turn ran and ended on the limit: the task is theirs again,
    // the host is asked, and its move is asked for.
    let (action, asked) = run(Some(Duration::from_secs(180)));
    assert_eq!(asked, ["account:wall:usage-session"]);
    assert!(
        matches!(
            &action,
            TurnEndAction::Restart { why: Restart::Account { to, at: AccountAt::Wall }, rule_id, .. }
                if to == "work-2" && *rule_id == RULE_ACCOUNT
        ),
        "{action:?}"
    );
    // NEGATIVE CONTROL: no turn ran — the task is still done.
    let (action, asked) = run(None);
    assert_eq!(action, TurnEndAction::Nothing);
    assert!(asked.is_empty(), "{asked:?}");
}

/// A session at its session limit under `host`, its clock the account
/// tests', and the point its screen shows.
fn account_session<'m>(m: &'m mut Mock) -> (Session<'m, Mock>, Turn) {
    let mut s = session(m, Some("@s-1".to_string()));
    s.set_clock(ACCOUNT_NOW, PDT);
    s.set_zone_lookup(test_zones);
    let wall = account_point_of(
        limited_screen(),
        Phase::Limited {
            message: String::new(),
            reset: None,
        },
    );
    (s, wall)
}

/// THE HOST IS ASKED AFTER THE POINT IS FOLDED IN, and a latch is its
/// wall's. A move the host refused for good is not asked again while that
/// wall stands; once the worker has worked and its turn ended with no wall,
/// THAT point asks again — the fold is what ends the latch, and asked before
/// it the host was passed over for one more turn end (and for a whole second
/// wall where the work ended on the limit again).
/// NEGATIVE CONTROL: the wall read again with no work asks nothing.
#[test]
fn the_host_is_asked_on_the_folded_point_where_a_latch_has_ended() {
    let host = AccountHost::moving("work-2", "refused:line");
    let opts = account_opts(&host);
    let mut m = Mock::new(vec![limited_screen()]);
    let (mut s, wall) = account_session(&mut m);
    let action = s
        .turn_end_at_point(&wall, Some(Duration::from_secs(180)), &opts)
        .expect("a decision");
    s.turn_end_execute(&wall, action, &opts, &[], &mut Alone)
        .expect("the refusal is taken");
    assert!(s.turn_end.account_refused());
    assert_eq!(host.said("account"), ["account:wall:usage-session"]);
    // NEGATIVE CONTROL: the same wall, no work — latched, nothing asked.
    let again = s.turn_end_at_point(&wall, None, &opts).expect("a decision");
    assert!(
        matches!(again, TurnEndAction::WaitUntil { .. }),
        "{again:?}"
    );
    assert_eq!(host.said("account").len(), 1, "{:?}", host.all());
    // The worker worked, and its turn ended with no wall.
    let end = account_point_of(ended("Stage 3 done; the suite is green."), Phase::Idle);
    let action = s
        .turn_end_at_point(&end, Some(Duration::from_secs(300)), &opts)
        .expect("a decision");
    assert_eq!(
        host.said("account"),
        ["account:wall:usage-session", "account:turn-end"],
        "asked at the very point that ended the latch"
    );
    assert!(
        matches!(
            &action,
            TurnEndAction::Restart { why: Restart::Account { to, at: AccountAt::Ahead }, .. }
                if to == "work-2"
        ),
        "{action:?}"
    );
}

/// NEWS OF THE ACCOUNTS REACHES A LATCHED TAB. A move refused for good is
/// not asked again while its wall stands — until the host's stamp moves: the
/// owner signed the account in and checked it, or said `accounts use`. Then
/// the latch is cleared, the point decided again, and the host asked.
/// NEGATIVE CONTROLS: with no news the refusal is not re-asked, however
/// often the point is decided; and news that follows a clearing within the
/// minute waits for the minute (a host whose refusals are themselves news
/// costs one ask a minute, never a hot loop).
#[test]
fn news_of_the_accounts_clears_a_latch_and_no_news_asks_nothing() {
    let host = AccountHost::moving("work-2", "refused:line");
    let opts = account_opts(&host);
    let mut m = Mock::new(vec![limited_screen()]);
    let (mut s, wall) = account_session(&mut m);
    let decide = |s: &mut Session<'_, Mock>| {
        let action = s.turn_end_at_point(&wall, None, &opts).expect("a decision");
        let asked = matches!(action, TurnEndAction::Restart { .. });
        s.turn_end_execute(&wall, action, &opts, &[], &mut Alone)
            .expect("carried out");
        asked
    };
    assert!(decide(&mut s), "the move is asked");
    assert!(s.turn_end.account_refused() && s.turn_end_due.is_some());
    // NEGATIVE CONTROL: no news.
    assert!(!s.account_edge(&opts));
    assert!(
        !decide(&mut s),
        "a refusal repeated with no news is not re-asked"
    );
    assert_eq!(host.said("restart").len(), 1, "{:?}", host.all());
    // News.
    host.stamp.store(1, Ordering::SeqCst);
    assert!(
        s.account_edge(&opts),
        "the stamp moved under a latched wait"
    );
    assert!(
        !s.turn_end.account_refused(),
        "the latch is the news's to end"
    );
    assert!(decide(&mut s), "asked again");
    assert_eq!(host.said("restart").len(), 2, "{:?}", host.all());
    // Refused again, and more news at once: not before the minute is out.
    assert!(s.turn_end.account_refused());
    host.stamp.store(2, Ordering::SeqCst);
    assert!(!s.account_edge(&opts), "inside the minute");
    s.account_news_at = Instant::now().checked_sub(Duration::from_secs(61));
    assert!(s.account_edge(&opts), "the minute is out");
}

/// `[harness] accounts = "off"` WITH `logins = "off"` STOPS THE TELLS TOO: a
/// session whose policy remembers a move (its ledger's, from before the
/// switch) tells its host nothing of what answered it, asks it nothing, and
/// its wait hears no news. (Under `accounts = "off"` alone the login
/// lifecycle's moves are still told: the host, which keeps the roster, is
/// the one that knows whether a row it renews is there.) NEGATIVE CONTROL:
/// the same session under the default is told at once.
#[test]
fn under_accounts_off_nothing_is_told_or_asked() {
    let run = |mode: crate::harness::accounts::Mode| {
        let host = AccountHost::moving("pool-a", "adopted");
        let mut opts = account_opts(&host);
        opts.policy.accounts = mode;
        let mut m = Mock::new(vec![limited_screen()]);
        opts.policy.logins = mode != crate::harness::accounts::Mode::Off;
        let (mut s, wall) = account_session(&mut m);
        // The session's own move, and a turn asked under it.
        let idle = ended("Carried on: stage 3 is done.");
        let r = crate::supervise::policy::turn_end::TurnEndReading::of(
            &aterm_phase::ClaudeReader.read(&idle, Some(2)),
            &idle,
            false,
            None,
            None,
            None,
        );
        let made = Restart::Account {
            to: "work-2".to_string(),
            at: AccountAt::Wall,
        };
        s.turn_end.restarted(&made, true, &r, Instant::now());
        s.turn_end.host_typed(
            Instant::now(),
            crate::supervise::policy::turn_end::HostTurn::CarryOn,
        );
        let _ = s
            .turn_end_at_point(&wall, Some(Duration::from_secs(180)), &opts)
            .expect("a decision");
        host.stamp.store(5, Ordering::SeqCst);
        s.set_due(
            Instant::now() + Duration::from_secs(3600),
            "usage-session resets",
        );
        (host.all(), s.account_edge(&opts))
    };
    assert_eq!(
        run(crate::harness::accounts::Mode::Off),
        (Vec::<String>::new(), false)
    );
    let (said, edge) = run(crate::harness::accounts::Mode::Early);
    assert_eq!(said.first().map(String::as_str), Some("answered:wall"));
    assert!(edge);
}

/// A MOVE MADE AT A WALL LEAVES THE LIMIT EPISODE BEHIND WITH THE ACCOUNT:
/// the episode the loop opened was the OLD account's, and kept open it
/// withheld every step of the host's until that account's reset plus an
/// hour — the move resumed LATER than no roster would have. The episode
/// closes with the move; the notice the resumed conversation repaints is no
/// wall to the host's last step of the relaunch, which is taken there and
/// types nothing (`done:resumed`); and what follows it is the wall's own
/// resume, at once, with the host asked nothing — as where the host owes no
/// step at all. (At a limit with no move made the host's step is withheld:
/// [`a_loop_that_takes_up_a_move_made_at_a_wall_carries_it_on_past_the_notice`]'s
/// control.)
#[test]
fn a_move_made_at_a_wall_is_carried_on_past_the_limit_it_left() {
    let moved = |carry: bool| {
        let host = AccountHost::moving("work-2", "adopted");
        let opts = account_opts(&host);
        let mut m = Mock::new(vec![limited_screen()]);
        let (mut s, wall) = account_session(&mut m);
        let action = s
            .turn_end_at_point(&wall, Some(Duration::from_secs(180)), &opts)
            .expect("a decision");
        let mut deadline = Instant::now() + Duration::from_secs(3600);
        s.limit_after(&wall, &mut deadline, true, &mut Alone)
            .expect("the episode opens");
        assert!(s.limit.is_some());
        s.turn_end_execute(&wall, action, &opts, &[], &mut Alone)
            .expect("the relaunch is made");
        assert_eq!(host.said("restart"), ["restart:account:work-2"]);
        assert!(
            s.limit.is_none(),
            "the episode was the limit of the account it left"
        );
        host.carry.store(carry, Ordering::SeqCst);
        let stepped = s
            .host_steps_here(&wall, &opts, &mut false, &mut Alone)
            .expect("the host's step");
        let action = s.turn_end_at_point(&wall, None, &opts).expect("a decision");
        (stepped, action, host.all())
    };
    let resume = TurnEndAction::Type {
        text: "keep going".to_string(),
        rule_id: crate::supervise::policy::turn_end::RULE_LIMIT_RESUME,
    };
    // The host's last step of the relaunch, taken at the notice the old
    // account left: nothing typed, nothing answered, and the wall's resume
    // follows.
    let (stepped, action, said) = moved(true);
    assert!(stepped, "{said:?}");
    assert_eq!(
        said,
        [
            "account:wall:usage-session",
            "restart:account:work-2",
            "carry-on"
        ]
    );
    assert_eq!(action, resume);
    // No step of the host's owed: the same resume, the host not asked.
    let (stepped, action, said) = moved(false);
    assert!(!stepped);
    assert_eq!(action, resume);
    assert_eq!(
        said,
        ["account:wall:usage-session", "restart:account:work-2"]
    );
}

/// A LIMIT ONLY THE TRANSCRIPT SHOWS IS THE WALL, AND HOLDS THE RELAUNCH'S
/// CARRY-ON (LIM-1; KI-1015-1 LC-10, measured on 2.1.300). A relaunched or
/// restored Claude Code redraws its conversation and then its own `⏺ Auto
/// mode lets Claude …` paragraph; here the conversation's rows above the
/// paragraph draw no limit (a cold restore's new tab, its loop new, nothing
/// remembered), and the agent's transcript stands on the weekly limit's row,
/// its reset three hours ahead. The host's carry-on is withheld
/// (`LimitEpisode`), and the decision reads the row as the wall — at the
/// first point, though the resumed process's start-up read busy: the weekly
/// reset is waited for, the point is a limit point, its episode opens, and
/// the next host step is withheld by it. ASKED ONCE A PROCESS AND
/// CONVERSATION: the decisions after the first on the same agent ask the host
/// nothing more; a new process is asked again, and so is a conversation the
/// host names since (none named at the first ask, a `/resume` in the same
/// process); a decision that reads a wall asks nothing and spends no ask
/// (the review of LIM-1: it did); a conversation the host names only in
/// answering (its ask reads the agent again) is the one asked about, not
/// asked again (the re-review: it was). NEGATIVE CONTROLS: a host that names
/// no limit — the transcript ending on the model's reply, or a row the
/// harness moved the conversation off (`relaunch_tests.rs`'s
/// `a_limit_row_a_move_left_is_no_standing_limit`: an account move, a
/// bucket's fallback) — has its carry-on typed, and the point is the
/// continue policy's;
/// a row whose reset is past its grace holds no step, and the decision is
/// the limit's own resume.
#[test]
fn a_limit_only_the_transcript_shows_is_the_wall_and_holds_the_carry_on() {
    let rows = {
        let mut r = rows(&[
            "⏺ Running the suites before the release notes.",
            "",
            "⏺ Auto mode lets Claude handle permission prompts automatically — Claude checks \
             each tool call for risky actions and prompt injection",
            "  before executing. Ideal for long-running tasks. Shift+Tab to change mode.",
            "",
        ]);
        r.extend(composer(
            "  ⏵⏵ auto mode on (shift+tab to cycle) · ← for agents",
        ));
        r
    };
    let weekly = |reset: i64| crate::harness::upgrade::StandingLimit {
        text: "You've hit your weekly limit · resets Sep 18 at 8pm (America/Los_Angeles)"
            .to_string(),
        until: u64::try_from(reset).ok(),
        window: Some("seven_day".to_string()),
        at: u64::try_from(ACCOUNT_NOW - 3600).ok(),
        row: Some("row-weekly".to_string()),
    };
    // One relaunched agent's first point: its host's step, then the decision
    // (its start-up read busy), the point as decided and its episode, then
    // the host's next step.
    let first_point = |standing: Option<crate::harness::upgrade::StandingLimit>, carry: bool| {
        let host = AccountHost::scripted(&[None], &["adopted"]);
        *host.standing.lock().unwrap() = standing;
        *host.pid.lock().unwrap() = Some(4242);
        // A relaunch's carry-on TYPES its turn (`continued`), as a crash's or
        // a cold restore's does; an account move's (`done:resumed`) types
        // none.
        *host.step.lock().unwrap() = Some("continued");
        host.carry.store(carry, Ordering::SeqCst);
        let opts = account_opts(&host);
        let mut m = Mock::new(vec![rows.clone()]);
        let mut s = session(&mut m, Some("@s-restored".to_string()));
        s.set_clock(ACCOUNT_NOW, PDT);
        s.set_zone_lookup(test_zones);
        let mut point = account_point_of(rows.clone(), Phase::Idle);
        // The terminal's cursor in the prompt box: an idle the reader vouches for.
        point.screen.cursor_row = rows.iter().position(|r| r.starts_with('❯')).expect("caret");
        let stepped = s
            .host_steps_here(&point, &opts, &mut false, &mut Alone)
            .expect("the host's step");
        let action = s
            .turn_end_at_point(&point, Some(Duration::from_secs(4)), &opts)
            .expect("a decision");
        s.point_as_decided(&mut point);
        let mut deadline = Instant::now() + Duration::from_secs(60);
        s.limit_after(&point, &mut deadline, false, &mut Alone)
            .expect("the episode");
        let episode = s.limit.is_some();
        // The carry-on still owed where it was withheld.
        host.carry.store(!stepped, Ordering::SeqCst);
        let again = s
            .host_steps_here(&point, &opts, &mut false, &mut Alone)
            .expect("the host's next step");
        (stepped, action, point.phase, episode, again, host)
    };
    let (stepped, action, phase, episode, again, host) =
        first_point(Some(weekly(ACCOUNT_NOW + 3 * 3600)), true);
    assert!(!stepped, "the carry-on is withheld");
    assert!(
        matches!(&action, TurnEndAction::WaitUntil { why, .. } if why.contains("usage-weekly")),
        "{action:?}"
    );
    assert!(
        matches!(&phase, Phase::Limited { message, reset: Some(r) }
            if message.starts_with("You've hit your weekly limit") && r.starts_with("Sep 18 at 8pm")),
        "{phase:?}"
    );
    assert!(episode, "the limit's episode opens");
    assert!(!again, "the episode withholds the host's next step");
    assert!(host.said("carry-on").is_empty(), "{:?}", host.all());

    // ASKED ONCE A PROCESS: a decision again on the same agent asks nothing;
    // a new process is asked.
    let host = AccountHost::scripted(&[None], &[]);
    *host.pid.lock().unwrap() = Some(4242);
    let opts = account_opts(&host);
    let mut m = Mock::new(vec![idle_screen()]);
    let mut s = session(&mut m, Some("@s-1".to_string()));
    s.set_clock(ACCOUNT_NOW, PDT);
    let idle = account_point_of(idle_screen(), Phase::Idle);
    let _ = s.turn_end_at_point(&idle, Some(Duration::from_secs(60)), &opts);
    assert_eq!(
        host.standing_asks.load(Ordering::SeqCst),
        1,
        "the first decision"
    );
    for _ in 0..3 {
        let _ = s.turn_end_at_point(&idle, None, &opts);
    }
    assert_eq!(host.standing_asks.load(Ordering::SeqCst), 1, "not again");
    *host.pid.lock().unwrap() = Some(5151);
    let _ = s.turn_end_at_point(&idle, Some(Duration::from_secs(60)), &opts);
    assert_eq!(
        host.standing_asks.load(Ordering::SeqCst),
        2,
        "a new process"
    );
    // …and so is a conversation the host names since: none at the last ask
    // (its snapshot not yet registered), or another one `/resume`d in the
    // same process — once each.
    *host.conversation.lock().unwrap() = Some("c-1".to_string());
    let _ = s.turn_end_at_point(&idle, None, &opts);
    let _ = s.turn_end_at_point(&idle, None, &opts);
    assert_eq!(
        host.standing_asks.load(Ordering::SeqCst),
        3,
        "a conversation named since"
    );
    *host.conversation.lock().unwrap() = Some("c-2".to_string());
    let _ = s.turn_end_at_point(&idle, None, &opts);
    assert_eq!(
        host.standing_asks.load(Ordering::SeqCst),
        4,
        "another conversation"
    );
    // A decision that is not OPEN — the screen reads a wall — asks nothing and
    // records nothing: the process is asked at its first open decision. Before,
    // the walled one spent the process's ask.
    let host = AccountHost::scripted(&[None], &[]);
    *host.pid.lock().unwrap() = Some(6161);
    let opts = account_opts(&host);
    let mut m = Mock::new(vec![limited_screen()]);
    let (mut s, wall) = account_session(&mut m);
    let _ = s.turn_end_at_point(&wall, Some(Duration::from_secs(60)), &opts);
    assert_eq!(host.standing_asks.load(Ordering::SeqCst), 0, "walled");
    let _ = s.turn_end_at_point(&idle, Some(Duration::from_secs(60)), &opts);
    assert_eq!(
        host.standing_asks.load(Ordering::SeqCst),
        1,
        "the first open decision"
    );
    // A host that reads the agent again to answer (the GUI refreshes its
    // snapshot): the conversation it names only in answering is the one it
    // was asked about, and the next decisions ask nothing. Before, the key
    // was read before the ask, and every relaunch was asked twice.
    let host = AccountHost::scripted(&[None], &[]);
    *host.pid.lock().unwrap() = Some(7171);
    *host.named_on_ask.lock().unwrap() = Some("c-1".to_string());
    let opts = account_opts(&host);
    let mut m = Mock::new(vec![idle_screen()]);
    let mut s = session(&mut m, Some("@s-1".to_string()));
    s.set_clock(ACCOUNT_NOW, PDT);
    let _ = s.turn_end_at_point(&idle, Some(Duration::from_secs(60)), &opts);
    for _ in 0..3 {
        let _ = s.turn_end_at_point(&idle, None, &opts);
    }
    assert_eq!(
        host.standing_asks.load(Ordering::SeqCst),
        1,
        "named in answering"
    );

    // NEGATIVE CONTROLS. The host names no limit: the carry-on is typed.
    let (stepped, action, phase, episode, _, host) = first_point(None, true);
    assert!(stepped);
    assert_eq!(host.said("carry-on"), ["carry-on"]);
    assert_eq!(phase, Phase::Idle);
    assert!(!episode);
    assert!(
        matches!(&action, TurnEndAction::Type { rule_id, .. }
            if *rule_id == crate::supervise::policy::turn_end::RULE_CONTINUE),
        "the carry-on answered, the continue policy's point: {action:?}"
    );
    // A reset past its grace holds no step, and the limit's own resume is
    // the decision where no step was taken.
    let spent = ACCOUNT_NOW
        - i64::try_from(crate::harness::upgrade_drive::LIMIT_GRACE_S).expect("grace")
        - 60;
    let (stepped, _, _, _, _, host) = first_point(Some(weekly(spent)), true);
    assert!(stepped, "{:?}", host.all());
    assert_eq!(host.said("carry-on"), ["carry-on"]);
    let (stepped, action, _, _, _, _) = first_point(Some(weekly(spent)), false);
    assert!(!stepped);
    assert_eq!(
        action,
        TurnEndAction::Type {
            text: "keep going".to_string(),
            rule_id: crate::supervise::policy::turn_end::RULE_LIMIT_RESUME,
        }
    );
}

/// A RELAUNCH'S FIRST DECISION ON A SNAPSHOT KEPT FROM BEFORE IT
/// (ATERM-KI-1016-1): the host still names the process it last read, the one
/// already asked about, so keyed on whom alone the decision asked nothing,
/// read no wall, and typed the continue policy's `keep going` into the weekly
/// limit the resumed screen no longer draws — the host's own step, asked
/// after it, read the row afresh and held only its carry-on. A point the host
/// wants a step at is asked about as the step asks: the decision reads the
/// limit, waits for its reset, and the carry-on stays withheld. So is the
/// point after any turn seen running (the review's KR-LIM-2): a host that
/// wants no step there (the carry-on settled or recorded, a person's own
/// relaunch) kept the old process's answer and backed off toward `keep
/// going`, the relaunched process's start-up read as the turn that served
/// the limit. NEGATIVE CONTROL: the same process with no turn seen running
/// since is asked nothing again.
#[test]
fn a_relaunchs_first_decision_on_a_kept_snapshot_reads_the_standing_limit() {
    let rows = {
        let mut r = rows(&[
            "⏺ Running the suites before the release notes.",
            "",
            "⏺ Auto mode lets Claude handle permission prompts automatically — Claude checks \
             each tool call for risky actions and prompt injection",
            "  before executing. Ideal for long-running tasks. Shift+Tab to change mode.",
            "",
        ]);
        r.extend(composer(
            "  ⏵⏵ auto mode on (shift+tab to cycle) · ← for agents",
        ));
        r
    };
    let weekly = crate::harness::upgrade::StandingLimit {
        text: "You've hit your weekly limit · resets Sep 18 at 8pm (America/Los_Angeles)"
            .to_string(),
        until: u64::try_from(ACCOUNT_NOW + 3 * 3600).ok(),
        window: Some("seven_day".to_string()),
        at: u64::try_from(ACCOUNT_NOW - 3600).ok(),
        row: Some("row-weekly".to_string()),
    };
    let relaunched = |carry: bool| {
        let host = AccountHost::scripted(&[None], &["adopted"]);
        *host.pid.lock().unwrap() = Some(4242);
        *host.step.lock().unwrap() = Some("continued");
        let opts = account_opts(&host);
        let mut m = Mock::new(vec![rows.clone()]);
        let mut s = session(&mut m, Some("@s-restored".to_string()));
        s.set_clock(ACCOUNT_NOW, PDT);
        s.set_zone_lookup(test_zones);
        // The old process's last open decision, after a long turn: asked,
        // nothing standing.
        let idle = account_point_of(idle_screen(), Phase::Idle);
        let _ = s.turn_end_at_point(&idle, Some(Duration::from_secs(1800)), &opts);
        assert_eq!(
            host.standing_asks.load(Ordering::SeqCst),
            1,
            "the old process"
        );
        // The relaunch: its transcript stands at the weekly limit, its
        // carry-on owed, and the host's snapshot still names the old process
        // until something reads the agent again.
        *host.standing.lock().unwrap() = Some(weekly.clone());
        *host.pid_on_ask.lock().unwrap() = Some(5151);
        host.carry.store(carry, Ordering::SeqCst);
        let mut point = account_point_of(rows.clone(), Phase::Idle);
        point.screen.cursor_row = rows.iter().position(|r| r.starts_with('❯')).expect("caret");
        let action = s
            .turn_end_at_point(&point, Some(Duration::from_secs(4)), &opts)
            .expect("a decision");
        s.point_as_decided(&mut point);
        let stepped = s
            .host_steps_here(&point, &opts, &mut false, &mut Alone)
            .expect("the host's step");
        (action, point.phase, stepped, host)
    };
    let (action, phase, stepped, host) = relaunched(true);
    assert!(
        matches!(&action, TurnEndAction::WaitUntil { why, .. } if why.contains("usage-weekly")),
        "{action:?}"
    );
    assert!(matches!(phase, Phase::Limited { .. }), "{phase:?}");
    assert!(!stepped, "the carry-on is withheld");
    assert!(host.said("carry-on").is_empty(), "{:?}", host.all());
    // No step wanted there: the start-up's turn asks, as the step would.
    let (action, phase, _, host) = relaunched(false);
    assert!(
        matches!(&action, TurnEndAction::WaitUntil { why, .. } if why.contains("usage-weekly")),
        "no step wanted: {action:?}"
    );
    assert!(matches!(phase, Phase::Limited { .. }), "{phase:?}");
    assert_eq!(host.standing_asks.load(Ordering::SeqCst), 2, "asked again");
    // NEGATIVE CONTROL: the same process, no step wanted and no turn seen
    // running since its last open decision — asked nothing again, and the
    // limit it does not name is no wall.
    let host = AccountHost::scripted(&[None], &[]);
    *host.pid.lock().unwrap() = Some(4242);
    let opts = account_opts(&host);
    let mut m = Mock::new(vec![rows.clone()]);
    let mut s = session(&mut m, Some("@s-restored".to_string()));
    s.set_clock(ACCOUNT_NOW, PDT);
    s.set_zone_lookup(test_zones);
    let idle = account_point_of(idle_screen(), Phase::Idle);
    let _ = s.turn_end_at_point(&idle, Some(Duration::from_secs(1800)), &opts);
    *host.standing.lock().unwrap() = Some(weekly.clone());
    let mut point = account_point_of(rows.clone(), Phase::Idle);
    point.screen.cursor_row = rows.iter().position(|r| r.starts_with('❯')).expect("caret");
    let action = s
        .turn_end_at_point(&point, None, &opts)
        .expect("a decision");
    s.point_as_decided(&mut point);
    assert_eq!(point.phase, Phase::Idle, "{action:?}");
    assert_eq!(
        host.standing_asks.load(Ordering::SeqCst),
        1,
        "asked once a process"
    );
}

/// THE LOOP READS WHOSE COUNTDOWN A NOTICE IS (KI-1015-1 W4, the relaunch
/// variant): the host's snapshot names the agent's process start, read at
/// each decision. A session limit with Claude Code's own countdown armed
/// under it (the transcript's record and the footer's live countdown, as
/// 2.1.296 draws them: `WALL_SESSION_AUTO_CONTINUE_ARMED_MEASURED`) is
/// waited for as the vendor's (`goes on by itself`); the agent relaunched,
/// the same countdown redrawn by the new process is waited out to its reset
/// and grace (`usage-session resets`). NEGATIVE CONTROL: the same process
/// read again keeps the vendor's wait.
#[test]
fn a_relaunched_agents_redrawn_countdown_is_waited_as_nobodys() {
    let rows = {
        let mut r = limited_screen();
        let notice = r
            .iter()
            .position(|row| row.contains("You've hit your session limit"))
            .expect("the notice");
        r.splice(
            notice + 1..notice + 1,
            [
                "",
                "⏺ Usage limit reached · continuing automatically at 7:30pm · esc to cancel",
            ]
            .map(str::to_string),
        );
        let mode = r
            .iter()
            .rposition(|row| row.contains("auto mode on"))
            .expect("the footer's mode row");
        r.splice(
            mode..mode,
            [
                "  ⚠ Usage limit reached · limit resets 7:30pm",
                "    Continuing automatically at 7:30pm · esc to cancel",
            ]
            .map(str::to_string),
        );
        r
    };
    let decide = |relaunched: bool| {
        let host = AccountHost::scripted(&[None], &[]);
        *host.started.lock().unwrap() = Some(ACCOUNT_NOW - 3600);
        let opts = account_opts(&host);
        let mut m = Mock::new(vec![rows.clone()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(ACCOUNT_NOW, PDT);
        s.set_zone_lookup(test_zones);
        let limited = Phase::Limited {
            message: String::new(),
            reset: None,
        };
        let point = account_point_of(rows.clone(), limited.clone());
        let first = s
            .turn_end_at_point(&point, Some(Duration::from_secs(180)), &opts)
            .expect("a decision");
        if relaunched {
            *host.started.lock().unwrap() = Some(ACCOUNT_NOW + 60);
        }
        let mut again = account_point_of(rows.clone(), limited);
        again.screen.seq += 1;
        let second = s
            .turn_end_at_point(&again, Some(Duration::from_secs(2)), &opts)
            .expect("a decision");
        (first, second)
    };
    let (first, second) = decide(true);
    assert!(
        matches!(&first, TurnEndAction::WaitUntil { why, .. } if why.contains("goes on by itself")),
        "{first:?}"
    );
    assert!(
        matches!(&second, TurnEndAction::WaitUntil { why, .. } if why == "usage-session resets"),
        "{second:?}"
    );
    // NEGATIVE CONTROL: the same process.
    let (_, second) = decide(false);
    assert!(
        matches!(&second, TurnEndAction::WaitUntil { why, .. } if why.contains("goes on by itself")),
        "{second:?}"
    );
}

/// THE TYPING BUDGET COUNTS TYPED ACTS, NOT RELAUNCHES: a made account
/// move's row is `typed` in the ledger (so that a later loop reads the move
/// back) and was counted toward `continue_per_hour` by a loop that started
/// after it — where the loop that made it counted no restart. NEGATIVE
/// CONTROL: a draft submitted under the rule is a typed act, and counts.
#[test]
fn an_account_move_made_is_no_typed_act_of_the_budgets() {
    use crate::supervise::approvals::{
        ACCOUNT_MOVE_COMMAND, Outcome, Row, account_switch_reason, typed_at,
    };
    let (dir, ledger) = ledger_at("account-budget");
    let row = |rule: &str, command: &str, reason: &str, ts: i64| {
        Row {
            rule_id: rule,
            outcome: Outcome::Typed,
            command,
            reason,
            box_seq: 1,
        }
        .to_json(ts, Some("s-1"))
    };
    let rows = [
        row("continue@v1", "keep going", "the turn-end policy", 1_000),
        row(
            RULE_ACCOUNT,
            &format!("{ACCOUNT_MOVE_COMMAND}work-2"),
            &account_switch_reason("work-2", AccountAt::Wall),
            2_000,
        ),
        row(RULE_ACCOUNT, "my own words", "the turn-end policy", 3_000),
    ];
    std::fs::write(&ledger, rows.join("\n") + "\n").expect("ledger");
    assert_eq!(typed_at(&ledger, Some("@s-1")), [1_000, 3_000]);
    let _ = std::fs::remove_dir_all(&dir);
}

/// A LOOP RESTARTED AT A WALL TAKES UP THE USAGE-RESUME THE LOOP BEFORE IT
/// TYPED — unless the session has moved to another account since: that
/// continuation was typed into the account it LEFT, and seeded, the new
/// account's first limit was worked as the retry of a wall it never met.
/// NEGATIVE CONTROLS: with no move after it the act is taken up as before;
/// one typed AFTER the move is the new account's own; a move that could not
/// be made changes nothing. An act typed in a limit's place is read as the
/// continuation is ([`an_act_in_a_limits_place_is_the_try_a_successor_backs_off_from`]);
/// its controls: the same act unmarked, another session's, one that typed
/// nothing.
#[test]
fn a_usage_resume_typed_into_the_account_a_session_left_is_not_taken_up() {
    use crate::supervise::approvals::{
        ACCOUNT_MOVE_COMMAND, Outcome, Row, account_switch_reason, account_unmade_reason,
        act_reason, usage_attempt,
    };
    use crate::supervise::policy::turn_end::{LimitTry, RULE_ANSWER, RULE_LIMIT_RESUME};
    let (dir, ledger) = ledger_at("account-usage-seed");
    let in_place = LimitTry {
        bucket: false,
        in_place: true,
        attempts: 1,
        entitlement: false,
    };
    let row = |rule: &str, outcome: Outcome, command: &str, reason: &str, ts: i64| {
        Row {
            rule_id: rule,
            outcome,
            command,
            reason,
            box_seq: 1,
        }
        .to_json(ts, Some("s-1"))
    };
    let resume = |ts: i64| {
        row(
            RULE_LIMIT_RESUME,
            Outcome::Typed,
            "keep going",
            "the turn-end policy",
            ts,
        )
    };
    let to = format!("{ACCOUNT_MOVE_COMMAND}work-2");
    let moved = |ts: i64| {
        row(
            RULE_ACCOUNT,
            Outcome::Typed,
            &to,
            &account_switch_reason("work-2", AccountAt::Wall),
            ts,
        )
    };
    let unmade = row(
        RULE_ACCOUNT,
        Outcome::Skipped,
        &to,
        &account_unmade_reason("work-2", AccountAt::Wall, Some("refused:line")),
        2_000,
    );
    let write = |rows: &[String]| std::fs::write(&ledger, rows.join("\n") + "\n").expect("ledger");
    let read = || usage_attempt(&ledger, Some("@s-1")).map(|a| a.at_ms);
    write(&[resume(1_000), moved(2_000)]);
    assert_eq!(read(), None, "typed into the account it left");
    // NEGATIVE CONTROLS.
    write(&[resume(1_000)]);
    assert_eq!(read(), Some(1_000));
    write(&[resume(1_000), moved(2_000), resume(3_000)]);
    assert_eq!(read(), Some(3_000), "the new account's own");
    write(&[resume(1_000), unmade]);
    assert_eq!(read(), Some(1_000), "no move was made");
    // AN ACT TYPED IN A LIMIT'S PLACE ([`act_reason`]'s mark: the done check,
    // the reversible answer) is the wall's try as the continuation is: the
    // latest of the two is taken up, under the same account-move rule — and
    // a row an older build wrote with the retired save-then-wait switch's
    // words before its mark reads back as ever.
    let worded = |wind: Option<&str>, reason: String| match wind {
        Some(w) => reason.replacen(
            "the turn-end policy",
            &format!("the turn-end policy {w}"),
            1,
        ),
        None => reason,
    };
    let placed = |rule: &str, wind: Option<&str>, ts: i64| {
        row(
            rule,
            Outcome::Typed,
            "…",
            &worded(wind, act_reason(Some(in_place))),
            ts,
        )
    };
    write(&[placed(RULE_DONE_CHECK, None, 1_000)]);
    assert_eq!(read(), Some(1_000));
    write(&[resume(1_000), placed(RULE_ANSWER, None, 3_000)]);
    assert_eq!(
        read(),
        Some(3_000),
        "the act in the limit's place, the latest"
    );
    write(&[placed(RULE_DONE_CHECK, None, 1_000), resume(3_000)]);
    assert_eq!(read(), Some(3_000), "the continuation, the latest");
    write(&[placed(RULE_DONE_CHECK, None, 1_000), moved(2_000)]);
    assert_eq!(read(), None, "typed into the account it left");
    write(&[moved(2_000), placed(RULE_DONE_CHECK, None, 3_000)]);
    assert_eq!(read(), Some(3_000), "the new account's own");
    let wind = "(model switch: kind=wind-down from=GPT-6-Astra effort=ultra to=gpt-6-luna \
                back_at=5000 marker=ATERM-SAVED-3f9a1c2e goal=paused phase=winding)";
    write(&[placed(RULE_DONE_CHECK, Some(wind), 1_000)]);
    assert_eq!(read(), Some(1_000), "under the switch's words");
    // THE LIMIT EACH ROW NAMES, the wall's attempts the act left and the
    // ladder it was on, are read back with it, the switch's words before the
    // mark or not; an unmarked continuation (0.104.0's rows) is a usage
    // window's first try, on the short ladder.
    let window = LimitTry {
        bucket: false,
        in_place: false,
        attempts: 1,
        entitlement: false,
    };
    let at_bucket = LimitTry {
        bucket: true,
        ..window
    };
    for (rule, wind, limit) in [
        (RULE_DONE_CHECK, None, in_place),
        (
            RULE_ANSWER,
            Some(wind),
            LimitTry {
                bucket: true,
                ..in_place
            },
        ),
        (RULE_LIMIT_RESUME, None, at_bucket),
        (RULE_LIMIT_RESUME, Some(wind), window),
        (
            RULE_LIMIT_RESUME,
            None,
            LimitTry {
                attempts: 3,
                ..window
            },
        ),
        (
            RULE_DONE_CHECK,
            Some(wind),
            LimitTry {
                attempts: 2,
                ..in_place
            },
        ),
        (
            RULE_LIMIT_RESUME,
            None,
            LimitTry {
                attempts: 2,
                entitlement: true,
                ..at_bucket
            },
        ),
        (
            RULE_DONE_CHECK,
            Some(wind),
            LimitTry {
                attempts: 3,
                entitlement: true,
                ..in_place
            },
        ),
    ] {
        write(&[row(
            rule,
            Outcome::Typed,
            "…",
            &worded(wind, act_reason(Some(limit))),
            1_000,
        )]);
        assert_eq!(
            usage_attempt(&ledger, Some("@s-1")).map(|a| (a.at_ms, a.limit)),
            Some((1_000, limit)),
            "{rule} {wind:?}"
        );
    }
    write(&[resume(1_000)]);
    assert_eq!(
        usage_attempt(&ledger, Some("@s-1")).map(|a| (a.at_ms, a.limit)),
        Some((1_000, window))
    );
    // NEGATIVE CONTROLS: the same act unmarked (an ordinary done check, with
    // the switch's words or not), another session's, and one that typed
    // nothing.
    for wind in [None, Some(wind)] {
        write(&[row(
            RULE_DONE_CHECK,
            Outcome::Typed,
            "…",
            &worded(wind, act_reason(None)),
            1_000,
        )]);
        assert_eq!(read(), None, "an ordinary done check");
    }
    let theirs = Row {
        rule_id: RULE_DONE_CHECK,
        outcome: Outcome::Typed,
        command: "…",
        reason: &act_reason(Some(in_place)),
        box_seq: 1,
    }
    .to_json(1_000, Some("s-9"));
    write(&[theirs]);
    assert_eq!(read(), None, "another session's");
    write(&[row(
        RULE_DONE_CHECK,
        Outcome::Skipped,
        "…",
        &act_reason(Some(in_place)),
        1_000,
    )]);
    assert_eq!(read(), None, "nothing typed");
    let _ = std::fs::remove_dir_all(&dir);
}

/// A TRY MET AGAIN IS READ FROM THE LEDGER'S WALL ROW AFTER IT
/// (`approvals::UsageAttempt::met_ms`, the verifier of e9e6f65e9, B-1): a
/// `wall-wait@v1` row of the try's limit — a bucket's for a try at one, a
/// usage window's or a spend limit's otherwise — after the try's row, open
/// still or closed since (a live turn's busy read ends the remembered wall,
/// and its end row closes it). A bucket whose row's words name no limit is
/// the bucket its `rateLimitType` named (the verifier of e09018898, B5-3:
/// read by its words alone, `You've hit your limit · … — seven_day_opus` was
/// a usage window's, and a try at the bucket was never met again).
/// NEGATIVE CONTROLS: no wall row after the try; a wall of the other limit,
/// that named bucket's at a window's try and a window its `rateLimitType`
/// named at a bucket's among them; a wall row before the try, or before a
/// newer try; and a try the worker's work ended (`approvals::LIMIT_ENDED`)
/// is none at all.
#[test]
fn a_try_met_again_is_read_from_the_walls_row_after_it() {
    use crate::supervise::approvals::{
        LIMIT_ENDED, Outcome, RULE_WALL_WAIT, RULE_WALL_WAIT_END, Row, act_reason, usage_attempt,
        wall_wait_reason,
    };
    use crate::supervise::policy::turn_end::{LimitTry, RULE_LIMIT_RESUME};
    let (dir, ledger) = ledger_at("try-met-again");
    let window = LimitTry {
        bucket: false,
        in_place: false,
        attempts: 1,
        entitlement: false,
    };
    let at_bucket = LimitTry {
        bucket: true,
        ..window
    };
    let row = |rule: &str, outcome: Outcome, reason: &str, ts: i64| {
        Row {
            rule_id: rule,
            outcome,
            command: if outcome == Outcome::Typed {
                "keep going"
            } else {
                ""
            },
            reason,
            box_seq: 1,
        }
        .to_json(ts, Some("s-1"))
    };
    let try_at = |limit: LimitTry, ts: i64| {
        row(
            RULE_LIMIT_RESUME,
            Outcome::Typed,
            &act_reason(Some(limit)),
            ts,
        )
    };
    // A wall's row from before the rows named the kind the loop read (0.104.0's,
    // and this branch's before R5-1): read by its words alone.
    let wall = |message: &str, ts: i64| {
        row(
            RULE_WALL_WAIT,
            Outcome::Waiting,
            &format!("the turn-end policy (wall: reset_unix=-; reset=-; message={message})"),
            ts,
        )
    };
    // ...and as the loop writes it now, naming that kind (the verifier of
    // b5a94f3c1, R5-1: the generic banner a bucket's `rateLimitType` named,
    // its countdown's words after the type, read back as a usage window).
    let wall_named = |kind: aterm_phase::WallKind, message: &str, ts: i64| {
        row(
            RULE_WALL_WAIT,
            Outcome::Waiting,
            &wall_wait_reason(None, None, kind, message),
            ts,
        )
    };
    let generic = "You've hit your limit · resets 4pm (America/Los_Angeles)";
    let counting = format!(
        "{generic} \u{2014} seven_day_opus \u{2014} \u{26a0} Usage limit reached \u{b7} limit resets \
         4pm \u{2014} Continuing automatically at 4pm \u{b7} esc to cancel"
    );
    let bucket_kind = aterm_phase::WallKind::ModelBucket { consent: false };
    let spend = |ts: i64| wall("You've hit your monthly spend limit.", ts);
    let sonnet = |ts: i64| {
        wall(
            "You've hit your Sonnet limit · resets Oct 17 at 4:20pm (America/Los_Angeles)",
            ts,
        )
    };
    // A bucket whose row's words name no limit, named by its
    // `rateLimitType`, as the loop writes it (the verifier of e09018898,
    // B5-3); and a five-hour window's words, as the loop writes them.
    let named_words = |limit: &str| {
        crate::supervise::run::wall_confirm::limit_words(
            "You've hit your limit · resets 4pm (America/Los_Angeles)",
            Some(limit),
        )
    };
    let opus = |ts: i64| wall(&named_words("seven_day_opus"), ts);
    let window_named = |ts: i64| wall(&named_words("five_hour"), ts);
    let left = |ts: i64| {
        row(
            RULE_WALL_WAIT_END,
            Outcome::Waiting,
            "the wall left the screen or the worker worked",
            ts,
        )
    };
    let worked = |ts: i64| row(RULE_WALL_WAIT_END, Outcome::Waiting, LIMIT_ENDED, ts);
    let cases = [
        (
            "a spend wall read after a window's try",
            vec![try_at(window, 1_000), spend(2_000)],
            Some((1_000, true)),
        ),
        (
            "a bucket its rateLimitType named, read after a bucket's try",
            vec![try_at(at_bucket, 1_000), opus(2_000)],
            Some((1_000, true)),
        ),
        (
            "control: a bucket its rateLimitType named, a window's try",
            vec![try_at(window, 1_000), opus(2_000)],
            Some((1_000, false)),
        ),
        (
            "control: a window its rateLimitType named, a bucket's try",
            vec![try_at(at_bucket, 1_000), window_named(2_000)],
            Some((1_000, false)),
        ),
        (
            "a bucket the row names, its countdown's words after the type",
            vec![
                try_at(at_bucket, 1_000),
                wall_named(bucket_kind, &counting, 2_000),
            ],
            Some((1_000, true)),
        ),
        (
            "a bucket the row names, words that carry no type (seven_day_overage_included)",
            vec![
                try_at(at_bucket, 1_000),
                wall_named(bucket_kind, generic, 2_000),
            ],
            Some((1_000, true)),
        ),
        (
            "control: the same words, a row that names no kind",
            vec![try_at(at_bucket, 1_000), wall(&counting, 2_000)],
            Some((1_000, false)),
        ),
        (
            "control: a window the row names, a bucket's try",
            vec![
                try_at(at_bucket, 1_000),
                wall_named(aterm_phase::WallKind::UsageSession, generic, 2_000),
            ],
            Some((1_000, false)),
        ),
        (
            "control: a bucket the row names, a window's try",
            vec![
                try_at(window, 1_000),
                wall_named(bucket_kind, generic, 2_000),
            ],
            Some((1_000, false)),
        ),
        (
            "closed since by a live turn",
            vec![try_at(window, 1_000), spend(2_000), left(3_000)],
            Some((1_000, true)),
        ),
        (
            "a bucket read after a bucket's try",
            vec![try_at(at_bucket, 1_000), sonnet(2_000), left(3_000)],
            Some((1_000, true)),
        ),
        // NEGATIVE CONTROLS.
        (
            "control: no wall after the try",
            vec![spend(500), try_at(window, 1_000)],
            Some((1_000, false)),
        ),
        (
            "control: the other limit's wall",
            vec![try_at(window, 1_000), sonnet(2_000)],
            Some((1_000, false)),
        ),
        (
            "control: the other limit's wall, a bucket's try",
            vec![try_at(at_bucket, 1_000), spend(2_000)],
            Some((1_000, false)),
        ),
        (
            "control: a newer try",
            vec![try_at(window, 1_000), spend(2_000), try_at(window, 3_000)],
            Some((3_000, false)),
        ),
        (
            "control: the worker's work ended it",
            vec![try_at(window, 1_000), spend(2_000), worked(3_000)],
            None,
        ),
        (
            "control: a try after the work",
            vec![try_at(window, 1_000), worked(2_000), try_at(window, 3_000)],
            Some((3_000, false)),
        ),
    ];
    let mut wrong = Vec::new();
    for (case, rows, want) in cases {
        std::fs::write(&ledger, rows.join("\n") + "\n").expect("ledger");
        let got = usage_attempt(&ledger, Some("@s-1")).map(|a| (a.at_ms, a.met_ms.is_some()));
        if got != want {
            wrong.push(format!("{case}: {got:?}, not {want:?}"));
        }
    }
    let _ = std::fs::remove_dir_all(&dir);
    assert!(wrong.is_empty(), "{wrong:#?}");
}

/// A TRY MET AGAIN IS SEEDED FROM THE WALL THAT MET IT
/// (`approvals::UsageAttempt`): WHEN — the first wall row of the try's limit
/// after it, the track's appearance as the first loop moved it where it read
/// the try's answer (the verifier of 5b72b1613, R5-2: counted from the try,
/// a successor typed as much sooner as the try's own short turn ran) — and
/// ON WHICH LADDER — the one that wall puts the track on, read after read
/// (M7-3: a five-hour try met by the monthly spend limit kept the short
/// ladder's mark, and a successor between 30 minutes and two hours after it
/// took up nothing and typed up to an hour before the first loop). The
/// first row after a take ([`approvals::WALL_TAKEN`]) is the try's own
/// turn's. NEGATIVE CONTROLS: a later row of the same meeting moves
/// nothing; a spend try met by a window whose reset was placed, and a
/// bucket that goes on by itself, are on the short ladder; a try met by
/// nothing keeps its mark.
#[test]
fn a_try_met_again_is_seeded_from_the_wall_that_met_it() {
    use crate::supervise::approvals::{
        Outcome, RULE_WALL_WAIT, RULE_WALL_WAIT_END, Row, WALL_TAKEN, act_reason, usage_attempt,
        wall_wait_reason,
    };
    use crate::supervise::policy::turn_end::{LimitTry, RULE_LIMIT_RESUME};
    use aterm_phase::WallKind;
    let (dir, ledger) = ledger_at("try-met-by");
    let window = LimitTry {
        bucket: false,
        in_place: false,
        attempts: 1,
        entitlement: false,
    };
    let at_spend = LimitTry {
        entitlement: true,
        ..window
    };
    let at_bucket = LimitTry {
        bucket: true,
        ..window
    };
    let row = |rule: &str, outcome: Outcome, reason: &str, ts: i64| {
        Row {
            rule_id: rule,
            outcome,
            command: if outcome == Outcome::Typed {
                "keep going"
            } else {
                ""
            },
            reason,
            box_seq: 1,
        }
        .to_json(ts, Some("s-1"))
    };
    let try_at = |limit: LimitTry, ts: i64| {
        row(
            RULE_LIMIT_RESUME,
            Outcome::Typed,
            &act_reason(Some(limit)),
            ts,
        )
    };
    let wall = |kind: WallKind, placed: Option<i64>, message: &str, ts: i64| {
        row(
            RULE_WALL_WAIT,
            Outcome::Waiting,
            &wall_wait_reason(placed, None, kind, message),
            ts,
        )
    };
    let spend = |ts: i64| {
        wall(
            WallKind::Spend,
            None,
            "You've hit your monthly spend limit.",
            ts,
        )
    };
    let five = |ts: i64| {
        wall(
            WallKind::UsageSession,
            Some(1_792_279_200),
            "You've hit your session limit · resets 4pm (America/Los_Angeles)",
            ts,
        )
    };
    let opus = |ts: i64| {
        wall(
            WallKind::ModelBucket { consent: false },
            None,
            "You've hit your Opus limit",
            ts,
        )
    };
    let opus_counting = |ts: i64| {
        wall(
            WallKind::ModelBucket { consent: false },
            None,
            "You've hit your Opus limit \u{2014} \u{26a0} Usage limit reached \u{b7} Continuing \
             automatically at 4pm \u{b7} esc to cancel",
            ts,
        )
    };
    let end = |why: &str, ts: i64| row(RULE_WALL_WAIT_END, Outcome::Waiting, why, ts);
    let left = |ts: i64| end("the wall left the screen or the worker worked", ts);
    // (case, rows, met at, on the entitlement ladder)
    let cases = [
        (
            "the try's own turn met the limit: that row's time",
            vec![try_at(at_spend, 1_000), left(1_020), spend(1_260)],
            Some(1_260),
            true,
        ),
        (
            "the first row of the meeting, a later one moving nothing",
            vec![
                try_at(at_spend, 1_000),
                spend(1_030),
                left(2_000),
                spend(3_000),
            ],
            Some(1_030),
            true,
        ),
        (
            "after the take, the try's own turn's row",
            vec![
                try_at(at_spend, 1_000),
                spend(1_005),
                end(WALL_TAKEN, 1_020),
                spend(4_000),
            ],
            Some(4_000),
            true,
        ),
        (
            "a five-hour try met by the spend limit: the entitlement ladder",
            vec![try_at(window, 1_000), spend(1_003)],
            Some(1_003),
            true,
        ),
        (
            "a bucket's try met by a bucket no reset ends",
            vec![try_at(at_bucket, 1_000), opus(1_003)],
            Some(1_003),
            true,
        ),
        // NEGATIVE CONTROLS.
        (
            "control: a spend try met by a window, its reset placed",
            vec![try_at(at_spend, 1_000), five(1_003)],
            Some(1_003),
            false,
        ),
        (
            "control: a bucket that goes on by itself",
            vec![try_at(at_bucket, 1_000), opus_counting(1_003)],
            Some(1_003),
            false,
        ),
        (
            "control: a five-hour try met by its window",
            vec![try_at(window, 1_000), five(1_003)],
            Some(1_003),
            false,
        ),
        (
            "control: not met, the mark's ladder",
            vec![try_at(at_spend, 1_000)],
            None,
            true,
        ),
        (
            "control: taken, not met since",
            vec![try_at(window, 1_000), spend(1_005), end(WALL_TAKEN, 1_020)],
            None,
            true,
        ),
    ];
    let mut wrong = Vec::new();
    for (case, rows, met, entitlement) in cases {
        std::fs::write(&ledger, rows.join("\n") + "\n").expect("ledger");
        let got = usage_attempt(&ledger, Some("@s-1")).map(|a| (a.met_ms, a.limit.entitlement));
        if got != Some((met, entitlement)) {
            wrong.push(format!("{case}: {got:?}, not {:?}", (met, entitlement)));
        }
    }
    let _ = std::fs::remove_dir_all(&dir);
    assert!(wrong.is_empty(), "{wrong:#?}");
}

/// THE DONE CHECK THE LEDGER SAYS IS OWED ITS ANSWER
/// (`approvals::done_check_owed`, the verifier of 5b72b1613, M7-5): the last
/// act is the check (when, and in a limit's place or not), or a wall's retry
/// typed while a check a wall cut stood; a wall's row after either cuts it,
/// a take row after that wall undoes the cut (that wall was the screen it
/// was typed at), and any other end row of the cut wall (the worker's work,
/// a person's turn) ends it. The open-items challenge is owed as the check
/// is, under its own rule, a wall's retry of it too (the merge review's
/// MG7-A3), and the loop's records end it as they end the check's (the merge
/// review's MG9-S4): its answer judged no done report (`point@v1`) owes it no
/// more, judged done (`task-done@v1`) owes it answered — after a wall's
/// retry too — and Off stood (`autopilot-off@v1`) drops it where a wall cut
/// it. Each case's first read and verdict are compared too. NEGATIVE
/// CONTROLS: any other act after the check; a wall's retry with no check
/// cut; the accounts probe's `/usage` is no act; a second point judged after
/// the challenge.
#[test]
fn the_done_check_the_ledger_says_is_owed_its_answer() {
    use crate::supervise::approvals::{
        Carried, CheckOwed, LIMIT_ENDED, OFF_STOOD, Outcome, RULE_OFF_STOOD, RULE_POINT,
        RULE_TASK_DONE, RULE_WALL_WAIT, RULE_WALL_WAIT_END, Row, TASK_DONE, WALL_TAKEN, act_reason,
        done_check_owed, point_reason, wall_wait_reason,
    };
    use crate::supervise::policy::turn_end::{
        LimitTry, RULE_CONTINUE, RULE_DONE_CHECK, RULE_LIMIT_RESUME, RULE_OPEN_ITEMS,
        RULE_USAGE_PROBE,
    };
    let (dir, ledger) = ledger_at("check-owed");
    let row = |rule: &str, outcome: Outcome, reason: &str, ts: i64| {
        Row {
            rule_id: rule,
            outcome,
            command: "keep going",
            reason,
            box_seq: 1,
        }
        .to_json(ts, Some("s-1"))
    };
    let typed = |rule: &str, ts: i64| row(rule, Outcome::Typed, "the turn-end policy", ts);
    let in_place = |ts: i64| {
        row(
            RULE_DONE_CHECK,
            Outcome::Typed,
            &act_reason(Some(LimitTry {
                bucket: false,
                in_place: true,
                attempts: 1,
                entitlement: false,
            })),
            ts,
        )
    };
    let wall = |ts: i64| {
        row(
            RULE_WALL_WAIT,
            Outcome::Waiting,
            &wall_wait_reason(
                None,
                None,
                aterm_phase::WallKind::UsageWeekly,
                "You've hit your weekly limit · resets Sep 19 at 11am (America/Los_Angeles)",
            ),
            ts,
        )
    };
    let end = |why: &str, ts: i64| row(RULE_WALL_WAIT_END, Outcome::Waiting, why, ts);
    let point = |ts: i64| {
        row(
            RULE_POINT,
            Outcome::Waiting,
            &point_reason(Carried::streak(0), false),
            ts,
        )
    };
    let task_done = |ts: i64| row(RULE_TASK_DONE, Outcome::Waiting, TASK_DONE, ts);
    let off = |ts: i64| row(RULE_OFF_STOOD, Outcome::Waiting, OFF_STOOD, ts);
    let of = |rule: &'static str, cut: bool, check: Option<(i64, bool)>| {
        Some(CheckOwed {
            rule,
            cut,
            check,
            read_ms: None,
            // In a limit's place, no read of it yet.
            unread: !cut && check.is_some_and(|(_, in_place)| in_place),
            answered: false,
        })
    };
    let owed = |cut: bool, check: Option<(i64, bool)>| of(RULE_DONE_CHECK, cut, check);
    let challenge = |cut: bool, check: Option<(i64, bool)>| of(RULE_OPEN_ITEMS, cut, check);
    // Its first read: the wall's row that cut it.
    let read = |o: Option<CheckOwed>, ms: i64| {
        o.map(|o| CheckOwed {
            read_ms: Some(ms),
            unread: false,
            ..o
        })
    };
    // Its answer judged: the task ended there.
    let answered = |o: Option<CheckOwed>| {
        o.map(|o| CheckOwed {
            answered: true,
            ..o
        })
    };
    let cases = [
        (
            "the check",
            vec![typed(RULE_DONE_CHECK, 1_000)],
            owed(false, Some((1_000, false))),
        ),
        (
            "the challenge",
            vec![typed(RULE_OPEN_ITEMS, 1_000)],
            challenge(false, Some((1_000, false))),
        ),
        (
            "the challenge cut, its retry delivers it",
            vec![
                typed(RULE_OPEN_ITEMS, 1_000),
                wall(2_000),
                typed(RULE_LIMIT_RESUME, 3_000),
            ],
            challenge(false, None),
        ),
        (
            "the challenge cut: its first read is the wall's row",
            vec![typed(RULE_OPEN_ITEMS, 1_000), wall(2_000)],
            read(challenge(true, Some((1_000, false))), 2_000),
        ),
        (
            "the challenge cut, the wall's point judged: the retry's to deliver still",
            vec![typed(RULE_OPEN_ITEMS, 1_000), wall(2_000), point(2_001)],
            read(challenge(true, Some((1_000, false))), 2_000),
        ),
        (
            "the challenge, its answer judged no done report",
            vec![typed(RULE_OPEN_ITEMS, 1_000), point(2_000)],
            None,
        ),
        (
            "the challenge, its answer judged done",
            vec![
                typed(RULE_OPEN_ITEMS, 1_000),
                point(2_000),
                task_done(2_001),
            ],
            answered(challenge(false, None)),
        ),
        (
            "the challenge cut, Off stood",
            vec![typed(RULE_OPEN_ITEMS, 1_000), wall(2_000), off(3_000)],
            None,
        ),
        (
            "the challenge Off stood over, no wall: still owed",
            vec![typed(RULE_OPEN_ITEMS, 1_000), off(3_000)],
            challenge(false, Some((1_000, false))),
        ),
        (
            "the challenge cut, its retry's answer judged done",
            vec![
                typed(RULE_OPEN_ITEMS, 1_000),
                wall(2_000),
                typed(RULE_LIMIT_RESUME, 3_000),
                point(4_000),
                task_done(4_001),
            ],
            answered(challenge(false, None)),
        ),
        (
            "control: another act after the challenge",
            vec![typed(RULE_OPEN_ITEMS, 1_000), typed(RULE_CONTINUE, 2_000)],
            None,
        ),
        (
            "control: a second point judged after the challenge",
            vec![
                typed(RULE_OPEN_ITEMS, 1_000),
                point(2_000),
                point(3_000),
                task_done(3_001),
            ],
            None,
        ),
        (
            "the check in a limit's place",
            vec![in_place(1_000)],
            owed(false, Some((1_000, true))),
        ),
        (
            "the check in a limit's place, Off stood over it: no read",
            vec![in_place(1_000), off(2_000)],
            owed(false, Some((1_000, true))),
        ),
        (
            "the check in a limit's place, its turn read running: read",
            vec![in_place(1_000), end(LIMIT_ENDED, 2_000)],
            owed(false, Some((1_000, true))).map(|o| CheckOwed { unread: false, ..o }),
        ),
        (
            "the check in a limit's place, cut by a wall: read there",
            vec![in_place(1_000), wall(2_000)],
            read(owed(true, Some((1_000, true))), 2_000),
        ),
        (
            "the check, the probe's /usage after it",
            vec![
                typed(RULE_DONE_CHECK, 1_000),
                typed(RULE_USAGE_PROBE, 2_000),
            ],
            owed(false, Some((1_000, false))),
        ),
        (
            "cut by a wall",
            vec![typed(RULE_DONE_CHECK, 1_000), wall(2_000)],
            read(owed(true, Some((1_000, false))), 2_000),
        ),
        (
            "cut, its retry delivers it",
            vec![
                typed(RULE_DONE_CHECK, 1_000),
                wall(2_000),
                typed(RULE_LIMIT_RESUME, 3_000),
            ],
            owed(false, None),
        ),
        (
            "the retry cut again",
            vec![
                typed(RULE_DONE_CHECK, 1_000),
                wall(2_000),
                typed(RULE_LIMIT_RESUME, 3_000),
                wall(4_000),
            ],
            read(owed(true, None), 4_000),
        ),
        (
            "the wall the screen it was typed at: taken",
            vec![
                typed(RULE_DONE_CHECK, 1_000),
                wall(2_000),
                typed(RULE_LIMIT_RESUME, 3_000),
                wall(3_005),
                end(WALL_TAKEN, 3_020),
            ],
            owed(false, None),
        ),
        // NEGATIVE CONTROLS.
        (
            "control: another act after the check",
            vec![typed(RULE_DONE_CHECK, 1_000), typed(RULE_CONTINUE, 2_000)],
            None,
        ),
        (
            "control: a wall's retry, no check cut",
            vec![
                typed(RULE_DONE_CHECK, 1_000),
                typed(RULE_LIMIT_RESUME, 2_000),
            ],
            None,
        ),
        (
            "control: the cut wall ended by work",
            vec![
                typed(RULE_DONE_CHECK, 1_000),
                wall(2_000),
                end(LIMIT_ENDED, 3_000),
            ],
            None,
        ),
        ("control: no check", vec![typed(RULE_CONTINUE, 1_000)], None),
    ];
    let mut wrong = Vec::new();
    for (case, rows, want) in cases {
        std::fs::write(&ledger, rows.join("\n") + "\n").expect("ledger");
        let got = done_check_owed(&ledger, Some("@s-1"));
        if got != want {
            wrong.push(format!("{case}: {got:?}, not {want:?}"));
        }
    }
    let _ = std::fs::remove_dir_all(&dir);
    assert!(wrong.is_empty(), "{wrong:#?}");
}

/// A BUCKET ITS RATE LIMIT TYPE NAMED IS THAT BUCKET IN THE LEDGER'S WALL
/// (the verifier of e09018898, B5-3). A limit row whose words name no limit
/// (`You've hit your limit · resets 4pm`) is named a model's bucket by its
/// `quotaLimits.rateLimitType` (`seven_day_opus`), and the loop writes the
/// wall's words with that type after them (`wall_confirm::limit_words`). A
/// loop that follows takes that open wall up as the bucket it is: its track
/// a bucket's, not a usage window's (`Session::seed_wall_memory`), as
/// `approvals::UsageAttempt::met_ms` reads it for a try (the ledger's own test,
/// [`a_try_met_again_is_read_from_the_walls_row_after_it`]). Measured before
/// (the verifier's probe): the words read back as a five-hour window's.
/// NEGATIVE CONTROLS: a window its `rateLimitType` named (`five_hour`: no
/// type after the words) and a bucket whose words name it are read by their
/// words, and so are words that only end on a dash and a type the loop
/// never writes there (`— seven_day`).
#[test]
fn a_bucket_its_rate_limit_type_named_is_that_bucket_in_the_ledgers_wall() {
    use crate::supervise::approvals::OpenWall;
    use crate::supervise::run::wall_confirm::{limit_named, limit_words, words_kind};
    use aterm_phase::WallKind;
    const RESET: i64 = 1_792_279_200;
    let bucket = WallKind::ModelBucket { consent: false };
    let text = "You've hit your limit · resets 4pm (America/Los_Angeles)";
    let opus = limit_words(text, Some("seven_day_opus"));
    assert_eq!(limit_named(text, Some("seven_day_opus")), Some(bucket));
    assert!(opus.ends_with(" \u{2014} seven_day_opus"), "{opus}");
    // The type a dash ends on is read for a bucket's only where the loop
    // wrote it so: `seven_day` alone would name the weekly window.
    assert_eq!(
        limit_named(text, Some("seven_day")),
        Some(WallKind::UsageWeekly)
    );
    let sonnet = "You've hit your Sonnet limit · resets Oct 17 at 4:20pm (America/Los_Angeles)";
    // The countdown's words the loop writes after a bucket's type where the
    // vendor goes on by itself (`named_by`; the verifier of b5a94f3c1, R5-1).
    let counting = format!(
        "{opus} \u{2014} \u{26a0} Usage limit reached \u{b7} limit resets 4pm \u{2014} \
         Continuing automatically at 4pm \u{b7} esc to cancel"
    );
    let mut wrong = Vec::new();
    for (case, words, named, want) in [
        (
            "a bucket its rateLimitType named",
            opus.clone(),
            None,
            Some(bucket),
        ),
        (
            "a bucket the row names, its countdown's words after the type",
            counting.clone(),
            Some(bucket),
            Some(bucket),
        ),
        (
            "a bucket the row names, words that carry no type (seven_day_overage_included)",
            text.to_string(),
            Some(bucket),
            Some(bucket),
        ),
        (
            "control: the countdown's words, a row that names no kind",
            counting.clone(),
            None,
            Some(WallKind::UsageSession),
        ),
        (
            "control: a window the row names",
            text.to_string(),
            Some(WallKind::UsageSession),
            Some(WallKind::UsageSession),
        ),
        (
            "control: a window its rateLimitType named",
            limit_words(text, Some("five_hour")),
            None,
            Some(WallKind::UsageSession),
        ),
        (
            "control: a bucket its words name",
            limit_words(sonnet, Some("seven_day_sonnet")),
            None,
            aterm_phase::classify_wall(sonnet),
        ),
        (
            "control: a dash and a type no bucket's",
            format!("{text} \u{2014} seven_day"),
            None,
            aterm_phase::classify_wall(&format!("{text} \u{2014} seven_day")),
        ),
    ] {
        let read = crate::supervise::approvals::wall_kind(named, &words);
        if named.is_none() {
            assert_eq!(
                read,
                words_kind(&words),
                "{case}: a row naming none is its words'"
            );
        }
        // A loop that follows takes the open wall up: the track it seeds.
        let mut m = Mock::new(vec![]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(RESET - 3600, PDT);
        s.seed_wall_memory(Some(OpenWall {
            at_ms: (RESET - 4000) * 1000,
            message: words.clone(),
            reset: Some("4pm (America/Los_Angeles)".to_string()),
            reset_unix: Some(RESET),
            kind: named,
            judged_ms: None,
            retry_ms: None,
        }));
        let tracked = [bucket, WallKind::UsageSession]
            .into_iter()
            .find(|&k| s.turn_end.wall_attempts(k).is_some());
        let want_track = want.map(|k| match k {
            WallKind::ModelBucket { .. } => bucket,
            _ => WallKind::UsageSession,
        });
        if read != want || tracked != want_track {
            wrong.push(format!(
                "{case} ({words:?}): read {read:?}, not {want:?}; tracked {tracked:?}"
            ));
        }
    }
    assert!(wrong.is_empty(), "{wrong:#?}");
}

/// `d` to the nearest whole second: a wait [`past_take_window`] measured
/// counts from the instant its first read was decided, a millisecond or so
/// after the test's own.
fn whole_secs(d: Duration) -> Duration {
    Duration::from_secs(u64::try_from((d.as_millis() + 500) / 1000).unwrap_or(u64::MAX))
}

/// A SUCCESSOR'S FIRST POINT, PAST THE TAKE WINDOW ITS FIRST READ OPENED:
/// where the act the loop before typed is unread still, this loop's first
/// read is the act's first, however long ago it was typed, and opens its
/// take window ([`TurnEndState::seed_awaited`]; ATERM-KI-1016-1, follow-2).
/// `first` decided there, the policy's clock moves past that window (and the
/// session's, from `unix`) and `screen` is decided again at its end — with no
/// window, as the seed matrix decides a read past it (the take window runs on
/// the worker's clock, which [`TurnEndState::slept`] leaves). The decision,
/// and the time slept.
fn past_take_window(
    s: &mut Session<'_, Mock>,
    first: TurnEndAction,
    screen: &[String],
    unix: i64,
    opts: &SuperviseOpts,
) -> (TurnEndAction, Duration) {
    match first {
        TurnEndAction::WaitUntil { until, .. } if s.turn_end.untaken_act().is_some() => {
            let gone = until.saturating_duration_since(Instant::now());
            s.turn_end.slept(gone);
            s.set_clock(
                unix + i64::try_from(gone.as_secs()).unwrap_or(i64::MAX),
                PDT,
            );
            let take = std::mem::replace(&mut s.turn_end.timing.take_within, Duration::ZERO);
            let point = point_at(s, screen.to_vec(), 102);
            let again = s
                .turn_end_at_point(&point, None, opts)
                .unwrap_or_else(|e| panic!("{e:?}"));
            s.turn_end.timing.take_within = take;
            (again, gone)
        }
        other => (other, Duration::ZERO),
    }
}

/// AN ACT TYPED IN A LIMIT'S PLACE IS THE LIMIT'S TRY ACROSS A LOOP'S RESTART
/// (the limit's-end refix's left-open item 1; D2's
/// `a_done_check_in_a_limits_place_that_meets_the_limit_is_its_retry`, in the
/// loop). Past a five-hour limit's reset the vendor went on by itself and the
/// worker's reply — a done report, or a question naming an irreversible act
/// — scrolled the limit's rows off the screen: the loop that waited on the
/// limit types the done check (or the reversible answer) in the place of
/// `usage-resume@v1`, and that act is the wall's attempt. A loop that starts
/// on the session's ledger right after it (a seamless update, a new window,
/// a policy reload, a fault restart), the limit met again and its reset
/// placed early, works the limit from THAT act: the same next act at the
/// same time as after the continuation it stands in for — the ladder's
/// first rung from the act, then `usage-resume@v1` — never `keep going`
/// into the standing limit the moment it attaches. Measured before: the
/// ledger's row (`continue-done-check@v1`, `answer@v1`) was read as no usage
/// act, and the successor typed `usage-resume@v1` at once. NEGATIVE
/// CONTROLS: the continuation's own row (`usage-resume@v1`, a reply that is
/// no done report) seeds as before, act for act; a done check at an
/// ordinary turn end (no limit's track) seeds nothing; and an act in a
/// limit's place before an account move MADE was typed into the account the
/// session left, and is not taken up.
#[test]
fn an_act_in_a_limits_place_is_the_try_a_successor_backs_off_from() {
    use crate::supervise::approvals::{
        ACCOUNT_MOVE_COMMAND, Carried, Ledger, OpenWall, Outcome, Row, account_switch_reason,
        act_reason, act_reason_after, usage_attempt,
    };
    use crate::supervise::policy::turn_end::{
        LimitTry, RULE_ANSWER, RULE_LIMIT_RESUME, decide_turn_end,
    };
    use aterm_phase::prompt::fixtures as fx;
    // 3:35pm PDT on the watch tests' day: the limit's reset; the first loop
    // decides twenty minutes past it, its successor a minute later.
    const RESET: i64 = TEST_NOW + 6 * 3600 + 40 * 60;
    let now = RESET + 20 * 60;
    let done = "All done: the change is committed and pushed, and every suite passes.";
    let opts = SuperviseOpts {
        policy: owners_policy(),
        ..auto(30)
    };
    // The vendor's continuation at the reset and the worker's `reply` under
    // it, the limit's rows scrolled off the screen (as D2's).
    let replied = |reply: &str| -> Vec<String> {
        let mut out = Vec::new();
        for r in fx::screen(fx::WALL_SESSION_RESUMED_BY_ITSELF_MEASURED) {
            if [
                "carry on with the task",
                "You've hit your",
                "/upgrade to",
                "Usage limit reached",
            ]
            .iter()
            .any(|g| r.contains(g))
            {
                continue;
            }
            if r.contains("(reply 3)") {
                out.extend(reply.lines().enumerate().map(|(i, l)| {
                    if i == 0 {
                        format!("⏺ {l}")
                    } else {
                        format!("  {l}")
                    }
                }));
                continue;
            }
            out.push(r);
        }
        out
    };
    // The limit the first loop waits on, as the reader reads its notice.
    let wall = aterm_phase::read(Some("claude"), &auto_continue_wall_at("3:35pm"), Some(2))
        .wall
        .expect("the armed wall");
    // The limit met again by whatever was typed: its notice once more, the
    // reset it names twenty minutes past (placed early: the limit stands).
    let met_again = {
        let mut r = rows(&[
            &format!("⏺ {done}"),
            "",
            &format!("❯ {DONE_CHECK}"),
            "  ⎿  You've hit your session limit · resets 3:35pm (America/Los_Angeles)",
            "     /upgrade to increase your usage limit.",
            "",
        ]);
        r.extend(composer("  ⏵⏵ auto mode on (shift+tab to cycle)"));
        r
    };
    // The `typed` rows of a ledger, oldest first.
    let typed_rows = |ledger: &Path| -> Vec<aterm_json::Value> {
        std::fs::read_to_string(ledger)
            .unwrap_or_default()
            .lines()
            .filter_map(|l| aterm_json::from_str::<aterm_json::Value>(l).ok())
            .filter(|v| v.get("decision").and_then(aterm_json::Value::as_str) == Some("typed"))
            .collect()
    };
    // THE FIRST LOOP, on its own ledger: at the limit's end (`limit`: the
    // limit's wait taken over from the ledger's open wall) or at an ordinary
    // turn end after work, the point `reply` makes decided and typed. The
    // act, the wall's attempts after it, and the ledger.
    let first_loop = |tag: &str, reply: &str, limit: bool| {
        let (dir, ledger) = ledger_at(tag);
        let screen = if limit { replied(reply) } else { ended(reply) };
        let mut m = Mock::new(vec![screen.clone()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(now, PDT);
        s.set_zone_lookup(test_zones);
        s.ledger = Ledger::open(Some(&ledger), Some("@s-1"), &mut Vec::new());
        if limit {
            s.seed_wall_memory(Some(OpenWall {
                at_ms: (RESET - 4 * 60) * 1000,
                message: wall.message.clone(),
                reset: wall.reset.clone(),
                reset_unix: Some(RESET),
                kind: Some(wall.kind),
                judged_ms: None,
                retry_ms: None,
            }));
        }
        let point = point_at(&s, screen, 101);
        let worked = (!limit).then_some(Duration::from_secs(12 * 60));
        let action = s
            .turn_end_at_point(&point, worked, &opts)
            .unwrap_or_else(|e| panic!("{e:?}"));
        s.turn_end_execute(&point, action.clone(), &opts, &[], &mut Alone)
            .unwrap_or_else(|e| panic!("{e:?}"));
        let attempts = s
            .turn_end
            .wall_attempts(aterm_phase::WallKind::UsageSession);
        // The act's row says whether it was the limit's try, typed in its
        // place or not, as the policy recorded it — and nothing else changes
        // in its words.
        let place = s.turn_end.acted_in_limits_place();
        let reason = typed_rows(&ledger)
            .last()
            .and_then(|v| v.get("reason").and_then(aterm_json::Value::as_str))
            .map(str::to_string);
        assert_eq!(
            reason,
            Some(act_reason_after(
                Carried {
                    short: s.turn_end.short_streak(),
                    retry: None,
                },
                s.turn_end.limit_try()
            )),
            "{tag}"
        );
        // Its first read after the act: Claude Code answers an act at a
        // standing limit at once, and the limit met again is written to the
        // ledger (the wall's row), the take window opened there.
        if limit {
            let point = point_at(&s, met_again.clone(), 102);
            let read = s
                .turn_end_at_point(&point, None, &opts)
                .unwrap_or_else(|e| panic!("{e:?}"));
            assert!(
                matches!(read, TurnEndAction::WaitUntil { .. }),
                "{tag}: the window: {read:?}"
            );
        }
        (dir, ledger, (action.rule_id(), place), attempts)
    };
    // THE SUCCESSOR, on `ledger`, a minute after the act written at
    // `act_ms`, at the limit met again: its first act — a wait's end measured
    // from `base`, its start on the policy's clock — the act it decides at
    // that wait's end, and the wall's attempts.
    let successor = |ledger: &Path, act_ms: i64| {
        let mut m = Mock::new(vec![met_again.clone()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(now + 60, PDT);
        s.set_zone_lookup(test_zones);
        let base = Instant::now();
        // Seeded as `drive_loop` seeds it: a done check typed in the limit's
        // place is awaited as the check ([`seed_done_check`]).
        let open = s.seed_from_ledger(ledger, act_ms + 60_000, false);
        s.seed_wall_memory(open);
        let point = point_at(&s, met_again.clone(), 101);
        let first = s
            .turn_end_at_point(&point, None, &opts)
            .unwrap_or_else(|e| panic!("{e:?}"));
        let (first, slept) = past_take_window(&mut s, first, &met_again, now + 60, &opts);
        let (after, next) = match &first {
            TurnEndAction::WaitUntil { until, .. } => {
                let r = s.turn_end_reading(&point.screen, None, &opts);
                (
                    Some(whole_secs(until.saturating_duration_since(base) + slept)),
                    decide_turn_end(&s.turn_end, &r, &opts.policy, *until).rule_id(),
                )
            }
            other => (None, other.rule_id()),
        };
        let backoff = s.turn_end.timing.limit_backoff.first().copied();
        (
            after,
            next,
            s.turn_end
                .wall_attempts(aterm_phase::WallKind::UsageSession),
            backoff,
        )
    };
    let mut wrong = Vec::new();
    // NEGATIVE CONTROL first: the continuation's own row, as before.
    let (dir, ledger, rule, attempts) = first_loop(
        "place-seed-resume",
        "Stage 2 of 5 is in; stage 3 is next.",
        true,
    );
    assert_eq!(
        (rule, attempts),
        ((Some(RULE_LIMIT_RESUME), false), Some(1))
    );
    let act_ms = typed_rows(&ledger)
        .last()
        .and_then(|v| v.get("ts").and_then(aterm_json::Value::as_i64))
        .expect("the act's row");
    let control = successor(&ledger, act_ms);
    let _ = std::fs::remove_dir_all(&dir);
    let (after, next, attempts, backoff) = control;
    // The try met again at the first loop's first read counts its first
    // rung from the end of the take window that read opened, as the loop
    // that typed it counts it.
    let take = TurnEndTiming::default().take_within;
    let rung = backoff.expect("a ladder") + take - Duration::from_secs(60);
    assert_eq!(
        (after, next, attempts),
        (Some(rung), Some(RULE_LIMIT_RESUME), Some(1)),
        "the usage-resume row: the first rung from where the try was judged met, then the \
         continuation"
    );
    // THE ACTS IN A LIMIT'S PLACE.
    for (tag, reply, want) in [
        ("place-seed-check", done, RULE_DONE_CHECK),
        (
            "place-seed-answer",
            "Shall I force-push the rewritten history over main?",
            RULE_ANSWER,
        ),
    ] {
        let (dir, ledger, rule, attempts) = first_loop(tag, reply, true);
        assert_eq!(
            (rule, attempts),
            ((Some(want), true), Some(1)),
            "{tag}: the act in the limit's place, the wall's attempt"
        );
        let act_ms = typed_rows(&ledger)
            .last()
            .and_then(|v| v.get("ts").and_then(aterm_json::Value::as_i64))
            .expect("the act's row");
        let seeded = successor(&ledger, act_ms);
        if seeded != control {
            wrong.push(format!("{tag}: {seeded:?}\nthe control's: {control:?}"));
        }
        // NEGATIVE CONTROL: an account move MADE after the act: typed into
        // the account the session left.
        let moved = Row {
            rule_id: RULE_ACCOUNT,
            outcome: Outcome::Typed,
            command: &format!("{ACCOUNT_MOVE_COMMAND}work-2"),
            reason: &account_switch_reason("work-2", AccountAt::Wall),
            box_seq: 102,
        }
        .to_json(act_ms + 1_000, Some("s-1"));
        let mut body = std::fs::read_to_string(&ledger).expect("the ledger");
        body.push_str(&moved);
        body.push('\n');
        std::fs::write(&ledger, body).expect("the ledger");
        let (after, next, attempts, _) = successor(&ledger, act_ms);
        if (after, next, attempts) != (None, Some(RULE_LIMIT_RESUME), Some(0)) {
            wrong.push(format!(
                "{tag}, moved since: {after:?} {next:?} {attempts:?}"
            ));
        }
        let _ = std::fs::remove_dir_all(&dir);
    }
    assert!(wrong.is_empty(), "{wrong:#?}");
    // THE RUNG THE LAST TRY LEFT (the verifier of the successor's seed, D3):
    // the check met the limit again and, after the first rung, the
    // continuation met it too — the wall's attempt 2, which its row carries
    // as the loop recorded it ([`TurnEndState::limit_try`]). The successor a
    // minute after that continuation, which nothing has read yet, waits the
    // SECOND rung from the take window its own first read opens
    // ([`past_take_window`]), where every seed was the first try and it typed
    // 20 minutes early.
    let (dir, ledger, rule, _) = first_loop("place-seed-rung", done, true);
    assert_eq!(rule, (Some(RULE_DONE_CHECK), true));
    let check_ms = typed_rows(&ledger)
        .last()
        .and_then(|v| v.get("ts").and_then(aterm_json::Value::as_i64))
        .expect("the check's row");
    let resume_ms = check_ms + 11 * 60_000;
    let second = Row {
        rule_id: RULE_LIMIT_RESUME,
        outcome: Outcome::Typed,
        command: "keep going",
        reason: &act_reason(Some(LimitTry {
            bucket: false,
            in_place: false,
            attempts: 2,
            entitlement: false,
        })),
        box_seq: 102,
    }
    .to_json(resume_ms, Some("s-1"));
    let mut body = std::fs::read_to_string(&ledger).expect("the ledger");
    body.push_str(&second);
    body.push('\n');
    std::fs::write(&ledger, body).expect("the ledger");
    let (after, next, attempts, _) = successor(&ledger, resume_ms);
    let rung = TurnEndTiming::default().limit_backoff[1] + take;
    assert_eq!(
        (after, next, attempts),
        (Some(rung), Some(RULE_LIMIT_RESUME), Some(2)),
        "the second rung from the continuation"
    );
    let _ = std::fs::remove_dir_all(&dir);
    // NEGATIVE CONTROL: the done check at an ordinary turn end (no limit's
    // track): its row seeds nothing, and the limit the successor finds
    // sitting is a new appearance — continued at once.
    let (dir, ledger, rule, attempts) = first_loop("place-seed-plain", done, false);
    assert_eq!((rule, attempts), ((Some(RULE_DONE_CHECK), false), None));
    assert_eq!(usage_attempt(&ledger, Some("@s-1")), None);
    let (after, next, attempts, _) = successor(&ledger, 0);
    assert_eq!(
        (after, next, attempts),
        (None, Some(RULE_LIMIT_RESUME), Some(0))
    );
    let _ = std::fs::remove_dir_all(&dir);
}

/// A DONE CHECK AT AN ORDINARY TURN END IS NO LIMIT'S TRY, WHATEVER A LOOP
/// SEEDED (the verifier of the successor's seed, D4). A loop starts on a
/// ledger whose last usage act is a done check typed in a limit's place
/// five minutes before; the limit has lifted since — the worker worked and
/// reported done, and the screen draws no limit. Its done check there could
/// never stand in for the limit's continuation (no limit is read, none
/// remembered): it is the continue policy's, typed as any loop types it, and
/// its row is unmarked — not the wall's attempt, so the loop after it takes
/// up the earlier act, not this one. Measured before: the seeded track
/// counted the check as the wall's attempt 2 and marked its row, so every
/// further restart within the ladder kept a phantom limit alive, a later
/// real limit backed off as its retry. NEGATIVE CONTROL: the same loop with
/// nothing to seed types the same check, unmarked.
#[test]
fn a_done_check_at_an_ordinary_turn_end_is_no_limits_try_whatever_was_seeded() {
    use crate::supervise::approvals::{
        Carried, Ledger, Outcome, Row, act_reason, act_reason_after, usage_attempt,
    };
    use crate::supervise::policy::turn_end::{LimitTry, decide_turn_end};
    let now = TEST_NOW + 6 * 3600;
    let done = "All done: the change is committed and pushed, and every suite passes.";
    let opts = SuperviseOpts {
        policy: owners_policy(),
        ..auto(30)
    };
    let seeded_ms = (now - 5 * 60) * 1000;
    let mut got = Vec::new();
    for (tag, seed) in [
        ("ordinary-check-seeded", true),
        ("ordinary-check-control", false),
    ] {
        let (dir, ledger) = ledger_at(tag);
        if seed {
            let row = Row {
                rule_id: RULE_DONE_CHECK,
                outcome: Outcome::Typed,
                command: DONE_CHECK,
                reason: &act_reason(Some(LimitTry {
                    bucket: false,
                    in_place: true,
                    attempts: 1,
                    entitlement: false,
                })),
                box_seq: 90,
            }
            .to_json(seeded_ms, Some("s-1"));
            std::fs::write(&ledger, format!("{row}\n")).expect("the ledger");
        }
        let screen = ended(done);
        let mut m = Mock::new(vec![screen.clone()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(now, PDT);
        s.set_zone_lookup(test_zones);
        s.ledger = Ledger::open(Some(&ledger), Some("@s-1"), &mut Vec::new());
        seed_usage_act(
            &mut s.turn_end,
            &ledger,
            s.setup.sid.as_deref(),
            now * 1000,
            Instant::now(),
        );
        let attempts = s
            .turn_end
            .wall_attempts(aterm_phase::WallKind::UsageSession);
        let point = point_at(&s, screen, 101);
        let first = s
            .turn_end_at_point(&point, None, &opts)
            .unwrap_or_else(|e| panic!("{e:?}"));
        let act = match &first {
            TurnEndAction::WaitUntil { until, .. } => {
                let r = s.turn_end_reading(&point.screen, None, &opts);
                decide_turn_end(&s.turn_end, &r, &opts.policy, *until)
            }
            other => other.clone(),
        };
        // The point's screen, as the loop last read it when the wait ends.
        s.last = Some(point.screen.clone());
        s.turn_end_execute(&point, act.clone(), &opts, &[], &mut Alone)
            .unwrap_or_else(|e| panic!("{e:?}"));
        let row = std::fs::read_to_string(&ledger)
            .unwrap_or_default()
            .lines()
            .filter_map(|l| aterm_json::from_str::<aterm_json::Value>(l).ok())
            .rfind(|v| v.get("decision").and_then(aterm_json::Value::as_str) == Some("typed"))
            .map(|v| {
                let text = |k: &str| {
                    v.get(k)
                        .and_then(aterm_json::Value::as_str)
                        .map(str::to_string)
                };
                (text("rule_id"), text("reason"))
            });
        got.push((
            tag,
            act.rule_id(),
            row,
            (
                attempts,
                s.turn_end
                    .wall_attempts(aterm_phase::WallKind::UsageSession),
            ),
            usage_attempt(&ledger, Some("@s-1")).map(|a| a.at_ms),
        ));
        drop(s);
        let _ = std::fs::remove_dir_all(&dir);
    }
    // (Typed after the first point's short turn: the streak it marks.)
    let check = Some((
        Some(RULE_DONE_CHECK.to_string()),
        Some(act_reason_after(Carried::streak(1), None)),
    ));
    assert_eq!(
        got,
        [
            (
                "ordinary-check-seeded",
                Some(RULE_DONE_CHECK),
                check.clone(),
                (Some(1), Some(1)),
                Some(seeded_ms),
            ),
            (
                "ordinary-check-control",
                Some(RULE_DONE_CHECK),
                check,
                (None, None),
                None,
            ),
        ]
    );
}

/// A LAND ACT TYPED IN A LIMIT'S PLACE IS THE LIMIT'S TRY ACROSS A LOOP'S
/// RESTART, AS THE DONE CHECK IS (the merge of the successor's seed with
/// Autopilot: one rule, the mark follows the act's place, whichever act it
/// is). Under Autopilot Land a limit's end gets Land's own act where Cruise
/// types the done check ([`limit_end`]'s `words_act`): the land instruction
/// for a done report, the land answer for a question that names an
/// irreversible act — the wall's attempt, as the check is. Its ledger row
/// names the limit's try (`(in the limit's place: wall=usage attempts=1)`),
/// and a loop that starts on that ledger a minute later, the limit met again
/// with its reset placed early, works the limit from that act exactly as
/// from the check's row: the ladder's first rung from the act, then
/// `usage-resume@v1`, never `keep going` into the standing limit the moment
/// it attaches. The marked row reads as every typed act reads to the
/// ledger's other readers: it closes the wall the loop waited on
/// ([`approvals::open_wall`]), and its text is the supervisor's own
/// ([`approvals::typed_texts`], which the record's readers and the
/// relaunch take as the harness's turn). NEGATIVE CONTROLS: under Land, the
/// land instruction at an ordinary turn end (no limit's track) is unmarked
/// and seeds nothing; at a track only a loop before this one's act seeded,
/// no limit read since (D4), it is unmarked too, and the earlier act stays
/// the one taken up; and under Off nothing is typed at the limit's end, so
/// no row is written and nothing is seeded.
#[test]
fn a_land_act_in_a_limits_place_is_the_try_a_successor_backs_off_from() {
    use crate::supervise::approvals::{
        Carried, Ledger, Outcome, RULE_WALL_WAIT, Row, act_reason, act_reason_after, open_wall,
        typed_texts, usage_attempt, wall_wait_reason,
    };
    use crate::supervise::config::Autopilot;
    use crate::supervise::policy::turn_end::{
        LimitTry, RULE_LAND, RULE_LAND_ANSWER, RULE_LIMIT_RESUME, decide_turn_end,
    };
    use aterm_phase::prompt::fixtures as fx;
    // 3:35pm PDT on the watch tests' day: the limit's reset; the first loop
    // decides twenty minutes past it, its successor a minute later.
    const RESET: i64 = TEST_NOW + 6 * 3600 + 40 * 60;
    let now = RESET + 20 * 60;
    let done = "All done: the change is committed and pushed, and every suite passes.";
    let force = "Shall I force-push the rewritten history over main?";
    let opts = |mode: Autopilot| SuperviseOpts {
        policy: SupervisorConfig {
            autopilot: mode,
            ..owners_policy()
        },
        ..auto(30)
    };
    // The vendor's continuation at the reset and the worker's `reply` under
    // it, the limit's rows scrolled off the screen.
    let replied = |reply: &str| -> Vec<String> {
        let mut out = Vec::new();
        for r in fx::screen(fx::WALL_SESSION_RESUMED_BY_ITSELF_MEASURED) {
            if [
                "carry on with the task",
                "You've hit your",
                "/upgrade to",
                "Usage limit reached",
            ]
            .iter()
            .any(|g| r.contains(g))
            {
                continue;
            }
            if r.contains("(reply 3)") {
                out.push(format!("⏺ {reply}"));
                continue;
            }
            out.push(r);
        }
        out
    };
    let wall = aterm_phase::read(Some("claude"), &auto_continue_wall_at("3:35pm"), Some(2))
        .wall
        .expect("the armed wall");
    // The limit's wait the loop before wrote, open in the ledger.
    let opened = Row {
        rule_id: RULE_WALL_WAIT,
        outcome: Outcome::Waiting,
        command: "",
        reason: &wall_wait_reason(Some(RESET), wall.reset.as_deref(), wall.kind, &wall.message),
        box_seq: 100,
    }
    .to_json((RESET - 4 * 60) * 1000, Some("s-1"));
    // The limit met again by whatever was typed (its reset placed early: the
    // limit stands).
    let met_again = {
        let mut r = rows(&[
            &format!("⏺ {done}"),
            "",
            &format!("❯ {DONE_CHECK}"),
            "  ⎿  You've hit your session limit · resets 3:35pm (America/Los_Angeles)",
            "     /upgrade to increase your usage limit.",
            "",
        ]);
        r.extend(composer("  ⏵⏵ auto mode on (shift+tab to cycle)"));
        r
    };
    // The last `typed` row of a ledger: its rule, its command, its reason,
    // its time.
    type Last = Option<(String, String, String, i64)>;
    let last_typed = |ledger: &Path| -> Last {
        std::fs::read_to_string(ledger)
            .unwrap_or_default()
            .lines()
            .filter_map(|l| aterm_json::from_str::<aterm_json::Value>(l).ok())
            .rfind(|v| v.get("decision").and_then(aterm_json::Value::as_str) == Some("typed"))
            .map(|v| {
                let text = |k: &str| {
                    v.get(k)
                        .and_then(aterm_json::Value::as_str)
                        .unwrap_or_default()
                        .to_string()
                };
                (
                    text("rule_id"),
                    text("command"),
                    text("reason"),
                    v.get("ts").and_then(aterm_json::Value::as_i64).unwrap_or(0),
                )
            })
    };
    // THE FIRST LOOP under `mode`, on a ledger holding `held` (one row a
    // line): at the limit's end — the limit's wait taken up from the
    // ledger's open wall, as `drive_loop` seeds it — or at an ordinary turn
    // end after work; the usage act a loop before it made seeded first, as
    // `drive_loop` seeds it. Its point decided (a wait's end decided again)
    // and typed. The act, whether the policy recorded it in the limit's
    // place, the wall's attempts before and after it, and the ledger.
    let first_loop = |tag: &str, mode: Autopilot, reply: &str, limit: bool, held: &[&str]| {
        let (dir, ledger) = ledger_at(tag);
        let body: String = held.iter().map(|r| format!("{r}\n")).collect();
        std::fs::write(&ledger, body).expect("the ledger");
        let screen = if limit { replied(reply) } else { ended(reply) };
        let opts = opts(mode);
        let mut m = Mock::new(vec![screen.clone()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(now, PDT);
        s.set_zone_lookup(test_zones);
        s.ledger = Ledger::open(Some(&ledger), Some("@s-1"), &mut Vec::new());
        seed_usage_act(
            &mut s.turn_end,
            &ledger,
            s.setup.sid.as_deref(),
            now * 1000,
            Instant::now(),
        );
        let before = s
            .turn_end
            .wall_attempts(aterm_phase::WallKind::UsageSession);
        s.seed_wall_memory(open_wall(&ledger, s.setup.sid.as_deref()));
        // The worker's work since any act before, which this loop never saw
        // (no busy read): only its words on the screen.
        let point = point_at(&s, screen, 101);
        let first = s
            .turn_end_at_point(&point, None, &opts)
            .unwrap_or_else(|e| panic!("{e:?}"));
        let action = match &first {
            TurnEndAction::WaitUntil { until, .. } => {
                let r = s.turn_end_reading(&point.screen, None, &opts);
                decide_turn_end(&s.turn_end, &r, &opts.policy, *until)
            }
            other => other.clone(),
        };
        s.last = Some(point.screen.clone());
        s.turn_end_execute(&point, action.clone(), &opts, &[], &mut Alone)
            .unwrap_or_else(|e| panic!("{e:?}"));
        let after = s
            .turn_end
            .wall_attempts(aterm_phase::WallKind::UsageSession);
        let place = s.turn_end.acted_in_limits_place();
        drop(s);
        (dir, ledger, (action.rule_id(), place, (before, after)))
    };
    // THE SUCCESSOR under `mode`, on `ledger`, a minute after the act
    // written at `act_ms`, at the limit met again: its first act — a wait's
    // end measured from its start on the policy's clock — the act it decides
    // at that wait's end, and the wall's attempts.
    let successor = |ledger: &Path, mode: Autopilot, act_ms: i64| {
        let opts = opts(mode);
        let mut m = Mock::new(vec![met_again.clone()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(now + 60, PDT);
        s.set_zone_lookup(test_zones);
        let base = Instant::now();
        seed_usage_act(
            &mut s.turn_end,
            ledger,
            s.setup.sid.as_deref(),
            act_ms + 60_000,
            base,
        );
        let point = point_at(&s, met_again.clone(), 101);
        let first = s
            .turn_end_at_point(&point, None, &opts)
            .unwrap_or_else(|e| panic!("{e:?}"));
        let (after, next) = match &first {
            TurnEndAction::WaitUntil { until, .. } => {
                let r = s.turn_end_reading(&point.screen, None, &opts);
                (
                    Some(until.saturating_duration_since(base)),
                    decide_turn_end(&s.turn_end, &r, &opts.policy, *until).rule_id(),
                )
            }
            other => (None, other.rule_id()),
        };
        (
            after,
            next,
            s.turn_end
                .wall_attempts(aterm_phase::WallKind::UsageSession),
        )
    };
    let in_place = LimitTry {
        bucket: false,
        in_place: true,
        attempts: 1,
        entitlement: false,
    };
    let rung = TurnEndTiming::default().limit_backoff[0] - Duration::from_secs(60);
    let mut wrong = Vec::new();
    // NEGATIVE CONTROL first, the done check's row under Cruise: the
    // successor's acts from it.
    let (dir, ledger, act) = first_loop(
        "land-place-check",
        Autopilot::Cruise,
        done,
        true,
        &[&opened],
    );
    assert_eq!(act, (Some(RULE_DONE_CHECK), true, (None, Some(1))));
    let (_, _, reason, act_ms) = last_typed(&ledger).expect("the check's row");
    assert_eq!(reason, act_reason_after(Carried::streak(1), Some(in_place)));
    let control = successor(&ledger, Autopilot::Cruise, act_ms);
    assert_eq!(
        control,
        (Some(rung), Some(RULE_LIMIT_RESUME), Some(1)),
        "the check's row: the first rung from the act, then the continuation"
    );
    let _ = std::fs::remove_dir_all(&dir);
    // LAND'S ACTS IN THE LIMIT'S PLACE: the same mark, the same successor.
    for (tag, reply, want) in [
        ("land-place-instruction", done, RULE_LAND),
        ("land-place-answer", force, RULE_LAND_ANSWER),
    ] {
        let (dir, ledger, act) = first_loop(tag, Autopilot::Land, reply, true, &[&opened]);
        if act != (Some(want), true, (None, Some(1))) {
            wrong.push(format!("{tag}: the act {act:?}"));
        }
        let Some((rule, command, reason, act_ms)) = last_typed(&ledger) else {
            wrong.push(format!("{tag}: no row"));
            continue;
        };
        if (rule.as_str(), reason.as_str())
            != (want, &*act_reason_after(Carried::streak(1), Some(in_place)))
        {
            wrong.push(format!("{tag}: the row {rule} {reason:?}"));
        }
        if usage_attempt(&ledger, Some("@s-1")).map(|a| (a.at_ms, a.limit))
            != Some((act_ms, in_place))
        {
            wrong.push(format!(
                "{tag}: read back {:?}",
                usage_attempt(&ledger, Some("@s-1")).map(|a| (a.at_ms, a.limit))
            ));
        }
        // The ledger's other readers: the wall the loop waited on is closed
        // by the act, and the act's text is the supervisor's own.
        let theirs = typed_texts(&ledger, Some("@s-1"));
        if open_wall(&ledger, Some("@s-1")).is_some()
            || !theirs
                .iter()
                .any(|t| t.at_ms == act_ms && t.text == command)
        {
            wrong.push(format!("{tag}: the readers {theirs:?}"));
        }
        for mode in [Autopilot::Land, Autopilot::Cruise] {
            let seeded = successor(&ledger, mode, act_ms);
            if seeded != control {
                wrong.push(format!(
                    "{tag}, the successor under {mode:?}: {seeded:?}, the check's {control:?}"
                ));
            }
        }
        let _ = std::fs::remove_dir_all(&dir);
    }
    assert!(wrong.is_empty(), "{wrong:#?}");
    // NEGATIVE CONTROL: the land instruction at an ordinary turn end (no
    // limit's track): unmarked, nothing seeded; the limit the successor
    // finds is a new appearance, continued at once.
    let (dir, ledger, act) = first_loop("land-place-plain", Autopilot::Land, done, false, &[]);
    assert_eq!(act, (Some(RULE_LAND), false, (None, None)));
    let (_, _, reason, _) = last_typed(&ledger).expect("the instruction's row");
    // No limit's mark (the first point's short turn is the streak's).
    assert_eq!(reason, act_reason_after(Carried::streak(1), None));
    assert_eq!(usage_attempt(&ledger, Some("@s-1")), None);
    assert_eq!(
        successor(&ledger, Autopilot::Land, 0),
        (None, Some(RULE_LIMIT_RESUME), Some(0))
    );
    let _ = std::fs::remove_dir_all(&dir);
    // NEGATIVE CONTROL (D4 under Land): a successor of a check typed in a
    // limit's place five minutes before, the limit lifted since — the
    // worker's done report, no limit drawn: the land instruction there is
    // Land's ordinary act, its row unmarked, the wall's attempt kept, and
    // the earlier act stays the one taken up.
    let seeded_ms = (now - 5 * 60) * 1000;
    let check = Row {
        rule_id: RULE_DONE_CHECK,
        outcome: Outcome::Typed,
        command: DONE_CHECK,
        reason: &act_reason(Some(in_place)),
        box_seq: 90,
    }
    .to_json(seeded_ms, Some("s-1"));
    let (dir, ledger, act) =
        first_loop("land-place-seeded", Autopilot::Land, done, false, &[&check]);
    assert_eq!(act, (Some(RULE_LAND), false, (Some(1), Some(1))));
    let (rule, _, reason, _) = last_typed(&ledger).expect("the instruction's row");
    assert_eq!(
        (rule.as_str(), reason),
        (RULE_LAND, act_reason_after(Carried::streak(1), None))
    );
    assert_eq!(
        usage_attempt(&ledger, Some("@s-1")).map(|a| (a.at_ms, a.limit)),
        Some((seeded_ms, in_place))
    );
    let _ = std::fs::remove_dir_all(&dir);
    // UNDER OFF nothing is typed at the limit's end: no row, nothing seeded,
    // the wall the loop before left still open, no attempt made at it.
    let (dir, ledger, act) = first_loop("land-place-off", Autopilot::Off, done, true, &[&opened]);
    assert_eq!(act, (None, false, (None, Some(0))));
    assert_eq!(last_typed(&ledger), None);
    assert_eq!(usage_attempt(&ledger, Some("@s-1")), None);
    assert!(open_wall(&ledger, Some("@s-1")).is_some());
    let _ = std::fs::remove_dir_all(&dir);
}

/// A LOOP THAT STARTS AT A MODEL BUCKET'S OPEN WALL WAITS ON ITS RESET,
/// WHATEVER USAGE ACT IT TAKES UP BESIDE IT (the verifier of the successor's
/// seed, D1). The loop before it typed its act at the lab's Sonnet bucket
/// (`resets Oct 17 at 4:20pm`, two days out; no relaunch on the fallback):
/// the done check in the continuation's place (its row marked), or the
/// continuation itself (`usage-resume@v1`, its row as 0.104.0 wrote it); the
/// act met the bucket again, and the loop wrote the bucket's wall open
/// (`wall-wait@v1`). Then Esc on the countdown, or a `/resume`: no notice on
/// the screen. A loop that starts on that ledger a minute later seeds as
/// `drive_loop` does — the usage act ([`seed_usage_act`]), then the open
/// wall (`seed_wall_memory`) — and waits on the bucket's reset, where
/// `usage-resume@v1` is typed. Measured before: the act seeded a usage
/// window's track, the bucket's reset was dropped beside it, and the
/// continue policy typed `keep going` into the bucket two minutes in.
/// NEGATIVE CONTROL: the check's row unmarked (an ordinary done check, no
/// usage act): the open wall alone — the same wait, the same act.
#[test]
fn a_loop_at_a_buckets_open_wall_waits_on_its_reset_beside_the_act_it_takes_up() {
    use crate::supervise::approvals::{
        Ledger, Outcome, RULE_WALL_WAIT, Row, act_reason, open_wall, wall_wait_reason,
    };
    use crate::supervise::policy::turn_end::{LimitTry, RULE_LIMIT_RESUME, decide_turn_end};
    use aterm_phase::prompt::fixtures as fx;
    // Oct 17 4:20pm PDT, the bucket's reset; the successor two days before.
    const RESET: i64 = 1_792_279_200;
    let now = RESET - 2 * 86_400;
    let opts = SuperviseOpts {
        policy: SupervisorConfig {
            model_fallback: None,
            ..owners_policy()
        },
        ..auto(30)
    };
    let armed = fx::screen(fx::WALL_SONNET_BUCKET_AUTO_CONTINUE_ARMED_2_1_300);
    let wall = aterm_phase::read(Some("claude"), &armed, Some(2))
        .wall
        .expect("the bucket");
    // Esc on the countdown: its banner and countdown gone, the vendor's word
    // that it will not go on drawn over the composer (as the policy tests'
    // `sonnet_bucket_then`).
    let cancelled = {
        let mut rows: Vec<String> = armed
            .iter()
            .filter(|r| {
                !r.contains("Usage limit reached") && !r.contains("Continuing automatically")
            })
            .cloned()
            .collect();
        let top = rows
            .iter()
            .position(|r| r.starts_with('─'))
            .expect("the composer's frame");
        rows.splice(
            top..top,
            [
                "⏺ Automatic continue cancelled · /rate-limit-options to re-arm".to_string(),
                String::new(),
            ],
        );
        rows
    };
    let resumed = fx::screen(fx::RESUMED_NO_LIMIT_AT_ARMED_LIMIT_2_1_300);
    let act_ms = (now - 60) * 1000;
    let act = |rule: &str, command: &str, reason: &str| {
        Row {
            rule_id: rule,
            outcome: Outcome::Typed,
            command,
            reason,
            box_seq: 90,
        }
        .to_json(act_ms, Some("s-1"))
    };
    let opened = Row {
        rule_id: RULE_WALL_WAIT,
        outcome: Outcome::Waiting,
        command: "",
        reason: &wall_wait_reason(Some(RESET), wall.reset.as_deref(), wall.kind, &wall.message),
        box_seq: 91,
    }
    .to_json(act_ms + 5_000, Some("s-1"));
    let mut wrong = Vec::new();
    let mut n = 0;
    for (screen_name, screen) in [("Esc", &cancelled), ("/resume", &resumed)] {
        for (row_name, row) in [
            (
                "the check in the continuation's place",
                act(
                    RULE_DONE_CHECK,
                    DONE_CHECK,
                    &act_reason(Some(LimitTry {
                        bucket: true,
                        in_place: true,
                        attempts: 1,
                        entitlement: false,
                    })),
                ),
            ),
            (
                "the continuation, as 0.104.0 wrote it",
                act(RULE_LIMIT_RESUME, "keep going", "the turn-end policy"),
            ),
            (
                "control: an ordinary done check",
                act(RULE_DONE_CHECK, DONE_CHECK, &act_reason(None)),
            ),
        ] {
            n += 1;
            let (dir, ledger) = ledger_at(&format!("bucket-open-wall-{n}"));
            std::fs::write(&ledger, format!("{row}\n{opened}\n")).expect("the ledger");
            let mut m = Mock::new(vec![screen.clone()]);
            let mut s = session(&mut m, Some("@s-1".to_string()));
            s.set_clock(now, PDT);
            s.set_zone_lookup(test_zones);
            s.ledger = Ledger::open(Some(&ledger), Some("@s-1"), &mut Vec::new());
            // `drive_loop`'s order: the usage act, then the open wall.
            seed_usage_act(
                &mut s.turn_end,
                &ledger,
                s.setup.sid.as_deref(),
                now * 1000,
                Instant::now(),
            );
            let open = open_wall(&ledger, s.setup.sid.as_deref());
            let had_open = open.is_some();
            s.seed_wall_memory(open);
            let point = point_at(&s, screen.clone(), 101);
            let first = s
                .turn_end_at_point(&point, None, &opts)
                .unwrap_or_else(|e| panic!("{e:?}"));
            // The wait reaches the bucket's reset, and the act at its end is
            // the bucket's continuation.
            let got = match &first {
                TurnEndAction::WaitUntil { until, .. } => {
                    let r = s.turn_end_reading(&point.screen, None, &opts);
                    (
                        *until >= s.instant_of(RESET),
                        decide_turn_end(&s.turn_end, &r, &opts.policy, *until).rule_id(),
                    )
                }
                other => (false, other.rule_id()),
            };
            let waits = s.turn_end.waits_on_named_reset();
            drop(s);
            let _ = std::fs::remove_dir_all(&dir);
            if (had_open, waits, got) != (true, true, (true, Some(RULE_LIMIT_RESUME))) {
                wrong.push(format!(
                    "{screen_name}, {row_name}: open wall {had_open}, waits on the reset \
                     {waits}, {first:?} then {:?}",
                    got.1
                ));
            }
        }
    }
    assert!(wrong.is_empty(), "{wrong:#?}");
}

/// A LIMIT ITS OWN TRY MET AGAIN STAYS OPEN FOR A LOOP THAT FOLLOWS (the
/// verifier of the successor's seed's refix, V2-1). Any `typed` row closes the
/// ledger's wall (`open_wall`: the act is the loop's record of what became of
/// it), so the wall the act met again must be written again. The loop wrote
/// nothing: the same notice answered the act with no busy read between (the
/// stub's 429 answers at once, as Claude Code 2.1.300's does), the memory held
/// it unchanged, and it is written only when it changes. A loop that started
/// on that ledger found no open wall and a seeded track with no reset, and at
/// a screen that draws no notice (Esc on the countdown, a `/resume`) the
/// continue policy typed `continue@v1 keep going` into the standing limit at
/// its two-minute back-off. The first loop waits on that limit.
/// Two limits, the act and the same notice read at points by the loop that
/// waited on the limit: the five-hour limit (`resets 3:35pm`), its countdown
/// past its net twenty minutes after the reset, with `usage-resume@v1` typed
/// there by the loop's own decision. And the lab's Sonnet bucket two days
/// before its reset, with its continuation typed there (the owner's clearing)
/// or the done check in its place, the row written as the loop writes every
/// act's. Then Esc, or a `/resume`. The act's row closed the ledger's wall;
/// the notice met again opened it again, and a loop that starts on it,
/// seeded in `drive_loop`'s order, works the limit as the first loop does: a
/// wait no sooner than the reset the wall names, then `usage-resume@v1`.
/// NEGATIVE CONTROL: the act answered by the worker's work (a turn end after
/// work, no wall). The ledger's wall stays closed, and the successor waits on
/// no reset.
#[test]
fn a_limit_its_own_try_met_again_stays_open_for_a_loop_that_follows() {
    use crate::supervise::approvals::{Ledger, Outcome, act_reason, open_wall, usage_attempt};
    use crate::supervise::policy::turn_end::{LimitTry, RULE_LIMIT_RESUME, decide_turn_end};
    use aterm_phase::prompt::fixtures as fx;
    // 3:35pm PDT on the watch tests' day; Oct 17 4:20pm PDT, the bucket's.
    const WINDOW_RESET: i64 = TEST_NOW + 6 * 3600 + 40 * 60;
    const BUCKET_RESET: i64 = 1_792_279_200;
    let opts = SuperviseOpts {
        policy: SupervisorConfig {
            model_fallback: None,
            ..owners_policy()
        },
        ..auto(30)
    };
    let resumed = fx::screen(fx::RESUMED_NO_LIMIT_AT_ARMED_LIMIT_2_1_300);
    let bucket = fx::screen(fx::WALL_SONNET_BUCKET_AUTO_CONTINUE_ARMED_2_1_300);
    // Esc on the bucket's countdown: its banner and countdown gone, the
    // vendor's word that it will not go on drawn over the composer.
    let bucket_cancelled = {
        let mut rows: Vec<String> = bucket
            .iter()
            .filter(|r| {
                !r.contains("Usage limit reached") && !r.contains("Continuing automatically")
            })
            .cloned()
            .collect();
        let top = rows
            .iter()
            .position(|r| r.starts_with('─'))
            .expect("the composer's frame");
        rows.splice(
            top..top,
            [
                "⏺ Automatic continue cancelled · /rate-limit-options to re-arm".to_string(),
                String::new(),
            ],
        );
        rows
    };
    // A screen, the first loop's decision there and the successor's: each a
    // wait's end in unix seconds and the act decided at it.
    type Decided = Option<(i64, Option<&'static str>)>;
    let decided = |s: &mut Session<'_, Mock>, rows: &[String], seq: u64| -> Decided {
        let point = point_at(s, rows.to_vec(), seq);
        match s
            .turn_end_at_point(&point, None, &opts)
            .expect("a decision")
        {
            TurnEndAction::WaitUntil { until, .. } => {
                let r = s.turn_end_reading(&point.screen, None, &opts);
                Some((
                    s.unix_of(until),
                    decide_turn_end(&s.turn_end, &r, &opts.policy, until).rule_id(),
                ))
            }
            other => Some((s.now_unix(), other.rule_id())),
        }
    };
    let mut wrong = Vec::new();
    let mut n = 0;
    // The try: the loop's own decision at the window, or, at the bucket, its
    // row as the loop writes it: the continuation, or the done check typed in
    // its place.
    for (limit, row) in [
        ("the window", None),
        ("the bucket", Some((RULE_LIMIT_RESUME, "keep going", false))),
        ("the bucket", Some((RULE_DONE_CHECK, DONE_CHECK, true))),
    ] {
        let bucketed = row.is_some();
        let (armed, met_again, cancelled, reset, now) = if bucketed {
            (
                bucket.clone(),
                bucket.clone(),
                bucket_cancelled.clone(),
                BUCKET_RESET,
                BUCKET_RESET - 2 * 86_400,
            )
        } else {
            (
                auto_continue_wall_at("3:35pm"),
                own_act_met_a_limit("3:35pm"),
                own_act_limit_cancelled("3:35pm"),
                WINDOW_RESET,
                WINDOW_RESET + 20 * 60,
            )
        };
        for (screen_name, screen) in [("Esc", &cancelled), ("/resume", &resumed)] {
            for worked in [false, true] {
                n += 1;
                let case = format!(
                    "{limit} ({:?}), {screen_name}, {}",
                    row.map(|(rule, ..)| rule),
                    if worked {
                        "control: work answered the act"
                    } else {
                        "the same notice answered the act"
                    }
                );
                let (dir, ledger) = ledger_at(&format!("own-try-met-again-{n}"));
                // THE LOOP THAT WAITED ON THE LIMIT: it reads the notice
                // before the reset (its wall written), then makes its try.
                let mut m = Mock::new(vec![armed.clone()]);
                let mut s = session(&mut m, Some("@s-1".to_string()));
                s.set_zone_lookup(test_zones);
                s.ledger = Ledger::open(Some(&ledger), Some("@s-1"), &mut Vec::new());
                s.set_turn_end_timing(TurnEndTiming {
                    take_within: Duration::ZERO,
                    ..TurnEndTiming::default()
                });
                s.set_clock(now.min(reset) - 4 * 60, PDT);
                let _ = decided(&mut s, &armed, 100);
                s.set_clock(now, PDT);
                if let Some((rule, command, in_place)) = row {
                    s.ledger_row(
                        rule,
                        Outcome::Typed,
                        command,
                        &act_reason(Some(LimitTry {
                            bucket: true,
                            in_place,
                            attempts: 1,
                            entitlement: false,
                        })),
                        101,
                    );
                } else {
                    let p = point_at(&s, armed.clone(), 101);
                    let a = s.turn_end_at_point(&p, None, &opts).expect("the try");
                    assert_eq!(a.rule_id(), Some(RULE_LIMIT_RESUME), "{case}");
                    // The fixed clock's step is a sleep to the loop's watch,
                    // and its settle holds every act: passed.
                    s.pass_wake_settle();
                    s.turn_end_execute(&p, a, &opts, &[], &mut Alone)
                        .expect("typed");
                }
                let act_ms = usage_attempt(&ledger, Some("@s-1"))
                    .expect("the try's row")
                    .at_ms;
                // The act's row closes the wall until something meets it.
                let closed = open_wall(&ledger, Some("@s-1")).is_none();
                // Its answer, at a point.
                s.set_clock(now + 30, PDT);
                if worked {
                    let p = point_at(&s, ended("Fixed the parser; the suite is green."), 102);
                    let _ = s.turn_end_at_point(&p, Some(Duration::from_secs(12 * 60)), &opts);
                } else {
                    let _ = decided(&mut s, &met_again, 102);
                }
                let open = open_wall(&ledger, Some("@s-1"));
                s.set_clock(now + 120, PDT);
                let first = (!worked).then(|| decided(&mut s, screen, 103)).flatten();
                drop(s);
                // THE LOOP THAT FOLLOWS, two minutes after the try, seeded
                // as `drive_loop` seeds it: the usage act, then the open wall.
                let mut m2 = Mock::new(vec![screen.clone()]);
                let mut s2 = session(&mut m2, Some("@s-1".to_string()));
                s2.set_clock(now + 120, PDT);
                s2.set_zone_lookup(test_zones);
                s2.ledger = Ledger::open(Some(&ledger), Some("@s-1"), &mut Vec::new());
                seed_usage_act(
                    &mut s2.turn_end,
                    &ledger,
                    s2.setup.sid.as_deref(),
                    act_ms + 120_000,
                    Instant::now(),
                );
                s2.seed_wall_memory(open.clone());
                let waits = s2.turn_end.waits_on_named_reset();
                let next = (!worked).then(|| decided(&mut s2, screen, 101)).flatten();
                drop(s2);
                let _ = std::fs::remove_dir_all(&dir);
                if worked {
                    if !closed || open.is_some() || waits {
                        wrong.push(format!(
                            "{case}: closed by the act {closed}, open wall {open:?}, waits {waits}"
                        ));
                    }
                    continue;
                }
                // The wall is open again, at the limit's reset; the first
                // loop waits on it and so does the successor, each typing
                // the limit's continuation at the wait's end.
                let named = open.as_ref().is_some_and(|o| o.reset_unix.is_some());
                let works = |d: Decided| {
                    d.is_some_and(|(until, rule)| {
                        until >= reset && until > now + 120 && rule == Some(RULE_LIMIT_RESUME)
                    })
                };
                if !closed || !named || !waits || !works(first) || !works(next) {
                    wrong.push(format!(
                        "{case}: closed by the act {closed}, open wall {open:?}, successor \
                         waits on its reset {waits}, first loop {first:?}, successor {next:?}"
                    ));
                }
            }
        }
    }
    assert!(wrong.is_empty(), "{wrong:#?}");
}

/// A BUCKET'S NOTICE THE LOOP'S OWN TRY MET, CANCELLED BEFORE THE LOOP'S
/// FIRST READ, IS THAT TRY'S ANSWER (the verifier of the successor's seed's
/// refix, V21-1). The lab's Sonnet bucket (2.1.300, `resets Oct 17 at
/// 4:20pm`), its countdown armed, waited on by the loop, which then types its
/// try: twenty minutes past the reset by its own decision, or two days before
/// it, kept in the loop's books as `turn_end_execute` keeps a typed act (the
/// reread, `acted`, the row). The bucket answers the try's own `keep going`
/// at once (its notice under that prompt), and a person's Esc on the new
/// countdown comes before the loop's first read: that read shows the vendor's
/// `⏺ Automatic continue cancelled` under the bucket's notice, no wall. The
/// screen is CONSTRUCTED from the measured armed bucket by the rule the
/// five-hour limit's measured Esc follows (2.1.300's Esc on a bucket's
/// countdown is not measured). That cancelled notice is the try's answer,
/// as a usage window's is: the first loop waits for the bucket's reset (or
/// the ladder's rung past it), the ledger's wall is open at that reset, and
/// a loop that follows waits no sooner and then types `usage-resume@v1`.
/// Measured before (a probe): the notice was read as no answer, the try was
/// a short turn, and `continue@v1 keep going` went into the standing bucket
/// at the two-minute back-off, from the first loop and its successor alike.
/// NEGATIVE CONTROL: the same try answered by the worker's work (a turn end
/// after twelve minutes of it, no wall): the ledger's wall stays closed and
/// the successor waits on no reset.
#[test]
fn a_buckets_notice_cancelled_before_the_loops_first_read_answers_its_try() {
    use crate::supervise::approvals::{Ledger, Outcome, act_reason, open_wall, usage_attempt};
    use crate::supervise::policy::turn_end::{RULE_LIMIT_RESUME, decide_turn_end};
    use aterm_phase::prompt::fixtures as fx;
    // Oct 17 4:20pm PDT, the bucket's reset.
    const RESET: i64 = 1_792_279_200;
    let opts = SuperviseOpts {
        policy: SupervisorConfig {
            model_fallback: None,
            ..owners_policy()
        },
        ..auto(30)
    };
    let armed = fx::screen(fx::WALL_SONNET_BUCKET_AUTO_CONTINUE_ARMED_2_1_300);
    // The armed bucket's banner and countdown taken off, `above` drawn over
    // the composer's frame.
    let then = |above: &[&str]| -> Vec<String> {
        let mut rows: Vec<String> = armed
            .iter()
            .filter(|r| {
                !r.contains("Usage limit reached") && !r.contains("Continuing automatically")
            })
            .cloned()
            .collect();
        let top = rows
            .iter()
            .position(|r| r.starts_with('─'))
            .expect("the composer's frame");
        rows.splice(top..top, above.iter().map(|r| (*r).to_string()));
        rows
    };
    // The try's own prompt answered by the bucket's notice, then Esc.
    let answered = then(&[
        "❯ keep going",
        "  ⎿  You've hit your Sonnet limit · resets Oct 17 at 4:20pm (America/Los_Angeles)",
        "",
        "✻ Churned for 0s · done 8:49 AM",
        "",
        "⏺ Automatic continue cancelled · /rate-limit-options to re-arm",
        "",
    ]);
    assert!(
        aterm_phase::left_wall(&answered).is_some_and(|w| w.kind
            == aterm_phase::WallKind::ModelBucket { consent: false }
            && w.reset.is_some()),
        "the screen draws the bucket a cancel left: {answered:#?}"
    );
    // …and as Claude Code 2.1.302 draws a bucket's countdown (MEASURED, the
    // lab, 2026-10-17: `claude-2.1.302-wall-sonnet-bucket-auto-continue-cancelled.txt`):
    // the notice's `/upgrade` row, the GENERIC countdown row under it, then
    // the cancel. Read before as a session window's (the generic row the
    // newest notice), the cancel left no bucket and the try was a short turn.
    let generic = then(&[
        "❯ keep going",
        "  ⎿  You've hit your Sonnet limit · resets Oct 17 at 4:20pm (America/Los_Angeles)",
        "     /upgrade to increase your usage limit.",
        "",
        "⏺ Usage limit reached · continuing automatically at Oct 17 at 4:20pm · esc to cancel",
        "",
        "✻ Churned for 0s · done 8:49 AM",
        "",
        "⏺ Automatic continue cancelled · /rate-limit-options to re-arm",
        "",
    ]);
    assert!(
        aterm_phase::left_wall(&generic).is_some_and(|w| w.kind
            == aterm_phase::WallKind::ModelBucket { consent: false }
            && w.reset.is_some()
            && w.message.contains("Sonnet")),
        "the generic row's cancel left the bucket: {:#?}",
        aterm_phase::left_wall(&generic)
    );
    type Decided = Option<(i64, Option<&'static str>)>;
    let decided = |s: &mut Session<'_, Mock>, rows: &[String], seq: u64| -> Decided {
        let point = point_at(s, rows.to_vec(), seq);
        match s
            .turn_end_at_point(&point, None, &opts)
            .expect("a decision")
        {
            TurnEndAction::WaitUntil { until, .. } => {
                let r = s.turn_end_reading(&point.screen, None, &opts);
                Some((
                    s.unix_of(until),
                    decide_turn_end(&s.turn_end, &r, &opts.policy, until).rule_id(),
                ))
            }
            other => Some((s.now_unix(), other.rule_id())),
        }
    };
    let mut wrong = Vec::new();
    let mut n = 0;
    for (shape, answered) in [("its dialog", &answered), ("the generic row", &generic)] {
        for (when, now) in [
            ("past its reset, the loop's decision", RESET + 20 * 60),
            ("two days before it, the loop's books", RESET - 2 * 86_400),
        ] {
            for worked in [false, true] {
                n += 1;
                let case = format!(
                    "{shape}, {when}, {}",
                    if worked {
                        "control: work answered the try"
                    } else {
                        "the bucket answered the try, then Esc"
                    }
                );
                let (dir, ledger) = ledger_at(&format!("bucket-left-answer-{n}"));
                let mut m = Mock::new(vec![armed.clone()]);
                let mut s = session(&mut m, Some("@s-1".to_string()));
                s.set_zone_lookup(test_zones);
                s.ledger = Ledger::open(Some(&ledger), Some("@s-1"), &mut Vec::new());
                s.set_turn_end_timing(TurnEndTiming {
                    take_within: Duration::ZERO,
                    ..TurnEndTiming::default()
                });
                // The loop waits on the bucket before its reset (the wall written).
                s.set_clock(now.min(RESET) - 4 * 60, PDT);
                let _ = decided(&mut s, &armed, 100);
                s.set_clock(now, PDT);
                let p = point_at(&s, armed.clone(), 101);
                if now > RESET {
                    let a = s.turn_end_at_point(&p, None, &opts).expect("the try");
                    assert_eq!(a.rule_id(), Some(RULE_LIMIT_RESUME), "{case}");
                    s.pass_wake_settle();
                    s.turn_end_execute(&p, a, &opts, &[], &mut Alone)
                        .expect("typed");
                } else {
                    let r = s.turn_end_reread(&p.screen, &opts);
                    s.turn_end.acted(
                        &TurnEndAction::Type {
                            text: "keep going".to_string(),
                            rule_id: RULE_LIMIT_RESUME,
                        },
                        &r,
                        Instant::now(),
                    );
                    let reason = act_reason(s.turn_end.limit_try());
                    s.ledger_row(
                        RULE_LIMIT_RESUME,
                        Outcome::Typed,
                        "keep going",
                        &reason,
                        101,
                    );
                }
                let act_ms = usage_attempt(&ledger, Some("@s-1"))
                    .expect("the try's row")
                    .at_ms;
                // Its answer, at the loop's first read after it.
                s.set_clock(now + 30, PDT);
                let at_answer = if worked {
                    let p = point_at(&s, ended("Fixed the parser; the suite is green."), 102);
                    let _ = s.turn_end_at_point(&p, Some(Duration::from_secs(12 * 60)), &opts);
                    None
                } else {
                    decided(&mut s, answered, 102)
                };
                let open = open_wall(&ledger, Some("@s-1"));
                s.set_clock(now + 120, PDT);
                let first = (!worked).then(|| decided(&mut s, answered, 103)).flatten();
                drop(s);
                let mut m2 = Mock::new(vec![answered.clone()]);
                let mut s2 = session(&mut m2, Some("@s-1".to_string()));
                s2.set_clock(now + 120, PDT);
                s2.set_zone_lookup(test_zones);
                s2.ledger = Ledger::open(Some(&ledger), Some("@s-1"), &mut Vec::new());
                seed_usage_act(
                    &mut s2.turn_end,
                    &ledger,
                    s2.setup.sid.as_deref(),
                    act_ms + 120_000,
                    Instant::now(),
                );
                s2.seed_wall_memory(open.clone());
                let waits = s2.turn_end.waits_on_named_reset();
                let next = (!worked).then(|| decided(&mut s2, answered, 101)).flatten();
                drop(s2);
                let _ = std::fs::remove_dir_all(&dir);
                let reset = open.as_ref().and_then(|o| o.reset_unix);
                if worked {
                    if open.is_some() || waits {
                        wrong.push(format!(
                            "{case}: open wall {open:?}, successor waits {waits}"
                        ));
                    }
                    continue;
                }
                // A wait for the bucket, never the short turn's back-off: no
                // sooner than its reset, and past it the ladder's rung after the
                // try's answer; then the bucket's continuation.
                let waits_out = |d: Decided| {
                    d.is_some_and(|(until, rule)| {
                        until > now + 120 && until >= RESET && rule == Some(RULE_LIMIT_RESUME)
                    })
                };
                // The successor counts the rung from the try's row, the first
                // loop from its answer's read thirty seconds later.
                let no_sooner = first
                    .zip(next)
                    .is_some_and(|((mine, _), (theirs, _))| theirs + 30 >= mine);
                if reset != Some(RESET)
                    || !waits
                    || !waits_out(at_answer)
                    || !waits_out(first)
                    || !waits_out(next)
                    || !no_sooner
                {
                    wrong.push(format!(
                        "{case}: open wall at {reset:?}, at the answer {at_answer:?}, first loop \
                     {first:?}, successor waits {waits} {next:?}"
                    ));
                }
            }
        }
    }
    assert!(wrong.is_empty(), "{wrong:#?}");
}

/// THE END OF A WALL AN ACT CLOSED IS WRITTEN STILL (the verifier of
/// 49f07f50e, V21-3). A typed row closes the ledger's wall for
/// `open_wall`, and the act re-arms the memory so the wall it meets again
/// is written again (V2-1), but `account_moves` ends a move refused at the
/// wall (`unmade`, the latch a loop that follows carries onto its first wall,
/// where no move is asked) at a typed row or the wall's end row only. The
/// loop reads the five-hour limit (its wall written), its try is typed, then
/// a move to another account is asked at the wall and refused (`skipped …
/// at=wall`); the wall then ends by the worker's work, no act typed: the end
/// row is written, and the ledger's latch is over, as the first loop's own
/// is (the worker worked). Measured before (a probe): the re-armed memory
/// wrote no end row, `unmade` stood, and a loop that followed waited out its
/// first wall beside an account that could serve. Ended by work at a point,
/// the policy's own end row (`approvals::LIMIT_ENDED`) is written too, and
/// it alone ends the latch; so the memory's end is pinned where that row is
/// not written (the verifiers of fde9e066a, A3 and B-2): a live turn read
/// busy ends the memory, and that turn's twelve minutes end on the same wall
/// (no retry of the loop's: its track is not begun again). NEGATIVE
/// CONTROL: the wall still standing (no work): no end row, the latch stands.
#[test]
fn the_end_of_a_wall_its_try_closed_is_written_for_the_refused_moves_latch() {
    use crate::supervise::approvals::{
        ACCOUNT_MOVE_COMMAND, LIMIT_ENDED, Ledger, Outcome, RULE_WALL_WAIT_END, account_moves,
        account_unmade_reason, act_reason,
    };
    use crate::supervise::policy::turn_end::{
        AccountAt, LimitTry, RULE_ACCOUNT, RULE_LIMIT_RESUME,
    };
    // 3:35pm PDT on the watch tests' day.
    const RESET: i64 = TEST_NOW + 6 * 3600 + 40 * 60;
    let opts = SuperviseOpts {
        policy: SupervisorConfig {
            model_fallback: None,
            ..owners_policy()
        },
        ..auto(30)
    };
    let armed = auto_continue_wall_at("3:35pm");
    // A person's turn, running: its prompt, the model's words, the spinner.
    let live = {
        let mut r = rows(&[
            "❯ please look at the schema",
            "",
            "⏺ Working.",
            "",
            "✻ Synthesizing… (18s)",
            "",
        ]);
        r.extend(composer("  esc to interrupt"));
        r
    };
    // (the case, the memory's end rows, the policy's, the latch at the end)
    for (n, (case, want)) in [
        ("the wall ended by the worker's work", (0, 1, false)),
        (
            "a live turn read busy, its work ending on the wall",
            (1, 0, false),
        ),
        ("control: the wall stands", (0, 0, true)),
    ]
    .into_iter()
    .enumerate()
    {
        let (dir, ledger) = ledger_at(&format!("written-end-{n}"));
        let mut m = Mock::new(vec![armed.clone()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_zone_lookup(test_zones);
        s.ledger = Ledger::open(Some(&ledger), Some("@s-1"), &mut Vec::new());
        s.set_clock(RESET - 4 * 60, PDT);
        let p = point_at(&s, armed.clone(), 100);
        let _ = s.turn_end_at_point(&p, None, &opts);
        s.set_clock(RESET + 20 * 60, PDT);
        s.ledger_row(
            RULE_LIMIT_RESUME,
            Outcome::Typed,
            "keep going",
            &act_reason(Some(LimitTry {
                bucket: false,
                in_place: false,
                attempts: 1,
                entitlement: false,
            })),
            101,
        );
        s.ledger_row(
            RULE_ACCOUNT,
            Outcome::Skipped,
            &format!("{ACCOUNT_MOVE_COMMAND}work-2"),
            &account_unmade_reason("work-2", AccountAt::Wall, Some("wait:busy")),
            102,
        );
        let latched = account_moves(&ledger, Some("@s-1")).unmade;
        if n == 0 {
            s.set_clock(RESET + 35 * 60, PDT);
            let p = point_at(&s, ended("Fixed the parser; the suite is green."), 103);
            let _ = s.turn_end_at_point(&p, Some(Duration::from_secs(12 * 60)), &opts);
        } else if n == 1 {
            s.set_clock(RESET + 23 * 60, PDT);
            let reader = s.reader(&live);
            s.end_memory_on_live_turn(reader, &live, 103);
            s.set_clock(RESET + 35 * 60, PDT);
            let p = point_at(&s, armed.clone(), 104);
            let _ = s.turn_end_at_point(&p, Some(Duration::from_secs(12 * 60)), &opts);
        }
        drop(s);
        let unmade = account_moves(&ledger, Some("@s-1")).unmade;
        let body = std::fs::read_to_string(&ledger).unwrap_or_default();
        let ends: Vec<&str> = body
            .lines()
            .filter(|l| l.contains(&format!("\"rule_id\":\"{RULE_WALL_WAIT_END}\"")))
            .collect();
        let worked = ends.iter().filter(|l| l.contains(LIMIT_ENDED)).count();
        let got = (ends.len() - worked, worked, unmade);
        let _ = std::fs::remove_dir_all(&dir);
        assert!(latched, "{case}: the refused move latched");
        assert_eq!(
            got, want,
            "{case}: the memory's end rows, the policy's, the latch"
        );
    }
}

/// A LIMIT'S TRY THE WORKER'S WORK ANSWERED IS NO SEED OF A LOOP THAT
/// FOLLOWS (the verifier of ed6efadb0, V22-A). The loop waits out a spend
/// limit (no reset: the entitlement ladder) and types its try at the first
/// rung; the try is served, the worker works fifty minutes, the turn ends
/// with no wall and the loop types its continuation; that work meets a NEW
/// wall: the spend limit again, or a five-hour window whose reset could not
/// be read (the same class, on the short ladder). Or the try's own turn works
/// seventy minutes and ends on the spend limit: a new episode of it, whose
/// wall is written again after the end of the old one. The first loop's track
/// ended at the work, so the new wall is a new appearance on its first rung.
/// A loop that starts on the ledger ten minutes into the new wall (a
/// seamless update), seeded in `drive_loop`'s order, works it as the first
/// loop does: no try is taken up, and it waits its first rung from
/// attaching, never sooner than the first loop. Measured before (the
/// verifier's probes): only an account move voided a try, so the successor
/// worked the new wall as the old try's rung: the spend limit waited out
/// the try's two-hour rung, and the window was continued with
/// `usage-resume@v1` the moment the successor attached, half an hour before
/// the first loop. The ledger now says where work ended the limit's track
/// (`wall-wait-end@v1`, `approvals::LIMIT_ENDED`), and a try that row
/// follows is no seed. NEGATIVE CONTROLS: the try met again, no work: the
/// try is taken up, and the successor holds its rung, two hours from the
/// try. So too where a person's turn then works twenty minutes and ends on
/// the wall, and the successor attached into it sees that work: the loop
/// that typed the try keeps its rung through a person's turn, and so does
/// the successor, whose ledger shows the wall read after the try
/// (`approvals::UsageAttempt::met_ms`). So too where the first loop reads that
/// turn busy — a live turn ends the remembered wall, and its end row closes
/// the ledger's — and the successor attaches during it, seeded from the
/// ledger as it stood then: no open wall, the wall's row after the try's
/// still. Measured before (the verifier of e9e6f65e9, B-1): read from the
/// open wall alone, that successor took the person's work for the try's own,
/// started the episode again and typed `usage-resume@v1` into the standing
/// spend limit fifty minutes before the first loop. The try's own turn above
/// (no wall read after the try) is the control that still starts again.
#[test]
fn a_limits_try_the_workers_work_answered_is_no_seed_of_a_loop_that_follows() {
    use crate::supervise::approvals::{
        LIMIT_ENDED, Ledger, RULE_WALL_WAIT_END, open_wall, usage_attempt,
    };
    use crate::supervise::policy::turn_end::{RULE_LIMIT_RESUME, decide_turn_end};
    // The spend limit's entitlement ladder: under `[harness] usage_credits =
    // true` alone.
    let opts = SuperviseOpts {
        policy: SupervisorConfig {
            model_fallback: None,
            usage_credits: true,
            ..owners_policy()
        },
        ..auto(30)
    };
    let walled = |notice: &str| {
        let mut r = rows(&[
            "⏺ Running the suite.",
            &format!("  ⎿  {notice}"),
            "",
            "✻ Worked for 3m 2s · done 4:51 PM",
            "",
        ]);
        r.extend(composer("  ? for shortcuts"));
        r
    };
    let spend = walled("You've hit your monthly spend limit.");
    // A person's turn, running: its prompt, the model's words, the spinner.
    let live = {
        let mut r = rows(&[
            "❯ please look at the schema",
            "",
            "⏺ Working.",
            "",
            "✻ Synthesizing… (18s)",
            "",
        ]);
        r.extend(composer("  esc to interrupt"));
        r
    };
    type Decided = Option<(i64, Option<&'static str>)>;
    let decided = |s: &mut Session<'_, Mock>,
                   rows: &[String],
                   seq: u64,
                   worked: Option<Duration>|
     -> Decided {
        let point = point_at(s, rows.to_vec(), seq);
        match s
            .turn_end_at_point(&point, worked, &opts)
            .expect("a decision")
        {
            TurnEndAction::WaitUntil { until, .. } => {
                let r = s.turn_end_reading(&point.screen, None, &opts);
                Some((
                    s.unix_of(until),
                    decide_turn_end(&s.turn_end, &r, &opts.policy, until).rule_id(),
                ))
            }
            other => Some((s.now_unix(), other.rule_id())),
        }
    };
    let t = TEST_NOW;
    let mut wrong = Vec::new();
    let mut n = 0;
    for (new_wall, served, person, busy) in [
        ("the spend limit again", true, false, false),
        ("a window, its reset unread", true, false, false),
        (
            "the try's own work met the spend limit again",
            true,
            false,
            false,
        ),
        ("control: the try met again", false, false, false),
        (
            "control: the try met again, then a person's turn",
            false,
            true,
            false,
        ),
        (
            "control: the try met again, then a person's turn read busy, attached into",
            false,
            true,
            true,
        ),
    ] {
        let direct = new_wall.starts_with("the try's own work");
        let again = if new_wall.starts_with("a window") {
            walled("You've hit your session limit")
        } else {
            spend.clone()
        };
        n += 1;
        let (dir, ledger) = ledger_at(&format!("try-worked-{n}"));
        let mid_turn = dir.join("mid-turn.jsonl");
        let mut m = Mock::new(vec![spend.clone()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_zone_lookup(test_zones);
        s.ledger = Ledger::open(Some(&ledger), Some("@s-1"), &mut Vec::new());
        s.set_turn_end_timing(TurnEndTiming {
            take_within: Duration::ZERO,
            ..TurnEndTiming::default()
        });
        s.set_clock(t, PDT);
        let wait = decided(&mut s, &spend, 100, Some(Duration::from_secs(3 * 60)));
        let try_at = wait.map_or(t, |(until, _)| until).max(t + 2 * 3600);
        s.set_clock(try_at, PDT);
        let p = point_at(&s, spend.clone(), 101);
        let a = s.turn_end_at_point(&p, None, &opts).expect("the try");
        assert_eq!(a.rule_id(), Some(RULE_LIMIT_RESUME), "{new_wall}");
        s.pass_wake_settle();
        s.turn_end_execute(&p, a, &opts, &[], &mut Alone)
            .expect("typed");
        // The ledger's clock: the try's row.
        let act_ms = usage_attempt(&ledger, Some("@s-1"))
            .expect("the try's row")
            .at_ms;
        // Whether the wall stood open in the ledger right after the first
        // loop's decision at the try's own work (before any reading after it).
        let mut open_at_once = None;
        let (wall_at, first) = if direct {
            // The try's turn works seventy minutes and ends on the wall.
            s.set_clock(try_at + 70 * 60, PDT);
            let p = point_at(&s, again.clone(), 102);
            let a = s
                .turn_end_at_point(&p, Some(Duration::from_secs(70 * 60)), &opts)
                .expect("a decision");
            open_at_once = Some(open_wall(&ledger, Some("@s-1")).is_some());
            let TurnEndAction::WaitUntil { until, .. } = a else {
                panic!("{new_wall}: {a:?}");
            };
            let r = s.turn_end_reading(&p.screen, None, &opts);
            (
                try_at + 70 * 60,
                Some((
                    s.unix_of(until),
                    decide_turn_end(&s.turn_end, &r, &opts.policy, until).rule_id(),
                )),
            )
        } else if served {
            // Served: fifty minutes of work, a turn end, the continuation.
            s.set_clock(try_at + 50 * 60, PDT);
            let p = point_at(&s, ended("Migrated the second table."), 102);
            let a = s
                .turn_end_at_point(&p, Some(Duration::from_secs(50 * 60)), &opts)
                .expect("the continuation");
            s.pass_wake_settle();
            s.turn_end_execute(&p, a, &opts, &[], &mut Alone)
                .expect("typed");
            // Its work meets the new wall.
            s.set_clock(try_at + 120 * 60, PDT);
            (
                try_at + 120 * 60,
                decided(&mut s, &again, 103, Some(Duration::from_secs(60 * 60))),
            )
        } else {
            s.set_clock(try_at + 30, PDT);
            let met = decided(&mut s, &again, 102, None);
            if person {
                if busy {
                    // The person's turn, twenty minutes after the try, read
                    // busy: a live turn ends the remembered wall. The
                    // successor attaches into it, on the ledger as it is now.
                    s.set_clock(try_at + 20 * 60, PDT);
                    let reader = s.reader(&live);
                    s.end_memory_on_live_turn(reader, &live, 103);
                    std::fs::copy(&ledger, &mid_turn).expect("the ledger mid-turn");
                }
                // A person's turn works twenty minutes and ends on the wall.
                s.set_clock(try_at + 40 * 60, PDT);
                (
                    try_at + 40 * 60,
                    decided(&mut s, &again, 104, Some(Duration::from_secs(20 * 60))),
                )
            } else {
                (try_at + 30, met)
            }
        };
        drop(s);
        // The successor attaches ten minutes on: after the new wall, or into
        // the person's turn, whose last ten minutes it sees.
        let (attach, seen) = if person {
            (wall_at, Some(Duration::from_secs(10 * 60)))
        } else {
            (wall_at + 10 * 60, None)
        };
        let books = if busy { &mid_turn } else { &ledger };
        let seed = usage_attempt(books, Some("@s-1")).map(|a| (a.at_ms, a.limit));
        let open = open_wall(books, Some("@s-1"));
        let mut m2 = Mock::new(vec![again.clone()]);
        let mut s2 = session(&mut m2, Some("@s-1".to_string()));
        s2.set_clock(attach, PDT);
        s2.set_zone_lookup(test_zones);
        s2.ledger = Ledger::open(Some(books), Some("@s-1"), &mut Vec::new());
        seed_usage_act(
            &mut s2.turn_end,
            books,
            s2.setup.sid.as_deref(),
            act_ms + (attach - try_at) * 1000,
            Instant::now(),
        );
        s2.seed_wall_memory(open.clone());
        let next = decided(&mut s2, &again, 101, seen);
        drop(s2);
        let body = std::fs::read_to_string(&ledger).unwrap_or_default();
        let worked_ends = body
            .lines()
            .filter(|l| l.contains(RULE_WALL_WAIT_END) && l.contains(LIMIT_ENDED))
            .count();
        let _ = std::fs::remove_dir_all(&dir);
        let due = |d: Decided| d.filter(|&(_, rule)| rule == Some(RULE_LIMIT_RESUME));
        let (Some((mine, _)), Some((theirs, _))) = (due(first), due(next)) else {
            wrong.push(format!(
                "{new_wall}: first loop {first:?}, successor {next:?}, open wall {open:?}"
            ));
            continue;
        };
        let ok = if served {
            // No try taken up; the new wall's first rung from attaching. The
            // new wall stands open for the successor: one the try's own work
            // met is written again after the end row, at once.
            seed.is_none()
                && worked_ends == 1
                && theirs > attach
                && theirs >= mine
                && open.is_some()
                && open_at_once != Some(false)
        } else {
            // The try's rung, two hours from where the first loop judged it
            // met (its answer's read, thirty seconds later: the take window
            // that read opened), as the first loop's (the verifier of
            // 341e1fa81, RS7-7). Attached into the turn read busy, the
            // ledger's wall was closed.
            seed.is_some_and(|(_, l)| l.attempts == 1 && l.entitlement)
                && worked_ends == 0
                && theirs == mine
                && (!busy || open.is_none())
        };
        if !ok {
            wrong.push(format!(
                "{new_wall}: try at +{}s, the new wall at +{}s, first loop until +{}s, \
                 successor at +{}s took up {seed:?} and waits until +{}s; {worked_ends} \
                 end row(s) of work, open wall {open:?}",
                try_at - t,
                wall_at - t,
                mine - t,
                attach - t,
                theirs - t,
            ));
        }
    }
    assert!(wrong.is_empty(), "{wrong:#?}");
}

/// A LIMIT'S TRACK DROPPED WITH NO WORK ROW ENDS ITS TRY FOR A LOOP THAT
/// FOLLOWS (the verifier of e09018898, B5-1). A spend limit's try, met again
/// thirty seconds on, then the first loop's track of it ends by no act of its
/// own: a person's `/clear` (a conversation with no task) — the remembered
/// wall standing then, or ended before it by a person's turn read busy, so
/// that only the policy's track ends there — or the try's own turn ending on
/// a 529 (another class's wall in its place) and its retry.
/// An hour and three quarters after the try, a new task's work meets the
/// spend limit again: a new appearance for the first loop, on its first rung
/// (30 minutes from it). A loop that starts on the ledger five minutes into
/// that wall — on it, or into a person's turn the first loop reads busy —
/// takes up no try, and types its `usage-resume@v1` no sooner than the first
/// loop. Measured before (the verifier's probe): only the worker's work
/// ended a try in the ledger, so the successor held the try's two-hour rung
/// and typed into the standing spend limit 15 minutes before the first loop.
/// The ledger now says where the policy's track ended
/// (`approvals::LIMIT_ENDED`, `approvals::WALL_LEFT_NO_TASK`). NEGATIVE
/// CONTROLS: the try met again with no drop: the try is taken up, and the
/// successor holds its rung, two hours from it, on the wall or attached into
/// a person's turn.
#[test]
fn a_limits_track_dropped_with_no_work_ends_its_try_for_a_loop_that_follows() {
    use crate::supervise::approvals::{Ledger, open_wall, usage_attempt};
    use crate::supervise::policy::turn_end::{RULE_LIMIT_RESUME, decide_turn_end};
    // The spend limit's entitlement ladder: under `[harness] usage_credits =
    // true` alone.
    let opts = SuperviseOpts {
        policy: SupervisorConfig {
            model_fallback: None,
            usage_credits: true,
            ..owners_policy()
        },
        ..auto(30)
    };
    let spend = {
        let mut r = rows(&[
            "⏺ Running the suite.",
            "  ⎿  You've hit your monthly spend limit.",
            "",
            "✻ Worked for 3m 2s · done 4:51 PM",
            "",
        ]);
        r.extend(composer("  ? for shortcuts"));
        r
    };
    let end_529 = aterm_phase::prompt::fixtures::screen(aterm_phase::prompt::fixtures::END_529);
    // A person's turn, running.
    let live = {
        let mut r = rows(&[
            "❯ please look at the schema",
            "",
            "⏺ Working.",
            "",
            "✻ Synthesizing… (18s)",
            "",
        ]);
        r.extend(composer("  esc to interrupt"));
        r
    };
    type Decided = Option<(i64, Option<&'static str>)>;
    let decided = |s: &mut Session<'_, Mock>,
                   rows: &[String],
                   seq: u64,
                   worked: Option<Duration>|
     -> Decided {
        let point = point_at(s, rows.to_vec(), seq);
        match s
            .turn_end_at_point(&point, worked, &opts)
            .expect("a decision")
        {
            TurnEndAction::WaitUntil { until, .. } => {
                let r = s.turn_end_reading(&point.screen, None, &opts);
                Some((
                    s.unix_of(until),
                    decide_turn_end(&s.turn_end, &r, &opts.policy, until).rule_id(),
                ))
            }
            other => Some((s.now_unix(), other.rule_id())),
        }
    };
    // Typed: the act a point decides, executed.
    let typed = |s: &mut Session<'_, Mock>, rows: &[String], seq: u64| -> Option<&'static str> {
        let p = point_at(s, rows.to_vec(), seq);
        let a = s.turn_end_at_point(&p, None, &opts).expect("an act");
        let rule = a.rule_id();
        s.pass_wake_settle();
        s.turn_end_execute(&p, a, &opts, &[], &mut Alone)
            .expect("typed");
        rule
    };
    let t = TEST_NOW;
    let mut wrong = Vec::new();
    for (n, (how, into_turn)) in [
        ("a /clear", false),
        ("a /clear", true),
        ("a /clear after a person's turn read busy", false),
        ("a 529 ending the try's own turn", false),
        ("a 529 ending the try's own turn", true),
        ("control: no drop", false),
        ("control: no drop", true),
    ]
    .into_iter()
    .enumerate()
    {
        let case = format!(
            "{how}, the successor {}",
            if into_turn {
                "attached into a person's turn"
            } else {
                "on the wall"
            }
        );
        let (dir, ledger) = ledger_at(&format!("track-dropped-{n}"));
        let books = dir.join("books.jsonl");
        let mut m = Mock::new(vec![spend.clone()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_zone_lookup(test_zones);
        s.ledger = Ledger::open(Some(&ledger), Some("@s-1"), &mut Vec::new());
        s.set_turn_end_timing(TurnEndTiming {
            take_within: Duration::ZERO,
            ..TurnEndTiming::default()
        });
        s.set_clock(t, PDT);
        let wait = decided(&mut s, &spend, 100, Some(Duration::from_secs(3 * 60)));
        let try_at = wait.map_or(t, |(until, _)| until).max(t + 2 * 3600);
        s.set_clock(try_at, PDT);
        assert_eq!(
            typed(&mut s, &spend, 101),
            Some(RULE_LIMIT_RESUME),
            "{case}"
        );
        let act_ms = usage_attempt(&ledger, Some("@s-1")).expect("the try").at_ms;
        let control = how.starts_with("control");
        let wall_at = if control {
            try_at + 30
        } else {
            try_at + 105 * 60
        };
        let mut step = if how.contains("529") {
            // The try's own turn works twenty minutes and ends on a 529; its
            // retry is typed at its rung.
            s.set_clock(try_at + 20 * 60, PDT);
            let p = point_at(&s, end_529.clone(), 102);
            let a = s
                .turn_end_at_point(&p, Some(Duration::from_secs(20 * 60)), &opts)
                .expect("the 529");
            let due = match a {
                TurnEndAction::WaitUntil { until, .. } => s.unix_of(until),
                _ => s.now_unix(),
            };
            s.set_clock(due, PDT);
            typed(&mut s, &end_529, 103);
            // That work meets the spend limit again.
            s.set_clock(wall_at, PDT);
            decided(&mut s, &spend, 104, Some(Duration::from_secs(60 * 60)))
        } else {
            // The try met again.
            s.set_clock(try_at + 30, PDT);
            let met = decided(&mut s, &spend, 102, None);
            if control {
                met
            } else {
                // A person's turn read busy ends the remembered wall (and its
                // row closes the ledger's): the `/clear` then ends the
                // policy's track alone.
                if how.contains("busy") {
                    s.set_clock(try_at + 3 * 60, PDT);
                    let reader = s.reader(&live);
                    s.end_memory_on_live_turn(reader, &live, 103);
                }
                // A person's `/clear`, then a new task's work meets the limit.
                s.set_clock(try_at + 5 * 60, PDT);
                decided(&mut s, &cleared_at_an_armed_limit(), 103, None);
                s.set_clock(wall_at, PDT);
                decided(&mut s, &spend, 104, Some(Duration::from_secs(5 * 60)))
            }
        };
        // The successor attaches five minutes into the wall: on it, or into
        // a person's turn the first loop reads busy, whose five minutes of
        // work it sees end on the wall.
        let attach = wall_at + 5 * 60;
        let (decide_at, seen) = if into_turn {
            s.set_clock(wall_at + 3 * 60, PDT);
            let reader = s.reader(&live);
            s.end_memory_on_live_turn(reader, &live, 105);
            std::fs::copy(&ledger, &books).expect("the books");
            s.set_clock(wall_at + 10 * 60, PDT);
            step = decided(&mut s, &spend, 106, Some(Duration::from_secs(7 * 60)));
            (wall_at + 10 * 60, Some(Duration::from_secs(5 * 60)))
        } else {
            std::fs::copy(&ledger, &books).expect("the books");
            (attach, None)
        };
        drop(s);
        let seed = usage_attempt(&books, Some("@s-1"));
        let mut m2 = Mock::new(vec![spend.clone()]);
        let mut s2 = session(&mut m2, Some("@s-1".to_string()));
        s2.set_clock(decide_at, PDT);
        s2.set_zone_lookup(test_zones);
        s2.ledger = Ledger::open(Some(&books), Some("@s-1"), &mut Vec::new());
        seed_usage_act(
            &mut s2.turn_end,
            &books,
            s2.setup.sid.as_deref(),
            act_ms + (decide_at - try_at) * 1000,
            Instant::now(),
        );
        s2.seed_wall_memory(open_wall(&books, Some("@s-1")));
        let next = decided(&mut s2, &spend, 101, seen);
        drop(s2);
        let _ = std::fs::remove_dir_all(&dir);
        let due = |d: Decided| d.filter(|&(_, rule)| rule == Some(RULE_LIMIT_RESUME));
        let (Some((mine, _)), Some((theirs, _))) = (due(step), due(next)) else {
            wrong.push(format!("{case}: first loop {step:?}, successor {next:?}"));
            continue;
        };
        let ok = if control {
            // The try's rung, two hours from where the first loop judged it
            // met (its answer's read, thirty seconds later: the take window
            // that read opened), as the first loop's (RS7-7).
            seed.is_some_and(|a| a.met_ms.is_some() && a.limit.attempts == 1) && theirs == mine
        } else {
            seed.is_none() && theirs >= mine
        };
        if !ok {
            wrong.push(format!(
                "{case}: the new wall at +{}s; first loop until +{}s; the successor took up \
                 {seed:?} and waits until +{}s",
                wall_at - try_at,
                mine - try_at,
                theirs - try_at
            ));
        }
    }
    assert!(wrong.is_empty(), "{wrong:#?}");
}

/// A WALL READ INSIDE A TRY'S TAKE WINDOW IS NO TRY MET AGAIN WHERE THE TRY
/// IS TAKEN (the verifier of e09018898, B5-2). A spend limit's try, its take
/// window the default thirty seconds. The loop reads the try's screen again
/// five seconds on, before Claude Code draws the submitted line: the same
/// notice, written to the ledger again (an act closes the ledger's wall).
/// Then the try is taken (a live turn read busy), and its own turn works
/// nineteen minutes and ends on the spend limit: the first loop starts that
/// wall's episode again (the try's work) and types 30 minutes from it. A
/// loop that starts on the ledger ten minutes into that turn decides as the
/// first loop does. Measured before (the verifier's probe): the wall's row
/// read as the try met again, and the successor held the try's two-hour
/// rung, 70 minutes after the first loop. The busy read's end row now
/// says the try was taken (`approvals::WALL_TAKEN`). So too where the
/// remembered wall ENDED inside the window before the take (the verifier of
/// 5b72b1613, M7-2): a person's `/model` under the notice is an idle point
/// there and ends the memory, then the person's own three-hour turn takes
/// the try and ends on the spend limit. The take row is written with no
/// memory standing; measured before, none was, and a successor attached
/// during that turn held the try's two-hour rung, 30 minutes before the
/// first loop. NEGATIVE CONTROLS: no
/// read inside the take window (both at 30 minutes from the wall); and the
/// notice read inside it with no take, the window's end judging the try met
/// again, then a person's turn read busy and ending on the wall: its end row
/// says nothing of a take, and the successor holds the try's rung as the
/// first loop does.
#[test]
fn a_wall_read_inside_a_tries_take_window_is_no_try_met_again_where_it_is_taken() {
    use crate::supervise::approvals::{Ledger, WALL_TAKEN, open_wall, usage_attempt};
    use crate::supervise::policy::turn_end::{RULE_LIMIT_RESUME, decide_turn_end};
    // The spend limit's entitlement ladder: under `[harness] usage_credits =
    // true` alone.
    let opts = SuperviseOpts {
        policy: SupervisorConfig {
            model_fallback: None,
            usage_credits: true,
            ..owners_policy()
        },
        ..auto(30)
    };
    let spend = {
        let mut r = rows(&[
            "⏺ Running the suite.",
            "  ⎿  You've hit your monthly spend limit.",
            "",
            "✻ Worked for 3m 2s · done 4:51 PM",
            "",
        ]);
        r.extend(composer("  ? for shortcuts"));
        r
    };
    // A live turn: the try's own, or a person's.
    let live = |prompt: &str| {
        let mut r = rows(&[
            &format!("❯ {prompt}"),
            "",
            "⏺ Working.",
            "",
            "✻ Synthesizing… (18s)",
            "",
        ]);
        r.extend(composer("  esc to interrupt"));
        r
    };
    type Decided = Option<(i64, Option<&'static str>)>;
    let decided = |s: &mut Session<'_, Mock>,
                   rows: &[String],
                   seq: u64,
                   worked: Option<Duration>|
     -> Decided {
        let point = point_at(s, rows.to_vec(), seq);
        match s
            .turn_end_at_point(&point, worked, &opts)
            .expect("a decision")
        {
            TurnEndAction::WaitUntil { until, .. } => {
                let r = s.turn_end_reading(&point.screen, None, &opts);
                Some((
                    s.unix_of(until),
                    decide_turn_end(&s.turn_end, &r, &opts.policy, until).rule_id(),
                ))
            }
            other => Some((s.now_unix(), other.rule_id())),
        }
    };
    let t = TEST_NOW;
    let mut wrong = Vec::new();
    // A person's local command under the notice: an idle point, no wall.
    let local = {
        let mut r = rows(&[
            "⏺ Running the suite.",
            "  ⎿  You've hit your monthly spend limit.",
            "",
            "✻ Worked for 3m 2s · done 4:51 PM",
            "",
            "❯ /model",
            "  ⎿  Kept model as Sonnet 5.5 (default)",
            "",
        ]);
        r.extend(composer("  ? for shortcuts"));
        r
    };
    for (n, case) in [
        "the notice read inside the take window, then the try taken",
        "the notice read inside the take window, a local command, then a person's 3 h turn takes the try",
        "control: no read inside the take window",
        "control: the notice read inside the take window, the try met again, then a person's turn",
    ]
    .into_iter()
    .enumerate()
    {
        let reread = !case.contains("no read");
        let person = case.ends_with("a person's turn");
        let long = case.contains("3 h turn");
        let (dir, ledger) = ledger_at(&format!("take-window-{n}"));
        let books = dir.join("books.jsonl");
        let mut m = Mock::new(vec![spend.clone()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_zone_lookup(test_zones);
        s.ledger = Ledger::open(Some(&ledger), Some("@s-1"), &mut Vec::new());
        // The default take window, or one the test outlasts.
        let window = if person {
            Duration::from_millis(50)
        } else {
            TurnEndTiming::default().take_within
        };
        s.set_turn_end_timing(TurnEndTiming {
            take_within: window,
            ..TurnEndTiming::default()
        });
        s.set_clock(t, PDT);
        let wait = decided(&mut s, &spend, 100, Some(Duration::from_secs(3 * 60)));
        let try_at = wait.map_or(t, |(until, _)| until).max(t + 2 * 3600);
        s.set_clock(try_at, PDT);
        let p = point_at(&s, spend.clone(), 101);
        let a = s.turn_end_at_point(&p, None, &opts).expect("the try");
        assert_eq!(a.rule_id(), Some(RULE_LIMIT_RESUME), "{case}");
        s.pass_wake_settle();
        s.turn_end_execute(&p, a, &opts, &[], &mut Alone)
            .expect("typed");
        let act_ms = usage_attempt(&ledger, Some("@s-1")).expect("the try").at_ms;
        if reread {
            s.set_clock(try_at + 5, PDT);
            decided(&mut s, &spend, 102, None);
        }
        if long {
            // Inside the window still: the idle point ends the memory.
            s.set_clock(try_at + 7, PDT);
            decided(&mut s, &local, 103, None);
        }
        if person {
            // No take: the window's end judges the try met again. (The take
            // window is the worker's own clock, which the test's does not
            // move: [`TurnEndState::slept`].)
            std::thread::sleep(window * 2);
            s.set_clock(try_at + 40, PDT);
            decided(&mut s, &spend, 103, None);
        }
        // A live turn read busy twenty seconds on (the try's own), or twenty
        // minutes on (a person's).
        let busy_at = if person { 20 * 60 } else { 20 };
        s.set_clock(try_at + busy_at, PDT);
        let turn = live(if person || long {
            "please look at the schema"
        } else {
            "keep going"
        });
        let reader = s.reader(&turn);
        s.end_memory_on_live_turn(reader, &turn, 104);
        s.turn_end.took();
        // The successor's books, ten minutes into that turn.
        s.set_clock(try_at + busy_at + 10 * 60, PDT);
        std::fs::copy(&ledger, &books).expect("the books");
        // The turn's work ends on the spend limit.
        let (end_at, work) = if person {
            (try_at + 40 * 60, 20 * 60)
        } else if long {
            (try_at + 20 + 3 * 3600, 3 * 3600)
        } else {
            (try_at + 20 * 60, 19 * 60)
        };
        s.set_clock(end_at, PDT);
        let first = decided(&mut s, &spend, 105, Some(Duration::from_secs(work)));
        drop(s);
        let rows = std::fs::read_to_string(&books).unwrap_or_default();
        let taken = rows.lines().filter(|l| l.contains(WALL_TAKEN)).count();
        let seed = usage_attempt(&books, Some("@s-1"));
        let mut m2 = Mock::new(vec![spend.clone()]);
        let mut s2 = session(&mut m2, Some("@s-1".to_string()));
        s2.set_clock(end_at, PDT);
        s2.set_zone_lookup(test_zones);
        s2.ledger = Ledger::open(Some(&books), Some("@s-1"), &mut Vec::new());
        seed_usage_act(
            &mut s2.turn_end,
            &books,
            s2.setup.sid.as_deref(),
            act_ms + (end_at - try_at) * 1000,
            Instant::now(),
        );
        s2.seed_wall_memory(open_wall(&books, Some("@s-1")));
        // It saw the turn's last ten minutes of work.
        let next = decided(&mut s2, &spend, 101, Some(Duration::from_secs(10 * 60)));
        drop(s2);
        let _ = std::fs::remove_dir_all(&dir);
        let due = |d: Decided| d.filter(|&(_, rule)| rule == Some(RULE_LIMIT_RESUME));
        let (Some((mine, _)), Some((theirs, _))) = (due(first), due(next)) else {
            wrong.push(format!("{case}: first loop {first:?}, successor {next:?}"));
            continue;
        };
        let ok = if person {
            // The try's rung, two hours from the end of the take window the
            // notice's read opened (its row stamped on the real clock, at the
            // try: thirty seconds on; RS7-7), as the first loop's (which
            // counts from the point that judged it, forty seconds on).
            taken == 0
                && seed.is_some_and(|a| a.met_ms.is_some())
                && theirs == try_at + 30 + 120 * 60
                && theirs + 40 >= mine
        } else {
            // Thirty minutes from the wall the try's own turn ended on.
            taken == usize::from(reread)
                && seed.is_some_and(|a| a.met_ms.is_none())
                && mine == end_at + 30 * 60
                && theirs == mine
        };
        if !ok {
            wrong.push(format!(
                "{case}: {taken} take row(s); the first loop until +{}s, the successor took up \
                 {seed:?} and waits until +{}s",
                mine - try_at,
                theirs - try_at
            ));
        }
    }
    assert!(wrong.is_empty(), "{wrong:#?}");
}

/// A BUCKET THE FALLBACK'S RELAUNCH LEFT IS NO WALL OF THE RELAUNCHED SESSION
/// (the verifier of 49f07f50e, V21-2). The lab's Sonnet bucket (2.1.300,
/// `resets Oct 17 at 4:20pm`, two days out), and the model fallback's
/// relaunch made (`relaunch --model opus`, as the loop's books keep it: the
/// policy's restart and its row). `claude --resume --model opus` redraws the
/// conversation, whose last thing said is the bucket's notice (CONSTRUCTED:
/// the measured bucket's history, its countdown and dialog rows gone, as a
/// `/resume` redraws an older limit's notice on 2.1.300; the relaunch's own
/// redraw is not measured). That notice is the old process's, of a model the
/// session no longer runs: the point is the continue policy's, as at a
/// relaunch that redraws nothing (the short turn's back-off, then
/// `continue@v1`), the ledger keeps no wall of it, and a loop that starts on
/// that ledger (seeded in `drive_loop`'s order: the switch, whose relaunch
/// no turn followed, then the open wall) decides the same. Measured before
/// (a probe): the redraw was read as the bucket, the session on opus waited
/// out the Sonnet reset two days away, and the wall written to the ledger
/// held a successor there too. NEGATIVE CONTROLS: once the continuation is
/// typed, the bucket's notice answering it is the wall again (the relaunch
/// did not take): its reset is waited out, by the first loop and by a loop
/// that starts after it; so too after a point that draws no such notice (the
/// conversation moved on); and a redrawn notice of another model's bucket is
/// a wall from the start.
#[test]
fn a_bucket_the_fallbacks_relaunch_left_is_no_wall_of_the_relaunched_session() {
    use crate::supervise::approvals::{Ledger, Outcome, model_switch_reason, open_wall};
    use crate::supervise::policy::turn_end::{
        RULE_CONTINUE, RULE_MODEL_FALLBACK, Restart, decide_turn_end,
    };
    use aterm_phase::prompt::fixtures as fx;
    // Oct 17 4:20pm PDT, the bucket's reset; the relaunch two days before.
    const RESET: i64 = 1_792_279_200;
    let now = RESET - 2 * 86_400;
    let opts = SuperviseOpts {
        policy: owners_policy(),
        ..auto(30)
    };
    assert_eq!(opts.policy.model_fallback.as_deref(), Some("opus"));
    let armed = fx::screen(fx::WALL_SONNET_BUCKET_AUTO_CONTINUE_ARMED_2_1_300);
    // The relaunched process's redraw: the history, the bucket's notice the
    // last thing said, the launch card naming the fallback.
    let redraw = |model: &str| -> Vec<String> {
        armed
            .iter()
            .filter(|r| {
                ![
                    "Usage limit reached",
                    "Continuing automatically",
                    "/rate-limit-options",
                    "Claude Code will continue automatically",
                    "to cancel the wait",
                ]
                .iter()
                .any(|g| r.contains(g))
            })
            .map(|r| {
                r.replace("Sonnet 5.5 · Claude API", "Opus 5.5 · Claude API")
                    .replace("your Sonnet limit", &format!("your {model} limit"))
            })
            .collect()
    };
    let redrawn = redraw("Sonnet");
    // The continuation answered by the bucket again.
    let met = {
        let mut rows = redrawn.clone();
        let top = rows
            .iter()
            .position(|r| r.starts_with('─'))
            .expect("the composer's frame");
        rows.splice(
            top..top,
            [
                "❯ keep going",
                "  ⎿  You've hit your Sonnet limit · resets Oct 17 at 4:20pm (America/Los_Angeles)",
                "",
                "✻ Churned for 0s · done 8:49 AM",
                "",
            ]
            .map(str::to_string),
        );
        rows
    };
    type Decided = Option<(i64, Option<&'static str>)>;
    let decided = |s: &mut Session<'_, Mock>, rows: &[String], seq: u64| -> Decided {
        let point = point_at(s, rows.to_vec(), seq);
        match s
            .turn_end_at_point(&point, None, &opts)
            .expect("a decision")
        {
            TurnEndAction::WaitUntil { until, .. } => {
                let r = s.turn_end_reading(&point.screen, None, &opts);
                Some((
                    s.unix_of(until),
                    decide_turn_end(&s.turn_end, &r, &opts.policy, until).rule_id(),
                ))
            }
            other => Some((s.now_unix(), other.rule_id())),
        }
    };
    // The successor: the switch the ledger holds (and whether a turn
    // followed its relaunch), then the open wall, as `drive_loop` seeds them.
    let successor = |ledger: &std::path::Path, at: i64, rows: &[String]| -> Decided {
        let mut m = Mock::new(vec![rows.to_vec()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(at, PDT);
        s.set_zone_lookup(test_zones);
        s.ledger = Ledger::open(Some(ledger), Some("@s-1"), &mut Vec::new());
        s.seed_model_switch(ledger);
        s.seed_wall_memory(open_wall(ledger, Some("@s-1")));
        decided(&mut s, rows, 101)
    };
    let short_turn = |d: Decided, from: i64| d == Some((from + 120, Some(RULE_CONTINUE)));
    let waits_out = |d: Decided| d.is_some_and(|(until, _)| until >= RESET);
    let mut wrong = Vec::new();
    for (case, model) in [
        ("the bucket the relaunch left", "Sonnet"),
        ("control: another model's bucket", "Opus"),
        ("control: a point since the relaunch", "Sonnet"),
    ] {
        let moved_on = case.ends_with("since the relaunch");
        let (dir, ledger) = ledger_at(&format!("bucket-left-{model}-{moved_on}"));
        let mut m = Mock::new(vec![armed.clone()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_zone_lookup(test_zones);
        s.ledger = Ledger::open(Some(&ledger), Some("@s-1"), &mut Vec::new());
        s.set_turn_end_timing(TurnEndTiming {
            take_within: Duration::ZERO,
            ..TurnEndTiming::default()
        });
        s.set_clock(now, PDT);
        let _ = decided(&mut s, &armed, 100);
        // The relaunch on the fallback, as the loop's books keep it.
        let p = point_at(&s, armed.clone(), 101);
        let r = s.turn_end_reread(&p.screen, &opts);
        s.turn_end.restarted(
            &Restart::Model {
                to: "opus".to_string(),
            },
            true,
            &r,
            Instant::now(),
        );
        s.ledger_row(
            RULE_MODEL_FALLBACK,
            Outcome::Typed,
            "relaunch --model opus",
            &model_switch_reason(Some("sonnet"), Some(RESET), now),
            101,
        );
        let screen = redraw(model);
        if moved_on {
            // A point that draws no such notice: the conversation moved on
            // (a person's own exchange). The bucket's notice after it is the
            // wall again.
            s.set_clock(now + 20, PDT);
            let _ = decided(&mut s, &ended("Here is the summary you asked for."), 102);
            s.set_clock(now + 30, PDT);
            let again = decided(&mut s, &met, 103);
            drop(s);
            let _ = std::fs::remove_dir_all(&dir);
            if !waits_out(again) {
                wrong.push(format!("{case}: {again:?}"));
            }
            continue;
        }
        s.set_clock(now + 30, PDT);
        let first = decided(&mut s, &screen, 102);
        let open = open_wall(&ledger, Some("@s-1")).is_some();
        let next = successor(&ledger, now + 60, &screen);
        if model == "Opus" {
            if !waits_out(first) || !waits_out(next) || !open {
                wrong.push(format!(
                    "{case}: first loop {first:?}, open wall {open}, successor {next:?}"
                ));
            }
            drop(s);
            let _ = std::fs::remove_dir_all(&dir);
            continue;
        }
        if !short_turn(first, now + 30) || open || !short_turn(next, now + 60) {
            wrong.push(format!(
                "{case}: first loop {first:?}, open wall {open}, successor {next:?}"
            ));
        }
        // The continuation, typed at the back-off's end.
        s.set_clock(now + 150, PDT);
        let p = point_at(&s, screen.clone(), 103);
        let a = s
            .turn_end_at_point(&p, None, &opts)
            .expect("the continuation");
        assert_eq!(a.rule_id(), Some(RULE_CONTINUE), "{case}");
        s.pass_wake_settle();
        s.turn_end_execute(&p, a, &opts, &[], &mut Alone)
            .expect("typed");
        // NEGATIVE CONTROL: the bucket answers it: the wall again, for a
        // successor that starts before the first loop reads that answer (its
        // ledger: the continuation's row after the relaunch's) and for one
        // after.
        let early = successor(&ledger, now + 160, &met);
        s.set_clock(now + 180, PDT);
        let again = decided(&mut s, &met, 104);
        drop(s);
        let after = successor(&ledger, now + 240, &met);
        let _ = std::fs::remove_dir_all(&dir);
        if !waits_out(early) || !waits_out(again) || !waits_out(after) {
            wrong.push(format!(
                "{case}, the continuation met the bucket: a successor before its read \
                 {early:?}, first loop {again:?}, a successor after {after:?}"
            ));
        }
    }
    assert!(wrong.is_empty(), "{wrong:#?}");
}

/// A TURN ASKED ON THE FALLBACK IS WRITTEN FOR A LOOP THAT FOLLOWS (the
/// verifier of fde9e066a, A1). The books of
/// [`a_bucket_the_fallbacks_relaunch_left_is_no_wall_of_the_relaunched_session`]:
/// the lab's Sonnet bucket two days before its reset, the fallback's relaunch
/// on opus made through the loop's own restart (the host relaunches), and the
/// relaunched process's redraw, its last thing said the bucket's notice. The
/// first loop's latch ends where a turn is asked with no act of its own: at
/// a point that draws no such notice (a person's `/model sonnet`; a person's
/// exchange), or where the host typed the carry-on, inside the relaunch or
/// at a step of its own after it (`Session::host_turn`). The
/// bucket's notice that then answers a person's prompt (or the carry-on) is
/// the wall again, and its reset is waited out — by the first loop, by a
/// loop that starts before the first loop's read of it, by one that starts
/// after, and by one after that. Measured before (the verifier's probes):
/// the successor read only typed rows as a turn asked, took the notice for
/// the redraw, typed `continue@v1` at its two-minute back-off two days
/// before the reset, and the one after the first loop's read closed the
/// ledger's wall too, so the next typed it as well. NEGATIVE CONTROL: the
/// redraw with nothing between: a successor decides the short turn's
/// back-off and `continue@v1`, as the first loop does.
#[test]
fn a_turn_asked_on_the_fallback_is_written_for_a_loop_that_follows() {
    use crate::supervise::approvals::{Ledger, open_wall};
    use crate::supervise::policy::turn_end::{HostTurn, RULE_CONTINUE, decide_turn_end};
    use aterm_phase::prompt::fixtures as fx;
    // Oct 17 4:20pm PDT, the bucket's reset; the relaunch two days before.
    const RESET: i64 = 1_792_279_200;
    let now = RESET - 2 * 86_400;
    let armed = fx::screen(fx::WALL_SONNET_BUCKET_AUTO_CONTINUE_ARMED_2_1_300);
    // The relaunched process's redraw: the history, the bucket's notice the
    // last thing said, the launch card naming the fallback (CONSTRUCTED, as
    // the relaunch's own redraw is not measured).
    let redrawn: Vec<String> = armed
        .iter()
        .filter(|r| {
            ![
                "Usage limit reached",
                "Continuing automatically",
                "/rate-limit-options",
                "Claude Code will continue automatically",
                "to cancel the wait",
            ]
            .iter()
            .any(|g| r.contains(g))
        })
        .map(|r| r.replace("Sonnet 5.5 · Claude API", "Opus 5.5 · Claude API"))
        .collect();
    let above_composer = |base: &[String], add: &[&str]| -> Vec<String> {
        let mut rows = base.to_vec();
        let top = rows
            .iter()
            .position(|r| r.starts_with('─'))
            .expect("the composer's frame");
        rows.splice(top..top, add.iter().map(|s| (*s).to_string()));
        rows
    };
    // A person's `/model sonnet` under the redraw.
    let to_sonnet = above_composer(
        &redrawn,
        &["❯ /model sonnet", "  ⎿  Set model to Sonnet 5.5", ""],
    );
    // A prompt under `base`, answered at once by the bucket's notice.
    let met = |prompt: &str, base: &[String]| {
        above_composer(
            base,
            &[
                &format!("❯ {prompt}"),
                "  ⎿  You've hit your Sonnet limit · resets Oct 17 at 4:20pm (America/Los_Angeles)",
                "",
                "✻ Churned for 0s · done 8:49 AM",
                "",
            ],
        )
    };
    type Decided = Option<(i64, Option<&'static str>)>;
    let decided = |s: &mut Session<'_, Mock>,
                   rows: &[String],
                   seq: u64,
                   worked: Option<Duration>,
                   opts: &SuperviseOpts|
     -> Decided {
        let point = point_at(s, rows.to_vec(), seq);
        match s
            .turn_end_at_point(&point, worked, opts)
            .expect("a decision")
        {
            TurnEndAction::WaitUntil { until, .. } => {
                let r = s.turn_end_reading(&point.screen, None, opts);
                Some((
                    s.unix_of(until),
                    decide_turn_end(&s.turn_end, &r, &opts.policy, until).rule_id(),
                ))
            }
            other => Some((s.now_unix(), other.rule_id())),
        }
    };
    let plain = SuperviseOpts {
        policy: owners_policy(),
        ..auto(30)
    };
    // The successor, seeded in `drive_loop`'s order: the switch the ledger
    // holds (and whether a turn was asked after its relaunch), then the open
    // wall.
    let successor = |ledger: &std::path::Path, at: i64, rows: &[String]| -> Decided {
        let mut m = Mock::new(vec![rows.to_vec()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(at, PDT);
        s.set_zone_lookup(test_zones);
        s.ledger = Ledger::open(Some(ledger), Some("@s-1"), &mut Vec::new());
        s.seed_model_switch(ledger);
        s.seed_wall_memory(open_wall(ledger, Some("@s-1")));
        decided(&mut s, rows, 101, None, &plain)
    };
    let waits_out = |d: Decided| d.is_some_and(|(until, _)| until >= RESET);
    let mut wrong = Vec::new();
    for (n, case) in [
        "a person's /model sonnet, then their prompt met by the bucket",
        "a person's exchange, then their prompt met by the bucket",
        "the host's carry-on typed inside the relaunch, met by the bucket",
        "control: the redraw, nothing between",
        "the host's carry-on typed at its own step, met by the bucket",
    ]
    .into_iter()
    .enumerate()
    {
        let carried = n == 2;
        let (dir, ledger) = ledger_at(&format!("fallback-asked-{n}"));
        // The host relaunches on the fallback; inside it, it types the
        // carry-on (`continued`) or nothing (`relaunched`).
        let host =
            AccountHost::scripted(&[None], &[if carried { "continued" } else { "relaunched" }]);
        let opts = SuperviseOpts {
            idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
            ..plain.clone()
        };
        let mut m = Mock::new(vec![armed.clone()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_zone_lookup(test_zones);
        s.ledger = Ledger::open(Some(&ledger), Some("@s-1"), &mut Vec::new());
        s.set_turn_end_timing(TurnEndTiming {
            take_within: Duration::ZERO,
            ..TurnEndTiming::default()
        });
        s.set_clock(now, PDT);
        let p = point_at(&s, armed.clone(), 100);
        let a = s.turn_end_at_point(&p, None, &opts).expect("the fallback");
        assert!(
            matches!(&a, TurnEndAction::Restart { why: Restart::Model { to }, .. } if to == "opus"),
            "{case}: {a:?}"
        );
        s.turn_end_execute(&p, a, &opts, &[], &mut Alone)
            .expect("relaunched");
        assert_eq!(host.said("restart"), ["restart:model"], "{case}");
        // What the session asks after the relaunch; a successor that starts
        // before the first loop reads the bucket's answer to it.
        let (last, early) = match n {
            0 | 1 => {
                s.set_clock(now + 30, PDT);
                let _ = decided(&mut s, &redrawn, 102, None, &opts);
                s.set_clock(now + 60, PDT);
                let last = if n == 0 {
                    let _ = decided(&mut s, &to_sonnet, 103, None, &opts);
                    met("please run the integration tests", &to_sonnet)
                } else {
                    let _ = decided(
                        &mut s,
                        &ended("Here is the summary you asked for."),
                        103,
                        Some(Duration::from_secs(20)),
                        &opts,
                    );
                    met("now do it on sonnet", &to_sonnet)
                };
                let early = successor(&ledger, now + 85, &last);
                s.set_clock(now + 90, PDT);
                (last, early)
            }
            2 | 4 => {
                if n == 4 {
                    s.host_turn(HostTurn::CarryOn, 102);
                }
                let last = met("Continue from where you left off.", &redrawn);
                let early = successor(&ledger, now + 25, &last);
                s.set_clock(now + 30, PDT);
                (last, early)
            }
            _ => {
                let early = successor(&ledger, now + 25, &redrawn);
                s.set_clock(now + 30, PDT);
                (redrawn.clone(), early)
            }
        };
        let first = decided(
            &mut s,
            &last,
            104,
            n.lt(&2).then(|| Duration::from_secs(1)),
            &opts,
        );
        drop(s);
        let after = successor(&ledger, now + 120, &last);
        let third = successor(&ledger, now + 600, &last);
        let _ = std::fs::remove_dir_all(&dir);
        let ok = if n != 3 {
            [early, first, after, third].into_iter().all(waits_out)
        } else {
            // The short turn's back-off from attaching, then the
            // continuation: the redraw is no wall of the relaunched session.
            early == Some((now + 25 + 120, Some(RULE_CONTINUE)))
                && first == Some((now + 30 + 120, Some(RULE_CONTINUE)))
                && after == Some((now + 120 + 120, Some(RULE_CONTINUE)))
        };
        if !ok {
            wrong.push(format!(
                "{case}: a successor before the first loop's read {early:?}, the first loop \
                 {first:?}, a successor after {after:?}, one after that {third:?}"
            ));
        }
    }
    assert!(wrong.is_empty(), "{wrong:#?}");
}

/// A BUCKET'S NOTICE THE TRANSCRIPT WROTE AFTER THE FALLBACK'S RELAUNCH IS
/// THE WALL (the verifier of fde9e066a, A2). The books of
/// [`a_turn_asked_on_the_fallback_is_written_for_a_loop_that_follows`], the
/// host reading the agent's transcript. The relaunched process's redraw ends
/// on the bucket's notice, and so does the transcript, on that notice's own
/// row written before the relaunch (a resumed conversation is appended to,
/// its rows its own): no wall of the relaunched session's. Then, with no
/// point of the loop's between (its wait wakes on the agent's verdict, not
/// on a prompt submitted), a person's prompt is answered at once by the
/// bucket's notice — the relaunch did not take, or the model was chosen
/// back — and the transcript's notice row is written after the relaunch:
/// the wall, its reset waited out by the first loop, by a loop that starts
/// before the first loop's read (its seed names when the relaunch was made:
/// the relaunch's row), by one after it, and one after that. Measured
/// before (the verifier's probe P1a): read as the redraw, `continue@v1` was
/// typed into the standing bucket at the short turn's back-off, by the first
/// loop and every successor. So too where the host's first answer is
/// `wait:resume` (the relaunch line typed, the new process not found yet) and
/// the next ask, ninety seconds on, adopts it, the person's prompt answered
/// by the bucket sixty seconds after the line: the relaunch was made at the
/// run's first ask, as the policy is told and the relaunch's row says
/// (`made=`). Measured before (the verifier of b2c17b2dd, A-2, its probe
/// P3): made was the adoption, that notice read as the redraw, and the first
/// loop and a successor typed `continue@v1` two days before the reset.
/// NEGATIVE CONTROLS: the redraw, the transcript on the notice written before
/// the relaunch, made at once or adopted at the next ask: the short turn's
/// back-off and `continue@v1`, for the first loop and a successor.
#[test]
fn a_buckets_notice_the_transcript_wrote_after_the_relaunch_is_the_wall() {
    use crate::supervise::approvals::{Ledger, open_model_switch, open_wall};
    use crate::supervise::policy::turn_end::{RULE_CONTINUE, decide_turn_end};
    use aterm_phase::prompt::fixtures as fx;
    // Oct 17 4:20pm PDT, the bucket's reset; the relaunch two days before.
    const RESET: i64 = 1_792_279_200;
    let now = RESET - 2 * 86_400;
    let armed = fx::screen(fx::WALL_SONNET_BUCKET_AUTO_CONTINUE_ARMED_2_1_300);
    // The relaunched process's redraw (CONSTRUCTED, as in the books above).
    let redrawn: Vec<String> = armed
        .iter()
        .filter(|r| {
            ![
                "Usage limit reached",
                "Continuing automatically",
                "/rate-limit-options",
                "Claude Code will continue automatically",
                "to cancel the wait",
            ]
            .iter()
            .any(|g| r.contains(g))
        })
        .map(|r| r.replace("Sonnet 5.5 · Claude API", "Opus 5.5 · Claude API"))
        .collect();
    let notice = "You've hit your Sonnet limit · resets Oct 17 at 4:20pm (America/Los_Angeles)";
    // A person's prompt under the redraw, answered at once by the bucket.
    let met = {
        let mut rows = redrawn.clone();
        let top = rows
            .iter()
            .position(|r| r.starts_with('─'))
            .expect("the composer's frame");
        rows.splice(
            top..top,
            [
                "❯ please run the integration tests".to_string(),
                format!("  ⎿  {notice}"),
                String::new(),
                "✻ Churned for 0s · done 8:49 AM".to_string(),
                String::new(),
            ],
        );
        rows
    };
    // The transcript ending on `prompt` answered by the bucket's notice,
    // written at `at` (the measured 2.1.294 limit's rows: the prompt, the
    // notice, the turn's close; the words, the limit and the time the
    // bucket's).
    let tail = |prompt: &str, at: i64| -> String {
        let stamp = crate::harness::usage::rfc3339_utc(at);
        include_str!("fixtures/claude-2.1.294-transcript-session-limit.jsonl")
            .lines()
            .skip(1)
            .filter(|l| !l.contains("\"subtype\":\"informational\""))
            .map(|l| {
                let mut row = l
                    .replace("seventh try", prompt)
                    .replace(
                        "You've hit your session limit · resets 11:33am (America/Los_Angeles)",
                        notice,
                    )
                    .replace("\"five_hour\"", "\"seven_day_sonnet\"");
                for ms in ["921", "951", "952", "953"] {
                    row = row.replace(
                        &format!("\"2026-10-08T16:34:58.{ms}Z\""),
                        &format!("\"{stamp}\""),
                    );
                }
                row
            })
            .collect::<Vec<_>>()
            .join("\n")
            + "\n"
    };
    // The notice the relaunch left, written ten minutes before it; the one
    // that answered the person, 85 seconds after it.
    let before = tail("carry on with the task", now - 600);
    let after = tail("please run the integration tests", now + 85);
    type Decided = Option<(i64, Option<&'static str>)>;
    let decided = |s: &mut Session<'_, Mock>,
                   rows: &[String],
                   seq: u64,
                   worked: Option<Duration>,
                   opts: &SuperviseOpts|
     -> Decided {
        let point = point_at(s, rows.to_vec(), seq);
        match s
            .turn_end_at_point(&point, worked, opts)
            .expect("a decision")
        {
            TurnEndAction::WaitUntil { until, .. } => {
                let r = s.turn_end_reading(&point.screen, None, opts);
                Some((
                    s.unix_of(until),
                    decide_turn_end(&s.turn_end, &r, &opts.policy, until).rule_id(),
                ))
            }
            other => Some((s.now_unix(), other.rule_id())),
        }
    };
    let hosted = |transcript: &str, answers: &[&'static str]| {
        let host = AccountHost::scripted(&[None], answers);
        *host.tail.lock().unwrap() = Some(transcript.to_string());
        let opts = SuperviseOpts {
            idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
            policy: owners_policy(),
            ..auto(30)
        };
        (host, opts)
    };
    // The successor, seeded in `drive_loop`'s order: the relaunch's row
    // names when it was made, on the loop's clock (the test's).
    let successor =
        |ledger: &std::path::Path, at: i64, rows: &[String], transcript: &str| -> Decided {
            let (_host, opts) = hosted(transcript, &["relaunched"]);
            let mut m = Mock::new(vec![rows.to_vec()]);
            let mut s = session(&mut m, Some("@s-1".to_string()));
            s.set_clock(at, PDT);
            s.set_zone_lookup(test_zones);
            s.ledger = Ledger::open(Some(ledger), Some("@s-1"), &mut Vec::new());
            s.seed_model_switch(ledger);
            s.seed_wall_memory(open_wall(ledger, Some("@s-1")));
            decided(&mut s, rows, 101, None, &opts)
        };
    let waits_out = |d: Decided| d.is_some_and(|(until, _)| until >= RESET);
    let short_turn = |d: Decided, from: i64| d == Some((from + 120, Some(RULE_CONTINUE)));
    let mut wrong = Vec::new();
    for (n, case) in [
        "a person's prompt answered by the bucket, no point between",
        "control: the redraw",
        "the relaunch adopted at the next ask, a person's prompt answered by the bucket before it",
        "control: the relaunch adopted at the next ask, the redraw",
    ]
    .into_iter()
    .enumerate()
    {
        let answered = !case.ends_with("the redraw");
        // The host's first answer: the relaunch made at once, or its line
        // typed and the new process not found yet (`wait:resume`), adopted
        // at the next ask.
        let adopted_later = case.contains("the next ask");
        let answers: &[&'static str] = if adopted_later {
            &["wait:resume", "relaunched"]
        } else {
            &["relaunched"]
        };
        let (dir, ledger) = ledger_at(&format!("bucket-written-after-{n}"));
        let (host, opts) = hosted(&before, answers);
        let mut m = Mock::new(vec![armed.clone()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_zone_lookup(test_zones);
        s.ledger = Ledger::open(Some(&ledger), Some("@s-1"), &mut Vec::new());
        s.set_turn_end_timing(TurnEndTiming {
            take_within: Duration::ZERO,
            ..TurnEndTiming::default()
        });
        s.set_clock(now, PDT);
        let p = point_at(&s, armed.clone(), 100);
        let a = s.turn_end_at_point(&p, None, &opts).expect("the fallback");
        assert!(
            matches!(&a, TurnEndAction::Restart { why: Restart::Model { to }, .. } if to == "opus"),
            "{case}: {a:?}"
        );
        s.turn_end_execute(&p, a, &opts, &[], &mut Alone)
            .expect("relaunched");
        assert_eq!(host.said("restart"), ["restart:model"], "{case}");
        if adopted_later {
            // Ninety seconds on, the point is decided again and the next ask
            // adopts the relaunched process. Before it, the person's prompt
            // was answered at once by the bucket (the relaunch did not
            // take): its notice's row written sixty seconds after the line.
            let screen = if answered {
                *host.tail.lock().unwrap() =
                    Some(tail("please run the integration tests", now + 60));
                met.clone()
            } else {
                redrawn.clone()
            };
            s.set_clock(now + 90, PDT);
            let p = point_at(&s, screen, 101);
            let a = s
                .turn_end_at_point(&p, None, &opts)
                .expect("the fallback again");
            assert!(
                matches!(
                    &a,
                    TurnEndAction::Restart {
                        why: Restart::Model { .. },
                        ..
                    }
                ),
                "{case}: {a:?}"
            );
            s.pass_wake_settle();
            s.turn_end_execute(&p, a, &opts, &[], &mut Alone)
                .expect("adopted");
            assert_eq!(
                host.said("restart"),
                ["restart:model", "restart:model"],
                "{case}"
            );
            assert!(
                open_model_switch(&ledger, Some("@s-1")).is_some_and(|o| o.made_unix == now),
                "{case}: the relaunch made at the run's first ask"
            );
            if answered {
                // The first loop reads that screen again, and successors start
                // after it.
                s.set_clock(now + 100, PDT);
                s.pass_wake_settle();
                let first = decided(&mut s, &met, 102, None, &opts);
                drop(s);
                let after_60 = tail("please run the integration tests", now + 60);
                let later = successor(&ledger, now + 120, &met, &after_60);
                let third = successor(&ledger, now + 600, &met, &after_60);
                let _ = std::fs::remove_dir_all(&dir);
                if ![first, later, third].into_iter().all(waits_out) {
                    wrong.push(format!(
                        "{case}: the first loop {first:?}, a successor {later:?}, one after \
                         that {third:?}"
                    ));
                }
                continue;
            }
        }
        // The redraw: the transcript on the notice the relaunch left.
        let redraw_at = if adopted_later { now + 120 } else { now + 30 };
        s.set_clock(redraw_at, PDT);
        s.pass_wake_settle();
        let redraw = decided(&mut s, &redrawn, 102, None, &opts);
        if !answered {
            drop(s);
            let next = successor(&ledger, redraw_at + 30, &redrawn, &before);
            let _ = std::fs::remove_dir_all(&dir);
            // The short turn's back-off, `continue@v1` (the first loop's
            // counted from the redraw's first showing, at the second ask).
            let continues = |d: Decided| matches!(d, Some((at, Some(RULE_CONTINUE))) if at < RESET);
            let first_ok = if adopted_later {
                continues(redraw)
            } else {
                short_turn(redraw, redraw_at)
            };
            if !first_ok || !short_turn(next, redraw_at + 30) {
                wrong.push(format!(
                    "{case}: the first loop {redraw:?}, a successor {next:?}"
                ));
            }
            continue;
        }
        // The person's prompt, answered at once: its notice's row written
        // 85 seconds after the relaunch.
        *host.tail.lock().unwrap() = Some(after.clone());
        let early = successor(&ledger, now + 88, &met, &after);
        s.set_clock(now + 90, PDT);
        let first = decided(&mut s, &met, 103, Some(Duration::from_secs(1)), &opts);
        drop(s);
        let later = successor(&ledger, now + 120, &met, &after);
        let third = successor(&ledger, now + 600, &met, &after);
        let _ = std::fs::remove_dir_all(&dir);
        if !short_turn(redraw, now + 30) || ![early, first, later, third].into_iter().all(waits_out)
        {
            wrong.push(format!(
                "{case}: the redraw {redraw:?}; a successor before the first loop's read \
                 {early:?}, the first loop {first:?}, a successor after {later:?}, one after \
                 that {third:?}"
            ));
        }
    }
    assert!(wrong.is_empty(), "{wrong:#?}");
}

/// A LIMIT'S TRY AT A MODEL BUCKET IS THE TRY A SUCCESSOR BACKS OFF FROM (the
/// verifier of the successor's seed, D2; the bucket's
/// [`an_act_in_a_limits_place_is_the_try_a_successor_backs_off_from`]). The
/// lab's Sonnet bucket (2.1.300, `resets Oct 17 at 4:20pm`), no relaunch on
/// the fallback: twenty minutes past its reset, the reply under the vendor's
/// continuation scrolled the notice off, and the loop that waited on the
/// bucket types its try — the done check in the continuation's place (a
/// done report), or `usage-resume@v1` (a report of progress) — the bucket's
/// attempt. A loop that starts on its ledger a minute later finds the
/// bucket met again (its reset placed early: it stands) and works it from
/// THAT act: the ladder's first rung from it, then `usage-resume@v1`, the
/// bucket's attempt kept — as the loop that typed it would. Measured before:
/// the row seeded a usage window's track, the bucket replaced it with a
/// track of no attempt, and `usage-resume@v1` went into the standing bucket
/// at once. NEGATIVE CONTROL: a try at a usage window (the continuation's
/// row as 0.104.0 wrote it) met by the bucket is no try at it — the bucket's
/// own track, continued at once, as the loop that typed it would.
#[test]
fn a_limits_try_at_a_bucket_is_the_try_a_successor_backs_off_from() {
    use crate::supervise::approvals::{Ledger, OpenWall, Outcome, Row};
    use crate::supervise::policy::turn_end::{RULE_LIMIT_RESUME, decide_turn_end};
    use aterm_phase::WallKind;
    use aterm_phase::prompt::fixtures as fx;
    // Oct 17 4:20pm PDT, the bucket's reset; the first loop decides twenty
    // minutes past it, its successor a minute later.
    const RESET: i64 = 1_792_279_200;
    let now = RESET + 20 * 60;
    let bucket = WallKind::ModelBucket { consent: false };
    let opts = SuperviseOpts {
        policy: SupervisorConfig {
            model_fallback: None,
            ..owners_policy()
        },
        ..auto(30)
    };
    let done = "All done: the change is committed and pushed, and every suite passes.";
    let armed = fx::screen(fx::WALL_SONNET_BUCKET_AUTO_CONTINUE_ARMED_2_1_300);
    let wall = aterm_phase::read(Some("claude"), &armed, Some(2))
        .wall
        .expect("the bucket");
    // The bucket's notice row, as the lab's screen draws it.
    let notice = armed
        .iter()
        .find(|r| r.contains("You've hit your"))
        .expect("the notice row")
        .clone();
    // The vendor's continuation at the reset and the worker's `reply` under
    // it, the limit's rows scrolled off the screen (the five-hour limit's
    // measured screen, as the usage window's test builds it).
    let replied = |reply: &str| -> Vec<String> {
        let mut out = Vec::new();
        for r in fx::screen(fx::WALL_SESSION_RESUMED_BY_ITSELF_MEASURED) {
            if [
                "carry on with the task",
                "You've hit your",
                "/upgrade to",
                "Usage limit reached",
            ]
            .iter()
            .any(|g| r.contains(g))
            {
                continue;
            }
            if r.contains("(reply 3)") {
                out.push(format!("⏺ {reply}"));
                continue;
            }
            out.push(r);
        }
        out
    };
    // The bucket met again by whatever was typed: its notice once more.
    let met_again = {
        let mut r = rows(&[
            &format!("⏺ {done}"),
            "",
            &format!("❯ {DONE_CHECK}"),
            &notice,
            "",
        ]);
        r.extend(composer("  ⏵⏵ auto mode on (shift+tab to cycle)"));
        r
    };
    let typed_ts = |ledger: &Path| -> Option<i64> {
        std::fs::read_to_string(ledger)
            .unwrap_or_default()
            .lines()
            .filter_map(|l| aterm_json::from_str::<aterm_json::Value>(l).ok())
            .filter(|v| v.get("decision").and_then(aterm_json::Value::as_str) == Some("typed"))
            .filter_map(|v| v.get("ts").and_then(aterm_json::Value::as_i64))
            .next_back()
    };
    // THE SUCCESSOR on `ledger`, a minute after the act written at `act_ms`,
    // seeded as `drive_loop` seeds it, at the bucket met again: its first
    // act (a wait's length from `base`, its start), the act decided at that
    // wait's end, and the bucket's attempts.
    let successor = |ledger: &Path, act_ms: i64| {
        let mut m = Mock::new(vec![met_again.clone()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(now + 60, PDT);
        s.set_zone_lookup(test_zones);
        s.ledger = Ledger::open(Some(ledger), Some("@s-1"), &mut Vec::new());
        let base = Instant::now();
        let open = s.seed_from_ledger(ledger, act_ms + 60_000, false);
        s.seed_wall_memory(open);
        let point = point_at(&s, met_again.clone(), 101);
        let first = s
            .turn_end_at_point(&point, None, &opts)
            .unwrap_or_else(|e| panic!("{e:?}"));
        let (first, slept) = past_take_window(&mut s, first, &met_again, now + 60, &opts);
        let (after, next) = match &first {
            TurnEndAction::WaitUntil { until, .. } => {
                let r = s.turn_end_reading(&point.screen, None, &opts);
                (
                    Some(whole_secs(until.saturating_duration_since(base) + slept)),
                    decide_turn_end(&s.turn_end, &r, &opts.policy, *until).rule_id(),
                )
            }
            other => (None, other.rule_id()),
        };
        (after, next, s.turn_end.wall_attempts(bucket))
    };
    // Nothing has read the try since it was typed: the successor's first
    // read opens its take window, and the bucket met again there counts its
    // first rung from that window's end ([`past_take_window`]).
    let timing = TurnEndTiming::default();
    let rung = timing.limit_backoff.first().copied().expect("a ladder") + timing.take_within;
    let mut wrong = Vec::new();
    for (tag, reply, want) in [
        ("bucket-try-check", done, RULE_DONE_CHECK),
        (
            "bucket-try-resume",
            "Stage 2 of 5 is in; stage 3 is next.",
            RULE_LIMIT_RESUME,
        ),
    ] {
        // THE FIRST LOOP, the bucket's wait taken over from the ledger's
        // open wall, at its end.
        let (dir, ledger) = ledger_at(tag);
        let screen = replied(reply);
        let mut m = Mock::new(vec![screen.clone()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(now, PDT);
        s.set_zone_lookup(test_zones);
        s.ledger = Ledger::open(Some(&ledger), Some("@s-1"), &mut Vec::new());
        s.seed_wall_memory(Some(OpenWall {
            at_ms: (now - 3600) * 1000,
            message: wall.message.clone(),
            reset: wall.reset.clone(),
            reset_unix: Some(RESET),
            kind: Some(wall.kind),
            judged_ms: None,
            retry_ms: None,
        }));
        let point = point_at(&s, screen, 101);
        let action = s
            .turn_end_at_point(&point, None, &opts)
            .unwrap_or_else(|e| panic!("{e:?}"));
        s.turn_end_execute(&point, action.clone(), &opts, &[], &mut Alone)
            .unwrap_or_else(|e| panic!("{e:?}"));
        let first = (action.rule_id(), s.turn_end.wall_attempts(bucket));
        drop(s);
        assert_eq!(first, (Some(want), Some(1)), "{tag}: the bucket's try");
        let act_ms = typed_ts(&ledger).expect("the act's row");
        let got = successor(&ledger, act_ms);
        if got != (Some(rung), Some(RULE_LIMIT_RESUME), Some(1)) {
            wrong.push(format!("{tag}: {got:?}"));
        }
        let _ = std::fs::remove_dir_all(&dir);
    }
    assert!(wrong.is_empty(), "{wrong:#?}");
    // NEGATIVE CONTROL: the continuation typed at a usage window.
    let (dir, ledger) = ledger_at("bucket-try-window");
    let act_ms = (now - 60) * 1000;
    let row = Row {
        rule_id: RULE_LIMIT_RESUME,
        outcome: Outcome::Typed,
        command: "keep going",
        reason: "the turn-end policy",
        box_seq: 90,
    }
    .to_json(act_ms, Some("s-1"));
    std::fs::write(&ledger, format!("{row}\n")).expect("the ledger");
    assert_eq!(
        successor(&ledger, act_ms),
        (None, Some(RULE_LIMIT_RESUME), Some(0)),
        "a usage window's try is none at the bucket"
    );
    let _ = std::fs::remove_dir_all(&dir);
}

/// WHAT ANSWERED A MOVE IS WRITTEN DOWN, so the loop after this one neither
/// forgets it nor tells it twice. A loop that starts on a move the ledger
/// shows unanswered, with a turn already asked under it (a `typed` row after
/// the move), tells its host `served` at the first turn that ends with no
/// wall — and writes the answer; a loop that starts after THAT tells nothing
/// and holds no move. A lost login told by the loop before is not told
/// again. NEGATIVE CONTROL: the same lost login, not told yet, is told.
#[test]
fn a_move_seeded_from_the_ledger_is_answered_once_across_loops() {
    use crate::supervise::approvals::{
        ACCOUNT_MOVE_COMMAND, Outcome, Row, account_answer_reason, account_moves,
        account_switch_reason,
    };
    use crate::supervise::policy::turn_end::{AccountAnswer, RULE_LIMIT_RESUME};
    let now_ms = crate::supervise::journal::unix_ms();
    let row = |rule: &str, outcome: Outcome, command: &str, reason: &str, ago_s: i64| {
        Row {
            rule_id: rule,
            outcome,
            command,
            reason,
            box_seq: 90,
        }
        .to_json(now_ms - ago_s * 1_000, None)
    };
    let to = format!("{ACCOUNT_MOVE_COMMAND}work-2");
    let made = row(
        RULE_ACCOUNT,
        Outcome::Typed,
        &to,
        &account_switch_reason("work-2", AccountAt::Wall),
        120,
    );
    let resumed = row(
        RULE_LIMIT_RESUME,
        Outcome::Typed,
        "keep going",
        "the turn-end policy",
        110,
    );
    let served = || vec![busy_screen(), ended("Carried on: stage 3 is done.")];
    let run = |tag: &str, rows: &[String], screens: Vec<Vec<String>>| {
        let (dir, ledger) = ledger_at(tag);
        std::fs::write(&ledger, rows.join("\n") + "\n").expect("the ledger");
        let host = AccountHost::scripted(&[None], &["adopted"]);
        let _ = account_run(&format!("te-{tag}"), screens, &host, &ledger);
        let after = account_moves(&ledger, None);
        let text = std::fs::read_to_string(&ledger).expect("the ledger");
        let _ = std::fs::remove_dir_all(&dir);
        (host.all(), after, text)
    };
    // The move, a turn asked under it, and this loop sees that turn served.
    let (said, after, text) = run(
        "account-seeded-served",
        &[made.clone(), resumed.clone()],
        served(),
    );
    assert_eq!(said.first().map(String::as_str), Some("served"), "{said:?}");
    assert_eq!(said.iter().filter(|s| *s == "served").count(), 1);
    assert_eq!(after.open, None, "served: the move is behind the session");
    assert!(
        text.contains("\"rule_id\":\"account-rotate@v1\",\"decision\":\"waiting\"")
            && text.contains("(account move answered: to=work-2 by=served)"),
        "{text}"
    );
    // The loop after THAT: nothing to tell.
    let answered = row(
        RULE_ACCOUNT,
        Outcome::Waiting,
        &to,
        &account_answer_reason("work-2", AccountAnswer::Served),
        100,
    );
    let (said, ..) = run(
        "account-seeded-served-again",
        &[made.clone(), resumed.clone(), answered],
        served(),
    );
    assert!(!said.iter().any(|s| s == "served"), "{said:?}");
    // A lost login the loop before told: not told again by this one.
    let lost = || {
        let mut login = rows(&[
            "⏺ Carrying on.",
            "  ⎿  Not logged in · Please run /login",
            "",
        ]);
        login.extend(composer("  ? for shortcuts"));
        vec![busy_screen(), login]
    };
    let told = row(
        RULE_ACCOUNT,
        Outcome::Waiting,
        &to,
        &account_answer_reason(
            "work-2",
            AccountAnswer::Bad(crate::supervise::policy::turn_end::AccountBad::SignedOut),
        ),
        100,
    );
    let (said, after, _) = run("account-seeded-told", &[made.clone(), told], lost());
    assert!(!said.iter().any(|s| s.starts_with("answered")), "{said:?}");
    assert!(after.open.is_some_and(|open| open.told));
    // NEGATIVE CONTROL: the same lost login after a turn asked under the
    // move, not told yet, is told.
    let (said, after, _) = run(
        "account-seeded-untold",
        &[made.clone(), resumed.clone()],
        lost(),
    );
    assert_eq!(
        said.first().map(String::as_str),
        Some("answered:signed-out"),
        "{said:?}"
    );
    assert!(after.open.is_some_and(|open| open.told), "and written down");
    // …and with NO turn asked under the move, the first point this loop
    // sees is the resumed process's start-up (R6): the row it repaints is
    // the old process's, nothing is told, and the wall's resume is typed.
    let (said, after, text) = run("account-seeded-unasked", &[made], lost());
    assert!(!said.iter().any(|s| s.starts_with("answered")), "{said:?}");
    assert!(after.open.is_some_and(|open| !open.told));
    assert_eq!(
        text.matches("\"rule_id\":\"usage-resume@v1\",\"decision\":\"typed\"")
            .count(),
        1,
        "the wall's resume, once: {text}"
    );
}

/// THE OWNER LIFTED THE WALL A SESSION STANDS AT (`accounts use` on its own
/// account; the host's advice is `Resume`): the loop types that wall's own
/// continuation at the wall, at once — one guarded turn, under
/// `usage-resume@v1`, counted as the wall's attempt — and the limit met
/// again under the SAME clearing is waited out by the wall's own ladder:
/// asked, and typed nothing more. No relaunch is asked for. NEGATIVE
/// CONTROL: a host with no advice types nothing at that wall.
#[test]
fn the_owners_clearing_continues_a_session_at_its_wall_once() {
    use crate::supervise::policy::turn_end::RULE_LIMIT_RESUME;
    let run = |advice: Option<AccountAdvice>| {
        let host = AccountHost::scripted(&[advice], &["adopted"]);
        let opts = account_opts(&host);
        let mut m = Mock::new(vec![limited_screen()]);
        let attempts = {
            let (mut s, wall) = account_session(&mut m);
            let first = s
                .turn_end_at_point(&wall, Some(Duration::from_secs(180)), &opts)
                .expect("a decision");
            s.turn_end_execute(&wall, first.clone(), &opts, &[], &mut Alone)
                .expect("carried out");
            // The account answers with its limit again, three seconds on.
            let again = s
                .turn_end_at_point(&wall, Some(Duration::from_secs(3)), &opts)
                .expect("a decision");
            assert!(
                matches!(again, TurnEndAction::WaitUntil { .. }),
                "{again:?}"
            );
            s.turn_end_execute(&wall, again, &opts, &[], &mut Alone)
                .expect("carried out");
            (
                first,
                s.turn_end
                    .wall_attempts(aterm_phase::WallKind::UsageSession),
            )
        };
        let typed = m.requests.iter().filter(|r| r.contains("keep going"));
        (attempts, typed.count(), host.all())
    };
    let ((first, attempts), turns, said) = run(Some(AccountAdvice::Resume {
        cleared_at: ACCOUNT_NOW - 30,
    }));
    assert_eq!(
        first,
        TurnEndAction::Type {
            text: "keep going".to_string(),
            rule_id: RULE_LIMIT_RESUME,
        }
    );
    assert_eq!(
        (attempts, turns),
        (Some(1), 1),
        "one continuation: {said:?}"
    );
    assert_eq!(
        said,
        ["account:wall:usage-session", "account:wall:usage-session"],
        "asked at each decision, and no relaunch"
    );
    // NEGATIVE CONTROL.
    let ((first, attempts), turns, _) = run(None);
    assert!(
        matches!(first, TurnEndAction::WaitUntil { .. }),
        "{first:?}"
    );
    assert_eq!((attempts, turns), (Some(0), 0));
}

/// THE STAMP A LOOP FIRST READS IS NO NEWS. A host's stamp counts the
/// accounts' news since the HOST started; a loop that starts later (each
/// seamless update, each fault) has read none of it, and the latch the loop
/// before it left in the ledger is still this wall's: read as news, the
/// first decision of every new loop ended that latch and asked the host for
/// the relaunch it had refused for good. NEGATIVE CONTROL: the stamp moving
/// AFTER that first read is news — the latch ends and the host is asked.
#[test]
fn the_stamp_a_loop_first_reads_is_no_news_to_its_latch() {
    let host = AccountHost::moving("work-2", "refused:line");
    host.stamp.store(3, Ordering::SeqCst);
    let opts = account_opts(&host);
    let mut m = Mock::new(vec![limited_screen()]);
    let (mut s, wall) = account_session(&mut m);
    s.turn_end.seed_account_unmade();
    let action = s
        .turn_end_at_point(&wall, Some(Duration::from_secs(180)), &opts)
        .expect("a decision");
    assert!(
        matches!(action, TurnEndAction::WaitUntil { .. }),
        "{action:?}"
    );
    assert!(
        s.turn_end.account_refused(),
        "the latch the loop before left stands"
    );
    assert!(host.all().is_empty(), "{:?}", host.all());
    s.turn_end_execute(&wall, action, &opts, &[], &mut Alone)
        .expect("the wait is set");
    assert!(!s.account_edge(&opts), "nothing new since the first read");
    // NEGATIVE CONTROL: news.
    host.stamp.store(4, Ordering::SeqCst);
    assert!(s.account_edge(&opts));
    let again = s.turn_end_at_point(&wall, None, &opts).expect("a decision");
    assert!(matches!(again, TurnEndAction::Restart { .. }), "{again:?}");
    assert_eq!(host.said("account"), ["account:wall:usage-session"]);
}

/// A MOVE MADE AT A WALL THAT A LATER LOOP TAKES UP — a loop that started
/// right after the relaunch, or the one that takes the agent a host's carry
/// landed (the host writes the move's row then) — IS CARRIED ON PAST THE
/// NOTICE IT LEFT, as by the loop that made it: the limit the resumed
/// conversation repaints is the old account's, the host's last step of the
/// relaunch is taken there (it types nothing) and not withheld until that
/// account's reset, and the wall's own resume follows at once — as where the
/// host owes no step — the host asked nothing.
/// NEGATIVE CONTROLS: with no such row the limit withholds the host's step
/// and is waited out; a move made AHEAD of a wall left no notice, so a limit
/// on the screen is a wall like any other.
#[test]
fn a_loop_that_takes_up_a_move_made_at_a_wall_carries_it_on_past_the_notice() {
    use crate::supervise::approvals::{ACCOUNT_MOVE_COMMAND, Outcome, Row, account_switch_reason};
    let now_ms = crate::supervise::journal::unix_ms();
    let made = |at: AccountAt| {
        Row {
            rule_id: RULE_ACCOUNT,
            outcome: Outcome::Typed,
            command: &format!("{ACCOUNT_MOVE_COMMAND}work-2"),
            reason: &account_switch_reason("work-2", at),
            box_seq: 90,
        }
        .to_json(now_ms - 120_000, None)
    };
    let run = |tag: &str, rows: &[String], carry: bool| {
        let (dir, ledger) = ledger_at(tag);
        if !rows.is_empty() {
            std::fs::write(&ledger, rows.join("\n") + "\n").expect("the ledger");
        }
        let host = AccountHost::scripted(&[None], &["adopted"]);
        host.carry.store(carry, Ordering::SeqCst);
        let (lines, m, journal) =
            account_run(&format!("te-{tag}"), vec![limited_screen()], &host, &ledger);
        let _ = std::fs::remove_dir_all(&dir);
        let typed = m.requests.iter().filter(|r| r.contains("keep going"));
        (
            host.all(),
            typed.count(),
            format!("{lines:#?}\n{journal:#?}"),
        )
    };
    // The host's last step of the relaunch, at the notice the old account
    // left, types nothing: the wall's own resume follows.
    let (said, typed, log) = run("account-taken-up-carry", &[made(AccountAt::Wall)], true);
    assert_eq!(said, ["carry-on"], "{log}");
    assert_eq!(typed, 1, "the wall's resume, once: {log}");
    assert!(log.contains("carry-on step=done:resumed"), "{log}");
    assert!(
        log.contains(&format!(
            "rule={}",
            crate::supervise::policy::turn_end::RULE_LIMIT_RESUME
        )),
        "{log}"
    );
    // No step of the host's owed: the same resume, the host not asked.
    let (said, typed, log) = run("account-taken-up-resume", &[made(AccountAt::Wall)], false);
    assert!(said.is_empty(), "{said:?}\n{log}");
    assert_eq!(typed, 1, "{log}");
    // NEGATIVE CONTROLS.
    let (said, typed, log) = run("account-taken-up-none", &[], true);
    assert_eq!(said, ["account:wall:usage-session"], "{log}");
    assert_eq!(typed, 0, "{log}");
    let (said, typed, log) = run("account-taken-up-ahead", &[made(AccountAt::Ahead)], true);
    assert_eq!(said, ["account:wall:usage-session"], "{log}");
    assert_eq!(typed, 0, "{log}");
}

/// A HOST WHOSE EVIDENCE LAGS THE SCREEN LEARNS TO LOOK AGAIN BY BEING ASKED
/// AGAIN ([`IdleHost::account`]: the limit's row is not in the transcript
/// yet). Its answer is a wait for a moment away; the wall's wait is cut to
/// it, never nearer than a minute; nothing is latched and no relaunch is
/// asked; and the point decided when that wait runs out asks the host once
/// more — which then has its row, and advises the move. NEGATIVE CONTROL: a
/// host that advises nothing leaves the wall's own wait, to its reset.
#[test]
fn a_host_that_answers_a_short_wait_is_asked_again_when_it_runs_out() {
    let decided = |first: Option<AccountAdvice>| {
        let host = AccountHost::scripted(
            &[
                first,
                Some(AccountAdvice::Move {
                    to: "work-2".to_string(),
                }),
            ],
            &["adopted"],
        );
        let opts = account_opts(&host);
        let mut m = Mock::new(vec![limited_screen()]);
        let (mut s, wall) = account_session(&mut m);
        let asked_at = Instant::now();
        let action = s
            .turn_end_at_point(&wall, Some(Duration::from_secs(180)), &opts)
            .expect("a decision");
        let TurnEndAction::WaitUntil { until, .. } = &action else {
            panic!("{action:?}")
        };
        let waits = until.saturating_duration_since(asked_at);
        s.turn_end_execute(&wall, action, &opts, &[], &mut Alone)
            .expect("the wait is set");
        assert!(!s.turn_end.account_refused(), "a wait latches nothing");
        assert!(host.said("restart").is_empty(), "{:?}", host.all());
        // The wait runs out: the point is decided again.
        let again = s.turn_end_at_point(&wall, None, &opts).expect("a decision");
        (waits, again, host.said("account").len())
    };
    let soon = Instant::now() + Duration::from_secs(5);
    let (waits, again, asked) = decided(Some(AccountAdvice::Wait { until: soon }));
    assert!(
        (Duration::from_secs(60)..Duration::from_secs(90)).contains(&waits),
        "cut to the host's moment, never nearer than a minute: {waits:?}"
    );
    assert_eq!(asked, 2, "asked again at the next decision");
    assert!(
        matches!(&again, TurnEndAction::Restart { why: Restart::Account { to, .. }, .. } if to == "work-2"),
        "{again:?}"
    );
    // NEGATIVE CONTROL.
    let (waits, ..) = decided(None);
    assert!(waits > Duration::from_secs(3600), "{waits:?}");
}

/// ONE CONTINUATION A CLEARING, ACROSS LOOPS. Which clearing was answered is
/// the policy's memory, and a loop's restart loses it: a loop that started at
/// the same notice — the continuation not taken, or the account's answer not
/// in the transcript yet — typed that clearing's continuation a second time.
/// The ledger's last `usage-resume@v1` row answers every clearing made before
/// it — and so does the row of an act typed in its place at a limit's end
/// (the done check: [`approvals::act_reason`]'s mark), which the loop that
/// typed it counted as the clearing's answer. NEGATIVE CONTROL: a clearing
/// made AFTER that row is a new one, and is continued.
#[test]
fn a_clearing_the_loop_before_answered_is_not_answered_again() {
    use crate::supervise::approvals::{Outcome, Row, act_reason};
    use crate::supervise::policy::turn_end::{LimitTry, RULE_LIMIT_RESUME};
    let now_ms = crate::supervise::journal::unix_ms();
    let window = LimitTry {
        bucket: false,
        in_place: false,
        attempts: 1,
        entitlement: false,
    };
    let row = |rule_id: &str, command: &str, reason: &str| {
        Row {
            rule_id,
            outcome: Outcome::Typed,
            command,
            reason,
            box_seq: 90,
        }
        .to_json(now_ms - 120_000, None)
    };
    // The act's first read, the limit met again, as the loop that typed it
    // writes it (the wall's row): no act is left for this loop to await.
    let wall = aterm_phase::read(Some("claude"), &limited_screen(), Some(2))
        .wall
        .expect("the limit");
    let read = Row {
        rule_id: crate::supervise::approvals::RULE_WALL_WAIT,
        outcome: Outcome::Waiting,
        command: "",
        reason: &crate::supervise::approvals::wall_wait_reason(
            None,
            wall.reset.as_deref(),
            wall.kind,
            &wall.message,
        ),
        box_seq: 91,
    }
    .to_json(now_ms - 119_000, None);
    for (what, resumed) in [
        (
            "resumed",
            row(RULE_LIMIT_RESUME, "keep going", &act_reason(Some(window))),
        ),
        (
            "resumed-unmarked",
            row(RULE_LIMIT_RESUME, "keep going", "the turn-end policy"),
        ),
        (
            "checked",
            row(
                RULE_DONE_CHECK,
                DONE_CHECK,
                &act_reason(Some(LimitTry {
                    in_place: true,
                    ..window
                })),
            ),
        ),
    ] {
        let typed_again = |tag: &str, cleared_ago_s: i64| {
            let (dir, ledger) = ledger_at(&format!("{tag}-{what}"));
            std::fs::write(&ledger, format!("{resumed}\n{read}\n")).expect("the ledger");
            let host = AccountHost::scripted(
                &[Some(AccountAdvice::Resume {
                    cleared_at: now_ms / 1000 - cleared_ago_s,
                })],
                &["adopted"],
            );
            let (lines, m, journal) = account_run(
                &format!("te-{tag}-{what}"),
                vec![limited_screen()],
                &host,
                &ledger,
            );
            let _ = std::fs::remove_dir_all(&dir);
            assert_eq!(
                host.said("account"),
                ["account:wall:usage-session"],
                "{what}: {lines:#?}\n{journal:#?}"
            );
            m.requests
                .iter()
                .filter(|r| r.contains("keep going"))
                .count()
        };
        assert_eq!(
            typed_again("account-cleared-before", 300),
            0,
            "{what}: the loop before answered that clearing"
        );
        assert_eq!(typed_again("account-cleared-after", 60), 1, "{what}");
    }
}

// ------------------------------------------------------------------------
// The accounts probe in the loop
// (`docs/SPEC-claude-accounts-probe-2026-10-01.md` §3): `/usage` typed where
// the host claims one, the Settings panel read settled, the sample handed
// over, the panel closed — every exit of the step, over the panel's world
// (`PanelWorld`: the measured 2.1.287 screens, reacting to what is written).
// Each run is also projected onto `SupervisorUsageProbe`
// (`usage_probe_violations`): nothing it wrote is anything the model forbids.
// ------------------------------------------------------------------------

use aterm_phase::prompt::fixtures as panel_fx;

/// 2026-10-01T21:20:00-07:00, minutes after the measured screens were
/// taken: their `Resets 2am` is 4 h 40 min ahead and their `Resets Oct 8 at
/// 9am` six and a half days, both inside what a sample believes.
const PROBE_NOW: i64 = 1_790_914_800;

/// The turn whose end is probed: real work behind it, nothing asked.
const PROBE_SAID: &str = "Stage 3 done; the suite is green.";

/// The world a probe test starts from: a live turn, its end at an empty
/// composer, and — once the loop has taken its own act there — a turn that
/// ends on a request for a decision, which is escalated and ends the run.
fn probe_world(frames: &[&str], host: &ProbeHost) -> Mock {
    let mut m = probe_mock(vec![busy_screen(), ended(PROBE_SAID)], frames, host);
    world(&mut m)
        .then
        .push_back(vec![busy_screen(), ended(STOP)]);
    m
}

/// The probe's waits at a scripted server's scale: 60 ms for a panel that
/// never comes, 100 ms for one that does not leave, a read every 10 ms at
/// the latest — and HALF A MINUTE to read settled, a hang detector and no
/// latency budget (a loaded machine may take its time between two reads;
/// the one test of a panel that never settles shortens it).
fn probe_waits<C: Ctl>(s: &mut Session<'_, C>) {
    let ms = Duration::from_millis;
    s.set_probe_waits(ms(60), Duration::from_secs(30), ms(10), ms(100));
}

/// One watch over `m` under `host`, the session's ledger at `ledger`, with
/// [`probe_waits`]: the lines printed and the journal's. The run ends when
/// the script does (the session gone); its budget of a minute is a hang
/// detector ([`probe_run_for`] ends another way).
fn probe_run(
    tag: &str,
    m: &mut Mock,
    host: &Arc<ProbeHost>,
    ledger: &Path,
    policy: SupervisorConfig,
    setup: impl FnOnce(&mut Watched<'_, '_>),
) -> (Vec<String>, Vec<String>) {
    let (dir, path) = journal_file(tag);
    let opts = SuperviseOpts {
        idle_host: Some(Arc::clone(host) as Arc<dyn IdleHost>),
        journal: Some(path.clone()),
        policy,
        ..hosted(60)
    };
    let (lines, _) = watch_lines_with(m, &opts, |s| {
        s.set_clock(PROBE_NOW, PDT);
        s.set_approval_ledger(Some(ledger.to_path_buf()));
        probe_waits(s);
        setup(s);
    });
    let (records, _) = journal_records(&path);
    let _ = std::fs::remove_dir_all(&dir);
    (lines, records.into_iter().map(|r| r.line).collect())
}

/// How many requests of the loop's [`probe_run_for`] lets a world that never
/// moves on by itself see, counted instead of timed. What these runs assert
/// comes by the 20th (measured 2026-10-19: all seven tests pass at 20, within
/// 60 ms of wall time at load 17-22, and three fail at 10), so a hundred is five
/// times that, and a third of what an idle machine served in the one second
/// such a run was given before (250 to 390). Not more: a step's wall time
/// grows with the machine's load, and 300 steps took up to 55 s of the run's
/// one-minute hang detector at background QoS beside 14 spinners.
const PROBE_STEPS: usize = 100;

/// [`probe_run`] for a world that never moves on by itself — a panel that
/// stands, text left typed — whose waits count nothing toward the script's
/// end: the session goes after [`PROBE_STEPS`] more requests of the loop's
/// own, so the run shows what the loop does for as long as it runs, on any
/// machine. Never a wall-clock budget, which a loaded machine fits fewer
/// steps into (such a run of a second failed at load 30-46, its writes not
/// yet made). It must end so: its minute is a hang detector.
fn probe_run_for(
    tag: &str,
    m: &mut Mock,
    host: &Arc<ProbeHost>,
    ledger: &Path,
    policy: SupervisorConfig,
    setup: impl FnOnce(&mut Watched<'_, '_>),
) -> (Vec<String>, Vec<String>) {
    m.exit_at_request = Some(m.requests.len() + PROBE_STEPS);
    let (lines, journal) = probe_run(tag, m, host, ledger, policy, setup);
    m.exit_at_request = None;
    assert!(
        lines
            .last()
            .is_some_and(|l| l.starts_with("EXIT session gone")),
        "{tag}: the run ends on its steps, never on its minute: {lines:#?}"
    );
    (lines, journal)
}

/// The owner's policy as these tests run it ([`hosted`]'s), with the
/// person's grace as given.
fn probe_policy(human_grace_s: u32) -> SupervisorConfig {
    SupervisorConfig {
        human_grace_s,
        ..hosted(60).policy
    }
}

/// The probe's rows of the session ledger at `path`, as `decision reason`.
fn probe_rows(path: &Path) -> Vec<String> {
    std::fs::read_to_string(path)
        .unwrap_or_default()
        .lines()
        .filter(|l| l.contains("\"rule_id\":\"usage-probe@v1\""))
        .map(|l| {
            let field = |name: &str| {
                l.split(&format!("\"{name}\":\""))
                    .nth(1)
                    .and_then(|rest| rest.split('"').next())
                    .unwrap_or("")
                    .to_string()
            };
            format!(
                "{} {} {}",
                field("decision"),
                field("command"),
                field("reason")
            )
        })
        .collect()
}

/// The loop's lines about a DUE probe it did not run
/// (`SKIPPED seq=<n> rule=usage-probe@v1 gate=<word>[ host=<word>]`:
/// [`Session::probe_shut`]), as `<seq> <word>[ host=<word>]`, in order.
fn gates_said(lines: &[String]) -> Vec<String> {
    lines
        .iter()
        .filter_map(|l| l.strip_prefix("SKIPPED seq="))
        .filter_map(|rest| {
            let (seq, rest) = rest.split_once(' ')?;
            let gate = rest.strip_prefix("rule=usage-probe@v1 gate=")?;
            Some(format!("{seq} {gate}"))
        })
        .collect()
}

/// [`gates_said`] without the seq — which counts the reads of a run, and so
/// moves with its timing at every point but the first.
fn gate_words(lines: &[String]) -> Vec<String> {
    gates_said(lines)
        .iter()
        .filter_map(|g| g.split_once(' '))
        .map(|(_, word)| word.to_string())
        .collect()
}

/// Every OTHER `SKIPPED` line: a step that was begun and not carried out.
fn other_skips(lines: &[String]) -> Vec<&String> {
    lines
        .iter()
        .filter(|l| l.starts_with("SKIPPED ") && !l.contains(" gate="))
        .collect()
}

/// THE PROBE, SETTLED. At a turn end read live, where the host's advice is
/// the probe and it grants the claim, the loop writes `/usage` and its Enter
/// — each fenced on the person count, the judged read's generation and the
/// composer's caret row — reads the panel until two reads in a row say
/// SETTLED with the same windows (the first read here is the measured
/// `Refreshing…` frame: no sample from it), hands the host the sample with
/// its resets placed on the loop's clock, and only THEN presses one Escape,
/// fenced on the person count and the panel's own header row. Then the point
/// is decided again and its own act typed. In the ledger: the `typed` row
/// and the `waiting` row; in the hourly budget's reader: only the act.
///
/// A PROBE THAT RUNS SAYS NO SKIP: the point it ran at has no `gate=` line,
/// though the host — asked again where the point is decided after the probe
/// — still answers that the read is due. (The one such line of the run is
/// the LATER point's, which the policy escalates: no probe there.)
///
/// NEGATIVE CONTROL: a host that advises nothing (no roster) is never asked
/// to claim, asks the server nothing the loop did not ask before the probe
/// existed (`modes` is never sent), and its request stream is byte for byte
/// that of a loop with no host at all. (A host that declines the claim is
/// written nothing of the probe's: the gates table's `claim` row, and
/// [`the_loop_says_once_why_a_due_probe_was_not_run`] in the whole loop.)
#[test]
fn a_claimed_probe_types_usage_samples_the_settled_panel_and_closes_it() {
    let (dir, ledger) = ledger_at("probe-settled");
    let host = ProbeHost::probing(true);
    let mut m = probe_world(
        &[panel_fx::USAGE_REFRESHING, panel_fx::USAGE_SETTLED],
        &host,
    );
    let (lines, journal) = probe_run(
        "te-probe-settled",
        &mut m,
        &host,
        &ledger,
        probe_policy(120),
        |_| {},
    );
    assert_eq!(
        m.writes(),
        ["text:/usage", "enter", "esc", "text:keep going", "enter"],
        "{:#?}",
        m.requests
    );
    let wrote = |what: &str| {
        m.requests
            .iter()
            .find(|r| matches!(verb_of(r), "send" | "key") && r.ends_with(what))
            .cloned()
            .unwrap_or_default()
    };
    assert_eq!(
        wrote("-- /usage"),
        "send if-human=0 if-gen=1.102 if=^❯\\s*$ -- /usage"
    );
    assert_eq!(
        wrote("usage\\s*$ enter"),
        "key if-human=0 if-gen=1.104 if=^❯\\x20/usage\\s*$ enter"
    );
    assert_eq!(
        wrote(" esc"),
        "key if-human=0 if=^...Settings..Status...Config...Usage esc",
        "the Escape: the person fence and the panel's header row, no generation"
    );
    assert_eq!(count(&m, "turn"), 0, "never the unfenced fallback");
    assert_eq!(
        host.said(""),
        [
            "turn-ran",
            "account:turn-end",
            "probe:claimed",
            "probed:ok",
            "account:turn-end",
            "turn-ran",
            "account:turn-end",
        ],
        "no turn ran between the probe and the point decided again: {lines:#?}"
    );
    let samples = host.samples.lock().unwrap().clone();
    assert_eq!(samples.len(), 1);
    let (sample, pan, hand) = &samples[0];
    assert_eq!(
        (sample.session_pct, sample.week_pct, sample.at),
        (Some(1), Some(10), PROBE_NOW),
        "the settled frame's figures, never the refreshing one's 9 %"
    );
    assert_eq!(
        (sample.session_reset, sample.week_reset),
        (Some(PROBE_NOW + 16_800), Some(PROBE_NOW + 560_400)),
        "2am and Oct 8 at 9am, Pacific"
    );
    assert_eq!((*pan, *hand), (2, false), "handed over at a settled panel");
    let kinds: Vec<&str> = lines
        .iter()
        .filter_map(|l| l.split_whitespace().next())
        .collect();
    assert_eq!(
        kinds,
        ["EVENT", "PROBED", "CONTINUED", "EVENT", "SKIPPED", "EXIT"],
        "{lines:#?}"
    );
    assert_eq!(
        lines[1],
        "PROBED seq=102 rule=usage-probe@v1 /usage session=1% week=10%"
    );
    // The probe ran at seq 102: no skip is said of that point — not at the
    // probe, and not where it was decided again with the read still advised.
    assert_eq!(
        gate_words(&journal),
        ["escalated"],
        "the later point's, which is a person's: {journal:#?}"
    );
    assert!(
        !gates_said(&journal).iter().any(|g| g.starts_with("102 ")),
        "{journal:#?}"
    );
    assert_eq!(gates_said(&lines), gates_said(&journal), "said, so printed");
    assert_eq!(
        probe_rows(&ledger),
        ["typed /usage the accounts probe", "waiting /usage closed"]
    );
    assert_eq!(
        crate::supervise::approvals::typed_at(&ledger, None).len(),
        1,
        "the budget's reader counts the continuation alone"
    );
    assert!(!crate::supervise::approvals::probe_owed(
        &std::fs::read_to_string(&ledger).unwrap_or_default(),
        None
    ));
    assert!(
        !journal
            .iter()
            .any(|l| l.starts_with("WAITING ") || l.starts_with("HELD ")),
        "{journal:#?}"
    );
    assert!(other_skips(&journal).is_empty(), "{journal:#?}");
    assert_eq!(usage_probe_violations(&m, &host), Vec::<String>::new());
    let _ = std::fs::remove_dir_all(&dir);

    // NEGATIVE CONTROL: no roster. A host that advises nothing — and would
    // grant any claim — is never asked for one, and the server sees exactly
    // what it sees from a loop with no host.
    let run = |host: Option<&Arc<ProbeHost>>, tag: &str| {
        let (dir, ledger) = ledger_at(tag);
        let none = ProbeHost::probing(true);
        let mut m = probe_world(&[panel_fx::USAGE_SETTLED], host.unwrap_or(&none));
        let opts = SuperviseOpts {
            idle_host: host.map(|h| Arc::clone(h) as Arc<dyn IdleHost>),
            ..hosted(60)
        };
        let _ = watch_lines_with(&mut m, &opts, |s| {
            s.set_clock(PROBE_NOW, PDT);
            s.set_approval_ledger(Some(ledger.clone()));
        });
        let _ = std::fs::remove_dir_all(&dir);
        // A wait's `timeout <ms>` is what is left of the run's budget on the
        // wall clock: the one thing two runs do not share.
        m.requests
            .iter()
            .map(|r| match r.rsplit_once(" timeout ") {
                Some((head, ms)) if ms.bytes().all(|b| b.is_ascii_digit()) => head.to_string(),
                _ => r.clone(),
            })
            .collect::<Vec<String>>()
    };
    let rosterless = ProbeHost::scripted(&[None], &[true]);
    let with_host = run(Some(&rosterless), "probe-no-roster");
    assert!(rosterless.said("probe").is_empty(), "never asked to claim");
    assert_eq!(
        rosterless.said("account"),
        ["account:turn-end", "account:turn-end"]
    );
    // The probe gate's `modes` (its fullscreen check) is never asked; a
    // turn's history read asks it too, the alternate screen's archive right
    // after it (`offscreen`).
    let probe_modes = |at: usize, r: &String| {
        r == "modes"
            && with_host
                .get(at + 1)
                .is_none_or(|next| !next.starts_with("offscreen"))
    };
    assert!(
        !with_host
            .iter()
            .enumerate()
            .any(|(at, r)| probe_modes(at, r) || r.contains("/usage") || r.ends_with(" esc")),
        "{with_host:#?}"
    );
    assert_eq!(with_host, run(None, "probe-no-host"));
}

/// THE PROBE'S `/usage` GOES UNDER THE WINDOW HOST'S HAND
/// ([`Session::type_under_hand`]), as every other text the loop types: the
/// hand taken (`upgrade_drive::hand_take_here_request`) before the fenced
/// `/usage` and its Enter and given back after them, before the panel's
/// Escape — so the server's ledger books `/usage` as the harness's turn
/// (`history … by=harness`) and the panel's close is no write under it —
/// then taken again for the point's own act. NEGATIVE CONTROL: the same
/// world without the hand sends no `lease` at all
/// ([`a_claimed_probe_types_usage_samples_the_settled_panel_and_closes_it`]).
#[test]
fn the_windows_host_types_the_probes_usage_under_its_hand() {
    use crate::harness::upgrade_drive::{
        hand_give_back_here_request_as, hand_take_here_request_as,
    };
    let run = |hand: bool| {
        let (dir, ledger) = ledger_at(&format!("probe-hand-{hand}"));
        let host = ProbeHost::probing(true);
        let mut m = probe_world(
            &[panel_fx::USAGE_REFRESHING, panel_fx::USAGE_SETTLED],
            &host,
        );
        let acquired = || {
            ok(
                "OK lease acquired holder=aterm-harness@1 ttl_ms=60000 expires_in_ms=60000 \
                hard=1\n",
            )
        };
        let released = || ok("OK lease released\n");
        m.verb_replies.insert(
            "lease",
            VecDeque::from([acquired(), released(), acquired(), released()]),
        );
        let _ = probe_run(
            &format!("te-probe-hand-{hand}"),
            &mut m,
            &host,
            &ledger,
            probe_policy(120),
            |s| {
                s.set_supervisor_name(Some(HAND_HOLDER.to_string()));
                s.type_under_hand(hand);
            },
        );
        let _ = std::fs::remove_dir_all(&dir);
        let (take, back) = (
            hand_take_here_request_as(HAND_HOLDER),
            hand_give_back_here_request_as(HAND_HOLDER),
        );
        m.requests
            .iter()
            .filter_map(|r| match verb_of(r) {
                "lease" if r.ends_with(&take) => Some("take".to_string()),
                "lease" if r.ends_with(&back) => Some("back".to_string()),
                "lease" => Some(r.clone()),
                "key" => r.rsplit_once(' ').map(|(_, k)| k.to_string()),
                "send" => r.split_once(" -- ").map(|(_, t)| format!("text:{t}")),
                _ => None,
            })
            .collect::<Vec<String>>()
    };
    assert_eq!(
        run(true),
        [
            "take",
            "text:/usage",
            "enter",
            "back",
            "esc",
            "take",
            "text:keep going",
            "enter",
            "back"
        ]
    );
    assert_eq!(
        run(false),
        ["text:/usage", "enter", "esc", "text:keep going", "enter"],
        "no hand asked for"
    );
}

/// What a step of the loop SAID (printed, journaled, and in a host's log)
/// and what it only NOTED (the journal alone).
#[derive(Default)]
struct Heard {
    said: Vec<String>,
    noted: Vec<String>,
}

impl Review for Heard {
    fn approved(&mut self, _seq: u64, _command: &str) -> Result<(), String> {
        Ok(())
    }
    fn review(&mut self, _turn: &Turn) -> Result<bool, String> {
        Ok(true)
    }
    fn say(&mut self, line: &str) -> Result<(), String> {
        self.said.push(line.to_string());
        Ok(())
    }
    fn note(&mut self, line: &str) {
        self.noted.push(line.to_string());
    }
    fn unattended(&self) -> bool {
        true
    }
}

/// One thing that shuts a gate, done to the session at its point (after the
/// decision that got the roster's advice), to its host, or to the decision.
type Shut = fn(&mut Session<'_, Mock>, &Turn, &ProbeHost, &mut TurnEndAction);

/// A session at a turn end where the roster says the probe is DUE, every
/// gate open — the turn read live, a ledger, the fences, the alternate
/// screen, a host that grants the claim — but for what `shut` does; then the
/// probe's step TWICE at that point and the point decided again. Answers
/// what the first step did, everything SAID, the probe's writes and what
/// the host was asked about a claim.
fn due_probe_at_a_gate(
    tag: &str,
    shut: Option<Shut>,
) -> (
    Result<Probed, Fail>,
    Vec<String>,
    Vec<&'static str>,
    Vec<String>,
) {
    let (dir, ledger) = ledger_at(tag);
    let host = ProbeHost::probing(true);
    let mut m = probe_mock(
        vec![ended(PROBE_SAID)],
        &[panel_fx::USAGE_REFRESHING, panel_fx::USAGE_SETTLED],
        &host,
    );
    let opts = SuperviseOpts {
        idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
        policy: SupervisorConfig {
            continue_policy: false,
            ..hosted(30).policy
        },
        ..hosted(30)
    };
    let mut s = session(&mut m, None);
    s.set_clock(PROBE_NOW, PDT);
    s.set_zone_lookup(test_zones);
    s.set_approval_ledger(Some(ledger.clone()));
    s.ledger = crate::supervise::approvals::Ledger::open(Some(&ledger), None, &mut Vec::new());
    probe_waits(&mut s);
    let screen = s.screen().expect("the point");
    let point = s.turn_of(screen);
    let mut decided = s
        .turn_end_at_point(&point, Some(Duration::from_secs(182)), &opts)
        .unwrap_or_else(|e| panic!("{e:?}"));
    assert_eq!(host.said("account"), ["account:turn-end"], "advised");
    s.turn_live = true;
    if let Some(shut) = shut {
        shut(&mut s, &point, &host, &mut decided);
    }
    let mut heard = Heard::default();
    let first = s.usage_probe(&point, &decided, &opts, &mut heard);
    // ONCE A POINT: the step again, and the point decided again — the host
    // advising the probe each time — say nothing more of it.
    if first == Ok(Probed::No) {
        assert_eq!(
            s.usage_probe(&point, &decided, &opts, &mut heard),
            Ok(Probed::No),
            "{tag}"
        );
    }
    s.turn_end_now(&point, &opts, &[], &mut heard)
        .unwrap_or_else(|e| panic!("{tag}: {e:?}"));
    drop(s);
    let _ = std::fs::remove_dir_all(&dir);
    (first, heard.said, probe_writes(&m), host.said("probe"))
}

/// The Mac slept eight hours after the point was decided, and a request
/// saw it ([`Session::call`]): the wake's settle stands.
fn a_night_slept(s: &mut Session<'_, Mock>, _: &Turn, _: &ProbeHost, _: &mut TurnEndAction) {
    s.set_clock(PROBE_NOW + 8 * 3600, PDT);
    let _ = s.call(&["status"]).expect("a read at the wake");
}

/// A DUE PROBE THAT IS NOT RUN SAYS WHICH GATE SHUT. One row a gate of
/// the loop's — each the same world with ONE thing changed — and for each:
/// nothing is written, and ONE line is said,
/// `SKIPPED seq=<n> rule=usage-probe@v1 gate=<word>`, the claim's with the
/// host's own word after it. Said once a point: the step asked again and
/// the point decided again, the read still advised, add nothing
/// ([`due_probe_at_a_gate`]). The policy's own gates have their words in
/// its table (`the_probes_gate_is_true_at_a_plain_idle_point_…`); the one
/// of them only a fresh `status` can shut, a person's grace, is here too;
/// and the inline renderer (`modes` says `alt_screen=false`, or names no
/// such row) is never probed. A point decided again is
/// [`a_point_decided_again_says_not_new`]'s.
///
/// NEGATIVE CONTROL: the same world with nothing changed RUNS the probe —
/// `/usage`, the sample, the Escape — and says no skip at all, though the
/// point is then decided again with the read still advised.
#[test]
fn a_due_probe_that_is_not_run_says_which_gate_shut_once_a_point() {
    let gates: [(&str, Shut); 16] = [
        ("watching", |s, _, _, _| {
            s.claim = claim::Claim::Behind {
                holder: "another".to_string(),
                tried: Instant::now(),
            };
        }),
        ("no-ledger", |s, _, _, _| s.set_approval_ledger(None)),
        ("probes-off", |s, _, _, _| s.probe_off = true),
        ("panel-owed", |s, _, _, _| {
            s.probe = UsageProbe::Owed {
                own: true,
                since: Instant::now(),
            };
        }),
        ("not-live", |s, _, _, _| s.turn_live = false),
        ("escalated", |_, _, _, decided| {
            *decided = TurnEndAction::Escalate {
                reason: "a person's".to_string(),
            };
        }),
        ("fold-latch", |s, point, _, _| {
            s.probe_fold = Some((point.screen.cols, point.screen.pane_rows));
        }),
        ("host-wants", |_, _, host, _| {
            host.wanting.store(true, Ordering::SeqCst);
        }),
        ("stalled", |s, _, _, _| s.stall_suspect = true),
        ("wake-settle", a_night_slept),
        ("no-fence", |s, _, _, _| s.caps.gen_fence = Some(false)),
        ("not-claude", |s, _, _, _| s.ctl.program = "zsh"),
        ("person", |s, _, _, _| s.ctl.human_ms = Some(5_000)),
        ("not-fullscreen", |s, _, _, _| {
            s.ctl.alt_screen = Some(false);
        }),
        // A host whose `modes` names no such row.
        ("not-fullscreen", |s, _, _, _| s.ctl.alt_screen = None),
        ("claim host=not-due", |_, _, host, _| {
            *host.claims.lock().unwrap() = VecDeque::from([false]);
        }),
    ];
    for (word, shut) in gates {
        let tag = format!("probe-gate-{}", word.replace([' ', '='], "-"));
        let (did, said, wrote, claims) = due_probe_at_a_gate(&tag, Some(shut));
        assert_eq!(did, Ok(Probed::No), "{word}");
        assert_eq!(
            said,
            [format!("SKIPPED seq=101 rule=usage-probe@v1 gate={word}")],
            "{word}: one line, once"
        );
        assert_eq!(wrote, Vec::<&str>::new(), "{word}: nothing written");
        // The host is asked for its claim only past every gate of the
        // loop's: at each of the two steps there, and both refused — which
        // is said once.
        let asked = if word.starts_with("claim") { 2 } else { 0 };
        assert_eq!(claims, vec!["probe:declined"; asked], "{word}");
    }
    // NEGATIVE CONTROL: nothing shut. The probe runs, and no skip is said —
    // not at the step, not where the point is decided again after it.
    let (did, said, wrote, claims) = due_probe_at_a_gate("probe-gate-none", None);
    assert_eq!(did, Ok(Probed::Done));
    assert_eq!(
        said,
        ["PROBED seq=101 rule=usage-probe@v1 /usage session=1% week=10%"]
    );
    assert_eq!(wrote, ["/usage", "esc"]);
    assert_eq!(claims, ["probe:claimed", "probed:ok"]);
}

/// A DUE PROBE NOT RUN, IN THE WHOLE LOOP: the roster advises
/// the probe at a turn end whose turn the loop never read LIVE — a reply
/// that came and went inside the settle after the Enter — and nothing is
/// typed. The loop SAYS so, printed (a hosted loop's printed lines are
/// its host's log) and journaled, right after the point's own line: `SKIPPED
/// … gate=not-live`. And a host that wants the point for a step of its own
/// is `gate=host-wants` — where the point is OFFERED to it and it takes it
/// (the look returns before the probe's step is ever reached), and where a
/// guard of the loop's withholds the point from it (the probe's own gate).
/// Each ONCE, for as long as the session then sits at that point.
///
/// NEGATIVE CONTROL: the same turn end read live, under the same host, is
/// probed and says no skip ([`a_claimed_probe_types_usage_samples_the_
/// settled_panel_and_closes_it`]); and with no roster nothing is said
/// (`gates_said` is empty for a host that advises nothing).
#[test]
fn the_loop_says_once_why_a_due_probe_was_not_run() {
    let idle_policy = || SupervisorConfig {
        continue_policy: false,
        ..probe_policy(120)
    };
    let run = |tag: &str, screens: Vec<Vec<String>>, host: &Arc<ProbeHost>| {
        let (dir, ledger) = ledger_at(tag);
        let mut m = probe_mock(screens, &[panel_fx::USAGE_SETTLED], host);
        // The cursor on the composer's caret row: the idle point a host is
        // offered (off it, the point is withheld from the host).
        m.cursor_on_caret = tag.ends_with("-offered");
        let (lines, journal) = probe_run(
            &format!("te-{tag}"),
            &mut m,
            host,
            &ledger,
            idle_policy(),
            |_| {},
        );
        let _ = std::fs::remove_dir_all(&dir);
        (lines, journal, probe_writes(&m))
    };

    // Never read live: the point is the first thing this loop sees.
    let host = ProbeHost::probing(true);
    let (lines, journal, wrote) = run("probe-loop-not-live", vec![ended(PROBE_SAID)], &host);
    assert_eq!(gates_said(&lines), ["101 not-live"], "{lines:#?}");
    assert_eq!(gates_said(&journal), gates_said(&lines), "{journal:#?}");
    let at = lines
        .iter()
        .position(|l| l.starts_with("SKIPPED "))
        .expect("said");
    assert!(
        lines[at - 1].starts_with("EVENT idle seq=101 "),
        "right after the point's own line: {lines:#?}"
    );
    assert_eq!(wrote, Vec::<&str>::new());
    assert!(host.said("probe").is_empty(), "no claim asked");

    // The host wants the point: offered it and taking it, and withheld it.
    let live = vec![busy_screen(), ended(PROBE_SAID)];
    for (tag, offered) in [
        ("probe-loop-host-wants-offered", true),
        ("probe-loop-host-wants-withheld", false),
    ] {
        let host = ProbeHost::probing(true);
        host.wanting.store(true, Ordering::SeqCst);
        let (lines, journal, wrote) = run(tag, live.clone(), &host);
        assert_eq!(gates_said(&lines), ["102 host-wants"], "{tag}: {lines:#?}");
        assert_eq!(gates_said(&journal), gates_said(&lines), "{tag}");
        assert_eq!(wrote, Vec::<&str>::new(), "{tag}");
        assert!(host.said("probe").is_empty(), "{tag}");
        assert_eq!(!host.said("at-idle").is_empty(), offered, "{tag}");
    }

    // NEGATIVE CONTROL: no roster — nothing advised, nothing said.
    let host = ProbeHost::scripted(&[None], &[true]);
    let (lines, journal, wrote) = run("probe-loop-no-roster", live, &host);
    assert_eq!(gates_said(&journal), Vec::<String>::new(), "{lines:#?}");
    assert_eq!(wrote, Vec::<&str>::new());

    // ONCE A POINT, AND A POINT AFTER A TURN IS ANOTHER — though it reads the
    // very same: two turn ends on the same words, the host refusing its
    // claim at each, have a line each (and the third, a person's, its own).
    let (dir, ledger) = ledger_at("probe-loop-same-words");
    let host = ProbeHost::probing(false);
    let mut m = probe_mock(
        vec![busy_screen(), ended(PROBE_SAID)],
        &[panel_fx::USAGE_SETTLED],
        &host,
    );
    world(&mut m).then.extend([
        vec![busy_screen(), ended(PROBE_SAID)],
        vec![busy_screen(), ended(STOP)],
    ]);
    let (lines, _) = probe_run(
        "te-probe-loop-same-words",
        &mut m,
        &host,
        &ledger,
        probe_policy(120),
        |_| {},
    );
    assert_eq!(
        gate_words(&lines),
        ["claim host=not-due", "claim host=not-due", "escalated"],
        "{lines:#?}"
    );
    assert_eq!(probe_writes(&m), Vec::<&str>::new());
    let _ = std::fs::remove_dir_all(&dir);
}

/// THE POINT IS NOT NEW: a probe goes only at the look that first takes a
/// point, so one the roster first calls due where the point is decided
/// AGAIN — a wait that ran out, the accounts' news — is not run, and says
/// `gate=not-new`, once: decided a third time, nothing more. NEGATIVE
/// CONTROL: with no probe advised (the host's first answer here) the
/// decision says nothing at all.
#[test]
fn a_point_decided_again_says_not_new() {
    let (dir, ledger) = ledger_at("probe-gate-not-new");
    // No advice at the point's first decision; the probe from then on.
    let host = ProbeHost::scripted(
        &[None, Some(AccountAdvice::Probe { otherwise: None })],
        &[true],
    );
    let mut m = probe_mock(vec![ended(PROBE_SAID)], &[panel_fx::USAGE_SETTLED], &host);
    let opts = SuperviseOpts {
        idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
        policy: SupervisorConfig {
            continue_policy: false,
            ..hosted(30).policy
        },
        ..hosted(30)
    };
    let mut s = session(&mut m, None);
    s.set_clock(PROBE_NOW, PDT);
    s.set_approval_ledger(Some(ledger));
    probe_waits(&mut s);
    let screen = s.screen().expect("the point");
    let point = s.turn_of(screen);
    let mut heard = Heard::default();
    let decided = s
        .turn_end_at_point(&point, Some(Duration::from_secs(182)), &opts)
        .unwrap_or_else(|e| panic!("{e:?}"));
    s.turn_live = true;
    assert_eq!(
        s.usage_probe(&point, &decided, &opts, &mut heard),
        Ok(Probed::No)
    );
    assert_eq!(heard.said, Vec::<String>::new(), "control: nothing advised");
    for _ in 0..3 {
        s.turn_end_now(&point, &opts, &[], &mut heard)
            .unwrap_or_else(|e| panic!("{e:?}"));
    }
    assert_eq!(
        host.said("account").len(),
        4,
        "asked at every decision: {:?}",
        host.said("")
    );
    assert_eq!(heard.said.len(), 1, "{:?}", heard.said);
    assert!(
        heard.said[0].starts_with("SKIPPED seq=")
            && heard.said[0].ends_with(" rule=usage-probe@v1 gate=not-new"),
        "{:?}",
        heard.said
    );
    assert!(host.said("probe").is_empty(), "no claim asked");
    drop(s);
    assert_eq!(probe_writes(&m), Vec::<&str>::new());
    let _ = std::fs::remove_dir_all(&dir);
}

/// THE PROBE MOVES NONE OF THE POLICY'S MEMORY: the turn-end policy's state
/// after the step — the hourly budget, the short-turn streak, the point it
/// counts from, the done reports, the act awaited, everything it holds — is
/// EQUAL to its state before, though `/usage` and an Escape were written
/// and a sample handed over. NEGATIVE CONTROL: the same command booked as an
/// act of the policy's ([`TurnEndState::acted`]) moves the budget and the
/// awaited act.
#[test]
fn a_probe_books_no_act_and_moves_none_of_the_policys_memory() {
    use crate::supervise::policy::turn_end::{RULE_COMPACT, Then};
    let (dir, ledger) = ledger_at("probe-books");
    let host = ProbeHost::probing(true);
    let mut m = probe_mock(
        vec![ended(PROBE_SAID)],
        &[panel_fx::USAGE_REFRESHING, panel_fx::USAGE_SETTLED],
        &host,
    );
    let opts = SuperviseOpts {
        idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
        ..hosted(30)
    };
    let mut s = session(&mut m, None);
    s.set_clock(PROBE_NOW, PDT);
    s.set_zone_lookup(test_zones);
    s.set_approval_ledger(Some(ledger.clone()));
    s.ledger = crate::supervise::approvals::Ledger::open(Some(&ledger), None, &mut Vec::new());
    probe_waits(&mut s);
    let screen = s.screen().expect("the point");
    let point = s.turn_of(screen);
    let decided = s
        .turn_end_at_point(&point, Some(Duration::from_secs(182)), &opts)
        .unwrap_or_else(|e| panic!("{e:?}"));
    assert!(
        matches!(decided, TurnEndAction::Type { .. }),
        "the point's own act is a continuation: {decided:?}"
    );

    s.turn_live = true;
    let before = s.turn_end.clone();
    let now = Instant::now();
    let booked = before.acts_in_window(now);
    assert_eq!(
        s.usage_probe(&point, &decided, &opts, &mut Alone),
        Ok(Probed::Done)
    );
    assert_eq!(host.said("probe"), ["probe:claimed", "probed:ok"]);
    assert_eq!(
        s.turn_end, before,
        "the policy's memory, whole: nothing of it moved"
    );
    assert_eq!(s.turn_end.acts_in_window(Instant::now()), booked);
    assert!(!s.turn_end.act_in_flight());
    assert_eq!(s.probe, UsageProbe::Idle);
    assert!(!s.turn_live || s.probe_fold.is_none() && !s.probe_off);

    // NEGATIVE CONTROL: booked as an act, the same command moves the books.
    let reading = s.turn_end_reading(&point.screen, None, &opts);
    let mut acted = before.clone();
    acted.acted(
        &TurnEndAction::TypeCommand {
            command: "/usage".to_string(),
            rule_id: RULE_COMPACT,
            then: Then::Nothing,
        },
        &reading,
        now,
    );
    assert_ne!(acted, before);
    assert_eq!(acted.acts_in_window(now), booked + 1);
    assert!(acted.act_in_flight());
    drop(s);
    assert_eq!(probe_writes(&m), ["/usage", "esc"]);
    let _ = std::fs::remove_dir_all(&dir);
}

/// NOT OPENED: `/usage` and its Enter were written and no panel came within
/// the bound. NO ESCAPE is pressed — nothing says a panel is there to take
/// one — the host is told `not-opened`, the composer's return settles what
/// was owed, and the point's own act goes on. A TURN THAT STARTS INSTEAD (a
/// spinner after the Enter) is the same, at once, with no Escape either —
/// and the point having changed across the probe, this loop probes no more.
#[test]
fn a_panel_that_never_opens_gets_no_escape() {
    let (dir, ledger) = ledger_at("probe-not-opened");
    let host = ProbeHost::probing(true);
    let mut m = probe_world(&[panel_fx::USAGE_SETTLED], &host);
    world(&mut m).opens = false;
    let (lines, journal) = probe_run(
        "te-probe-not-opened",
        &mut m,
        &host,
        &ledger,
        probe_policy(120),
        |_| {},
    );
    assert_eq!(
        m.writes(),
        ["text:/usage", "enter", "text:keep going", "enter"],
        "{lines:#?}"
    );
    assert_eq!(probe_writes(&m), ["/usage"], "no Escape");
    assert_eq!(host.said("probe"), ["probe:claimed", "probed:not-opened"]);
    assert!(host.samples.lock().unwrap().is_empty());
    assert!(
        journal
            .iter()
            .any(|l| l == "PROBED seq=102 rule=usage-probe@v1 /usage no sample (not-opened)"),
        "{journal:#?}"
    );
    assert_eq!(
        probe_rows(&ledger),
        ["typed /usage the accounts probe", "waiting /usage closed"]
    );
    assert_eq!(usage_probe_violations(&m, &host), Vec::<String>::new());
    let _ = std::fs::remove_dir_all(&dir);

    // A turn starts instead.
    let (dir, ledger) = ledger_at("probe-turn-instead");
    let host = ProbeHost::probing(true);
    let mut m = probe_world(&[panel_fx::USAGE_SETTLED], &host);
    world(&mut m).turn_instead = Some(vec![busy_screen(), busy_screen(), ended(STOP)]);
    let (lines, journal) = probe_run(
        "te-probe-turn-instead",
        &mut m,
        &host,
        &ledger,
        probe_policy(120),
        |_| {},
    );
    assert_eq!(m.writes(), ["text:/usage", "enter"], "{lines:#?}");
    assert_eq!(host.said("probe"), ["probe:claimed", "probed:not-opened"]);
    assert!(
        journal
            .iter()
            .any(|l| l.contains("the point changed across the probe")),
        "{journal:#?}"
    );
    assert_eq!(usage_probe_violations(&m, &host), Vec::<String>::new());
    let _ = std::fs::remove_dir_all(&dir);
}

/// UNSETTLED: a panel that says `Refreshing…` for the whole bound is never
/// sampled — the host is told `unsettled` — and gets its one Escape.
#[test]
fn a_panel_that_never_settles_is_closed_with_no_sample() {
    let (dir, ledger) = ledger_at("probe-unsettled");
    let host = ProbeHost::probing(true);
    let mut m = probe_world(&[panel_fx::USAGE_REFRESHING], &host);
    let (lines, journal) = probe_run(
        "te-probe-unsettled",
        &mut m,
        &host,
        &ledger,
        probe_policy(120),
        |s| {
            let ms = Duration::from_millis;
            s.set_probe_waits(ms(60), ms(200), ms(10), ms(100));
        },
    );
    assert_eq!(
        m.writes(),
        ["text:/usage", "enter", "esc", "text:keep going", "enter"],
        "{lines:#?}"
    );
    assert_eq!(host.said("probe"), ["probe:claimed", "probed:unsettled"]);
    assert!(host.samples.lock().unwrap().is_empty());
    assert!(
        journal
            .iter()
            .any(|l| l.ends_with("/usage no sample (unsettled)")),
        "{journal:#?}"
    );
    assert!(!lines.iter().any(|l| l.starts_with("PROBED")), "{lines:#?}");
    assert_eq!(usage_probe_violations(&m, &host), Vec::<String>::new());
    let _ = std::fs::remove_dir_all(&dir);
}

/// One watch over two turn ends — the second on a screen `taller` rows
/// taller than the first — under a host that grants every claim, the panel
/// showing `frames`: what the probe wrote, and what the host was told.
fn two_turn_ends(tag: &str, frames: &[&str], taller: usize) -> (Vec<&'static str>, Vec<String>) {
    let (dir, ledger) = ledger_at(tag);
    let host = ProbeHost::probing(true);
    let mut m = probe_mock(vec![busy_screen(), ended(PROBE_SAID)], frames, &host);
    let mut second = vec![String::new(); taller];
    second.extend(ended("Stage 4 done; the suite is green."));
    world(&mut m).then.extend([
        vec![busy_screen(), second],
        vec![busy_screen(), ended(STOP)],
    ]);
    let (lines, _) = probe_run(
        &format!("te-{tag}"),
        &mut m,
        &host,
        &ledger,
        probe_policy(120),
        |_| {},
    );
    assert_eq!(
        usage_probe_violations(&m, &host),
        Vec::<String>::new(),
        "{lines:#?}"
    );
    let _ = std::fs::remove_dir_all(&dir);
    (probe_writes(&m), host.said("probe"))
}

/// THE FOLD. A grid on which the panel's tail is under the fold from the
/// first read (measured: 110x32, the last row the vendor's `↓` alone) is no
/// sample — the host is told `fold` — the panel gets its one Escape, and
/// THAT GRID SIZE IS NOT PROBED AGAIN by this loop: at the next turn end no
/// claim is asked and nothing is typed. NEGATIVE CONTROL: after a resize (a
/// taller pane) the gate admits one.
///
/// A RACE LOST IS NOT A SIZE: where a read of the probe DID show the panel's
/// tail region before it folded (measured at 150x50: the refresh line for a
/// quarter second, the whole settled tab for about a second, then the
/// contributing block fills in and the tail is gone), the host is told
/// `fold` and the size is tried again at the next turn end.
#[test]
fn a_folded_panel_is_no_sample_and_its_grid_size_is_not_probed_again() {
    let (wrote, told) = two_turn_ends("probe-fold", &[panel_fx::USAGE_SHORT], 0);
    assert_eq!(wrote, ["/usage", "esc"], "one probe, one Escape");
    assert_eq!(
        told,
        ["probe:claimed", "probed:fold"],
        "the second turn end asks for no claim"
    );

    // NEGATIVE CONTROL: a resize.
    let (wrote, told) = two_turn_ends("probe-fold-resized", &[panel_fx::USAGE_SHORT], 3);
    assert_eq!(wrote, ["/usage", "esc", "/usage", "esc"]);
    assert_eq!(
        told,
        [
            "probe:claimed",
            "probed:fold",
            "probe:claimed",
            "probed:fold"
        ]
    );

    // The race lost: unsettled, settled ONCE, then folded for good.
    let lost = [
        panel_fx::USAGE_REFRESHING,
        panel_fx::USAGE_SETTLED,
        panel_fx::USAGE_FOLD,
    ];
    let (wrote, told) = two_turn_ends("probe-fold-race", &lost, 0);
    assert_eq!(wrote, ["/usage", "esc", "/usage", "esc"]);
    assert_eq!(
        told,
        [
            "probe:claimed",
            "probed:fold",
            "probe:claimed",
            "probed:fold"
        ],
        "no sample from one settled read, and no latch on the size"
    );
}

/// A PERSON whose key lands between the judged read and the write skips it
/// under the person fence (`OK skipped reason=person`): the host is told
/// `person`, nothing is in the composer and no Enter follows. (One who typed
/// within the grace of the point shuts the gate: the gates table's `person`;
/// one who keys while the panel is read ends the sample and the Escape waits
/// out their grace: `tier1_the_probes_writes_go_only_where_the_model_allows`.)
#[test]
fn a_person_at_the_session_is_never_typed_under() {
    // A key between the read and the write.
    let (dir, ledger) = ledger_at("probe-person-at-send");
    let host = ProbeHost::probing(true);
    let mut m = probe_world(&[panel_fx::USAGE_SETTLED], &host);
    m.person_at_send = 1;
    let (lines, journal) = probe_run(
        "te-probe-person-at-send",
        &mut m,
        &host,
        &ledger,
        probe_policy(120),
        |_| {},
    );
    assert_eq!(m.writes(), ["text:/usage"], "asked once: {lines:#?}");
    assert_eq!(m.person_skipped.len(), 1, "and skipped for the person");
    assert_eq!(world(&mut m).at, PanelAt::Rest, "nothing in the composer");
    assert_eq!(host.said("probe"), ["probe:claimed", "probed:person"]);
    assert!(
        journal
            .iter()
            .any(|l| l.starts_with("SKIPPED seq=102 rule=usage-probe@v1 ")),
        "{journal:#?}"
    );
    assert!(
        probe_rows(&ledger).is_empty(),
        "nothing written, nothing owed"
    );
    let _ = std::fs::remove_dir_all(&dir);
}

/// REFUSALS. An Escape the server turns away — `ERR halted`, then `ERR
/// busy` — is parked on or backed off from, spends no try, and is SENT
/// AGAIN: three Escapes asked, the third written. Through all of it no
/// second `/usage` is typed while the panel is owed, and the sample, handed
/// over before the first Escape, is not lost to the close. What follows the
/// close (the point decided again once its window has run, its act typed) is
/// not this test's: how far the loop gets into it before the script's waits
/// are out is a matter of the machine's load, so the panel is held to being
/// closed, not to which act came after.
#[test]
fn a_refused_escape_is_sent_again_and_never_a_second_usage() {
    let (dir, ledger) = ledger_at("probe-refused");
    let host = ProbeHost::probing(true);
    let mut m = probe_world(
        &[panel_fx::USAGE_REFRESHING, panel_fx::USAGE_SETTLED],
        &host,
    );
    world(&mut m).esc_replies = [err("halted by the owner"), err("busy turn=1")].into();
    let (lines, journal) = probe_run(
        "te-probe-refused",
        &mut m,
        &host,
        &ledger,
        probe_policy(120),
        |_| {},
    );
    assert_eq!(
        probe_writes(&m),
        ["/usage", "esc", "esc", "esc"],
        "{lines:#?}"
    );
    assert_eq!(host.said("probe"), ["probe:claimed", "probed:ok"]);
    assert_ne!(world(&mut m).at, PanelAt::Open, "closed by the third");
    assert!(
        journal.iter().any(|l| l.starts_with("HALTED "))
            && journal.iter().any(|l| l.starts_with("REFUSED ")),
        "{journal:#?}"
    );
    assert!(
        !journal
            .iter()
            .any(|l| l.starts_with("WAITING ") && l.contains("panel is open")),
        "a refusal spends no try: {journal:#?}"
    );
    assert_eq!(
        probe_rows(&ledger),
        ["typed /usage the accounts probe", "waiting /usage closed"]
    );
    assert_eq!(usage_probe_violations(&m, &host), Vec::<String>::new());
    let _ = std::fs::remove_dir_all(&dir);
}

/// A world that STARTS with the panel on the screen — `frame` — over the
/// composer screen it returns to: what a loop meets that starts after the
/// one that typed `/usage` died.
fn panel_standing(frame: &str, host: &ProbeHost) -> Mock {
    let mut m = probe_mock(vec![panel_fx::screen(frame)], &[frame], host);
    let w = world(&mut m);
    w.at = PanelAt::Open;
    w.rest = Some(ended(PROBE_SAID));
    m
}

/// The session ledger of a loop that wrote `/usage` and never saw the panel
/// gone.
fn owed_ledger(path: &Path) {
    let row = crate::supervise::approvals::Row {
        rule_id: "usage-probe@v1",
        outcome: crate::supervise::approvals::Outcome::Typed,
        command: "/usage",
        reason: crate::supervise::approvals::PROBE_TYPED_REASON,
        box_seq: 7,
    };
    std::fs::write(path, format!("{}\n", row.to_json(1_000, None))).expect("the ledger");
}

/// THE LOOP DIED MID-PROBE. Its successor finds the ledger's `typed` row
/// with no `waiting` row after it and a Settings panel on the screen: it
/// lets the panel stand ONE PERSON'S GRACE in its own sight (a second here)
/// before its one guarded Escape. (That it samples nothing and writes the
/// `waiting` row: `tier1_the_probes_writes_go_only_where_the_model_allows`
/// and [`a_loop_stopped_mid_probe_presses_nothing_and_the_next_loop_closes_the_panel`].)
///
/// NEGATIVE CONTROLS. With no such row — a person's own `/usage`, on every
/// machine that never ran a probe — the same panel gets NO KEY AT ALL, for
/// as long as the loop runs. And with the row but NO HEADER ROW ON THE GRID
/// (the measured inline panel once it scrolled: the cancel hint in sight,
/// its rule and header gone) nothing is pressed either: an Escape is only
/// ever written under the panel's own header.
#[test]
fn a_successor_closes_only_a_panel_the_ledger_says_the_harness_opened() {
    let (dir, ledger) = ledger_at("probe-successor");
    owed_ledger(&ledger);
    let host = ProbeHost::probing(true);
    let mut m = panel_standing(panel_fx::USAGE_SETTLED, &host);
    let started = Instant::now();
    let (lines, _) = probe_run(
        "te-probe-successor",
        &mut m,
        &host,
        &ledger,
        probe_policy(1),
        |_| {},
    );
    assert_eq!(probe_writes(&m), ["esc"], "{lines:#?}");
    let esc = &world(&mut m).probes[0];
    assert!(
        esc.at.duration_since(started) >= Duration::from_secs(1),
        "one grace in the successor's own sight: {:?}",
        esc.at.duration_since(started)
    );
    assert_eq!(
        esc.request,
        "key if-human=0 if=^...Settings..Status...Config...Usage esc"
    );
    let _ = std::fs::remove_dir_all(&dir);

    // NEGATIVE CONTROL: no row. The panel is a person's.
    let (dir, ledger) = ledger_at("probe-not-ours");
    let host = ProbeHost::probing(true);
    let mut m = panel_standing(panel_fx::USAGE_SETTLED, &host);
    let (lines, _) = probe_run_for(
        "te-probe-not-ours",
        &mut m,
        &host,
        &ledger,
        probe_policy(0),
        |_| {},
    );
    assert_eq!(m.writes(), Vec::<String>::new(), "{lines:#?}");
    assert_eq!(world(&mut m).at, PanelAt::Open, "it stands as it stood");
    assert!(probe_rows(&ledger).is_empty());
    let _ = std::fs::remove_dir_all(&dir);

    // NEGATIVE CONTROL: the row, and no header row on the grid.
    let (dir, ledger) = ledger_at("probe-no-header");
    owed_ledger(&ledger);
    let host = ProbeHost::probing(true);
    let mut m = panel_standing(panel_fx::USAGE_INLINE_SCROLLED, &host);
    let (lines, _) = probe_run_for(
        "te-probe-no-header",
        &mut m,
        &host,
        &ledger,
        probe_policy(0),
        |_| {},
    );
    assert_eq!(m.writes(), Vec::<String>::new(), "{lines:#?}");
    assert_eq!(world(&mut m).at, PanelAt::Open);
    let _ = std::fs::remove_dir_all(&dir);
}

/// A LOOP THAT ONLY WATCHES WAITS ON THE PANEL. The ledger says a panel is
/// owed and one stands, but another supervisor holds the session's claim
/// (`ERR busy supervisor=gui%3A1`): the panel is the holder's to close, and
/// this loop asks for no Escape — none is sent, and no `REFUSED` is
/// journaled for one its own claim would refuse. It waits on the panel's
/// header row, and once the panel is gone and the composer back it writes
/// the `waiting` row: the panel is owed no more.
///
/// NEGATIVE CONTROL: the same world with the claim free gets its one
/// guarded Escape.
#[test]
fn a_loop_watching_behind_another_claim_asks_no_escape_of_an_owed_panel() {
    let run = |tag: &str, behind: bool| {
        let (dir, ledger) = ledger_at(tag);
        owed_ledger(&ledger);
        let host = ProbeHost::probing(true);
        let mut m = panel_standing(panel_fx::USAGE_SETTLED, &host);
        if behind {
            m.claim_replies = VecDeque::from([err("busy supervisor=gui%3A1")]);
            // The holder closes it: it leaves by itself after a few reads.
            world(&mut m).leaves_after = Some(3);
        }
        let (lines, journal) = probe_run(tag, &mut m, &host, &ledger, probe_policy(0), |s| {
            s.set_claim_timing(Duration::from_secs(3600), 90_000)
        });
        let rows = probe_rows(&ledger);
        let _ = std::fs::remove_dir_all(&dir);
        (m, lines, journal, rows)
    };
    let refused = |journal: &[String]| {
        journal
            .iter()
            .filter(|l| l.starts_with("REFUSED "))
            .cloned()
            .collect::<Vec<_>>()
    };

    let (mut m, lines, journal, rows) = run("probe-watching", true);
    assert!(
        lines[0].starts_with("WATCHING ") && lines[0].contains("gui:1"),
        "{lines:#?}"
    );
    assert_eq!(probe_writes(&m), Vec::<&str>::new(), "{lines:#?}");
    assert!(
        !m.requests.iter().any(|r| r.ends_with(" esc")),
        "{:#?}",
        m.requests
    );
    assert_eq!(refused(&journal), Vec::<String>::new());
    assert_eq!(world(&mut m).at, PanelAt::Rest, "the holder closed it");
    assert_eq!(
        rows,
        ["typed /usage the accounts probe", "waiting /usage closed"]
    );

    // NEGATIVE CONTROL: the claim free.
    let (m, lines, journal, rows) = run("probe-watching-free", false);
    assert_eq!(probe_writes(&m), ["esc"], "{lines:#?}");
    assert_eq!(refused(&journal), Vec::<String>::new());
    assert_eq!(
        rows,
        ["typed /usage the accounts probe", "waiting /usage closed"]
    );
}

/// AN OUTAGE MID-PROBE: the answer to a read of the open panel never comes.
/// The step ends there — the host is told `lost`, nothing sampled — the
/// outage is ridden out, and THE SAME LOOP, which remembers the panel it
/// owes, closes it at its next look with one guarded Escape.
#[test]
fn an_outage_in_the_read_leaves_the_panel_owed_and_the_same_loop_closes_it() {
    let (dir, ledger) = ledger_at("probe-outage");
    let host = ProbeHost::probing(true);
    let mut m = probe_world(
        &[panel_fx::USAGE_REFRESHING, panel_fx::USAGE_SETTLED],
        &host,
    );
    world(&mut m).lose_read = Some(2);
    let (lines, _) = probe_run(
        "te-probe-outage",
        &mut m,
        &host,
        &ledger,
        probe_policy(120),
        |s| s.setup.pause = Duration::from_millis(5),
    );
    assert_eq!(host.said("probe"), ["probe:claimed", "probed:lost"]);
    assert!(host.samples.lock().unwrap().is_empty());
    assert_eq!(probe_writes(&m), ["/usage", "esc"], "{lines:#?}");
    assert!(
        lines.iter().any(|l| l.starts_with("RECONNECT ")),
        "{lines:#?}"
    );
    assert_eq!(world(&mut m).at, PanelAt::Over, "closed, and the act typed");
    assert_eq!(
        probe_rows(&ledger),
        ["typed /usage the accounts probe", "waiting /usage closed"]
    );
    assert_eq!(usage_probe_violations(&m, &host), Vec::<String>::new());
    let _ = std::fs::remove_dir_all(&dir);
}

/// THE PANEL'S REPAINT IS NOT WORK. A panel the harness owes its close
/// repaints for ever (no read ever finds the screen still): the loop does
/// not read it as output being written — the worker working — so the host
/// hears of no turn that ran, nothing is printed for it, and the panel is
/// closed. NEGATIVE CONTROL: the same repainting screen with NO panel owed
/// (a person's own) reads as it always did — busy, until it leaves — and
/// the host is told a turn ran.
#[test]
fn an_owed_panels_repaint_is_never_the_worker_working() {
    let grace = || probe_policy(0);
    let (dir, ledger) = ledger_at("probe-repaint");
    owed_ledger(&ledger);
    let host = ProbeHost::probing(true);
    let mut m = panel_standing(panel_fx::USAGE_SETTLED, &host);
    world(&mut m).repaints = true;
    let (lines, _) = probe_run("te-probe-repaint", &mut m, &host, &ledger, grace(), |_| {});
    assert_eq!(probe_writes(&m), ["esc"], "{lines:#?}");
    assert_eq!(host.said("turn-ran"), Vec::<String>::new(), "{lines:#?}");
    let _ = std::fs::remove_dir_all(&dir);

    // NEGATIVE CONTROL: not owed. It leaves by itself after eight reads.
    let (dir, ledger) = ledger_at("probe-repaint-not-ours");
    let host = ProbeHost::probing(true);
    let mut m = panel_standing(panel_fx::USAGE_SETTLED, &host);
    world(&mut m).repaints = true;
    world(&mut m).leaves_after = Some(8);
    let (lines, _) = probe_run(
        "te-probe-repaint-not-ours",
        &mut m,
        &host,
        &ledger,
        grace(),
        |_| {},
    );
    assert_eq!(probe_writes(&m), Vec::<&str>::new(), "{lines:#?}");
    assert_eq!(host.said("turn-ran"), ["turn-ran"], "{lines:#?}");
    let _ = std::fs::remove_dir_all(&dir);
}

/// PROBE, THEN MOVE. The roster says the read is due with nothing behind it
/// (`Probe { otherwise: None }`); the probe is made; the point is decided
/// again, the host asked afresh — and now, the sample in, it advises the
/// move: the relaunch under the other account is asked AT THE SAME POINT,
/// ahead of any wall, and the loop types no continuation of its own.
#[test]
fn a_sample_that_shows_the_account_low_moves_the_session_at_the_same_point() {
    let (dir, ledger) = ledger_at("probe-then-move");
    let host = ProbeHost::scripted(
        &[
            Some(AccountAdvice::Probe { otherwise: None }),
            Some(AccountAdvice::Move {
                to: "work-2".to_string(),
            }),
        ],
        &[true],
    );
    *host.answer.lock().unwrap() = Some("adopted");
    let mut m = probe_world(
        &[panel_fx::USAGE_REFRESHING, panel_fx::USAGE_SETTLED],
        &host,
    );
    let (lines, _) = probe_run(
        "te-probe-then-move",
        &mut m,
        &host,
        &ledger,
        probe_policy(120),
        |_| {},
    );
    assert_eq!(
        host.said(""),
        [
            "turn-ran",
            "account:turn-end",
            "probe:claimed",
            "probed:ok",
            "account:turn-end",
            "restart:account-ahead:work-2",
        ],
        "{lines:#?}"
    );
    assert_eq!(m.writes(), ["text:/usage", "enter", "esc"], "{lines:#?}");
    assert!(
        lines
            .iter()
            .any(|l| l.starts_with("RESTARTED seq=") && l.contains("relaunch under account work-2")),
        "{lines:#?}"
    );
    let _ = std::fs::remove_dir_all(&dir);
}

/// THE PANEL HALF ERASED, as one read caught it right after the Escape.
/// MEASURED on 2.1.287, 2026-10-01 (150x80; the read taken as soon as the
/// header row had left, a few tens of milliseconds after the key, in one
/// close of the live check's eight): the transcript redrawn at the top, the
/// panel's rule, header and upper rows GONE, its lower rows down to the
/// cancel hint still on the grid, and the composer NOT DRAWN YET. COMPOSED
/// here on that shape — the capture's own banner names the login — from the
/// measured settled screen: the turn's rows, then that screen's rows from
/// its last window's reset down.
fn panel_torn() -> Vec<String> {
    let settled = panel_fx::screen(panel_fx::USAGE_SETTLED);
    let from = settled
        .iter()
        .rposition(|row| row.trim_start().starts_with("Resets "))
        .expect("a window's reset row");
    let mut torn = ended(PROBE_SAID);
    let frame = torn
        .iter()
        .position(|row| row.starts_with('─'))
        .expect("the composer's frame");
    torn.truncate(frame);
    torn.extend(settled[from..].iter().cloned());
    torn
}

/// A HALF-ERASED PANEL IS NO PANEL AND NO NEW POINT. The read that follows
/// the Escape can catch the panel mid-erase ([`panel_torn`], measured): no
/// header row, no composer. The loop takes it for neither a panel that did
/// not take its Escape — NO SECOND ESCAPE, no failed try — nor a point that
/// changed across the probe: the panel stays owed for one more look, the
/// composer's return closes it (the ledger's `waiting` row), and the point's
/// own act is decided again and typed. The sample, handed over before the
/// Escape, is the settled panel's.
///
/// NEGATIVE CONTROL: the same world where the Escape does NOT take — the
/// panel, header and all, still on the grid at the read after it — is a
/// failed try: `WAITING … (1 tries)`, and a second Escape.
#[test]
fn a_half_erased_panel_after_the_escape_gets_no_second_escape() {
    let torn = panel_torn();
    assert_eq!(aterm_phase::settings_panel(&torn), None);
    assert!(!has_composer_frame(&torn));
    assert!(torn.iter().any(|row| aterm_phase::panel_tail(row)));
    let run = |tag: &str, edit: &dyn Fn(&mut PanelWorld)| {
        let (dir, ledger) = ledger_at(tag);
        let host = ProbeHost::probing(true);
        let mut m = probe_world(
            &[panel_fx::USAGE_REFRESHING, panel_fx::USAGE_SETTLED],
            &host,
        );
        edit(world(&mut m));
        // The re-decision comes a tenth of a second after the close (the
        // tests' `Timings::FAST`), in waits a scripted server answers 5 ms
        // apart: 200 of them, a second at least, are let pass.
        m.vanish_after = Some(200);
        let (lines, journal) = probe_run(tag, &mut m, &host, &ledger, probe_policy(120), |s| {
            s.set_survey_retry([Duration::from_millis(20); SURVEY_TRIES]);
        });
        let rows = probe_rows(&ledger);
        let bad = usage_probe_violations(&m, &host);
        let _ = std::fs::remove_dir_all(&dir);
        (m, host, lines, journal, rows, bad)
    };
    let stuck = |journal: &[String]| {
        journal
            .iter()
            .filter(|l| l.starts_with("WAITING ") && l.contains("the /usage panel is open"))
            .count()
    };

    let (mut m, host, lines, journal, rows, bad) =
        run("te-probe-torn", &|w| w.torn = Some(panel_torn()));
    assert_eq!(
        m.writes(),
        ["text:/usage", "enter", "esc", "text:keep going", "enter"],
        "{lines:#?}"
    );
    assert!(
        world(&mut m).torn.is_none() && world(&mut m).mends.is_none(),
        "the half-erased frame was served to a read, and the composer after it"
    );
    assert_eq!(host.said("probe"), ["probe:claimed", "probed:ok"]);
    assert_eq!(
        host.samples
            .lock()
            .unwrap()
            .iter()
            .map(|(sample, pan, _)| (sample.session_pct, sample.week_pct, *pan))
            .collect::<Vec<_>>(),
        [(Some(1), Some(10), 2)]
    );
    assert_eq!(stuck(&journal), 0, "{journal:#?}");
    assert!(other_skips(&journal).is_empty(), "{journal:#?}");
    assert_eq!(
        gate_words(&journal),
        ["escalated"],
        "the later point's alone: {journal:#?}"
    );
    assert_eq!(
        rows,
        ["typed /usage the accounts probe", "waiting /usage closed"]
    );
    assert_eq!(bad, Vec::<String>::new());

    // NEGATIVE CONTROL: the Escape does not take, and the panel stands.
    let (m, _, lines, journal, _, bad) = run("te-probe-torn-control", &|w| w.esc_fails = 1);
    assert_eq!(probe_writes(&m), ["/usage", "esc", "esc"], "{lines:#?}");
    assert_eq!(stuck(&journal), 1, "{journal:#?}");
    assert!(
        journal
            .iter()
            .any(|l| l.starts_with("WAITING ") && l.contains("(1 tries)")),
        "{journal:#?}"
    );
    assert_eq!(bad, Vec::<String>::new());
}

/// A PANEL THAT CLOSES UNDER THE READ IS NO NEW POINT. The panel reads
/// settled once; then it closes with no Escape of the loop's (a key the loop
/// did not write, the vendor's own repaint), and the next two reads catch it
/// half erased ([`panel_torn`]) — the step's own, which ends it with nothing
/// sampled (`closed`), and the one that decides the point again after it —
/// before the composer is drawn. A screen with no composer while the panel
/// is owed is a close not yet painted: NO `point changed across the probe`,
/// the composer's return closes what was owed (the `waiting` row), the
/// point's own act is typed once, and THE LOOP'S PROBES GO ON — the next
/// point's line names the gate that shut there (`escalated`), not
/// `probes-off`. Where the key that closed it was a PERSON'S, the act waits
/// out their grace like any act.
///
/// NEGATIVE CONTROL: the same close onto ANOTHER point, its composer drawn
/// (rows left in the transcript), still ends the loop's probes: the `point
/// changed` line, and `probes-off` at every point after it.
#[test]
fn a_panel_closed_under_the_read_is_no_new_point_and_the_probes_go_on() {
    let run = |tag: &str, edit: &dyn Fn(&mut Mock)| {
        let (dir, ledger) = ledger_at(tag);
        let host = ProbeHost::probing(true);
        let mut m = probe_world(&[panel_fx::USAGE_SETTLED], &host);
        edit(&mut m);
        let (lines, journal) = probe_run(tag, &mut m, &host, &ledger, probe_policy(120), |_| {});
        let rows = probe_rows(&ledger);
        let bad = usage_probe_violations(&m, &host);
        let _ = std::fs::remove_dir_all(&dir);
        (m, host, lines, journal, rows, bad)
    };
    let changed = |journal: &[String]| {
        journal
            .iter()
            .filter(|l| l.contains("the point changed across the probe"))
            .count()
    };

    let (m, host, lines, journal, rows, bad) = run("te-probe-closed-mid-read", &|m| {
        let w = world(m);
        w.frames = vec![panel_fx::screen(panel_fx::USAGE_SETTLED), panel_torn()];
        w.leaves_after = Some(3);
    });
    assert_eq!(changed(&journal), 0, "{journal:#?}");
    assert_eq!(
        m.writes(),
        ["text:/usage", "enter", "text:keep going", "enter"],
        "no Escape of the loop's, and the act once: {lines:#?}"
    );
    assert_eq!(host.said("probe"), ["probe:claimed", "probed:closed"]);
    assert!(host.samples.lock().unwrap().is_empty());
    assert_eq!(
        gate_words(&journal),
        ["escalated"],
        "the later point's, and never probes-off: {journal:#?}"
    );
    assert_eq!(
        rows,
        ["typed /usage the accounts probe", "waiting /usage closed"]
    );
    assert_eq!(bad, Vec::<String>::new());

    // A PERSON'S Esc closed it (their key served with the half-erased
    // read): no new point either, and the act is HELD for their grace (two
    // minutes here, past the script's end) — never typed into their hands.
    let (m, _, lines, journal, rows, bad) = run("te-probe-closed-by-a-person", &|m| {
        let w = world(m);
        w.frames = vec![panel_fx::screen(panel_fx::USAGE_SETTLED), panel_torn()];
        w.leaves_after = Some(3);
        w.person_after = Some(2);
    });
    assert_eq!(changed(&journal), 0, "{journal:#?}");
    assert_eq!(m.writes(), ["text:/usage", "enter"], "{lines:#?}");
    assert!(
        journal
            .iter()
            .any(|l| l.starts_with("WAITING ") && l.ends_with("a person is typing")),
        "{journal:#?}"
    );
    assert_eq!(
        rows,
        ["typed /usage the accounts probe", "waiting /usage closed"]
    );
    assert_eq!(bad, Vec::<String>::new());

    // NEGATIVE CONTROL: the composer back, on another point.
    let (_, _, lines, journal, _, bad) = run("te-probe-closed-mid-read-moved", &|m| {
        // The run goes on past the point it was moved to, to the next: a
        // second at least of 5 ms waits, ten re-decisions' worth.
        m.vanish_after = Some(200);
        let w = world(m);
        w.leaves_after = Some(1);
        w.after = Some(ended("Something else stands here now."));
    });
    assert_eq!(changed(&journal), 1, "{lines:#?}");
    assert!(
        !gate_words(&journal).is_empty() && gate_words(&journal).iter().all(|g| g == "probes-off"),
        "{journal:#?}"
    );
    assert_eq!(bad, Vec::<String>::new());
}

/// NO ESCAPE WHILE A BUSY SIGNAL SHOWS (the spec's P14, P20): Escape stops a
/// running turn, and what it does with the panel over one is not measured.
/// A panel that comes up with a turn running under it
/// ([`panel_under_a_turn`], composed: never observed) is NOT sampled — the
/// host is told `unsettled` — and gets NO Escape for as long as the turn
/// runs: it stands, owed, and no second `/usage` is typed over it.
///
/// NEGATIVE CONTROL: the same world whose turn ends — the next read shows
/// the panel with no busy row — gets its one Escape, and still no sample:
/// nothing is recorded from a panel a turn ran under.
#[test]
fn a_panel_with_a_turn_running_under_it_gets_no_escape_and_no_sample() {
    let busy = panel_under_a_turn();
    assert!(aterm_phase::settings_panel(&busy).is_some());
    assert_eq!(worker_phase(&busy), Phase::Busy);
    let still = panel_fx::screen(panel_fx::USAGE_SETTLED);
    assert_ne!(worker_phase(&still), Phase::Busy);

    let (dir, ledger) = ledger_at("probe-turn-under");
    let host = ProbeHost::probing(true);
    let mut m = probe_world(&[panel_fx::USAGE_SETTLED], &host);
    world(&mut m).frames = vec![busy.clone()];
    // The turn runs for as long as the run does: it ends on its steps.
    let (lines, _) = probe_run_for(
        "te-probe-turn-under",
        &mut m,
        &host,
        &ledger,
        probe_policy(120),
        |_| {},
    );
    assert_eq!(m.writes(), ["text:/usage", "enter"], "{lines:#?}");
    assert_eq!(host.said("probe"), ["probe:claimed", "probed:unsettled"]);
    assert!(host.samples.lock().unwrap().is_empty());
    assert_eq!(world(&mut m).at, PanelAt::Open, "it stands, owed");
    assert_eq!(probe_rows(&ledger), ["typed /usage the accounts probe"]);
    assert_eq!(usage_probe_violations(&m, &host), Vec::<String>::new());
    let _ = std::fs::remove_dir_all(&dir);

    // NEGATIVE CONTROL: the turn ends. The run ends at the first sitting
    // wait after the Escape: what follows the close (the point decided again
    // once its window has run, its act typed) is not this test's, and how far
    // the loop gets into it before the script's two waits are out is a matter
    // of the machine's load.
    let (dir, ledger) = ledger_at("probe-turn-ended");
    let host = ProbeHost::probing(true);
    let mut m = probe_world(&[panel_fx::USAGE_SETTLED], &host);
    world(&mut m).frames = vec![busy, still];
    m.exit_when = Some(|m| probe_writes(m).contains(&"esc"));
    let (lines, _) = probe_run(
        "te-probe-turn-ended",
        &mut m,
        &host,
        &ledger,
        probe_policy(120),
        |_| {},
    );
    assert_eq!(probe_writes(&m), ["/usage", "esc"], "{lines:#?}");
    assert_eq!(host.said("probe"), ["probe:claimed", "probed:unsettled"]);
    assert!(host.samples.lock().unwrap().is_empty());
    assert_ne!(
        world(&mut m).at,
        PanelAt::Open,
        "closed once the turn ended"
    );
    assert_eq!(usage_probe_violations(&m, &host), Vec::<String>::new());
    let _ = std::fs::remove_dir_all(&dir);
}

/// A `/usage` THE SERVER DOES NOT TAKE IS NEVER FORCED. Turned away (`ERR
/// busy`, `ERR halted`): nothing is in the composer, the host is told
/// `not-written`, the loop backs off or parks — and the point's own act,
/// not carried out at that look, is decided again and typed. Skipped on the
/// judged screen because the guard matched no row (`OK skipped`): the act
/// goes on at once, as decided, with no probe.
#[test]
fn a_usage_the_server_turns_away_or_skips_is_not_written_and_the_act_goes_on() {
    for (refusal, word) in [
        ("busy turn=1", "REFUSED "),
        ("halted by the owner", "HALTED "),
    ] {
        let (dir, ledger) = ledger_at("probe-send-refused");
        let host = ProbeHost::probing(true);
        let mut m = probe_world(&[panel_fx::USAGE_SETTLED], &host);
        m.send_replies.push_back(err(refusal));
        // The re-decision is a tenth of a second off (`Timings::FAST`), after
        // the busy refusal's quarter-second pause: 200 waits of 5 ms, a second
        // at least.
        m.vanish_after = Some(200);
        let (lines, journal) = probe_run(
            "te-probe-send-refused",
            &mut m,
            &host,
            &ledger,
            probe_policy(120),
            |_| {},
        );
        assert_eq!(
            m.writes(),
            ["text:/usage", "text:keep going", "enter"],
            "{refusal}: {lines:#?}"
        );
        assert_eq!(probe_writes(&m), ["/usage"], "asked once, no Escape");
        assert_eq!(
            host.said("probe"),
            ["probe:claimed", "probed:not-written"],
            "{refusal}"
        );
        assert!(
            journal.iter().any(|l| l.starts_with(word)),
            "{refusal}: {journal:#?}"
        );
        assert!(
            probe_rows(&ledger).is_empty(),
            "nothing written: nothing owed"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    // The guard matched no row of the judged screen.
    let (dir, ledger) = ledger_at("probe-send-skipped");
    let host = ProbeHost::probing(true);
    let mut m = probe_world(&[panel_fx::USAGE_SETTLED], &host);
    m.send_replies.push_back(ok("OK skipped seq=102\n"));
    let (lines, journal) = probe_run(
        "te-probe-send-skipped",
        &mut m,
        &host,
        &ledger,
        probe_policy(120),
        |_| {},
    );
    assert_eq!(
        m.writes(),
        ["text:/usage", "text:keep going", "enter"],
        "{lines:#?}"
    );
    assert_eq!(host.said("probe"), ["probe:claimed", "probed:not-written"]);
    assert!(
        journal
            .iter()
            .any(|l| l.starts_with("SKIPPED seq=102 rule=usage-probe@v1 ")),
        "{journal:#?}"
    );
    assert!(probe_rows(&ledger).is_empty());
    let _ = std::fs::remove_dir_all(&dir);
}

/// `/usage` WRITTEN AND NOT SUBMITTED (the screen moved before its Enter:
/// `OK skipped reason=changed`) IS A RECORD AND RAISES NOTHING (alerts have
/// a class, and this is none): the host is told
/// `not-written` and informed ONCE
/// ([`IdleHost::inform`], no badge), the journal holds its one `SKIPPED`
/// line — and no attention is set, no ask posted, nothing escalated. THE
/// PANEL STAYS OWED, in the ledger too, because text of the harness's that
/// stands in the composer may still be sent (and the panel that opens then
/// is the harness's to close: [`a_loop_stopped_mid_probe_presses_nothing_and_the_next_loop_closes_the_panel`]).
///
/// NEGATIVE CONTROL: ANOTHER RULE'S LEFTOVER STILL ESCALATES. The same world
/// and the same skipped Enter with the claim declined — so the text left typed is the continuation's — sets the
/// worker's `attention` to `typed, not submitted (…): `keep going``,
/// journals `ESCALATED`, and informs nobody. And the look that finds the
/// composer still holding `/usage` closes nothing and writes no `waiting`
/// row.
#[test]
fn usage_left_typed_is_a_record_that_raises_nothing_and_the_panel_stays_owed() {
    let raised = |m: &Mock| -> Vec<String> {
        m.requests
            .iter()
            .filter(|r| r.starts_with("meta set attention"))
            .cloned()
            .collect()
    };
    let (dir, ledger) = ledger_at("probe-left-typed");
    let host = ProbeHost::probing(true);
    let mut m = probe_world(&[panel_fx::USAGE_SETTLED], &host);
    m.tick_at_key = 1;
    // The text stands in the composer and nothing moves on: the run ends on
    // its steps.
    let (lines, journal) = probe_run_for(
        "te-probe-left-typed",
        &mut m,
        &host,
        &ledger,
        probe_policy(120),
        |_| {},
    );
    assert_eq!(m.writes(), ["text:/usage", "enter"], "{lines:#?}");
    assert_eq!(
        world(&mut m).at,
        PanelAt::Typed("/usage".to_string()),
        "it stands in the composer"
    );
    assert_eq!(host.said("probe"), ["probe:claimed", "probed:not-written"]);
    assert_eq!(host.said("inform").len(), 1, "told once: a record");
    assert_eq!(raised(&m), Vec::<String>::new(), "nothing is raised for it");
    assert!(
        !journal.iter().any(|l| l.starts_with("ESCALATED ")),
        "{journal:#?}"
    );
    let skipped: Vec<&String> = journal
        .iter()
        .filter(|l| l.contains("typed, not submitted"))
        .collect();
    assert!(
        skipped.len() == 1 && skipped[0].starts_with("SKIPPED seq=102 rule=usage-probe@v1 "),
        "its one journal line: {journal:#?}"
    );
    assert_eq!(
        probe_rows(&ledger),
        ["typed /usage the accounts probe"],
        "owed: no `waiting` row while the text stands"
    );
    assert!(crate::supervise::approvals::probe_owed(
        &std::fs::read_to_string(&ledger).unwrap_or_default(),
        None
    ));
    let _ = std::fs::remove_dir_all(&dir);

    // NEGATIVE CONTROL: the claim declined, the text left typed is the
    // continuation's — escalated as every other typed act's leftover is.
    let (dir, ledger) = ledger_at("probe-left-typed-other-rule");
    let host = ProbeHost::probing(false);
    let mut m = probe_world(&[panel_fx::USAGE_SETTLED], &host);
    m.tick_at_key = 1;
    let (lines, journal) = probe_run_for(
        "te-probe-left-typed-other-rule",
        &mut m,
        &host,
        &ledger,
        probe_policy(120),
        |_| {},
    );
    assert_eq!(m.writes(), ["text:keep going", "enter"], "{lines:#?}");
    assert_eq!(world(&mut m).at, PanelAt::Typed("keep going".to_string()));
    let raised = raised(&m);
    assert!(
        raised.len() == 1
            && raised[0].starts_with("meta set attention owner=supervisor claude idle: ")
            && raised[0].ends_with("`keep going`)"),
        "{:#?}",
        m.requests
    );
    assert_eq!(
        journal
            .iter()
            .filter(|l| l.starts_with("ESCALATED "))
            .count(),
        1,
        "{journal:#?}"
    );
    assert!(
        host.said("inform").is_empty(),
        "an escalation, not a record"
    );
    assert!(probe_rows(&ledger).is_empty());
    let _ = std::fs::remove_dir_all(&dir);
}

/// WHAT BECOMES OF `/usage` LEFT TYPED, with nobody at the session. The
/// turn-end policy reads it as the draft it is and, past a person's grace,
/// sends it in its act's place — and that Enter is THE PROBE'S, not the
/// act's: fenced three ways as the probe's own, journaled under the probe's
/// rule, and booked nowhere in the policy (no `CONTINUED`, no `typed` row
/// under the act's rule, nothing of the hour's budget). The panel it opens
/// is owed since the text was written: the next look closes it with ONE
/// Escape under its own header row and samples nothing, the ledger gets its
/// `waiting` row, and the point — decided again on the empty composer — gets
/// its own act at once: `keep going` is typed within the two seconds of the
/// re-decision, which an act booked for `/usage` would have held back for
/// the half minute a typed act is given to be taken, and a step of the
/// back-off after it. Nothing is raised on the way, and the host is asked
/// for no second claim.
///
/// NEGATIVE CONTROL: a `/usage` standing in the composer that NO LEDGER ROW
/// OWES — a person's own draft — is sent as the draft rule sends any: as
/// the act (`CONTINUED … rule=continue@v1 /usage`, its `typed` row counted
/// by the budget's reader), and the panel it opens gets NO Escape: a loop
/// closes only a panel the harness opened.
#[test]
fn usage_left_typed_is_sent_as_the_probes_own_and_its_panel_is_closed() {
    let (dir, ledger) = ledger_at("probe-left-sent");
    let host = ProbeHost::probing(true);
    let mut m = probe_world(&[panel_fx::USAGE_SETTLED], &host);
    m.tick_at_key = 1;
    // The re-decision after the panel's close is a tenth of a second off
    // (`Timings::FAST`), in 5 ms waits: 200 of them, a second at least (the
    // one before it is waited out while the text stands, which counts no
    // wait).
    m.vanish_after = Some(200);
    let (lines, journal) = probe_run(
        "te-probe-left-sent",
        &mut m,
        &host,
        &ledger,
        probe_policy(0),
        |_| {},
    );
    assert_eq!(
        m.writes(),
        [
            "text:/usage",
            "enter",
            "enter",
            "esc",
            "text:keep going",
            "enter"
        ],
        "{lines:#?}\n{journal:#?}"
    );
    let keys: Vec<&String> = m
        .requests
        .iter()
        .filter(|r| verb_of(r) == "key" && (r.contains("/usage") || r.ends_with(" esc")))
        .collect();
    assert_eq!(keys.len(), 3, "{keys:#?}");
    assert_eq!(
        keys[0], "key if-human=0 if-gen=1.104 if=^❯\\x20/usage\\s*$ enter",
        "the probe's Enter, which the moved screen skipped"
    );
    assert!(
        keys[1].starts_with("key if-human=0 if-gen=1.")
            && keys[1].ends_with(" if=^❯\\x20/usage\\s*$ enter")
            && keys[1] != keys[0],
        "the Enter of the text left typed: fenced three ways on a later read: {keys:#?}"
    );
    assert_eq!(
        keys[2],
        "key if-human=0 if=^...Settings..Status...Config...Usage esc"
    );
    assert_eq!(count(&m, "turn"), 0, "never the unfenced fallback");
    assert_eq!(
        probe_writes(&m),
        ["/usage", "esc"],
        "one `/usage`, one Escape"
    );
    assert_eq!(
        host.said("probe"),
        ["probe:claimed", "probed:not-written"],
        "no second claim, and nothing sampled"
    );
    assert_eq!(host.said("inform").len(), 1, "told once: a record");
    assert!(
        !journal
            .iter()
            .any(|l| l.starts_with("CONTINUED ") && l.contains("/usage")),
        "`/usage` is no continuation: {journal:#?}"
    );
    let typed: Vec<&String> = journal.iter().filter(|l| l.starts_with("TYPED ")).collect();
    assert!(
        typed.len() == 1 && typed[0].starts_with("TYPED seq=106 rule=usage-probe@v1 "),
        "{journal:#?}"
    );
    assert_eq!(
        probe_rows(&ledger),
        ["typed /usage the accounts probe", "waiting /usage closed"]
    );
    let body = std::fs::read_to_string(&ledger).expect("the ledger");
    assert_eq!(
        body.lines()
            .filter(|l| l.contains("\"command\":\"/usage\""))
            .count(),
        2,
        "no row of `/usage` under the act's rule: {body}"
    );
    assert_eq!(
        crate::supervise::approvals::typed_at(&ledger, None).len(),
        1,
        "the budget's reader counts the continuation alone"
    );
    assert!(!crate::supervise::approvals::probe_owed(
        &std::fs::read_to_string(&ledger).unwrap_or_default(),
        None
    ));
    assert_eq!(usage_probe_violations(&m, &host), Vec::<String>::new());
    let _ = std::fs::remove_dir_all(&dir);

    // NEGATIVE CONTROL: the same text with nothing owed is a person's draft.
    let (dir, ledger) = ledger_at("probe-left-not-ours");
    let host = ProbeHost::probing(true);
    let mut m = probe_world(&[panel_fx::USAGE_SETTLED], &host);
    let rest = m.screens.last().cloned().expect("the point");
    *m.screens.last_mut().expect("the point") = with_draft(&rest, "/usage");
    m.cursor_col = Some(8);
    world(&mut m).at = PanelAt::Typed("/usage".to_string());
    world(&mut m).rest = Some(rest);
    // The panel stands and nothing moves on: the run ends on its steps.
    let (lines, _) = probe_run_for(
        "te-probe-left-not-ours",
        &mut m,
        &host,
        &ledger,
        probe_policy(0),
        |_| {},
    );
    assert_eq!(m.writes(), ["enter"], "{lines:#?}");
    assert!(
        lines
            .iter()
            .any(|l| l.starts_with("CONTINUED ") && l.ends_with(" rule=continue@v1 /usage")),
        "the draft rule's act, as before: {lines:#?}"
    );
    assert_eq!(
        world(&mut m).at,
        PanelAt::Open,
        "not the harness's to close"
    );
    assert_eq!(probe_writes(&m), Vec::<&str>::new());
    assert!(host.said("probe").is_empty() && host.said("inform").is_empty());
    assert!(probe_rows(&ledger).is_empty());
    assert_eq!(
        crate::supervise::approvals::typed_at(&ledger, None).len(),
        1
    );
    let _ = std::fs::remove_dir_all(&dir);
}

/// AN ENTER OF THE TEXT LEFT TYPED THAT DOES NOT TAKE IS NOT THE LAST LOOK
/// AT IT, whether the server wrote it and the composer holds `/usage` still,
/// the screen as it was, or turned it away ([`Session::probe_left_enter`]'s
/// refusal arms, the review of 2026-10-14: `ERR halted`, an owner's hold
/// parked on until `status` reads `hold=0`, or `ERR busy lease=…`, another
/// driver's, backed off from) and wrote nothing: the screen never moves, so
/// no look would come. The point is decided again once the wait a typed act
/// is given has passed, the Enter is written again there, and the run goes on
/// as [`usage_left_typed_is_sent_as_the_probes_own_and_its_panel_is_closed`]
/// — the panel closed, the act typed. Every Enter written is journaled under
/// the probe's rule, and none is an act. Parked or backed off and nothing
/// THE PROBE'S `/usage` LEFT TYPED OVER CLAUDE CODE'S SLASH MENU, its own
/// entry highlighted (`  ❯ /usage …` under the composer, as 2.1.300 was
/// MEASURED to draw it: `SLASH_MENU_USAGE_MEASURED`), is still the probe's
/// to send: the menu's Enter runs the very command the composer shows, so
/// the draft is no diverted one (`Composer::Diverted` is for a highlighted
/// entry that is another command) and the run is
/// [`usage_left_typed_is_sent_as_the_probes_own_and_its_panel_is_closed`]'s
/// — the Enter the probe's own, the panel closed, the act typed, nothing
/// escalated for the text.
#[test]
fn usage_left_typed_over_its_own_menu_entry_is_still_the_probes_to_send() {
    let (dir, ledger) = ledger_at("probe-left-menu");
    let host = ProbeHost::probing(true);
    let mut m = probe_world(&[panel_fx::USAGE_SETTLED], &host);
    world(&mut m).menu = true;
    m.tick_at_key = 1;
    m.vanish_after = Some(700);
    let (lines, journal) = probe_run(
        "te-probe-left-menu",
        &mut m,
        &host,
        &ledger,
        probe_policy(0),
        |_| {},
    );
    assert_eq!(
        m.writes(),
        [
            "text:/usage",
            "enter",
            "enter",
            "esc",
            "text:keep going",
            "enter"
        ],
        "{lines:#?}\n{journal:#?}"
    );
    assert_eq!(
        journal
            .iter()
            .filter(|l| l.starts_with("TYPED "))
            .collect::<Vec<_>>(),
        [
            "TYPED seq=106 rule=usage-probe@v1 /usage left typed, its Enter written now: no act \
          of the policy's, and the panel it opens is closed unsampled"
        ],
        "{journal:#?}"
    );
    assert!(
        !journal
            .iter()
            .any(|l| l.contains(crate::supervise::policy::turn_end::MENU_DIVERTS)),
        "{journal:#?}"
    );
    assert_eq!(
        probe_rows(&ledger),
        ["typed /usage the accounts probe", "waiting /usage closed"]
    );
    let _ = std::fs::remove_dir_all(&dir);
}

/// more, the text stood unsent until something else moved the screen, and
/// the act behind it with it. The run ends on the fact, its stalls a hang
/// detector.
#[test]
fn an_enter_of_the_text_left_typed_that_does_not_take_is_written_again() {
    for (case, reply, written) in [
        ("not-taken", ok("OK seq=106\n"), 2),
        ("halted", err("halted reason=owner origin=local"), 1),
        ("busy", err("busy lease=s-9"), 1),
    ] {
        let tag = format!("probe-left-{case}");
        let (dir, ledger) = ledger_at(&tag);
        let host = ProbeHost::probing(true);
        let mut m = probe_world(&[panel_fx::USAGE_SETTLED], &host);
        // The probe's own Enter is skipped (the screen moved); the first
        // Enter of the text left typed does not take; the next one is the
        // world's to take.
        m.key_replies
            .push_back(ok("OK skipped reason=changed seq=104\n"));
        m.key_replies.push_back(reply);
        if case == "halted" {
            m.hold = "1";
            m.hold_lifts_after = Some(1);
        }
        // The re-decisions are a tenth of a second off (`Timings::FAST`),
        // after a quarter-second refusal pause: 200 waits of 5 ms, a second at
        // least.
        m.vanish_after = Some(200);
        let (lines, journal) = probe_run(
            &format!("te-{tag}"),
            &mut m,
            &host,
            &ledger,
            probe_policy(0),
            |s| {
                s.set_turn_end_timing(TurnEndTiming {
                    take_within: Duration::from_millis(100),
                    ..TurnEndTiming::default()
                });
            },
        );
        assert_eq!(
            m.writes(),
            [
                "text:/usage",
                "enter",
                "enter",
                "enter",
                "esc",
                "text:keep going",
                "enter"
            ],
            "{case}: {lines:#?}\n{journal:#?}"
        );
        assert_eq!(probe_writes(&m), ["/usage", "esc"], "{case}");
        assert_eq!(
            journal
                .iter()
                .filter(|l| l.starts_with("TYPED ")
                    && l.contains(" rule=usage-probe@v1 /usage left typed"))
                .count(),
            written,
            "{case}: {journal:#?}"
        );
        assert!(
            !journal
                .iter()
                .any(|l| l.starts_with("CONTINUED ") && l.contains("/usage")),
            "{case}: {journal:#?}"
        );
        assert_eq!(
            probe_rows(&ledger),
            ["typed /usage the accounts probe", "waiting /usage closed"],
            "{case}"
        );
        assert_eq!(
            crate::supervise::approvals::typed_at(&ledger, None).len(),
            1,
            "{case}"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }
}

/// `rows` with `text` typed into its composer (the caret row).
fn with_draft(rows: &[String], text: &str) -> Vec<String> {
    let mut rows = rows.to_vec();
    let caret = rows.iter().rposition(|r| r == "❯").expect("a composer");
    rows[caret] = format!("❯ {text}");
    rows
}

/// THE PROBE IS NEVER TYPED A SECOND TIME OVER ITS OWN TEXT (no
/// `/usage/usage`). `/usage` stands typed and unsent, and another turn runs
/// and ends over it — read live, under a roster that says the read is due
/// and a host that would grant every claim: the loop that takes the session
/// up asks for NO claim and writes nothing. Three things shut it, any one
/// enough: a panel is owed (the first of the probe's gates), the composer is
/// not empty (the policy's own gate — and with a draft standing the host is
/// not even asked about the account), and the write's caret-row guard
/// (`^❯\s*$`) matches no row of a composer that holds text.
///
/// NEGATIVE CONTROL: the same second turn end with the text cleared first is
/// probed — the host asked, the claim granted, `/usage` typed, the panel
/// sampled and closed. (The owed panel's gate alone is the gates table's,
/// `panel-owed`.)
#[test]
fn the_probe_is_not_typed_again_over_its_own_text_left_typed() {
    let second_turn_end = |tag: &str, cleared: bool| {
        let (dir, ledger) = ledger_at(tag);
        let host = ProbeHost::probing(true);
        let mut m = probe_world(
            &[panel_fx::USAGE_REFRESHING, panel_fx::USAGE_SETTLED],
            &host,
        );
        m.tick_at_key = 1;
        let _ = probe_run_for(
            &format!("te-{tag}"),
            &mut m,
            &host,
            &ledger,
            probe_policy(120),
            |_| {},
        );
        assert_eq!(probe_writes(&m), ["/usage"], "{tag}");
        assert_eq!(world(&mut m).at, PanelAt::Typed("/usage".to_string()));
        let rest = world(&mut m).rest.clone().expect("the composer");
        if cleared {
            // A person took the text out.
            world(&mut m).at = PanelAt::Rest;
            m.cursor_col = None;
            *m.screens.last_mut().expect("a screen") = rest;
        }
        // A turn runs and ends over the composer as it stands.
        let standing = m.screens.last().cloned().expect("a screen");
        let busy = if cleared {
            busy_screen()
        } else {
            with_draft(&busy_screen(), "/usage")
        };
        m.screens.push(busy);
        m.screens.push(standing);
        m.served = m.screens.len() - 2;
        m.stalls = 0;
        let next = ProbeHost::probing(true);
        // With the text standing nothing moves on: that run ends on its
        // steps; cleared, on its script.
        let run_tag = format!("te-{tag}-next");
        let (lines, _) = if cleared {
            probe_run(&run_tag, &mut m, &next, &ledger, probe_policy(120), |_| {})
        } else {
            probe_run_for(&run_tag, &mut m, &next, &ledger, probe_policy(120), |_| {})
        };
        let _ = std::fs::remove_dir_all(&dir);
        assert_eq!(
            next.said("").first().map(String::as_str),
            Some("turn-ran"),
            "{tag}: the turn was read live: {lines:#?}"
        );
        (probe_writes(&m), next.said(""), m.writes())
    };
    let (probes, said, writes) = second_turn_end("probe-left-again", false);
    assert_eq!(probes, ["/usage"], "the first loop's alone");
    assert_eq!(said, ["turn-ran"], "asked for no advice and no claim");
    assert_eq!(writes, ["text:/usage", "enter"], "nothing written over it");

    let (probes, said, _) = second_turn_end("probe-left-cleared", true);
    assert_eq!(probes, ["/usage", "/usage", "esc"]);
    assert_eq!(
        said[..4],
        ["turn-ran", "account:turn-end", "probe:claimed", "probed:ok"],
        "{said:#?}"
    );
}

/// WHAT CAME UP IS NOT THE USAGE TAB UNDER THE FULLSCREEN RENDERER'S RULE —
/// the inline renderer's panel (its `─` rule, two columns in), or another
/// tab of the Settings panel: no sample, the host is told `renderer`, the
/// panel gets its one Escape under its own header row, and THIS LOOP PROBES
/// NO MORE — not even on another grid size (so it is not the fold's latch).
/// (A panel that LEAVES BY ITSELF while it is read is `closed`:
/// [`a_panel_closed_under_the_read_is_no_new_point_and_the_probes_go_on`].)
#[test]
fn another_panel_ends_the_loops_probes() {
    let (wrote, told) = two_turn_ends("probe-inline-panel", &[panel_fx::USAGE_INLINE], 3);
    assert_eq!(wrote, ["/usage", "esc"]);
    assert_eq!(told, ["probe:claimed", "probed:renderer"]);

    // Another tab: the measured panel's header over rows the Usage tab does
    // not draw (COMPOSED: no other tab was ever captured — the Status tab
    // names the login).
    let settled = panel_fx::screen(panel_fx::USAGE_SETTLED);
    let header = aterm_phase::settings_panel(&settled)
        .expect("the panel")
        .header;
    let mut other: Vec<String> = settled[..=header].to_vec();
    other.extend(
        ["", "   Version: 2.1.287", "", "   Esc to cancel"]
            .iter()
            .map(|r| r.to_string()),
    );
    let other = other.join("\n");
    let (wrote, told) = two_turn_ends("probe-other-tab", &[other.as_str()], 3);
    assert_eq!(wrote, ["/usage", "esc"]);
    assert_eq!(told, ["probe:claimed", "probed:renderer"]);
}

/// THE LOOP IS STOPPED MID-PROBE (its host's stop lands while the panel is
/// read): a stopped loop writes nothing — NO ESCAPE goes — the host is told
/// `lost`, and the ledger keeps the `typed` row with no `waiting` row after
/// it. The loop that follows reads that row and closes the panel.
#[test]
fn a_loop_stopped_mid_probe_presses_nothing_and_the_next_loop_closes_the_panel() {
    let (dir, ledger) = ledger_at("probe-stopped");
    let host = ProbeHost::probing(true);
    let mut m = probe_world(&[panel_fx::USAGE_REFRESHING], &host);
    let stop = Arc::new(AtomicBool::new(false));
    world(&mut m).stop_at_read = Some((2, Arc::clone(&stop)));
    let opts = SuperviseOpts {
        idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
        ledger: Some(ledger.clone()),
        policy: probe_policy(120),
        ..SuperviseOpts::hosted_with(&owners_policy())
    };
    let mut out: Vec<u8> = Vec::new();
    {
        let mut s = session(&mut m, None);
        s.set_clock(PROBE_NOW, PDT);
        s.set_zone_lookup(test_zones);
        probe_waits(&mut s);
        assert_eq!(s.run_hosted(&opts, stop, &mut out), Ok(()));
    }
    assert_eq!(probe_writes(&m), ["/usage"], "{:#?}", m.requests);
    assert_eq!(world(&mut m).at, PanelAt::Open, "the panel stands");
    assert_eq!(host.said("probe"), ["probe:claimed", "probed:lost"]);
    assert_eq!(probe_rows(&ledger), ["typed /usage the accounts probe"]);
    assert!(crate::supervise::approvals::probe_owed(
        &std::fs::read_to_string(&ledger).unwrap_or_default(),
        None
    ));

    // The next loop.
    m.stalls = 0;
    let next = ProbeHost::probing(true);
    let (lines, _) = probe_run(
        "te-probe-stopped-next",
        &mut m,
        &next,
        &ledger,
        probe_policy(0),
        |_| {},
    );
    assert_eq!(probe_writes(&m), ["/usage", "esc"], "{lines:#?}");
    assert!(next.said("probe").is_empty());
    assert!(!crate::supervise::approvals::probe_owed(
        &std::fs::read_to_string(&ledger).unwrap_or_default(),
        None
    ));
    let _ = std::fs::remove_dir_all(&dir);
}

// ------------------------------------------------------------------------
// The task record (`docs/DESIGN-sessions-as-subagents-2026-10-15.md` §2.2,
// §2.3; `task_mark.rs`): what a tasked worker's record hears from the loop,
// over the scripted server's record (`Mock::task`).
// ------------------------------------------------------------------------

/// One transcript row as Claude Code 2.1.299 writes it, cut to the keys the
/// result reader reads: a typed prompt (`user`), or an assistant message
/// `id` holding one text block.
fn task_row(kind: &str, uuid: &str, id: &str, text: &str) -> String {
    let text = aterm_json::to_string(&aterm_json::Value::String(text.to_string())).expect("json");
    if kind == "user" {
        format!(
            r#"{{"parentUuid":null,"isSidechain":false,"type":"user","message":{{"role":"user","content":{text}}},"uuid":"{uuid}","sessionId":"0b2299fa","version":"2.1.299"}}"#
        )
    } else {
        format!(
            r#"{{"parentUuid":"p","isSidechain":false,"message":{{"id":"{id}","type":"message","role":"assistant","model":"claude-sonnet-5-5","content":[{{"type":"text","text":{text}}}],"stop_reason":"end_turn"}},"type":"assistant","uuid":"{uuid}","sessionId":"0b2299fa","version":"2.1.299"}}"#
        )
    }
}

fn transcript_of(rows: &[String]) -> String {
    let mut out = rows.join("\n");
    out.push('\n');
    out
}

/// A host whose agent's transcript is `path`, read as each of `texts` in
/// turn (the last repeats) — what a done edge snapshots ([`IdleHost::transcript`])
/// — and, with `ready`, the live upgrade: once a done edge has read the
/// transcript it asks for the next idle point and types its READY notice
/// there (a step that types: the next point is that turn's answer). With
/// `stepped`, the transcript is the first of `texts` until the host has
/// taken a step and `stepped` after it: the READY exchange its step typed.
/// With `sleep` (the session's [`Session::clock_jump_handle`]), the Mac
/// sleeps two hours once the host has typed its step.
#[derive(Debug, Default)]
struct TaskHost {
    path: PathBuf,
    texts: std::sync::Mutex<VecDeque<String>>,
    stepped: Option<String>,
    sleep: std::sync::Mutex<Option<super::super::ClockJump>>,
    asks: std::sync::atomic::AtomicUsize,
    /// How many steps the host had taken at each read.
    read_at: std::sync::Mutex<Vec<usize>>,
    ready: bool,
    wanting: AtomicBool,
    steps: std::sync::atomic::AtomicUsize,
    /// How many points it wants and passes (no step) before it takes one.
    passes: std::sync::atomic::AtomicUsize,
}

impl TaskHost {
    fn reading(path: &Path, texts: &[&str]) -> Arc<Self> {
        Arc::new(Self {
            path: path.to_path_buf(),
            texts: std::sync::Mutex::new(texts.iter().map(|t| (*t).to_string()).collect()),
            ..Self::default()
        })
    }
}

impl IdleHost for TaskHost {
    fn wants(&self) -> bool {
        self.wanting.load(Ordering::SeqCst)
    }
    fn at_idle(&self) -> Option<HostStep> {
        if self
            .passes
            .try_update(Ordering::SeqCst, Ordering::SeqCst, |n| n.checked_sub(1))
            .is_ok()
        {
            return None;
        }
        self.wanting.store(false, Ordering::SeqCst);
        self.steps.fetch_add(1, Ordering::SeqCst);
        if let Some(clock) = self.sleep.lock().unwrap().take() {
            clock.slept(2 * 3600);
        }
        Some(HostStep {
            line: "upgrade step=notice".to_string(),
            moved: true,
            typed: Some(crate::supervise::policy::turn_end::HostTurn::Notice),
            repeat: false,
        })
    }
    fn owns_turn_end(&self) -> bool {
        false
    }
    fn transcript(&self) -> Option<(PathBuf, String)> {
        self.asks.fetch_add(1, Ordering::SeqCst);
        let steps = self.steps.load(Ordering::SeqCst);
        self.read_at.lock().unwrap().push(steps);
        if self.ready && steps == 0 {
            self.wanting.store(true, Ordering::SeqCst);
        }

        if let Some(after) = self.stepped.as_ref().filter(|_| steps > 0) {
            return Some((self.path.clone(), after.clone()));
        }
        let mut texts = self.texts.lock().unwrap();
        let text = if texts.len() > 1 {
            texts.pop_front()
        } else {
            texts.front().cloned()
        }?;
        Some((self.path.clone(), text))
    }
}

/// One `watch` of `m` as session `@s-1` under the owner's policy, `host`
/// its idle host, results snapshotted under `tasks`: the lines printed.
fn tasked_watch(
    m: &mut Mock,
    host: &Arc<TaskHost>,
    tasks: &Path,
    journal: Option<&Path>,
) -> Vec<String> {
    let opts = SuperviseOpts {
        policy: owners_policy(),
        journal: journal.map(Path::to_path_buf),
        idle_host: Some(Arc::clone(host) as Arc<dyn IdleHost>),
        tasks: Some(tasks.to_path_buf()),
        ..auto(30)
    };
    let mut out: Vec<u8> = Vec::new();
    let mut s = session(m, Some("@s-1".to_string()));
    s.set_clock(TEST_NOW, PDT);
    s.set_zone_lookup(test_zones);
    let _ = s.watch(&opts, &mut out);
    String::from_utf8(out)
        .expect("utf-8")
        .lines()
        .map(str::to_string)
        .collect()
}

/// A worker's record as its starter leaves it: `working`, rev 1.
fn working_task() -> Option<(u64, String)> {
    Some((
        1,
        "state=working from=s-0a1b since_ms=0 result_bytes=0".to_string(),
    ))
}

/// The `task mark …` requests the loop sent.
fn task_marks(m: &Mock) -> Vec<String> {
    m.task_requests
        .iter()
        .filter(|r| r.starts_with("task mark"))
        .cloned()
        .collect()
}

/// `task mark done why=<why>` for the snapshot at `path` of `bytes`.
fn done_mark(why: &str, bytes: usize, path: &Path) -> String {
    format!(
        "task mark done why={why} result_bytes={bytes} result_path={}",
        aterm_codec::pct::encode(&path.to_string_lossy())
    )
}

/// What a tasked worker reports at the end of its turn of work: no done.
const WORK: &str = "Fixed the parser; pushing it next.";

/// THE LANDING'S CLEAN DEFENSE (FOREVER LAND: only Land's landed ends a task
/// the harness publishes), the worker's result: what the snapshot holds.
const LANDED: &str = "Fixed the parser and pushed it.\nNothing left: all of it is merged into \
                      the remote main branch.";

/// [`LANDED`] as the worker answers Land's instruction with it: no token
/// (FOREVER LAND: the defense is ordinary language).
fn landed_reply() -> String {
    LANDED.to_string()
}

/// The landing's result as the task record's snapshot holds it
/// (`crate::harness::result`'s landing rule): the worker's report before
/// Land's instruction ([`WORK`]), then the defense that landed it.
fn landed_result() -> String {
    format!("{WORK}\n\n{LANDED}")
}

/// A landing's transcript rows: the task, the worker's turn of work, Land's
/// instruction and `reply` answering it.
fn landing_rows(reply: &str) -> Vec<String> {
    vec![
        task_row("user", "u-task", "", "Fix the parser."),
        task_row("assistant", "a-work", "msg_1", WORK),
        task_row("user", "u-land", "", LAND),
        task_row("assistant", "a-land", "msg_2", reply),
    ]
}

/// A landing's screens: a turn of work, then `reply` answering Land's
/// instruction typed at its end.
fn landing_screens(reply: &str) -> Vec<Vec<String>> {
    vec![busy_screen(), ended(WORK), busy_screen(), ended(reply)]
}

/// `m` under Land, its turn of work's end sitting until Land's instruction
/// is typed there ([`landing_screens`]).
fn landing(m: &mut Mock) {
    m.autopilot = Some("land");
    m.turn_releases = Some(1);
    m.history_served();
}

/// LANDED, PUBLISHED ONCE: the worker's turn of work gets Land's
/// instruction, and its clean defense at that instruction's yield lands the
/// task — at that point, and only there, its record is read and marked
/// `done` with the landing's result (the report before Land's instruction,
/// then the defense) snapshotted under
/// `<tasks>/<gsid>-<rev>.result.md`, and the journal says so (`TASK …`).
/// NEGATIVE CONTROLS: the same run under Cruise — never an end — types the
/// done check at the defense and marks and writes nothing; a session with no
/// task reads the record and marks and writes nothing.
#[test]
fn a_landed_workers_task_is_marked_once_with_its_defense() {
    let root = crate::supervise::ScratchDir::new("task", "landed");
    let text = transcript_of(&landing_rows(&landed_reply()));
    let run = |task: Option<(u64, String)>, tasks: &Path, word: &'static str| {
        let host = TaskHost::reading(&root.join("t.jsonl"), &[&text]);
        let journal = root.join(format!("journal-{word}-{}.jsonl", task.is_some()));
        let mut m = Mock::new(landing_screens(&landed_reply()));
        landing(&mut m);
        m.autopilot = Some(word);
        m.vanish_after = Some(4);
        m.task = task;
        let lines = tasked_watch(&mut m, &host, tasks, Some(&journal));
        let task_lines: Vec<String> = journal_records(&journal)
            .0
            .into_iter()
            .map(|r| r.line)
            .filter(|l| l.starts_with("TASK "))
            .collect();
        (m, lines, task_lines)
    };
    let tasks = root.join("tasks");
    let (m, lines, task_lines) = run(working_task(), &tasks, "land");
    assert!(
        lines
            .iter()
            .any(|l| l.starts_with(&format!("CONTINUED seq=102 rule={RULE_LAND} "))),
        "{lines:#?}"
    );
    let path = tasks.join("s-1-1.result.md");
    assert_eq!(
        task_marks(&m),
        [done_mark("landed", landed_result().len(), &path)],
        "{lines:#?}"
    );
    assert_eq!(
        std::fs::read_to_string(&path).expect("the snapshot"),
        landed_result()
    );
    assert!(
        m.task
            .as_ref()
            .is_some_and(|(rev, f)| *rev == 2 && f.starts_with("state=done ")),
        "{:?}",
        m.task
    );
    assert_eq!(
        task_lines,
        [format!(
            "TASK seq=104 done why=landed rev=2 result_bytes={}",
            landed_result().len()
        )]
    );
    // NEGATIVE CONTROL: Cruise.
    let cruise = root.join("cruise");
    let (m, lines, task_lines) = run(working_task(), &cruise, "cruise");
    assert!(
        lines
            .iter()
            .any(|l| l.starts_with(&format!("CONTINUED seq=104 rule={RULE_DONE_CHECK} "))),
        "{lines:#?}"
    );
    assert!(task_marks(&m).is_empty(), "{:?}", m.task_requests);
    assert!(task_lines.is_empty(), "{task_lines:#?}");
    assert!(!cruise.exists(), "nothing written");
    // NEGATIVE CONTROL: no task.
    let untasked = root.join("untasked");
    let (m, _, task_lines) = run(None, &untasked, "land");
    assert!(!m.task_requests.is_empty(), "the record read");
    assert!(task_marks(&m).is_empty(), "{:?}", m.task_requests);
    assert!(task_lines.is_empty(), "{task_lines:#?}");
    assert!(!untasked.exists(), "nothing written");
}

/// A DEFENSE TALLER THAN THE SCREEN IS READ WHOLE BEFORE IT LANDS
/// (`Session::said_read_whole`): the land act's yield is a message whose
/// `⏺` head scrolled into the history above the screen, its rows on the
/// screen a clean defense. The loop reads the history up to that head, and
/// the message with it: with a NEEDS YOU line at its head (in the history),
/// no landing — the nudge typed, the record left `working`; with none, the
/// landing, marked once. The review of 2026-10-20 found the tall report
/// landed on its last rows with its need unread. NEGATIVE CONTROLS: each
/// case flips the other's outcome, and a host whose history cannot be read
/// lands nothing on the rows read (they stay cut).
#[test]
fn a_defense_taller_than_the_screen_is_read_whole_before_it_lands() {
    let root = crate::supervise::ScratchDir::new("task", "tall");
    let tall = |need: bool| -> (Vec<String>, Vec<String>, String) {
        let mut said = vec!["Merged the parser, the lexer and their suites.".to_string()];
        if need {
            said.push("NEEDS YOU: the signing credential".to_string());
        }
        said.extend((0..45).map(|i| format!("- merged item {i} into the remote main branch")));
        said.push(String::new());
        said.push("Nothing left: all of it is merged into the remote main branch.".to_string());
        let mut drawn: Vec<String> = vec!["❯ Fix the parser.".to_string(), String::new()];
        drawn.extend(
            said.iter()
                .enumerate()
                .map(|(i, l)| match (i, l.is_empty()) {
                    (0, _) => format!("⏺ {l}"),
                    (_, true) => String::new(),
                    _ => format!("  {l}"),
                }),
        );
        drawn.extend(rows(&["", "✻ Worked for 12m 2s · done 4:24 PM", ""]));
        drawn.extend(composer("  ⏵⏵ bypass permissions on (shift+tab to cycle)"));
        // The screen holds the last 34 rows; the rest is its history.
        let cut = drawn.len() - 34;
        let screen = drawn.split_off(cut);
        (screen, drawn, said.join("\n"))
    };
    let run = |need: bool, history: bool, tag: &str| {
        let (screen, above, text) = tall(need);
        assert!(
            !aterm_phase::said_whole(&screen),
            "the head is above the screen"
        );
        let transcript = transcript_of(&landing_rows(&text));
        let host = TaskHost::reading(&root.join(format!("{tag}.jsonl")), &[&transcript]);
        let mut m = Mock::new(vec![busy_screen(), ended(WORK), busy_screen(), screen]);
        landing(&mut m);
        m.scrollback = history.then_some(above);
        m.alt_screen = Some(false);
        m.vanish_after = Some(4);
        m.task = working_task();
        let lines = tasked_watch(&mut m, &host, &root.join(format!("tasks-{tag}")), None);
        (m, lines)
    };
    let (m, lines) = run(false, true, "clean");
    let marks = task_marks(&m);
    assert!(
        marks.len() == 1 && marks[0].starts_with("task mark done why=landed "),
        "{marks:?}: {lines:#?}"
    );
    let (m, lines) = run(true, true, "need");
    assert!(task_marks(&m).is_empty(), "{:?}", m.task_requests);
    assert!(
        lines.iter().any(|l| l.contains(&format!(
            "rule={} ",
            crate::supervise::policy::turn_end::RULE_LAND_NUDGE
        ))),
        "{lines:#?}"
    );
    // NEGATIVE CONTROL: no history to read.
    let (m, _) = run(false, false, "unread");
    assert!(task_marks(&m).is_empty(), "{:?}", m.task_requests);
}

/// A tall Land report as `program`'s screen draws it: its rows `said` (the
/// first its head, under `reply_at` of `end`, the program's turn's end
/// whose reply row is replaced), and the rows of the reply drawn above
/// the screen — `(screen, history)`, the screen as tall as `end`.
fn tall_on(
    end: &[String],
    reply_at: usize,
    said: &[String],
    head: &str,
) -> (Vec<String>, Vec<String>) {
    let mut drawn = end[..reply_at].to_vec();
    drawn.extend(
        said.iter()
            .enumerate()
            .map(|(i, l)| match (i, l.is_empty()) {
                (_, true) => String::new(),
                (0, _) => format!("{head}{l}"),
                _ => format!("  {l}"),
            }),
    );
    drawn.extend(end[reply_at + 1..].iter().cloned());
    let screen = drawn.split_off(drawn.len() - end.len());
    (screen, drawn)
}

/// The words of a tall Land report: a NEEDS YOU line near its head when
/// `need`, 55 merged items, and a clean defense at its foot.
fn tall_said(need: bool) -> Vec<String> {
    let mut said = vec!["Merged the parser, the lexer and their suites.".to_string()];
    if need {
        said.push("NEEDS YOU: the signing credential".to_string());
    }
    said.extend((0..55).map(|i| format!("- merged item {i} into the remote main branch")));
    said.push(String::new());
    said.push("Nothing left: all of it is merged into the remote main branch.".to_string());
    said
}

/// A Land run on `program`'s screens (its mock `mock`): `busy`, its turn
/// of work's end `work` sitting until Land's instruction is typed there,
/// `busy` again, and that instruction's yield `tall` — `(screen,
/// history)`, the history served only where `history`. The lines printed
/// with the journal's `DONE` lines after them (the landing's), and the
/// `meta … attention owner=needs` requests sent (the need raised).
fn tall_landing(
    mock: fn(Vec<Vec<String>>) -> Mock,
    busy: &[String],
    work: &[String],
    tall: (Vec<String>, Vec<String>),
    history: bool,
) -> (Vec<String>, Vec<String>) {
    let (dir, journal) = journal_file("tall-landing");
    let (screen, above) = tall;
    let mut m = mock(vec![busy.to_vec(), work.to_vec(), busy.to_vec(), screen]);
    landing(&mut m);
    m.gen_fence = true;
    m.sends_gen = true;
    m.scrollback = history.then_some(above);
    m.alt_screen = Some(false);
    m.vanish_after = Some(6);
    m.stall_sleep = Some(Duration::from_millis(20));
    let opts = SuperviseOpts {
        policy: owners_policy(),
        journal: Some(journal.clone()),
        ..auto(30)
    };
    let (mut lines, _) = watch_lines_with(&mut m, &opts, |s| {
        s.set_turn_end_timing(TurnEndTiming {
            min_work: Duration::ZERO,
            short_backoff: Duration::from_millis(30),
            short_backoff_max: Duration::from_millis(60),
            ..TurnEndTiming::default()
        });
    });
    lines.extend(
        journal_records(&journal)
            .0
            .into_iter()
            .map(|r| r.line)
            .filter(|l| l.starts_with("DONE ")),
    );
    let _ = std::fs::remove_dir_all(&dir);
    (lines, m.needs_calls.clone())
}

/// A TALL LAND REPORT ON EVERY HARNESS IS READ WHOLE BEFORE IT LANDS
/// (`Session::said_read_whole` by the program's own reader,
/// [`aterm_phase::ScreenReader::said_whole`]): Gemini CLI's, agy's and Muse
/// Code's yield of Land's instruction a 60-row report whose head is in the
/// history above the screen, its rows on the screen a clean defense. With a
/// NEEDS YOU line near its head: no landing, the nudge typed, the need
/// raised. The recheck of d88a7bf289 found the cut read on Claude Code
/// alone: each of these landed on its last rows, the need unread.
/// NEGATIVE CONTROLS: with no need, the same report read whole lands; with
/// no history to read, it lands nothing (the words stay cut). agy's report
/// answers a message that wrapped its `NEEDS YOU:` hint onto a row of its
/// own: the history is read up to the rule above the message, never its
/// caret row, so the person's words are no part of the report.
#[test]
fn a_tall_land_report_on_every_harness_is_read_whole_before_it_lands() {
    use aterm_phase::prompt::fixtures::screen;
    use aterm_phase::{agy, gemini, muse};
    let gemini_tall = |need: bool| {
        let end = screen(gemini::fixtures::END_OF_TURN);
        let at = end
            .iter()
            .rposition(|r| r.starts_with("✦ "))
            .expect("the reply");
        tall_on(&end, at, &tall_said(need), "✦ ")
    };
    let muse_tall = |need: bool| {
        let end = screen(muse::fixtures::END_OF_TURN_1_4_10);
        let at = end
            .iter()
            .position(|r| r.starts_with("◆ Hi!"))
            .expect("the reply");
        tall_on(&end, at, &tall_said(need), "◆ ")
    };
    // agy's reply has no head: its rows two columns in under the message.
    let agy_tall = |need: bool| {
        let end = screen(agy::fixtures::END_OF_TURN);
        let user = end
            .iter()
            .position(|r| r.starts_with("> Write about"))
            .expect("the message");
        let composer = (user..end.len())
            .find(|&i| end[i].starts_with('─'))
            .expect("the composer's rule");
        let mut drawn = end[..user].to_vec();
        drawn.extend([
            "> Land it all in the remote main branch. Put what only a person can give on a line \
             starting"
                .to_string(),
            "  NEEDS YOU: and carry on.".to_string(),
            String::new(),
        ]);
        drawn.extend(tall_said(need).iter().map(|l| {
            if l.is_empty() {
                String::new()
            } else {
                format!("  {l}")
            }
        }));
        drawn.push(String::new());
        drawn.extend(end[composer..].iter().cloned());
        let screen = drawn.split_off(drawn.len() - end.len());
        (screen, drawn)
    };
    type Tall = Box<dyn Fn(bool) -> (Vec<String>, Vec<String>)>;
    type Harness = (
        &'static str,
        fn(Vec<Vec<String>>) -> Mock,
        &'static str,
        &'static str,
        Tall,
    );
    let harnesses: [Harness; 3] = [
        (
            "gemini",
            gemini_mock,
            gemini::fixtures::BUSY_THINKING,
            gemini::fixtures::END_OF_TURN,
            Box::new(gemini_tall),
        ),
        (
            "agy",
            agy_mock,
            agy::fixtures::BUSY,
            agy::fixtures::END_OF_TURN,
            Box::new(agy_tall),
        ),
        (
            "muse",
            muse_mock,
            muse::fixtures::BUSY_1_4_10,
            muse::fixtures::END_OF_TURN_1_4_10,
            Box::new(muse_tall),
        ),
    ];
    let landed = |lines: &[String]| {
        lines
            .iter()
            .any(|l| l.starts_with("DONE ") && l.contains(&format!(" rule={RULE_LAND} ")))
    };
    for (program, mock, busy, work, tall) in harnesses {
        let (busy, work) = (screen(busy), screen(work));
        let (cut, _) = tall(true);
        assert!(
            !program_reader(program, &cut).said_whole(&cut),
            "{program}: the report's head is above the screen"
        );
        let (lines, needs) = tall_landing(mock, &busy, &work, tall(true), true);
        assert!(!landed(&lines), "{program}: {lines:#?}");
        assert!(
            lines.iter().any(|l| l.contains(&format!(
                " rule={} ",
                crate::supervise::policy::turn_end::RULE_LAND_NUDGE
            ))),
            "{program}: the nudge: {lines:#?}"
        );
        assert!(
            needs
                .first()
                .is_some_and(|c| c.starts_with("set attention owner=needs ")
                    && c.contains("the signing credential")),
            "{program}: the need raised: {needs:#?}\n{lines:#?}"
        );
        // NEGATIVE CONTROL: no need — read whole, it lands.
        let (lines, needs) = tall_landing(mock, &busy, &work, tall(false), true);
        assert!(landed(&lines), "{program}: {lines:#?}");
        assert!(needs.is_empty(), "{program}: {needs:#?}");
        // NEGATIVE CONTROL: no history — cut, it lands nothing.
        let (lines, _) = tall_landing(mock, &busy, &work, tall(false), false);
        assert!(!landed(&lines), "{program}: {lines:#?}");
    }
}

/// A NEED SAID EARLIER IN A TURN WHOSE START IS ABOVE THE SCREEN IS READ
/// BEFORE IT LANDS (`Session::said_read_whole` on Claude Code's whole turn,
/// [`aterm_phase::turn_whole`]): the land act's yield a turn whose last
/// message, a clean defense, fits on the screen, but whose earlier message —
/// a NEEDS YOU said before a tool call — and the `❯` row that opened it are
/// in the history above. The loop reads the history up to that row: no
/// landing, the nudge typed, the need raised. The recheck of d88a7bf289
/// found the earlier message never read where the last one fit. NEGATIVE
/// CONTROL: the same turn with no need lands. A TURN WHOSE START CANNOT BE
/// READ LANDS NOTHING (the recheck of ea564676a3): with no history to read,
/// or a turn of 140 tool calls whose `❯` row is further up than the
/// history is looked through (`OWNER_ROWS`), the need at its start unread,
/// no landing and the nudge typed — where the build before landed on the
/// screen's words, the need never raised.
#[test]
fn a_need_said_earlier_in_a_turn_above_the_screen_is_read_before_it_lands() {
    let turn_of = |need: bool, calls: usize| -> (Vec<String>, Vec<String>) {
        let mut drawn: Vec<String> = vec![
            "❯ Land it all in the remote main branch.".to_string(),
            String::new(),
            "⏺ Merged the lexer and its suites.".to_string(),
        ];
        if need {
            drawn.push("  NEEDS YOU: the signing credential".to_string());
        }
        for call in 0..calls {
            drawn.extend([
                String::new(),
                format!("⏺ Bash(git log --oneline -1 branch-{call})"),
                format!("  ⎿  {call:04}abc merged branch {call}"),
            ]);
        }
        drawn.extend([String::new(), "⏺ Bash(git push origin main)".to_string()]);
        drawn.push("  ⎿  To github.com:a/parser.git".to_string());
        drawn.extend((0..40).map(|i| format!("     {i:02}a1b2c..{i:02}d3e4f  main -> main")));
        drawn.extend(rows(&[
            "",
            "⏺ Nothing left: all of it is merged into the remote main branch.",
            "",
            "✻ Worked for 12m 2s · done 4:24 PM",
            "",
        ]));
        drawn.extend(composer("  ⏵⏵ bypass permissions on (shift+tab to cycle)"));
        let screen = drawn.split_off(drawn.len() - 30);
        (screen, drawn)
    };
    let turn = |need: bool| turn_of(need, 0);
    let (screen, _) = turn(true);
    assert!(
        aterm_phase::said_whole(&screen) && !aterm_phase::turn_whole(&screen),
        "the last message on the screen, the turn's start above it"
    );
    let landed = |lines: &[String]| {
        lines
            .iter()
            .any(|l| l.starts_with("DONE ") && l.contains(&format!(" rule={RULE_LAND} ")))
    };
    let busy = busy_screen();
    let work = ended(WORK);
    let (lines, needs) = tall_landing(Mock::new, &busy, &work, turn(true), true);
    assert!(!landed(&lines), "{lines:#?}");
    assert!(
        lines.iter().any(|l| l.contains(&format!(
            " rule={} ",
            crate::supervise::policy::turn_end::RULE_LAND_NUDGE
        ))),
        "the nudge: {lines:#?}"
    );
    assert!(
        needs
            .first()
            .is_some_and(|c| c.starts_with("set attention owner=needs ")
                && c.contains("the signing credential")),
        "the need raised: {needs:#?}\n{lines:#?}"
    );
    // NEGATIVE CONTROL: no need.
    let (lines, needs) = tall_landing(Mock::new, &busy, &work, turn(false), true);
    assert!(landed(&lines), "{lines:#?}");
    assert!(needs.is_empty(), "{needs:#?}");
    // A TURN WHOSE START CANNOT BE READ: no history, or a turn longer than
    // the history is looked through.
    let nudged = |lines: &[String]| {
        lines.iter().any(|l| {
            l.contains(&format!(
                " rule={} ",
                crate::supervise::policy::turn_end::RULE_LAND_NUDGE
            ))
        })
    };
    for (why, read) in [
        ("no history", (turn(true), false)),
        ("140 calls", (turn_of(true, 140), true)),
        ("140 calls, no need", (turn_of(false, 140), true)),
    ] {
        let ((screen, above), history) = read;
        assert!(above.len() > 400 || !history, "{why}: {}", above.len());
        let (lines, _) = tall_landing(Mock::new, &busy, &work, (screen, above), history);
        assert!(!landed(&lines), "{why}: {lines:#?}");
        assert!(nudged(&lines), "{why}: the nudge: {lines:#?}");
    }
}

/// A NEED SAID BEFORE A TOOL CALL ON EVERY HARNESS IS READ BEFORE IT LANDS
/// (`TurnEndReading::of` and `Session::said_read_whole` by the program's
/// own reader, [`aterm_phase::ScreenReader::turn_said_before`]): Gemini
/// CLI's, agy's and Muse Code's yield of Land's instruction a turn whose
/// first reply says NEEDS YOU, then a tool call, then a clean defense. With
/// the whole turn on the screen, and with its start in the history above
/// (sixty tool rows tall): no landing, the nudge typed, the need raised. The
/// recheck of ea564676a3 found the turn's earlier words read on Claude Code
/// alone: each of these landed on its last reply, the need unread.
/// NEGATIVE CONTROLS: the same turns with no need land; with no history to
/// read, the tall turn lands nothing (its start unread).
#[test]
fn a_need_said_before_a_tool_call_on_every_harness_is_read_before_it_lands() {
    use aterm_phase::prompt::fixtures::screen;
    use aterm_phase::{agy, gemini, muse};
    let before = |need: bool, head: &str| -> Vec<String> {
        if need {
            vec![
                format!("{head}NEEDS YOU: the signing credential"),
                "  I will push the branch now.".to_string(),
            ]
        } else {
            vec![format!("{head}I will push the branch now.")]
        }
    };
    let defense = "Nothing left: all of it is merged into the remote main branch.";
    let calls = |tall: bool| if tall { 60 } else { 1 };
    // The screen: the whole turn, or the end's height of its foot.
    let split = |mut drawn: Vec<String>, height: usize, tall: bool| {
        if tall {
            let screen = drawn.split_off(drawn.len() - height);
            (screen, drawn)
        } else {
            (drawn, Vec::new())
        }
    };
    let gemini_turn = move |need: bool, tall: bool| {
        let end = screen(gemini::fixtures::END_OF_TURN);
        let at = end
            .iter()
            .rposition(|r| r.starts_with("✦ "))
            .expect("the reply");
        let mut drawn = end[..at].to_vec();
        drawn.extend(before(need, "✦ "));
        drawn.push(String::new());
        drawn.push("╭────────────────────────────────────────────╮".to_string());
        for call in 0..calls(tall) {
            drawn.push(format!(
                "│ ✓  Shell git push origin branch-{call:02}             │"
            ));
        }
        drawn.push("╰────────────────────────────────────────────╯".to_string());
        drawn.push(String::new());
        drawn.push(format!("✦ {defense}"));
        drawn.extend(end[at + 1..].iter().cloned());
        split(drawn, end.len(), tall)
    };
    let agy_turn = move |need: bool, tall: bool| {
        let end = screen(agy::fixtures::END_OF_TURN);
        let user = end
            .iter()
            .position(|r| r.starts_with("> Write about"))
            .expect("the message");
        let composer = (user..end.len())
            .find(|&i| end[i].starts_with('─'))
            .expect("the composer's rule");
        let mut drawn = end[..user].to_vec();
        drawn.push("> Land it all in the remote main branch.".to_string());
        drawn.push(String::new());
        drawn.extend(before(need, "  "));
        drawn.push(String::new());
        for call in 0..calls(tall) {
            drawn.push(format!(
                "● Ran git push origin branch-{call:02} (ctrl+o to expand)"
            ));
        }
        drawn.push(String::new());
        drawn.push(format!("  {defense}"));
        drawn.push(String::new());
        drawn.extend(end[composer..].iter().cloned());
        split(drawn, end.len(), tall)
    };
    let muse_turn = move |need: bool, tall: bool| {
        let end = screen(muse::fixtures::END_OF_TURN_1_4_10);
        let at = end
            .iter()
            .position(|r| r.starts_with("◆ Hi!"))
            .expect("the reply");
        let mut drawn = end[..at].to_vec();
        drawn.extend(before(need, "◆ "));
        drawn.push(String::new());
        for call in 0..calls(tall) {
            drawn.push(format!(
                "◆ Ran command · Push branch-{call:02} · ✓ · 2.3s · ctrl+o"
            ));
            drawn.push(String::new());
        }
        drawn.push(format!("◆ {defense}"));
        drawn.extend(end[at + 1..].iter().cloned());
        split(drawn, end.len().max(20), tall)
    };
    type Turn = Box<dyn Fn(bool, bool) -> (Vec<String>, Vec<String>)>;
    type Harness = (
        &'static str,
        fn(Vec<Vec<String>>) -> Mock,
        &'static str,
        &'static str,
        Turn,
    );
    let harnesses: [Harness; 3] = [
        (
            "gemini",
            gemini_mock,
            gemini::fixtures::BUSY_THINKING,
            gemini::fixtures::END_OF_TURN,
            Box::new(gemini_turn),
        ),
        (
            "agy",
            agy_mock,
            agy::fixtures::BUSY,
            agy::fixtures::END_OF_TURN,
            Box::new(agy_turn),
        ),
        (
            "muse",
            muse_mock,
            muse::fixtures::BUSY_1_4_10,
            muse::fixtures::END_OF_TURN_1_4_10,
            Box::new(muse_turn),
        ),
    ];
    let landed = |lines: &[String]| {
        lines
            .iter()
            .any(|l| l.starts_with("DONE ") && l.contains(&format!(" rule={RULE_LAND} ")))
    };
    let nudged = |lines: &[String]| {
        lines.iter().any(|l| {
            l.contains(&format!(
                " rule={} ",
                crate::supervise::policy::turn_end::RULE_LAND_NUDGE
            ))
        })
    };
    for (program, mock, busy, work, turn) in harnesses {
        let (busy, work) = (screen(busy), screen(work));
        for tall in [false, true] {
            let at = if tall {
                "above the screen"
            } else {
                "on the screen"
            };
            let (rows, _) = turn(true, tall);
            let reader = program_reader(program, &rows);
            assert_eq!(
                reader.said_tail(&rows).as_deref(),
                Some(defense),
                "{program} {at}: the last reply"
            );
            assert_eq!(
                reader.turn_whole(&rows),
                !tall,
                "{program} {at}: the turn's start"
            );
            let (lines, needs) = tall_landing(mock, &busy, &work, turn(true, tall), true);
            assert!(!landed(&lines), "{program} {at}: {lines:#?}");
            assert!(nudged(&lines), "{program} {at}: the nudge: {lines:#?}");
            assert!(
                needs
                    .first()
                    .is_some_and(|c| c.starts_with("set attention owner=needs ")
                        && c.contains("the signing credential")),
                "{program} {at}: the need raised: {needs:#?}\n{lines:#?}"
            );
            // NEGATIVE CONTROL: no need — it lands.
            let (lines, needs) = tall_landing(mock, &busy, &work, turn(false, tall), true);
            assert!(landed(&lines), "{program} {at}: {lines:#?}");
            assert!(needs.is_empty(), "{program} {at}: {needs:#?}");
        }
        // NEGATIVE CONTROL: no history — the tall turn's start unread, it
        // lands nothing.
        let (lines, _) = tall_landing(mock, &busy, &work, turn(false, true), false);
        assert!(!landed(&lines), "{program}: {lines:#?}");
        assert!(nudged(&lines), "{program}: the nudge: {lines:#?}");
    }
}

/// The reader the loop reads `program`'s screen `rows` with.
fn program_reader(program: &str, rows: &[String]) -> &'static dyn aterm_phase::ScreenReader {
    let name = if program == "gemini" { "node" } else { program };
    aterm_phase::identify(Some(name), rows)
}

/// A LANDING, AND A LOOP RESTARTED ON IT: the landed task is marked `done
/// why=landed` once, with the defense. A loop started again on the landed
/// screen (the host's worker restarted, a seamless update's successor)
/// reads the record — `done` already — takes the landing on at its first
/// point, whose words are still the landing's clean defense, types nothing
/// into the landed worker and marks nothing, and the snapshot stands.
/// NEGATIVE CONTROLS: the record put back to `working` (a mark the first
/// loop never got answered), the restarted loop lands and publishes it; and
/// a restarted loop whose first point is a report that is no defense (a
/// turn after the landing that no loop watched, the review of 2026-10-20)
/// takes nothing from the `done` record: the record reopened, Land's
/// instruction typed, and the task landed and published again.
#[test]
fn a_landing_is_published_once_and_a_restarted_loop_marks_nothing() {
    let root = crate::supervise::ScratchDir::new("task", "marker");
    let tasks = root.join("tasks");
    let text = transcript_of(&landing_rows(&landed_reply()));
    let host = TaskHost::reading(&root.join("t.jsonl"), &[&text]);
    let run_on = |screens: Vec<Vec<String>>, task: Option<(u64, String)>| {
        let held = screens.len() > 1;
        let mut m = Mock::new(screens);
        landing(&mut m);
        // The landed screen alone sits as it is: nothing to release.
        m.turn_releases = m.turn_releases.filter(|_| held);
        m.vanish_after = Some(4);
        m.task = task;
        let _ = tasked_watch(&mut m, &host, &tasks, None);
        m
    };
    let run = |task: Option<(u64, String)>| run_on(landing_screens(&landed_reply()), task);
    let m = run(working_task());
    let path = tasks.join("s-1-1.result.md");
    assert_eq!(
        task_marks(&m),
        [done_mark("landed", landed_result().len(), &path)]
    );
    assert_eq!(
        std::fs::read_to_string(&path).expect("snapshot"),
        landed_result()
    );
    // The loop again, on the record the first one left.
    let done = m.task.clone();
    std::fs::write(&path, "the snapshot as the first loop left it").expect("mark it");
    let again = run_on(vec![ended(&landed_reply())], done.clone());
    assert_eq!(again.task_requests, ["task"], "read, never marked");
    assert_eq!(again.turns, 0, "nothing typed into the landed worker");
    assert_eq!(again.task, done, "the record stands");
    assert_eq!(
        std::fs::read_to_string(&path).expect("snapshot"),
        "the snapshot as the first loop left it",
        "and the snapshot"
    );
    // NEGATIVE CONTROL: a record still `working`.
    let unanswered = run(working_task());
    assert_eq!(
        task_marks(&unanswered),
        [done_mark("landed", landed_result().len(), &path)]
    );
    // NEGATIVE CONTROL: the `done` record, the first point no defense.
    let undefended = run(done.clone());
    assert!(
        undefended
            .task_requests
            .iter()
            .any(|r| r.starts_with("task mark working ")),
        "reopened: {:?}",
        undefended.task_requests
    );
    assert_eq!(undefended.turns, 1, "Land's instruction");
    assert!(
        undefended
            .task_requests
            .last()
            .is_some_and(|r| r.starts_with("task mark done why=landed ")),
        "{:?}",
        undefended.task_requests
    );
    // A worker the window host's held deadline stalled — a box no rule knew,
    // which a person answered, and it went on to land — is published as a
    // working one is, its result under the stall's rev.
    let stalled = |why: &str| {
        Some((
            2,
            format!("state=stalled from=s-0a1b since_ms=0 result_bytes=0 why={why}"),
        ))
    };
    let held = run(stalled("held"));
    assert_eq!(
        task_marks(&held),
        [done_mark(
            "landed",
            landed_result().len(),
            &tasks.join("s-1-2.result.md")
        )]
    );
    // NEGATIVE CONTROL: the launcher's stall typed nothing, so no landing of
    // this loop's is that task's.
    let shell = run(stalled("shell"));
    assert!(task_marks(&shell).is_empty(), "{:?}", shell.task_requests);
    // A loop with nowhere to snapshot (no tasks dir) leaves the record
    // alone: the window's harness publishes it.
    let mut m = Mock::new(landing_screens(&landed_reply()));
    landing(&mut m);
    m.vanish_after = Some(4);
    m.task = working_task();
    let opts = SuperviseOpts {
        policy: owners_policy(),
        idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
        tasks: None,
        ..auto(30)
    };
    let mut s = session(&mut m, Some("@s-1".to_string()));
    s.set_clock(TEST_NOW, PDT);
    s.set_zone_lookup(test_zones);
    let mut out: Vec<u8> = Vec::new();
    let _ = s.watch(&opts, &mut out);
    drop(s);
    assert!(m.task_requests.is_empty(), "{:?}", m.task_requests);
    assert_eq!(m.task, working_task());
}

/// THE LANDING READ BEFORE CLAUDE CODE WROTE ITS REPLY (F1, 2.1.301 on a
/// real login): the host's read at the landing point holds Land's
/// instruction and no reply, and the transcript on disk has the defense and
/// the turn's `turn_duration` row by the time it is read again — the record
/// is marked with that defense (`crate::harness::result::settled`).
/// NEGATIVE CONTROL: with no transcript left to read again, the mark is the
/// miss it always was (`result_bytes=0`).
#[test]
fn a_landing_read_before_the_reply_was_written_waits_for_the_turns_end() {
    let root = crate::supervise::ScratchDir::new("task", "lag");
    let tasks = root.join("tasks");
    let mut rows = landing_rows(&landed_reply());
    let lagging = transcript_of(&rows[..rows.len() - 1]);
    rows.push(
        r#"{"parentUuid":"a-land","isSidechain":false,"type":"system","subtype":"turn_duration","durationMs":9000,"uuid":"td","sessionId":"0b2299fa","version":"2.1.301"}"#
            .to_string(),
    );
    let whole = transcript_of(&rows);
    let run = |transcript: &Path| {
        let host = TaskHost::reading(transcript, &[&lagging]);
        let mut m = Mock::new(landing_screens(&landed_reply()));
        landing(&mut m);
        m.vanish_after = Some(4);
        m.task = working_task();
        let _ = tasked_watch(&mut m, &host, &tasks, None);
        m
    };
    let on_disk = root.join("t.jsonl");
    std::fs::write(&on_disk, &whole).expect("the transcript as Claude Code finished it");
    let path = tasks.join("s-1-1.result.md");
    let m = run(&on_disk);
    assert_eq!(
        task_marks(&m),
        [done_mark("landed", landed_result().len(), &path)]
    );
    assert_eq!(
        std::fs::read_to_string(&path).expect("snapshot"),
        landed_result()
    );
    // NEGATIVE CONTROL: nothing to read again.
    let m = run(&root.join("gone.jsonl"));
    assert_eq!(task_marks(&m), [done_mark("landed", 0, &path)]);
    assert_eq!(std::fs::read_to_string(&path).expect("snapshot"), "");
}

/// `row` (a transcript row, [`task_row`]) stamped `at` (unix seconds), as
/// Claude Code stamps each row it writes.
fn stamped(row: String, at: i64) -> String {
    let at = aterm_types::rfc3339::format_rfc3339(u64::try_from(at).expect("a stamp"));
    row.replacen('{', &format!(r#"{{"timestamp":"{at}","#), 1)
}

/// A turn's `system turn_duration` end row, stamped `at` (unix seconds).
fn end_row_at(at: i64) -> String {
    stamped(
        r#"{"parentUuid":"p","isSidechain":false,"type":"system","subtype":"turn_duration","durationMs":9000,"uuid":"td","sessionId":"0b2299fa","version":"2.1.301"}"#
            .to_string(),
        at,
    )
}

/// A background command's `<task-notification>` row (the user row Claude
/// Code wakes the worker on), stamped `at` (unix seconds).
fn notification_at(at: i64) -> String {
    stamped(
        task_row(
            "user",
            "u-woke",
            "",
            "<task-notification>\n<task-id>b1</task-id>\n<status>completed</status>\n\
             </task-notification>",
        ),
        at,
    )
}

/// THE TURN THE LANDING WAS READ ON IS THE ONE SNAPSHOTTED — the loop hands
/// the read that decided the landing to the result reader: the worker
/// answered Land's instruction (the retired token under it, which the
/// result drops), a background command's `<task-notification>` woke it and
/// the woken turn ran a tool, all in the landing's read; the woken turn's
/// reply (the token under it too) and end row
/// are on disk by the next read. Where the notification was written BEFORE
/// the landing's read, the wake's turn is waited for and its reply is the
/// result. NEGATIVE CONTROL, each of the other: the same rows with the
/// notification written AFTER that read (a shell that ended once the
/// defense was on the screen) — the earlier reply, the wake's never taken.
#[test]
fn the_landing_points_showing_places_the_turn_snapshotted() {
    let root = crate::supervise::ScratchDir::new("task", "shown");
    let tasks = root.join("tasks");
    let run = |woke_at: i64| {
        let first = vec![
            stamped(
                task_row("user", "u-task", "", "Fix the parser."),
                TEST_NOW - 300,
            ),
            stamped(
                task_row("assistant", "a-work", "msg_1", WORK),
                TEST_NOW - 200,
            ),
            end_row_at(TEST_NOW - 200),
            stamped(task_row("user", "u-land", "", LAND), TEST_NOW - 150),
            stamped(
                task_row(
                    "assistant",
                    "a-held",
                    "msg_2",
                    "Started the review in the background.\nATERM-TASK-DONE",
                ),
                TEST_NOW - 110,
            ),
            end_row_at(TEST_NOW - 110),
            notification_at(woke_at),
        ];
        let mut whole = first.clone();
        whole.extend([
            stamped(
                task_row(
                    "assistant",
                    "a-wake",
                    "msg_3",
                    "The review found nothing more.\nATERM-TASK-DONE",
                ),
                woke_at + 5,
            ),
            end_row_at(woke_at + 5),
        ]);
        let on_disk = root.join(format!("t-{woke_at}.jsonl"));
        std::fs::write(&on_disk, transcript_of(&whole)).expect("the transcript on disk");
        let host = TaskHost::reading(&on_disk, &[&transcript_of(&first)]);
        let mut m = Mock::new(landing_screens(&landed_reply()));
        landing(&mut m);
        m.vanish_after = Some(4);
        m.task = working_task();
        let _ = tasked_watch(&mut m, &host, &tasks, None);
        let path = tasks.join("s-1-1.result.md");
        (
            task_marks(&m),
            std::fs::read_to_string(&path).expect("snapshot"),
            path,
        )
    };
    let (marks, snapshot, path) = run(TEST_NOW - 30);
    let report = format!("{WORK}\n\nThe review found nothing more.");
    assert_eq!(snapshot, report);
    assert_eq!(marks, [done_mark("landed", report.len(), &path)]);
    // NEGATIVE CONTROL: the notification written after the landing's read.
    let (marks, snapshot, path) = run(TEST_NOW + 30);
    let report = format!("{WORK}\n\nStarted the review in the background.");
    assert_eq!(snapshot, report);
    assert_eq!(marks, [done_mark("landed", report.len(), &path)]);
}

/// NEVER A PERSON'S OWN EXCHANGE: their greeting, answered in seconds, is a
/// `done` of theirs (`LEFT … rule=left-to-person@v1`) — even with the
/// retired marker under it — and a tasked session's record is not read or
/// marked for it. (On a tasked worker it comes only from a person typing at
/// its window: the task itself is argv, and a manager's follow-up is a
/// `turn`, no window gesture.) NEGATIVE CONTROL: the same words ending a
/// turn of the worker's own, nobody's stamp, get Land's instruction, and the
/// clean defense that answers it is marked.
#[test]
fn a_persons_own_exchange_marks_no_task() {
    let root = crate::supervise::ScratchDir::new("task", "left");
    let tasks = root.join("tasks");
    let said = format!("Hi! What would you like me to work on?\n{FINISHED}");
    let quick = |said: &str| {
        let mut r = rows(&[&format!("⏺ {said}"), ""]);
        r.extend(composer("  ⏵⏵ bypass permissions on (shift+tab to cycle)"));
        r
    };
    let greeting = transcript_of(&[
        task_row("user", "u-hi", "", "hi"),
        task_row("assistant", "a-hi", "msg_1", &said),
    ]);
    let landed = transcript_of(&landing_rows(&landed_reply()));
    let run = |person: bool| {
        let journal = root.join(format!("journal-{person}.jsonl"));
        let (screens, text) = if person {
            (vec![busy_screen(), quick(&said)], &greeting)
        } else {
            (
                vec![
                    busy_screen(),
                    quick(&said),
                    busy_screen(),
                    quick(&landed_reply()),
                ],
                &landed,
            )
        };
        let host = TaskHost::reading(&root.join("t.jsonl"), &[text]);
        let mut m = Mock::new(screens);
        landing(&mut m);
        m.vanish_after = Some(8);
        if person {
            m.human = vec!["2000"];
        }
        m.task = working_task();
        let mut out: Vec<u8> = Vec::new();
        let opts = SuperviseOpts {
            policy: SupervisorConfig {
                human_grace_s: 0,
                ..owners_policy()
            },
            journal: Some(journal.clone()),
            idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
            tasks: Some(tasks.clone()),
            ..auto(1)
        };
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_turn_end_timing(TurnEndTiming {
            short_backoff: Duration::from_millis(30),
            short_backoff_max: Duration::from_millis(60),
            ..TurnEndTiming::default()
        });
        let _ = s.watch(&opts, &mut out);
        drop(s);
        let left = journal_records(&journal)
            .0
            .into_iter()
            .filter(|r| r.line.starts_with("LEFT "))
            .count();
        (m, left)
    };
    let (m, left) = run(true);
    assert_eq!(left, 1, "the person's exchange");
    assert_eq!(m.task_requests, ["task"], "the loop's first read, no mark");
    // NEGATIVE CONTROL: nobody's stamp.
    let (m, left) = run(false);
    assert_eq!(left, 0);
    assert_eq!(task_marks(&m).len(), 1, "{:?}", m.task_requests);
}

/// OPEN AGAIN, AND LANDED AGAIN: after the landing is published, someone
/// else's turn (a manager's follow-up) that ends with no defense opens the
/// task again — the record is marked `working why=turn`. And a follow-up
/// landed in turn — Land's act typed at its end and answered with a clean
/// defense, the server having moved the record back to `working` at that
/// turn (`Mock::task_reopens_at`) — is a landing of its own: a second
/// snapshot, under the record's new rev, of the second defense. NEGATIVE
/// CONTROL: with no turn after the landing, nothing more is read or marked.
#[test]
fn someone_elses_turn_opens_the_task_again_and_its_landing_is_published_again() {
    const HALF: &str = "Half of the README is in.";
    const AGAIN: &str = "Updated the README and pushed it.\nNothing left: the README is on the \
                         remote main branch.";
    let root = crate::supervise::ScratchDir::new("task", "reopen");
    let tasks = root.join("tasks");
    let first = landing_rows(&landed_reply());
    let one = transcript_of(&first);
    let first_mark = done_mark(
        "landed",
        landed_result().len(),
        &tasks.join("s-1-1.result.md"),
    );
    // A follow-up that is not landed.
    let host = TaskHost::reading(&root.join("t.jsonl"), &[&one]);
    let mut screens = landing_screens(&landed_reply());
    screens.extend([busy_screen(), ended(HALF)]);
    let mut m = Mock::new(screens);
    landing(&mut m);
    m.vanish_after = Some(4);
    m.task = working_task();
    let lines = tasked_watch(&mut m, &host, &tasks, None);
    assert_eq!(
        task_marks(&m),
        [first_mark.clone(), "task mark working why=turn".to_string()],
        "{lines:#?}"
    );
    // A follow-up landed in turn.
    let again_reply = AGAIN.to_string();
    let mut rows = first.clone();
    rows.extend([
        task_row("user", "u-more", "", "Also update the README."),
        task_row("assistant", "a-more", "msg_3", HALF),
        task_row("user", "u-nudge", "", LAND_NUDGE),
        task_row("assistant", "a-again", "msg_4", &again_reply),
    ]);
    let two = transcript_of(&rows);
    let relanded = |reopens: Option<usize>| {
        let host = TaskHost::reading(&root.join("t.jsonl"), &[&one, &two]);
        let mut screens = landing_screens(&landed_reply());
        screens.extend([
            busy_screen(),
            ended(HALF),
            busy_screen(),
            ended(&again_reply),
        ]);
        let mut m = Mock::new(screens);
        m.history_served();
        m.autopilot = Some("land");
        // The work's end sits until Land's instruction, the follow-up's
        // until Land's next act.
        m.turn_gates = vec![1, 5];
        m.vanish_after = Some(4);
        m.task = working_task();
        m.task_reopens_at = reopens;
        let lines = tasked_watch(&mut m, &host, &tasks, None);
        (m, lines)
    };
    let second = tasks.join("s-1-3.result.md");
    // The landing's result: the follow-up's report before Land's nudge, then
    // the defense that landed it.
    let again_result = format!("{HALF}\n\n{AGAIN}");
    let (m, lines) = relanded(Some(5));
    assert_eq!(
        task_marks(&m),
        [
            first_mark.clone(),
            done_mark("landed", again_result.len(), &second)
        ],
        "{lines:#?}"
    );
    assert_eq!(
        std::fs::read_to_string(&second).expect("snapshot"),
        again_result
    );
    assert!(
        !tasks.join("s-1-1.result.md").exists(),
        "the new landing prunes the previous result pair"
    );
    // The same follow-up typed with `send` (or at the keyboard): the server
    // leaves the record `done`, and the loop opens it again itself at the
    // follow-up's end before publishing its landing under the new rev.
    let (m, lines) = relanded(None);
    assert_eq!(
        task_marks(&m),
        [
            first_mark,
            "task mark working why=turn".to_string(),
            done_mark("landed", again_result.len(), &second),
        ],
        "{lines:#?}"
    );
    // NEGATIVE CONTROL: nothing after the landing.
    let host = TaskHost::reading(&root.join("t.jsonl"), &[&one]);
    let mut m = Mock::new(landing_screens(&landed_reply()));
    landing(&mut m);
    m.vanish_after = Some(4);
    m.task = working_task();
    let _ = tasked_watch(&mut m, &host, &tasks, None);
    assert_eq!(
        m.task_requests.len(),
        3,
        "the loop's first read, the read at the landing and the mark: {:?}",
        m.task_requests
    );
}

/// THE SNAPSHOT IS THE LANDING'S: the live upgrade's READY notice, typed by
/// the host into the landed worker, and its answer change nothing — the
/// record is not read again, nothing is marked (its answer is not someone
/// else's turn), and the result file stands — though the
/// transcript has grown by that exchange. NEGATIVE CONTROL: the same READY
/// turn typed by nobody of the harness's (no host step) is someone else's
/// turn, and opens the task again.
#[test]
fn the_upgrades_ready_after_the_landing_leaves_the_snapshot_and_the_record() {
    let root = crate::supervise::ScratchDir::new("task", "ready");
    let tasks = root.join("tasks");
    let done = landing_rows(&landed_reply());
    let mut later = done.clone();
    later.extend([
        task_row(
            "user",
            "u-ready",
            "",
            "[aterm harness] A newer Claude Code is installed.",
        ),
        task_row("assistant", "a-ready", "msg_r", "READY"),
    ]);
    let run = |ready: bool| {
        let host = Arc::new(TaskHost {
            path: root.join("t.jsonl"),
            texts: std::sync::Mutex::new(
                [transcript_of(&done), transcript_of(&later)]
                    .into_iter()
                    .collect(),
            ),
            ready,
            ..TaskHost::default()
        });
        let mut screens = landing_screens(&landed_reply());
        screens.extend([
            // The point read again: where the host takes its step.
            ended(&landed_reply()),
            busy_screen(),
            ended("READY"),
        ]);
        let mut m = Mock::new(screens);
        landing(&mut m);
        m.vanish_after = Some(4);
        // The cursor in the composer, where Claude Code keeps it at an idle
        // point: the reading the host's step needs.
        m.cursor_on_caret = true;
        m.task = working_task();
        let lines = tasked_watch(&mut m, &host, &tasks, None);
        (m, lines, host)
    };
    let path = tasks.join("s-1-1.result.md");
    let (m, lines, host) = run(true);
    assert_eq!(
        host.steps.load(Ordering::SeqCst),
        1,
        "the notice: {lines:#?}"
    );
    assert_eq!(
        task_marks(&m),
        [done_mark("landed", landed_result().len(), &path)],
        "{lines:#?}"
    );
    assert_eq!(
        m.task_requests.len(),
        3,
        "the loop's first read, the read at the landing and the mark: {:?}",
        m.task_requests
    );
    assert_eq!(
        host.asks.load(Ordering::SeqCst),
        1,
        "read once, at the landing"
    );
    assert_eq!(
        std::fs::read_to_string(&path).expect("snapshot"),
        landed_result()
    );
    // NEGATIVE CONTROL: the same turn, nobody of the harness's.
    let (m, lines, _) = run(false);
    assert_eq!(
        task_marks(&m),
        [
            done_mark("landed", landed_result().len(), &path),
            "task mark working why=turn".to_string(),
        ],
        "{lines:#?}"
    );
}

/// THE LANDING IS PUBLISHED BEFORE THE HOST'S STEP TAKES ITS POINT: a host
/// that wants the very point the defense lands (a Claude Code update
/// installed while the task ran, a relaunched agent's continuation) types
/// its turn there — and the landing was read and marked as the point was
/// folded in, before the step: the transcript read once, with no step
/// taken, and the snapshot is the defense, never the exchange the step typed
/// after it. (The host passes the turn of work's point, where Land's
/// instruction goes.) NEGATIVE CONTROL: the transcript as the step leaves it
/// reads the host's exchange as its newest turn's result.
#[test]
fn the_landing_is_published_before_the_hosts_step_takes_its_point() {
    let root = crate::supervise::ScratchDir::new("task", "first");
    let tasks = root.join("tasks");
    let done = landing_rows(&landed_reply());
    let mut later = done.clone();
    later.extend([
        task_row(
            "user",
            "u-host",
            "",
            "[aterm harness] A newer Claude Code is installed.",
        ),
        task_row("assistant", "a-ready", "msg_r", "READY"),
    ]);
    let host = Arc::new(TaskHost {
        path: root.join("t.jsonl"),
        texts: std::sync::Mutex::new([transcript_of(&done)].into_iter().collect()),
        stepped: Some(transcript_of(&later)),
        wanting: AtomicBool::new(true),
        passes: std::sync::atomic::AtomicUsize::new(1),
        ..TaskHost::default()
    });
    let mut screens = landing_screens(&landed_reply());
    screens.extend([busy_screen(), ended("READY")]);
    let mut m = Mock::new(screens);
    landing(&mut m);
    m.vanish_after = Some(4);
    m.cursor_on_caret = true;
    m.task = working_task();
    let lines = tasked_watch(&mut m, &host, &tasks, None);
    assert_eq!(
        host.steps.load(Ordering::SeqCst),
        1,
        "the host's turn at the landing point: {lines:#?}"
    );
    assert_eq!(
        *host.read_at.lock().unwrap(),
        [0],
        "read once, before the step"
    );
    let path = tasks.join("s-1-1.result.md");
    assert_eq!(
        task_marks(&m),
        [done_mark("landed", landed_result().len(), &path)],
        "{lines:#?}"
    );
    assert_eq!(
        std::fs::read_to_string(&path).expect("snapshot"),
        landed_result()
    );
    // NEGATIVE CONTROL: read after the step, the newest turn is the host's
    // exchange, and its words are what a late read would have published.
    assert_eq!(
        crate::harness::result::report(
            &transcript_of(&later),
            crate::harness::result::DoneBy::Turn
        )
        .map(|r| r.text),
        Ok("READY".to_string())
    );
}

/// A SLEEP AFTER THE LANDING PUBLISHES NOTHING MORE: the landing is
/// published, the live upgrade's READY notice is typed by the host into the
/// landed worker, and the Mac sleeps before its answer — the point's first
/// showing moves back by the night ([`TurnEndState::slept`]). The READY,
/// answered short, keeps the point ([`TurnEndState::point_number`]): the
/// record is not opened again, no second landing is marked, and the
/// snapshot stands. An identity read off the point's instant made the same
/// point a new one at the wake — `working why=turn`, then a done under a new
/// rev, read from the transcript the READY had moved.
#[test]
fn a_sleep_after_the_landing_marks_nothing_more_at_the_hosts_short_turn() {
    let root = crate::supervise::ScratchDir::new("task", "sleep");
    let tasks = root.join("tasks");
    let done = landing_rows(&landed_reply());
    let mut later = done.clone();
    later.extend([
        task_row(
            "user",
            "u-ready",
            "",
            "[aterm harness] A newer Claude Code is installed.",
        ),
        task_row("assistant", "a-ready", "msg_r", "READY"),
    ]);
    let host = Arc::new(TaskHost {
        path: root.join("t.jsonl"),
        texts: std::sync::Mutex::new(
            [transcript_of(&done), transcript_of(&later)]
                .into_iter()
                .collect(),
        ),
        ready: true,
        ..TaskHost::default()
    });
    // READY in seconds: a short turn of the host's.
    let ready: Vec<String> = ended("READY")
        .into_iter()
        .map(|r| r.replace("Worked for 12m 2s", "Worked for 2s"))
        .collect();
    let mut screens = landing_screens(&landed_reply());
    screens.extend([ended(&landed_reply()), busy_screen(), ready]);
    let mut m = Mock::new(screens);
    landing(&mut m);
    m.vanish_after = Some(4);
    m.cursor_on_caret = true;
    m.task = working_task();
    let opts = SuperviseOpts {
        policy: owners_policy(),
        idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
        tasks: Some(tasks.clone()),
        ..auto(30)
    };
    let mut out: Vec<u8> = Vec::new();
    let mut s = session(&mut m, Some("@s-1".to_string()));
    s.set_clock(TEST_NOW, PDT);
    s.set_zone_lookup(test_zones);
    *host.sleep.lock().unwrap() = Some(s.clock_jump_handle());
    let _ = s.watch(&opts, &mut out);
    let woke = s.wake_settle.is_some();
    drop(s);
    let lines = String::from_utf8(out).expect("utf-8");
    assert!(woke, "the Mac slept after the landing: {lines}");
    assert_eq!(host.steps.load(Ordering::SeqCst), 1, "the notice: {lines}");
    let path = tasks.join("s-1-1.result.md");
    assert_eq!(
        task_marks(&m),
        [done_mark("landed", landed_result().len(), &path)],
        "{lines}"
    );
    assert_eq!(m.turns, 1, "Land's instruction alone: {lines}");
    assert_eq!(
        std::fs::read_to_string(&path).expect("snapshot"),
        landed_result()
    );
}

/// AN OLDER BUILD'S `done` IS NO LANDING: a loop that starts on a record an
/// older build marked done by its marker or its done check (`why=marker`,
/// `why=done-check`) takes nothing on — the task goes on to Land's landing,
/// and the record is opened again and marked done with the landing's
/// result (`why=landed`). NEGATIVE CONTROL: the loop started on a record
/// still `working` marks only the landing.
#[test]
fn an_older_builds_done_record_is_opened_again_and_the_landing_published() {
    let root = crate::supervise::ScratchDir::new("task", "older-done");
    let tasks = root.join("tasks");
    let text = transcript_of(&landing_rows(&landed_reply()));
    let host = TaskHost::reading(&root.join("t.jsonl"), &[&text]);
    let run = |task: Option<(u64, String)>| {
        let mut m = Mock::new(landing_screens(&landed_reply()));
        landing(&mut m);
        m.vanish_after = Some(4);
        m.task = task;
        let lines = tasked_watch(&mut m, &host, &tasks, None);
        (task_marks(&m), lines)
    };
    for why in ["marker", "done-check"] {
        let older = Some((
            2,
            format!("state=done from=ctl since_ms=0 result_bytes=17 why={why}"),
        ));
        let (marks, lines) = run(older);
        // Opened again, under the record's next rev.
        let path = tasks.join("s-1-3.result.md");
        assert_eq!(
            marks.last(),
            Some(&done_mark("landed", landed_result().len(), &path)),
            "why={why}: {marks:#?} {lines:#?}"
        );
        assert!(
            marks.len() >= 2 && marks[0].starts_with("task mark working"),
            "why={why}: opened again first: {marks:#?}"
        );
    }
    // NEGATIVE CONTROL: the record still `working`.
    let working = Some((
        2,
        "state=working from=s-0a1b since_ms=0 result_bytes=0".to_string(),
    ));
    let (marks, lines) = run(working);
    let path = tasks.join("s-1-2.result.md");
    assert_eq!(
        marks,
        [done_mark("landed", landed_result().len(), &path)],
        "{lines:#?}"
    );
}

/// A LOOP STARTED ON A PUBLISHED LANDING TAKES IT ON: a loop that starts at
/// the point a loop before it landed and published (the record reads
/// `done`) meets the defense with no Land act of its own before it, which
/// its policy alone would answer with Land's instruction. The record, read
/// once at the loop's first fold, makes the landing this loop's: nothing is
/// typed, nothing is held back (no `SKIPPED` line: no act is decided), no
/// `DONE` line is said again, and nothing is marked — though the run stays
/// on for several more waits at that point. NEGATIVE CONTROLS: the record
/// still `working` (no loop published a landing), Land's instruction is
/// typed; so is it at an older build's `done` record (`why=marker`,
/// `why=done-check`: no landing); and under Cruise no record is done — the
/// defense is a done claim, and Cruise's defend prompt is typed.
#[test]
fn a_loop_started_at_a_published_landing_types_nothing() {
    let root = crate::supervise::ScratchDir::new("task", "held-check");
    let text = transcript_of(&landing_rows(&landed_reply()));
    let host = TaskHost::reading(&root.join("t.jsonl"), &[&text]);
    let record = |why: &str| {
        Some((
            2,
            format!(
                "state=done from=ctl since_ms=0 result_bytes={} why={why} result_path={}",
                landed_result().len(),
                aterm_codec::pct::encode(&root.join("tasks/s-1-1.result.md").to_string_lossy())
            ),
        ))
    };
    let published = record("landed");
    let run = |task: Option<(u64, String)>, word: &'static str| {
        let journal = root.join(format!(
            "journal-{word}-{}.jsonl",
            task.as_ref().map_or(0, |t| t.0)
        ));
        let mut m = Mock::new(vec![ended(&landed_reply())]);
        m.history_served();
        m.autopilot = Some(word);
        // Several waits at the point past the read: a decision made again
        // there would read again, and type.
        m.vanish_after = Some(6);
        m.task = task;
        let opts = SuperviseOpts {
            policy: owners_policy(),
            journal: Some(journal.clone()),
            idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
            tasks: Some(root.join("tasks")),
            ..auto(30)
        };
        let mut out: Vec<u8> = Vec::new();
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(TEST_NOW, PDT);
        s.set_zone_lookup(test_zones);
        s.set_turn_end_timing(TurnEndTiming {
            short_backoff: Duration::from_millis(30),
            short_backoff_max: Duration::from_millis(60),
            ..TurnEndTiming::default()
        });
        let _ = s.watch(&opts, &mut out);
        drop(s);
        // What it printed, and what it journaled.
        let mut lines: Vec<String> = String::from_utf8(out)
            .expect("utf-8")
            .lines()
            .map(str::to_string)
            .collect();
        lines.extend(journal_records(&journal).0.into_iter().map(|r| r.line));
        (m, lines)
    };
    // The lines of a kind, each once though printed and journaled.
    let said = |lines: &[String], kind: &str| {
        lines
            .iter()
            .filter(|l| l.starts_with(kind))
            .collect::<std::collections::BTreeSet<_>>()
            .len()
    };
    let typed = |lines: &[String], rule: &str| {
        lines
            .iter()
            .filter(|l| l.starts_with("CONTINUED ") && l.contains(&format!("rule={rule} ")))
            .collect::<std::collections::BTreeSet<_>>()
            .len()
    };
    let (m, lines) = run(published.clone(), "land");
    assert!(m.stalls >= 6, "the run stayed past the read: {}", m.stalls);
    assert_eq!(said(&lines, "CONTINUED "), 0, "{lines:#?}");
    assert_eq!(said(&lines, "SKIPPED "), 0, "never decided: {lines:#?}");
    assert_eq!(
        said(&lines, "DONE "),
        0,
        "said by the loop before: {lines:#?}"
    );
    assert_eq!(m.task_requests, ["task"], "read once: {lines:#?}");
    assert_eq!(m.task, published, "the record stands");
    // NEGATIVE CONTROL: the record still `working`.
    let (m, lines) = run(working_task(), "land");
    assert_eq!(typed(&lines, RULE_LAND), 1, "{lines:#?}");
    assert!(task_marks(&m).is_empty(), "{:?}", m.task_requests);
    // NEGATIVE CONTROL: an older build's `done` (its marker or its check, no
    // landing) is no landing to take on: Land's instruction is typed.
    for why in ["marker", "done-check"] {
        let (_, lines) = run(record(why), "land");
        assert_eq!(typed(&lines, RULE_LAND), 1, "why={why}: {lines:#?}");
    }
    // NEGATIVE CONTROL: Cruise takes no `done` record on.
    let (m, lines) = run(published, "cruise");
    assert!(typed(&lines, RULE_DONE_CHECK) >= 1, "{lines:#?}");
    assert_eq!(said(&lines, "DONE "), 0, "{lines:#?}");
    assert!(
        !task_marks(&m)
            .iter()
            .any(|r| r.starts_with("task mark done")),
        "{:?}",
        m.task_requests
    );
}

/// A RETRY'S WALL WHOSE NOTICE LEFT WITHHOLDS THE HOST'S STEP as it holds the
/// policy's rung (the decision review's RR-DEC-3): a 529 met at a point, then
/// its notice gone from the screen with no work since (a person's `/status`,
/// a scroll). The policy waits its rung (`left_retry`); the host's step —
/// the live upgrade's notice turn, a relaunch and its carry-on — is withheld
/// as at the wall (`Guard::Wall`), not typed into the outage the policy waits
/// out. NEGATIVE CONTROLS: a busy read between the 529 and the left screen
/// (work: the track is gone) offers the step; so does a refused 400 whose
/// notice left, which the policy continues there.
#[test]
fn a_retrys_wall_whose_notice_left_withholds_the_hosts_step() {
    use aterm_phase::prompt::fixtures::{END_529, screen};
    let walled = screen(END_529);
    let left = |rows: &[String]| -> Vec<String> {
        rows.iter()
            .filter(|r| !r.contains("API Error"))
            .cloned()
            .collect()
    };
    let refused: Vec<String> = walled
        .iter()
        .map(|r| {
            if r.contains("API Error") {
                "  ⎿  API Error: 400 due to tool use concurrency issues. Run /rewind to recover \
                 the conversation."
                    .to_string()
            } else {
                r.clone()
            }
        })
        .collect();
    for (label, screens, held) in [
        (
            "the 529's notice left",
            vec![busy_screen(), walled.clone(), left(&walled)],
            true,
        ),
        (
            "work between",
            vec![busy_screen(), walled.clone(), busy_screen(), left(&walled)],
            false,
        ),
        (
            "a refused 400's notice left",
            vec![busy_screen(), refused.clone(), left(&refused)],
            false,
        ),
    ] {
        let host = Arc::new(PointHost {
            wants: true,
            ..PointHost::default()
        });
        let mut m = Mock::new(screens);
        m.vanish_after = Some(3);
        m.stall_sleep = Some(Duration::from_millis(5));
        m.exit_when = Some(|m| m.turns >= 1);
        let opts = SuperviseOpts {
            idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
            ..hosted(30)
        };
        let (lines, _) = watch_lines_with(&mut m, &opts, |s| {
            s.set_turn_end_timing(TurnEndTiming {
                short_backoff: Duration::ZERO,
                ..TurnEndTiming::default()
            });
        });
        let withheld = host.withheld.lock().unwrap().clone();
        let why = format!("{label}: {withheld:?}\n{lines:#?}");
        assert_eq!(
            host.idle.load(Ordering::SeqCst),
            usize::from(!held),
            "{why}"
        );
        if held {
            assert_eq!(m.turns, 0, "{why}");
            assert!(withheld.contains(&crate::supervise::Guard::Wall), "{why}");
        }
    }
}

/// Claude Code's own retry of a usage limit under a hand-set
/// `CLAUDE_CODE_RETRY_WATCHDOG` (the lab's capture `fixture`), the prompt it
/// retries the supervisor's own `keep going`, its ticking span `tick`, and no
/// `esc to interrupt` in the footer (as with a statusLine configured: the
/// retry row is then the screen's only word that the turn is not over).
fn watchdog_after_keep_going(fixture: &str, tick: &str) -> Vec<String> {
    aterm_phase::prompt::fixtures::screen(fixture)
        .into_iter()
        .map(|r| {
            let r = r
                .replace("❯ carry on with the task", "❯ keep going")
                .replace("❯ toolstart", "❯ keep going")
                .replace(" · esc to interrupt", "");
            match r.split_once(" · Retrying in ") {
                Some((head, rest)) => match rest.split_once(" (") {
                    Some((_, clock)) => format!("{head} · Retrying in {tick} ({clock}"),
                    None => r,
                },
                None => r,
            }
        })
        .collect()
}

/// `rows` as the reader before accounts v2 S5 took the retry row: a status
/// row it could not count the attempt of, a done row.
fn retry_read_as_done(rows: &[String]) -> Vec<String> {
    rows.iter()
        .map(|r| r.replace("attempt 1/300", "attempt one of 300"))
        .collect()
}

/// A loop over `screens` (the first continuation's turn, then whatever
/// follows), its acts' window a millisecond and no back-off, `grace` the
/// person's ([`SupervisorConfig::human_grace_s`]): the Mock and the lines.
fn watchdog_run(
    tag: &str,
    screens: Vec<Vec<String>>,
    grace: u32,
) -> (Mock, Vec<String>, Vec<String>) {
    let (dir, path) = journal_file(tag);
    let mut m = Mock::new(screens);
    m.turn_releases = Some(1);
    m.vanish_after = Some(8);
    m.stall_sleep = Some(Duration::from_millis(20));
    let mut opts = SuperviseOpts {
        journal: Some(path.clone()),
        ..hosted(30)
    };
    opts.policy.human_grace_s = grace;
    let (lines, _) = watch_lines_with(&mut m, &opts, |s| {
        s.set_turn_end_timing(TurnEndTiming {
            take_within: Duration::from_millis(1),
            short_backoff: Duration::ZERO,
            min_work: Duration::ZERO,
            ..TurnEndTiming::default()
        });
    });
    // What each wait was for, its `until=` (a clock reading) left out.
    let (records, _) = journal_records(&path);
    let waits = records
        .iter()
        .filter(|r| r.kind == "waiting")
        .map(|r| {
            r.summary
                .split_once(' ')
                .map_or(r.summary.clone(), |(_, why)| why.to_string())
        })
        .collect();
    let _ = std::fs::remove_dir_all(&dir);
    (m, lines, waits)
}

/// The acts a run typed (`CONTINUED`, `TYPED`), as `rule text`.
fn typed_acts(lines: &[String]) -> Vec<String> {
    lines
        .iter()
        .filter(|l| l.starts_with("CONTINUED") || l.starts_with("TYPED"))
        .map(|l| l.split(" rule=").nth(1).unwrap_or_default().to_string())
        .collect()
}

/// CLAUDE CODE'S OWN RETRY OF A USAGE LIMIT IS A TURN IN PROGRESS, AND NOTHING
/// IS TYPED INTO IT (accounts v2 S5). The supervisor's continuation meets
/// the five-hour limit under a hand-set watchdog: no notice and no
/// transcript row, one status row ticking every second (`✻ Session limit
/// reached · Retrying in … (8:48am) · attempt 1/300`) until the vendor sends
/// the request again by itself — measured on 2.1.300 inline, on 2.1.301 on
/// the fullscreen renderer and met by a turn's second request. Every read of
/// it is busy: no point, no limit, no wait, and nothing typed after the one
/// continuation however long it ticks. NEGATIVE CONTROL: the same run read
/// as the reader before read it (the row a done row) is an idle point, and
/// the continue policy types `keep going` into the session that is retrying.
#[test]
fn the_watchdogs_retry_row_is_a_turn_in_progress_and_nothing_is_typed_into_it() {
    use aterm_phase::prompt::fixtures::{
        WALL_WATCHDOG_FULLSCREEN_2_1_301, WALL_WATCHDOG_MIDTURN_2_1_301,
        WALL_WATCHDOG_SESSION_STATUSLINE_2_1_300,
    };
    for (name, fixture) in [
        ("inline", WALL_WATCHDOG_SESSION_STATUSLINE_2_1_300),
        ("fullscreen", WALL_WATCHDOG_FULLSCREEN_2_1_301),
        ("mid-turn", WALL_WATCHDOG_MIDTURN_2_1_301),
    ] {
        // The row ticks every second: each read a new screen.
        let ticking: Vec<Vec<String>> = (40..46)
            .map(|s| watchdog_after_keep_going(fixture, &format!("59m {s}s")))
            .collect();
        let run = |tag: &str, retry: Vec<Vec<String>>| {
            let mut screens = vec![
                busy_screen(),
                ended("Fixed the parser; the suite is green."),
            ];
            screens.extend(retry);
            watchdog_run(tag, screens, 120)
        };
        let (m, lines, waits) = run("te-watchdog-busy", ticking.clone());
        assert_eq!(
            typed_acts(&lines),
            ["continue@v1 keep going"],
            "{name}: the first continuation only: {lines:#?}"
        );
        assert_eq!(m.turns, 1, "{name}: {lines:#?}\n{:#?}", m.requests);
        assert!(
            !lines
                .iter()
                .any(|l| l.starts_with("EVENT limited") || l.starts_with("LIMITED")),
            "{name}: no limit: {lines:#?}"
        );
        assert!(
            waits
                .iter()
                .all(|w| w.contains("to take the continue@v1 act")),
            "{name}: no wait but the act's own window: {waits:#?}"
        );
        // NEGATIVE CONTROL: the row read as a done row, as before.
        let old: Vec<Vec<String>> = ticking.iter().map(|r| retry_read_as_done(r)).collect();
        let (m, lines, _) = run("te-watchdog-done-row", old);
        assert!(m.turns >= 2, "{name}: typed into the retry: {lines:#?}");
    }
}

/// THE LOOP TELLS THE POLICY OF EVERY BOX IT READS ([`TurnEndState::box_up`]),
/// so a person's Esc read after a box — their refusal of it — is a new one,
/// held for their grace from that read, though no busy read came before the
/// box (the refusal the Gemini CLI review of 2026-10-16 saw continued 0.6 s
/// after the Esc; the policy's half is
/// `a_persons_esc_is_held_from_its_own_read_not_from_an_old_point`). A run
/// that read a person's Esc and then a box keeps no Esc read. NEGATIVE
/// CONTROL: the same run ending on the Esc keeps its read.
#[test]
fn a_box_the_loop_reads_makes_the_next_esc_a_new_one() {
    use aterm_phase::prompt::fixtures::{BOX_BASH_TOUCH, screen};
    let run = |screens: Vec<Vec<String>>| {
        let mut m = Mock::new(screens);
        m.vanish_after = Some(3);
        m.stall_sleep = Some(Duration::from_millis(5));
        let opts = hosted(30);
        let mut out: Vec<u8> = Vec::new();
        let mut s = session(&mut m, None);
        s.set_clock(TEST_NOW, PDT);
        s.set_zone_lookup(test_zones);
        let _ = s.watch(&opts, &mut out);
        (
            s.turn_end.esc_read(),
            String::from_utf8(out).expect("utf-8"),
        )
    };
    let mut stopped = rows(&[
        "⏺ Working.",
        "  ⎿  Interrupted · What should Claude do instead?",
        "",
    ]);
    stopped.extend(composer("  ⏵⏵ bypass permissions on (shift+tab to cycle)"));
    let (read, out) = run(vec![busy_screen(), stopped.clone()]);
    assert!(read.is_some(), "the control: the Esc read: {out}");
    let (read, out) = run(vec![busy_screen(), stopped, screen(BOX_BASH_TOUCH)]);
    // The box read (whatever the fences let the policy do with it).
    assert!(out.contains("EVENT prompt seq="), "the box was read: {out}");
    assert_eq!(read, None, "the box read since: {out}");
}

/// ESC ON THE VENDOR'S RETRY IS A PERSON ENDING THE TURN, AS ANYWHERE (accounts
/// v2 S5). Measured on 2.1.301: Esc on the row of a limit met mid-turn leaves
/// `⎿  Interrupted · What should Claude do instead?` under the turn's Bash
/// call; Esc on it at a turn's first request (the fullscreen renderer) puts
/// the prompt back in the composer, as Esc before any answer does. Each run
/// is decided exactly as the same Esc on an ordinary turn — the retry row's
/// place a spinner's — is decided: the person's grace first (`a person
/// stopped the turn with Esc`; the prompt put back is their draft, `a person
/// is typing`), then, the grace spent, the same acts; no limit, no wait on a
/// reset. And the retry served at the reset is the turn
/// going on: its done row is an ordinary turn end, decided as the same turn
/// served with no retry before it. NEGATIVE CONTROL: the run read as the
/// reader before read the row (a done row) is not the ordinary turn's: the
/// continue policy typed into the retry before the Esc.
#[test]
fn esc_on_the_vendors_retry_is_an_ordinary_turn_a_person_ended() {
    use aterm_phase::prompt::fixtures::{
        WALL_WATCHDOG_FULLSCREEN_2_1_301, WALL_WATCHDOG_FULLSCREEN_ESC_2_1_301,
        WALL_WATCHDOG_MIDTURN_2_1_301, WALL_WATCHDOG_MIDTURN_ESC_2_1_301,
        WALL_WATCHDOG_MIDTURN_SERVED_2_1_301,
    };
    // The retry row's place a spinner's: the ordinary turn.
    let spinning = |rows: Vec<String>| -> Vec<String> {
        rows.into_iter()
            .map(
                |r| match r.split_once(" Session limit reached · Retrying in ") {
                    Some((glyph, _)) => format!("{glyph} Cooking… (2m 4s · ↓ 1.1k tokens)"),
                    None => r,
                },
            )
            .collect()
    };
    for (name, standing, after, held) in [
        (
            "mid-turn Esc",
            WALL_WATCHDOG_MIDTURN_2_1_301,
            WALL_WATCHDOG_MIDTURN_ESC_2_1_301,
            Some("a person stopped the turn with Esc"),
        ),
        (
            "first-request Esc",
            WALL_WATCHDOG_FULLSCREEN_2_1_301,
            WALL_WATCHDOG_FULLSCREEN_ESC_2_1_301,
            Some("a person is typing"),
        ),
        (
            "served",
            WALL_WATCHDOG_MIDTURN_2_1_301,
            WALL_WATCHDOG_MIDTURN_SERVED_2_1_301,
            None,
        ),
    ] {
        let screens = |turn: &dyn Fn(Vec<String>) -> Vec<String>| -> Vec<Vec<String>> {
            let mut screens = vec![
                busy_screen(),
                ended("Fixed the parser; the suite is green."),
            ];
            screens.extend(
                (40..46).map(|s| turn(watchdog_after_keep_going(standing, &format!("59m {s}s")))),
            );
            screens.push(watchdog_after_keep_going(after, ""));
            screens
        };
        for grace in [120, 0] {
            let (_, retry, retry_waits) = watchdog_run("te-watchdog-esc", screens(&|r| r), grace);
            let (_, plain, plain_waits) =
                watchdog_run("te-watchdog-esc-plain", screens(&spinning), grace);
            assert_eq!(
                (typed_acts(&retry), &retry_waits),
                (typed_acts(&plain), &plain_waits),
                "{name}, grace {grace}: as the ordinary turn: {retry:#?}\n{plain:#?}"
            );
            assert!(
                !retry
                    .iter()
                    .any(|l| l.starts_with("EVENT limited") || l.starts_with("LIMITED")),
                "{name}: no limit: {retry:#?}"
            );
            assert!(
                retry_waits
                    .iter()
                    .all(|w| !w.contains("resets") && !w.contains("by itself")),
                "{name}: no wait on a reset: {retry_waits:#?}"
            );
            if let Some(held) = held.filter(|_| grace > 0) {
                assert!(
                    retry_waits.iter().any(|w| w.ends_with(held)),
                    "{name}: the person's grace: {retry_waits:#?}\n{retry:#?}"
                );
            }
        }
        // NEGATIVE CONTROL: the row read as a done row.
        let old = screens(&|r| retry_read_as_done(&r));
        let (_, old, _) = watchdog_run("te-watchdog-esc-old", old, 0);
        let (_, plain, _) = watchdog_run("te-watchdog-esc-plain", screens(&spinning), 0);
        assert_ne!(typed_acts(&old), typed_acts(&plain), "{name}: {old:#?}");
    }
}

/// THE STALLED STREAM'S RETRY IN A NARROW PANE IS TYPED NOTHING: after the
/// one continuation, Claude Code's retry of a stalled stream (2.1.301's
/// `aSn`) ticks at 36 columns, its glyph on a row of its own and its uncut
/// head `Waiting for API response` filling its column to the tail's ` · `,
/// with no `esc to interrupt` in the cut footer. The merge of main's strict
/// retry rule read it row by row as no retry, an idle point, and typed `keep
/// going` into the session that was about to retry. NEGATIVE CONTROL: the
/// turn's done row in the retry's place is an idle point, and the continue
/// policy types again.
#[test]
fn the_stalled_streams_retry_in_a_narrow_pane_is_typed_nothing() {
    let rule = "─".repeat(36);
    let after_keep_going = |status: &[String]| {
        let mut r = rows(&["❯ keep going", ""]);
        r.extend(status.iter().cloned());
        r.extend(rows(&[
            "",
            &rule,
            "❯",
            &rule,
            "  ⏵⏵ bypass permissions on (shift+tab",
        ]));
        r
    };
    let run = |tag: &str, retry: Vec<Vec<String>>| {
        let mut screens = vec![
            busy_screen(),
            ended("Fixed the parser; the suite is green."),
        ];
        screens.extend(retry);
        watchdog_run(tag, screens, 120)
    };
    let ticking: Vec<Vec<String>> = (30..36)
        .rev()
        .map(|s| {
            after_keep_going(&rows(&[
                "✻",
                &format!("Waiting for API · will retry in {s}s"),
                "response       · check your network",
            ]))
        })
        .collect();
    let (m, lines, _) = run("te-stalled-retry", ticking);
    assert_eq!(
        typed_acts(&lines),
        ["continue@v1 keep going"],
        "the first continuation only: {lines:#?}"
    );
    assert_eq!(m.turns, 1, "{lines:#?}");
    // NEGATIVE CONTROL: the done row in the retry's place.
    let done = vec![after_keep_going(&rows(&["✻ Worked for 3m 2s · done 4:31 PM"])); 6];
    let (m, lines, _) = run("te-stalled-retry-done", done);
    assert!(m.turns >= 2, "the done row is an idle point: {lines:#?}");
}

/// A host that keeps what the loop tells it of the account's usage.
#[derive(Debug, Default)]
struct UsageHost {
    told: std::sync::Mutex<Vec<UsageSeen>>,
}

impl IdleHost for UsageHost {
    fn wants(&self) -> bool {
        false
    }
    fn at_idle(&self) -> Option<HostStep> {
        None
    }
    fn owns_turn_end(&self) -> bool {
        false
    }
    fn usage_seen(&self, seen: &UsageSeen) {
        self.told.lock().unwrap().push(seen.clone());
    }
}

/// WHAT THE SCREEN SAYS OF THE ACCOUNT'S USAGE IS TOLD TO THE HOST, ONCE PER
/// CHANGE (accounts v2 S5): busy reads included — credits start mid-turn —
/// and the turn ends as an ordinary idle point, no wall and no limit episode:
/// credits are work going on. The measured credits screens (2.1.300) are told as credits
/// in use, the started notice with its window, then the lasting one; the same
/// screen read again tells nothing new. NEGATIVE CONTROL: a run with no
/// notice tells the host only that nothing is said, once.
#[test]
fn what_the_screen_says_of_usage_is_told_to_the_host_once_per_change() {
    use aterm_phase::prompt::fixtures::{CREDITS_IN_USE_2_1_300, CREDITS_STARTED_2_1_300};
    let run = |screens: Vec<Vec<String>>| {
        let host = Arc::new(UsageHost::default());
        let mut m = Mock::new(screens);
        m.vanish_after = Some(3);
        m.stall_sleep = Some(Duration::from_millis(5));
        let opts = SuperviseOpts {
            idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
            ..hosted(30)
        };
        let (lines, _) = watch_lines(&mut m, &opts);
        let told = host.told.lock().unwrap().clone();
        (lines, told)
    };
    let busy_on_credits = {
        let mut r = busy_screen();
        let at = r.len() - 1;
        // Right-aligned against the 120-column rules, two short.
        r[at] = format!("{:<95}Now using usage credits", r[at]);
        r
    };
    let started = aterm_phase::prompt::fixtures::screen(CREDITS_STARTED_2_1_300);
    let lasting = aterm_phase::prompt::fixtures::screen(CREDITS_IN_USE_2_1_300);
    let (lines, told) = run(vec![
        busy_screen(),
        busy_on_credits,
        started.clone(),
        lasting.clone(),
        lasting,
    ]);
    let credits: Vec<Option<bool>> = told
        .iter()
        .map(|t| t.credits.as_ref().map(|c| c.started.is_some()))
        .collect();
    assert_eq!(
        credits,
        [None, Some(false), Some(true), Some(false)],
        "{told:#?}\n{lines:#?}"
    );
    assert!(
        lines.iter().any(|l| l.starts_with("EVENT idle"))
            && !lines
                .iter()
                .any(|l| l.starts_with("EVENT limited") || l.starts_with("LIMITED")),
        "an ordinary turn end, no wall: {lines:#?}"
    );
    // NEGATIVE CONTROL: nothing said.
    let (_, told) = run(vec![
        busy_screen(),
        ended("Fixed the parser; the suite is green."),
    ]);
    assert_eq!(told, [UsageSeen::default()], "{told:#?}");
}

/// AN OFF SESSION IS LEFT WITH NO `/usage` PANEL OF THE HARNESS'S: the loop
/// that takes up the panel a stopped loop left owed, on a session whose
/// Autopilot word is `off`, lets it stand the person's grace in its own
/// sight (a second here, as the default's 120 s would: the grace starts as
/// the panel is taken up, so the first look is always inside it), closes it
/// — its one Escape, past that grace — BEFORE it parks, and while parked
/// writes nothing more: no continuation, no probe, no second Escape. (What
/// a park does leave standing — a limit reset's step, a Codex switch — is
/// the design's §7.) The run ends a few park steps in, so a park reached
/// with the panel still open ends it too. NEGATIVE CONTROL: before the
/// close, the panel stood.
#[test]
fn an_off_session_has_the_harnesss_usage_panel_closed_before_the_park() {
    let (dir, ledger) = ledger_at("probe-off");
    let mut m = panel_left_owed(&ledger);
    // NEGATIVE CONTROL: the panel the stopped loop left stands.
    assert_eq!(world(&mut m).at, PanelAt::Open);
    let before = m.writes();

    // The next loop, the session's word `off`, a grace of a second.
    m.autopilot = Some("off");
    m.exit_when = Some(|m| m.metas >= 3);
    let next = ProbeHost::probing(true);
    let started = Instant::now();
    let (lines, journal) = probe_run(
        "te-probe-off-next",
        &mut m,
        &next,
        &ledger,
        probe_policy(1),
        |_| {},
    );
    assert_eq!(probe_writes(&m), ["/usage", "esc"], "{lines:#?}");
    assert_eq!(world(&mut m).at, PanelAt::Rest, "{lines:#?}");
    let esc = world(&mut m).probes.last().expect("the Escape").at;
    assert!(
        esc.duration_since(started) >= Duration::from_secs(1),
        "one grace in the loop's own sight: {:?}",
        esc.duration_since(started)
    );
    assert!(
        journal.iter().any(|l| l.starts_with("PARKED seq=")),
        "{journal:#?}"
    );
    // The Escape went before the park's first step (its wait for the
    // screen to move, `OFF_STEP` long).
    let escaped = m
        .requests
        .iter()
        .rposition(|r| verb_of(r) == "key" && r.ends_with(" esc"))
        .unwrap_or_else(|| panic!("the Escape: {:#?}", m.requests));
    let step = format!("timeout {}", OFF_STEP.as_millis());
    let parked = m
        .requests
        .iter()
        .position(|r| r.starts_with("await seq ") && r.ends_with(&step))
        .unwrap_or_else(|| panic!("the park's step: {:#?}", m.requests));
    assert!(escaped < parked, "{:#?}", m.requests);
    assert_eq!(
        m.writes()[before.len()..],
        ["esc"],
        "the Escape alone: {:#?}",
        m.requests
    );
    assert!(next.said("probe").is_empty(), "no probe while parked");
    let _ = std::fs::remove_dir_all(&dir);
}

/// The world an Off test of the panel starts from: a loop stopped mid-probe
/// (its host's stop lands while the panel is read) has left its `/usage`
/// panel standing, owed its close in the ledger at `ledger`, which the next
/// loop takes up. The counts the next loop's tests read start over: the
/// waits that end a run, the `meta` and `status` reads.
fn panel_left_owed(ledger: &Path) -> Mock {
    let host = ProbeHost::probing(true);
    let mut m = probe_world(&[panel_fx::USAGE_REFRESHING], &host);
    let stop = Arc::new(AtomicBool::new(false));
    world(&mut m).stop_at_read = Some((2, Arc::clone(&stop)));
    let opts = SuperviseOpts {
        idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
        ledger: Some(ledger.to_path_buf()),
        policy: probe_policy(120),
        ..SuperviseOpts::hosted_with(&owners_policy())
    };
    let mut out: Vec<u8> = Vec::new();
    {
        let mut s = session(&mut m, None);
        s.set_clock(PROBE_NOW, PDT);
        s.set_zone_lookup(test_zones);
        probe_waits(&mut s);
        assert_eq!(s.run_hosted(&opts, stop, &mut out), Ok(()));
    }
    assert_eq!(world(&mut m).at, PanelAt::Open, "the panel stands");
    m.stalls = 0;
    m.metas = 0;
    m.status_reads = 0;
    m
}

/// What the next loop over [`panel_left_owed`] did ([`off_panel_run`]).
struct OffPanelRun {
    m: Mock,
    /// The next loop's requests.
    requests: Vec<String>,
    /// The next loop's writes of the probe's ([`probe_writes`]).
    writes: Vec<&'static str>,
    journal: Vec<String>,
    /// The ledger still owes the panel's close.
    owed: bool,
}

/// The next loop over [`panel_left_owed`], under the session's word `word`,
/// with a stall suspected or not (`suspect`: as after a press of the loop's
/// refused `ERR busy input-unread`), the worker's input as `input` (`status
/// input=…`), and the panel's Escapes as `esc` makes them ([`esc_takes`],
/// [`esc_refused_unread`], …) — the host's relaunch and the restart's bound
/// in place, so a stall held at the panel journals `FROZEN` and restarts the
/// worker. The run ends at
/// the first wait after `exit` holds of the mock (else on the script).
fn off_panel_run(
    tag: &str,
    word: &'static str,
    suspect: bool,
    input: &'static str,
    esc: fn(&mut PanelWorld),
    exit: fn(&Mock) -> bool,
) -> OffPanelRun {
    let (dir, ledger) = ledger_at(tag);
    let mut m = panel_left_owed(&ledger);
    let (requests_before, writes_before) = (m.requests.len(), probe_writes(&m).len());
    m.autopilot = Some(word);
    m.input = input;
    m.exit_when = Some(exit);
    esc(world(&mut m));
    let next = ProbeHost::probing(true);
    next.relaunches.store(true, Ordering::SeqCst);
    let policy = SupervisorConfig {
        stall_term: true,
        stall_term_after_s: 60,
        ..probe_policy(0)
    };
    let (_, journal) = probe_run(tag, &mut m, &next, &ledger, policy, |s| {
        s.stall_suspect = suspect;
        if suspect {
            s.seeds_learned_state("a stall suspected before the run");
        }
    });
    let owed = crate::supervise::approvals::probe_owed(
        &std::fs::read_to_string(&ledger).unwrap_or_default(),
        None,
    );
    let _ = std::fs::remove_dir_all(&dir);
    let requests = m.requests[requests_before..].to_vec();
    let writes = probe_writes(&m)[writes_before..].to_vec();
    OffPanelRun {
        m,
        requests,
        writes,
        journal,
        owed,
    }
}

/// An [`off_panel_run`] whose panel's Escape takes, as the world's does.
fn esc_takes(_: &mut PanelWorld) {}

/// An [`off_panel_run`] whose panel's first Escape is refused `ERR busy
/// input-unread` (which suspects a stall).
fn esc_refused_unread(w: &mut PanelWorld) {
    w.esc_replies = [err(
        "busy input-unread bytes=1 wait_ms=1500 input=pending (the program has not read input \
         queued 1s ago; retry in a moment)",
    )]
    .into();
}

/// An [`off_panel_run`] whose panel's first Escape is refused by a hold
/// (`ERR halted`).
fn esc_halted(w: &mut PanelWorld) {
    w.esc_replies = [err("halted by the owner")].into();
}

/// An [`off_panel_run`] whose panel's first Escape is written and does not
/// take: the panel stands.
fn esc_fails_once(w: &mut PanelWorld) {
    w.esc_fails = 1;
}

/// Whether `requests` hold one whose verb is `verb`.
fn sent(requests: &[String], verb: &str) -> bool {
    requests.iter().any(|r| verb_of(r) == verb)
}

/// AN OFF SESSION'S PANEL GETS ONE PLAIN CLOSE, NEVER A STALL'S HOLD (the
/// review of c1d193998). The panel a stopped loop left owed, on a session
/// whose word is `off`, with a stall suspected and the worker published
/// stalled, is not looked into: the loop parks at once — no `FROZEN`, no
/// restart, no Escape — and the panel stays owed for the word's turn.
/// NEGATIVE CONTROL: the same world under Cruise holds the stall at the panel
/// — `FROZEN`, the restart.
#[test]
fn an_off_session_with_a_stall_suspected_parks_and_leaves_the_panel_owed() {
    let off = off_panel_run(
        "probe-off-stall",
        "off",
        true,
        INPUT_STALLED,
        esc_takes,
        |m| m.metas >= 3,
    );
    assert!(
        off.journal.iter().any(|l| l.starts_with("PARKED seq=")),
        "{:#?}",
        off.journal
    );
    assert!(
        !off.journal.iter().any(|l| l.starts_with("FROZEN")),
        "{:#?}",
        off.journal
    );
    assert!(!sent(&off.requests, "restart"), "{:#?}", off.requests);
    assert!(off.writes.is_empty(), "no Escape: {:#?}", off.requests);
    let mut m = off.m;
    assert_eq!(world(&mut m).at, PanelAt::Open, "the panel stands");
    assert!(off.owed, "owed until the word turns");

    // NEGATIVE CONTROL: Cruise.
    let cruise = off_panel_run(
        "probe-cruise-stall",
        "cruise",
        true,
        INPUT_STALLED,
        esc_takes,
        |m| m.requests.iter().any(|r| verb_of(r) == "restart"),
    );
    assert!(
        cruise.journal.iter().any(|l| l.starts_with("FROZEN seq=")),
        "{:#?}",
        cruise.journal
    );
    assert!(sent(&cruise.requests, "restart"), "{:#?}", cruise.requests);
    assert!(
        !cruise.journal.iter().any(|l| l.starts_with("PARKED")),
        "{:#?}",
        cruise.journal
    );
}

/// UNDER OFF A REFUSED ESCAPE IS NOT TRIED AGAIN: the panel's one guarded
/// Escape, refused `ERR busy input-unread` (which suspects a stall), and the
/// loop parks — no second Escape, no stall's hold, the panel owed. NEGATIVE CONTROL: under Cruise the refusal is backed off and the
/// Escape tried again, which closes the panel.
#[test]
fn an_off_sessions_refused_escape_is_its_one_close() {
    let off = off_panel_run(
        "probe-off-refused",
        "off",
        false,
        INPUT_CLEAR,
        esc_refused_unread,
        |m| m.metas >= 3,
    );
    assert_eq!(off.writes, ["esc"], "one Escape: {:#?}", off.requests);
    assert!(
        off.journal
            .iter()
            .any(|l| l.starts_with("REFUSED") && l.contains("ERR busy input-unread")),
        "{:#?}",
        off.journal
    );
    assert!(
        off.journal.iter().any(|l| l.starts_with("PARKED seq=")),
        "{:#?}",
        off.journal
    );
    assert!(
        !off.journal.iter().any(|l| l.starts_with("FROZEN")),
        "{:#?}",
        off.journal
    );
    let mut m = off.m;
    assert_eq!(world(&mut m).at, PanelAt::Open, "the panel stands");
    assert!(off.owed, "owed until the word turns");

    // NEGATIVE CONTROL: Cruise backs off and tries again, and the panel
    // closes.
    let cruise = off_panel_run(
        "probe-cruise-refused",
        "cruise",
        false,
        INPUT_CLEAR,
        esc_refused_unread,
        |_| false,
    );
    assert_eq!(cruise.writes, ["esc", "esc"], "{:#?}", cruise.requests);
    let mut m = cruise.m;
    assert_ne!(world(&mut m).at, PanelAt::Open, "closed");
    assert!(!cruise.owed);
}

/// UNDER OFF THE ONE CLOSE PROMISES NOTHING MORE AND WAITS ON NO HOLD (the
/// review of b512d03d8). An Escape that does not take is journaled
/// `WAITING … owed until the word turns` — never `Escape again in 5 s`, as
/// no Escape follows under Off — and the loop parks. An Escape a hold
/// refuses (`ERR halted`) is journaled `HALTED … owed until the word turns`
/// and the loop parks, never waiting the hold out (`park_on_hold`: an
/// unbounded wait, with the loop's badges and claim up; no `UNHALTED`).
/// Each leaves one Escape and the panel owed. NEGATIVE CONTROLS: under
/// Cruise the failed Escape's line names its next try, and the hold is
/// waited out (`UNHALTED`) and the Escape sent again.
#[test]
fn an_off_sessions_one_close_promises_no_second_escape_and_waits_on_no_hold() {
    let parked = |run: &OffPanelRun| run.journal.iter().any(|l| l.starts_with("PARKED seq="));
    let off = off_panel_run(
        "probe-off-failed",
        "off",
        false,
        INPUT_CLEAR,
        esc_fails_once,
        |m| m.metas >= 3,
    );
    assert_eq!(off.writes, ["esc"], "one Escape: {:#?}", off.requests);
    let waiting: Vec<&String> = off
        .journal
        .iter()
        .filter(|l| l.starts_with("WAITING seq="))
        .collect();
    assert_eq!(waiting.len(), 1, "{:#?}", off.journal);
    assert!(
        waiting[0].ends_with(
            "panel is open (1 tries): owed until the word turns (autopilot off: no Escape again)"
        ),
        "{}",
        waiting[0]
    );
    assert!(parked(&off), "{:#?}", off.journal);
    assert!(off.owed, "owed until the word turns");

    let off = off_panel_run(
        "probe-off-halted",
        "off",
        false,
        INPUT_CLEAR,
        esc_halted,
        |m| m.metas >= 3,
    );
    assert_eq!(off.writes, ["esc"], "one Escape: {:#?}", off.requests);
    assert!(
        off.journal.iter().any(|l| l.starts_with("HALTED seq=")
            && l.contains("halted by the owner")
            && l.contains("owed until the word turns")),
        "{:#?}",
        off.journal
    );
    assert!(
        !off.journal.iter().any(|l| l.starts_with("UNHALTED")),
        "no wait on the hold: {:#?}",
        off.journal
    );
    assert!(parked(&off), "{:#?}", off.journal);
    assert!(off.owed, "owed until the word turns");

    // NEGATIVE CONTROLS: Cruise. The failed Escape names its next try (the
    // run ends at the wait for it: the second wait on the header row after
    // the Escape, the first being the Escape's own).
    let cruise = off_panel_run(
        "probe-cruise-failed",
        "cruise",
        false,
        INPUT_CLEAR,
        esc_fails_once,
        |m| {
            m.requests
                .iter()
                .rposition(|r| verb_of(r) == "key" && r.ends_with(" esc"))
                .is_some_and(|at| {
                    m.requests[at..]
                        .iter()
                        .filter(|r| r.starts_with("await gone "))
                        .count()
                        >= 2
                })
        },
    );
    assert!(
        cruise
            .journal
            .iter()
            .any(|l| l.starts_with("WAITING seq=") && l.ends_with("(1 tries): Escape again in 5 s")),
        "{:#?}",
        cruise.journal
    );
    // The hold is waited out, and the Escape sent again.
    let cruise = off_panel_run(
        "probe-cruise-halted",
        "cruise",
        false,
        INPUT_CLEAR,
        esc_halted,
        |_| false,
    );
    assert!(
        cruise.journal.iter().any(|l| l.starts_with("UNHALTED")),
        "{:#?}",
        cruise.journal
    );
    assert_eq!(cruise.writes, ["esc", "esc"], "{:#?}", cruise.requests);
    assert!(!cruise.owed);
}

/// A LANDING WHOSE MARK WAS TURNED AWAY IS ASKED FOR AGAIN (a seamless
/// update committing answered `ERR busy`): the point decided again asks
/// again, the record ends `done`, and the landing is said once (`DONE`).
/// NEGATIVE CONTROL: the mark served at once is asked for once.
#[test]
fn a_landings_mark_turned_away_is_asked_for_again() {
    let root = crate::supervise::ScratchDir::new("task", "busy");
    let text = transcript_of(&landing_rows(&landed_reply()));
    let run = |busy: usize, tag: &str| {
        let host = TaskHost::reading(&root.join(format!("t-{tag}.jsonl")), &[&text]);
        let tasks = root.join(format!("tasks-{tag}"));
        let journal = root.join(format!("journal-{tag}.jsonl"));
        let mut m = Mock::new(landing_screens(&landed_reply()));
        landing(&mut m);
        m.vanish_after = Some(4);
        m.task = working_task();
        m.task_busy = busy;
        let _ = tasked_watch(&mut m, &host, &tasks, Some(&journal));
        let dones = journal_records(&journal)
            .0
            .into_iter()
            .filter(|r| r.line.starts_with("DONE "))
            .count();
        let mark = done_mark(
            "landed",
            landed_result().len(),
            &tasks.join("s-1-1.result.md"),
        );
        (m, mark, dones)
    };
    let (m, mark, dones) = run(1, "refused");
    assert_eq!(
        task_marks(&m),
        [mark.clone(), mark],
        "{:?}",
        m.task_requests
    );
    assert!(
        m.task
            .as_ref()
            .is_some_and(|(_, f)| f.starts_with("state=done ")),
        "{:?}",
        m.task
    );
    assert_eq!(dones, 1);
    // NEGATIVE CONTROL: served at once.
    let (m, mark, _) = run(0, "served");
    assert_eq!(task_marks(&m), [mark], "{:?}", m.task_requests);
}

/// A LOOP STARTED ON A `done` RECORD AT A WALL STILL ACTS ON THE WALL: a done
/// point never shows one, so the 529 its first screen shows ended someone
/// else's turn after the done (a follow-up the server did not reopen on).
/// Taken on as done, the retry was never typed; here the record is opened
/// again (`working why=turn`) and the retry goes. NEGATIVE CONTROL: the same
/// loop on a plain screen whose reply is a clean defense takes the landing
/// on and types nothing. (Under Land: Cruise takes no `done` record on at
/// all.)
#[test]
fn a_loop_started_on_a_done_record_at_a_wall_still_types_the_retry() {
    let root = crate::supervise::ScratchDir::new("task", "seed-wall");
    let published = Some((
        2,
        "state=done from=ctl since_ms=0 result_bytes=17 why=landed".to_string(),
    ));
    let run = |screens: Vec<Vec<String>>, screens_held: bool, tag: &str| {
        let host = TaskHost::reading(&root.join("t.jsonl"), &[""]);
        let mut m = Mock::new(screens);
        m.history_served();
        // The wall's screen sits until a `turn` is typed; the run ends at
        // the wait after one, or after a few waits with none.
        m.turn_releases = (screens_held).then_some(0);
        m.exit_when = Some(|m| m.turns > 0 || m.stalls >= 3);
        m.vanish_after = Some(3);
        m.autopilot = Some("land");
        m.task = published.clone();
        let opts = SuperviseOpts {
            policy: owners_policy(),
            idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
            tasks: Some(root.join(format!("tasks-{tag}"))),
            ..auto(30)
        };
        let mut out: Vec<u8> = Vec::new();
        {
            let mut s = session(&mut m, Some("@s-1".to_string()));
            s.set_clock(TEST_NOW, PDT);
            s.set_zone_lookup(test_zones);
            s.set_turn_end_timing(TurnEndTiming {
                retry_backoff: vec![Duration::from_millis(50); 3],
                ..TurnEndTiming::default()
            });
            let _ = s.watch(&opts, &mut out);
        }
        let lines: Vec<String> = String::from_utf8(out)
            .expect("utf-8")
            .lines()
            .map(str::to_string)
            .collect();
        (m, lines)
    };
    let end_529 = aterm_phase::prompt::fixtures::screen(aterm_phase::prompt::fixtures::END_529);
    let (m, lines) = run(
        vec![end_529, busy_screen(), ended("Stage 2 landed.")],
        true,
        "529",
    );
    assert!(
        lines
            .iter()
            .any(|l| l.starts_with("CONTINUED ") && l.contains("rule=api-retry@v1")),
        "{lines:#?}"
    );
    assert_eq!(
        task_marks(&m),
        ["task mark working why=turn"],
        "{:?}",
        m.task_requests
    );
    // NEGATIVE CONTROL: a plain done screen.
    let (m, lines) = run(
        vec![ended(
            "Yes, it's all done.\nNothing left: it is merged into the remote main branch.",
        )],
        false,
        "plain",
    );
    assert!(
        !lines.iter().any(|l| l.starts_with("CONTINUED ")),
        "{lines:#?}"
    );
    assert!(task_marks(&m).is_empty(), "{:?}", m.task_requests);
}

/// A SEED READ SERVED ONLY AFTER THE LOOP ACTED READS NOTHING INTO THE POINT
/// (a8's third fix): the loop starts on a `done` record at a 529 wall, but
/// every read of the record is turned away until it has typed the wall's
/// retry; the point is then decided again — the retry not taken yet — with
/// the read served. The seed is refused there (a wall, an act of the loop's
/// owed), and the record stands: no `working why=turn` over the harness's
/// own retry, which that point's edge would read as someone else's turn
/// after the done. NEGATIVE CONTROL: the read served at once, before the
/// retry, reads the walled point so, and opens the record again.
#[test]
fn a_seed_read_served_after_the_loop_acted_reads_nothing_into_the_point() {
    let root = crate::supervise::ScratchDir::new("task", "seed-owed");
    let published = Some((
        2,
        "state=done from=ctl since_ms=0 result_bytes=17 why=landed".to_string(),
    ));
    let host = TaskHost::reading(&root.join("t.jsonl"), &[""]);
    let opts = SuperviseOpts {
        policy: owners_policy(),
        idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
        tasks: Some(root.join("tasks")),
        ..auto(30)
    };
    let wall = aterm_phase::prompt::fixtures::screen(aterm_phase::prompt::fixtures::END_529);
    let run = |served_at_once: bool| {
        let mut m = Mock::new(vec![wall.clone()]);
        m.task = published.clone();
        m.task_lost = if served_at_once { 0 } else { usize::MAX };
        {
            let mut s = session(&mut m, Some("@s-1".to_string()));
            s.set_clock(TEST_NOW, PDT);
            s.set_zone_lookup(test_zones);
            s.set_turn_end_timing(TurnEndTiming {
                retry_backoff: vec![Duration::ZERO; 3],
                ..TurnEndTiming::default()
            });
            let point = point_at(&s, wall.clone(), 101);
            let action = s
                .turn_end_at_point(&point, None, &opts)
                .expect("a decision");
            s.task_edge(&point.screen, &opts, &mut Alone)
                .expect("the edge");
            s.turn_end_execute(&point, action, &opts, &[], &mut Alone)
                .expect("carried out");
            assert_eq!(s.ctl.turns, 1, "the retry typed");
            assert!(s.turn_end.act_in_flight(), "and not taken yet");
            // The read served from here on; the point decided again.
            s.ctl.task_lost = 0;
            s.turn_end_now(&point, &opts, &[], &mut Alone)
                .expect("decided again");
        }
        m
    };
    let m = run(false);
    assert!(
        m.task_requests.iter().filter(|r| *r == "task").count() >= 2,
        "turned away, then served: {:?}",
        m.task_requests
    );
    assert!(task_marks(&m).is_empty(), "{:?}", m.task_requests);
    assert_eq!(m.task, published, "the record stands");
    // NEGATIVE CONTROL: served at once, before the retry.
    let m = run(true);
    assert_eq!(
        task_marks(&m),
        ["task mark working why=turn"],
        "{:?}",
        m.task_requests
    );
}

/// A WORKER'S DONE CHECK GOES WITHOUT THE BACK-OFF (design §2.4): the loop
/// meets a worker's done report at its first point — a short turn, whose
/// back-off an idle person's tokens are saved by — and, its task record read,
/// types the check at once: its manager waits. NEGATIVE CONTROL: a session
/// with no task record waits the back-off out (`WAITING … back-off`) and
/// types nothing within the run.
#[test]
fn a_workers_done_check_goes_without_the_back_off() {
    let root = crate::supervise::ScratchDir::new("task", "backoff");
    let text = transcript_of(&[
        task_row("user", "u-task", "", "Fix the parser."),
        task_row("assistant", "a-1", "msg_1", "Fixed the parser; all done."),
    ]);
    let run = |task: Option<(u64, String)>| {
        let host = TaskHost::reading(&root.join("t.jsonl"), &[&text]);
        let journal = root.join(format!("journal-{}.jsonl", task.is_some()));
        let mut m = Mock::new(vec![ended("Fixed the parser; all done.")]);
        m.exit_when = Some(|m| m.turns > 0 || m.stalls >= 3);
        m.vanish_after = Some(3);
        m.task = task;
        let mut lines = tasked_watch(&mut m, &host, &root.join("tasks"), Some(&journal));
        lines.extend(journal_records(&journal).0.into_iter().map(|r| r.line));
        (m, lines)
    };
    let (m, lines) = run(working_task());
    assert!(
        lines.iter().any(|l| l.starts_with("CONTINUED ")
            && l.ends_with(&format!("rule={RULE_DONE_CHECK} {}", clip(DONE_CHECK)))),
        "{lines:#?}"
    );
    assert!(!lines.iter().any(|l| l.contains("back-off")), "{lines:#?}");
    assert_eq!(m.turns, 1);
    // NEGATIVE CONTROL: no task record.
    let (m, lines) = run(None);
    assert!(
        lines
            .iter()
            .any(|l| l.starts_with("WAITING ") && l.contains("1 short turn(s) in a row")),
        "{lines:#?}"
    );
    assert_eq!(m.turns, 0, "{lines:#?}");
}

/// THE OWNER'S OFF IS READ BEFORE A CARRIED WAIT'S BREAK GOES TO THE HOST
/// (the merge review): a break of the agent's background work is offered to
/// the host only on the session's word read fresh (main's c67772c33), and a
/// wait the session's transcript carries (BG-1: the screen draws no waiting
/// row) is such a break. The owner chooses Off as the read is taken: no step
/// is offered. NEGATIVE CONTROLS: under Cruise the carried break is offered;
/// a drawn wait under Off offers none, as before.
#[test]
fn a_carried_waits_break_reads_the_owners_off_before_the_host_step() {
    let carried = waiting_on(&[
        "⏺ Monitor event: \"lander\"",
        "",
        "⏺ Still in its crates-tests lane. I restarted the watch.",
        "",
    ]);
    for (label, screen, tail, word, offered) in [
        (
            "carried",
            &carried,
            Some(transcript_closed(1)),
            "off",
            false,
        ),
        (
            "carried",
            &carried,
            Some(transcript_closed(1)),
            "cruise",
            true,
        ),
        ("drawn", &woken(&[]), None, "off", false),
    ] {
        let host = Arc::new(CarriedHost {
            launched: tail.as_ref().map(|_| transcript_at("20:00:00")),
            tail,
            ..CarriedHost::default()
        });
        let mut m = Mock::new(vec![busy_screen(), screen.clone()]);
        m.autopilot = Some("cruise");
        m.autopilot_on.insert(1, Some(word));
        m.vanish_after = Some(2);
        let opts = SuperviseOpts {
            idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
            ..hosted(30)
        };
        let (lines, _) = watch_lines_with(&mut m, &opts, |s| {
            s.set_background_settle(Duration::ZERO);
        });
        assert_eq!(
            host.backgrounds.load(Ordering::SeqCst) > 0,
            offered,
            "{label} {word}: {lines:#?}\n{:#?}",
            m.requests
        );
        // The break read the session's word fresh: past the start-up read.
        assert!(m.metas > 1, "{label} {word}: {:#?}", m.requests);
    }
}

/// The rows `ledger` gained past the first `seen`, stamped `now_ms` (the
/// test's fixed clock: the ledger stamps its rows on the real one, which the
/// test's does not move) and kept in `books`: the ledger as a loop that
/// follows reads it, each row at the instant it was written.
fn stamp_rows(ledger: &Path, seen: &mut usize, books: &mut Vec<String>, now_ms: i64) {
    let body = std::fs::read_to_string(ledger).unwrap_or_default();
    for (i, line) in body.lines().enumerate().skip(*seen) {
        let ms = now_ms + i64::try_from(i - *seen).unwrap_or(0);
        let stamped = match line.strip_prefix("{\"ts\":") {
            Some(rest) => {
                let digits = rest.chars().take_while(char::is_ascii_digit).count();
                format!("{{\"ts\":{ms}{}", &rest[digits..])
            }
            None => line.to_string(),
        };
        books.push(stamped);
    }
    *seen = body.lines().count();
}

/// A TRY'S OWN SHORT TURN THAT ENDS ON ITS LIMIT IS WHERE ITS NEXT RUNG
/// COUNTS FROM, FOR A LOOP THAT FOLLOWS TOO (the verifier of 5b72b1613,
/// R5-2). A spend limit's try is taken (its turn read busy 20 s on), works
/// under `progress` and ends on the limit again: the first loop moves the
/// track's appearance to that point (its retry's answer) and keeps the try's
/// two-hour rung. A loop that follows on the ledger, each row at the instant
/// it was written ([`stamp_rows`]), types no sooner, attached after that
/// turn (the wall's row that met the try: `approvals::UsageAttempt::met_ms`)
/// or into it (the seed's first read of its limit is the try's answer:
/// `TurnEndState::track_wall`). Measured before: both counted from the try,
/// 100 and 260 s sooner. NEGATIVE CONTROL: the try's turn works past
/// `progress` (six minutes): the first loop starts the episode again (its
/// end row), and a successor takes up no try and types no sooner.
#[test]
fn a_tries_own_short_turn_ending_on_its_limit_is_where_its_next_rung_counts_from() {
    use crate::supervise::approvals::{Ledger, open_wall, usage_attempt};
    use crate::supervise::policy::turn_end::{RULE_LIMIT_RESUME, decide_turn_end};
    // The spend limit's entitlement ladder: under `[harness] usage_credits =
    // true` alone.
    let opts = SuperviseOpts {
        policy: SupervisorConfig {
            model_fallback: None,
            usage_credits: true,
            ..owners_policy()
        },
        ..auto(30)
    };
    let spend = {
        let mut r = rows(&[
            "⏺ Running the suite.",
            "  ⎿  You've hit your monthly spend limit.",
            "",
            "✻ Worked for 3m 2s · done 4:51 PM",
            "",
        ]);
        r.extend(composer("  ? for shortcuts"));
        r
    };
    let live = {
        let mut r = rows(&[
            "❯ keep going",
            "",
            "⏺ Working.",
            "",
            "✻ Synthesizing… (18s)",
            "",
        ]);
        r.extend(composer("  esc to interrupt"));
        r
    };
    type Decided = Option<(i64, Option<&'static str>)>;
    let decided = |s: &mut Session<'_, Mock>,
                   rows: &[String],
                   seq: u64,
                   worked: Option<Duration>|
     -> Decided {
        let point = point_at(s, rows.to_vec(), seq);
        match s
            .turn_end_at_point(&point, worked, &opts)
            .expect("a decision")
        {
            TurnEndAction::WaitUntil { until, .. } => {
                let r = s.turn_end_reading(&point.screen, None, &opts);
                Some((
                    s.unix_of(until),
                    decide_turn_end(&s.turn_end, &r, &opts.policy, until).rule_id(),
                ))
            }
            other => Some((s.now_unix(), other.rule_id())),
        }
    };
    let t = TEST_NOW;
    let mut wrong = Vec::new();
    for (n, (work_s, after)) in [
        (240_i64, true),
        (240, false),
        (100, true),
        (100, false),
        (360, true),
    ]
    .into_iter()
    .enumerate()
    {
        let case = format!(
            "the try's turn works {work_s} s, the successor attached {}",
            if after { "after it" } else { "into it" }
        );
        let (dir, ledger) = ledger_at(&format!("short-try-turn-{n}"));
        let books_path = dir.join("books.jsonl");
        let (mut seen, mut books) = (0, Vec::new());
        let mut m = Mock::new(vec![spend.clone()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_zone_lookup(test_zones);
        s.ledger = Ledger::open(Some(&ledger), Some("@s-1"), &mut Vec::new());
        s.set_turn_end_timing(TurnEndTiming {
            take_within: Duration::ZERO,
            ..TurnEndTiming::default()
        });
        s.set_clock(t, PDT);
        let wait = decided(&mut s, &spend, 100, Some(Duration::from_secs(3 * 60)));
        stamp_rows(&ledger, &mut seen, &mut books, t * 1000);
        let try_at = wait.map_or(t, |(until, _)| until);
        s.set_clock(try_at, PDT);
        let p = point_at(&s, spend.clone(), 101);
        let a = s.turn_end_at_point(&p, None, &opts).expect("the try");
        assert_eq!(a.rule_id(), Some(RULE_LIMIT_RESUME), "{case}");
        s.pass_wake_settle();
        s.turn_end_execute(&p, a, &opts, &[], &mut Alone)
            .expect("typed");
        stamp_rows(&ledger, &mut seen, &mut books, try_at * 1000);
        // The try taken: its own turn read busy twenty seconds on.
        s.set_clock(try_at + 20, PDT);
        let reader = s.reader(&live);
        s.end_memory_on_live_turn(reader, &live, 102);
        s.turn_end.took();
        stamp_rows(&ledger, &mut seen, &mut books, (try_at + 20) * 1000);
        let end_at = try_at + 20 + work_s;
        let attach = if after {
            end_at + 30
        } else {
            try_at + 20 + work_s / 2
        };
        if !after {
            std::fs::write(&books_path, books.join("\n") + "\n").expect("the books");
        }
        s.set_clock(end_at, PDT);
        let first = decided(
            &mut s,
            &spend,
            103,
            Some(Duration::from_secs(work_s.unsigned_abs())),
        );
        stamp_rows(&ledger, &mut seen, &mut books, end_at * 1000);
        if after {
            std::fs::write(&books_path, books.join("\n") + "\n").expect("the books");
        }
        drop(s);
        let seed = usage_attempt(&books_path, Some("@s-1"));
        let mut m2 = Mock::new(vec![spend.clone()]);
        let mut s2 = session(&mut m2, Some("@s-1".to_string()));
        s2.set_clock(attach, PDT);
        s2.set_zone_lookup(test_zones);
        s2.ledger = Ledger::open(Some(&books_path), Some("@s-1"), &mut Vec::new());
        seed_usage_act(
            &mut s2.turn_end,
            &books_path,
            s2.setup.sid.as_deref(),
            attach * 1000,
            Instant::now(),
        );
        s2.seed_wall_memory(open_wall(&books_path, Some("@s-1")));
        // Attached into the turn, it sees its second half end on the limit.
        let next = if after {
            decided(&mut s2, &spend, 101, None)
        } else {
            s2.set_clock(end_at, PDT);
            decided(
                &mut s2,
                &spend,
                101,
                Some(Duration::from_secs((work_s / 2).unsigned_abs())),
            )
        };
        drop(s2);
        let _ = std::fs::remove_dir_all(&dir);
        let due = |d: Decided| d.filter(|&(_, rule)| rule == Some(RULE_LIMIT_RESUME));
        let (Some((mine, _)), Some((theirs, _))) = (due(first), due(next)) else {
            wrong.push(format!("{case}: first loop {first:?}, successor {next:?}"));
            continue;
        };
        let restarted = work_s >= 5 * 60;
        let ok = if restarted {
            seed.is_none() && theirs >= mine
        } else {
            // The try's rung, two hours from its own turn's end.
            mine == end_at + 120 * 60 && theirs == mine
        };
        if !ok {
            wrong.push(format!(
                "{case}: the first loop at try+{}s, the successor (seed {seed:?}) at try+{}s",
                mine - try_at,
                theirs - try_at
            ));
        }
    }
    assert!(wrong.is_empty(), "{wrong:#?}");
}

/// A TRY INSIDE ITS TAKE WINDOW IS AWAITED BY A LOOP THAT FOLLOWS (the
/// verifier of 5b72b1613, M7-1). A spend limit's try, its take window the
/// default 30 s: the loop reads the try's screen again 5 s on (the same
/// notice: no answer yet), the try is taken (a live turn 20 s on), and its own
/// turn works three hours and ends on the spend limit: the first loop starts
/// the wall's episode again (the try's work) and types 30 minutes after it. A
/// loop that follows attached inside the window — 1 s after the try (its
/// books the try's row alone), or 6 s after it (the window's wall row too) —
/// on the ledger as it stood, each row at its instant ([`stamp_rows`]),
/// types at the same instant — and attached 19 s after it, its first look
/// the try's turn, it writes the take as the first loop does
/// (`approvals::WALL_TAKEN`: the window's wall row is no try met again, for a
/// third loop). Measured before: it read the try's screen as the try met
/// again, and typed the moment the three-hour turn ended, 30 minutes sooner.
/// NEGATIVE CONTROLS: a 90-minute turn, the same; and a
/// successor attached past the window, the try judged met there and a
/// person's 20-minute turn after it, holds the try's two-hour rung as the
/// first loop does (the take window's slack aside) — it awaits nothing.
#[test]
fn a_try_inside_its_take_window_is_awaited_by_a_loop_that_follows() {
    use crate::supervise::approvals::{Ledger, open_wall};
    use crate::supervise::policy::turn_end::{RULE_LIMIT_RESUME, decide_turn_end};
    // The spend limit's entitlement ladder: under `[harness] usage_credits =
    // true` alone.
    let opts = SuperviseOpts {
        policy: SupervisorConfig {
            model_fallback: None,
            usage_credits: true,
            ..owners_policy()
        },
        ..auto(30)
    };
    let spend = {
        let mut r = rows(&[
            "⏺ Running the suite.",
            "  ⎿  You've hit your monthly spend limit.",
            "",
            "✻ Worked for 3m 2s · done 4:51 PM",
            "",
        ]);
        r.extend(composer("  ? for shortcuts"));
        r
    };
    let live = |prompt: &str| {
        let mut r = rows(&[
            &format!("❯ {prompt}"),
            "",
            "⏺ Working.",
            "",
            "✻ Synthesizing… (18s)",
            "",
        ]);
        r.extend(composer("  esc to interrupt"));
        r
    };
    type Decided = Option<(i64, Option<&'static str>)>;
    let decided = |s: &mut Session<'_, Mock>,
                   rows: &[String],
                   seq: u64,
                   worked: Option<Duration>|
     -> Decided {
        let point = point_at(s, rows.to_vec(), seq);
        match s
            .turn_end_at_point(&point, worked, &opts)
            .expect("a decision")
        {
            TurnEndAction::WaitUntil { until, .. } => {
                let r = s.turn_end_reading(&point.screen, None, &opts);
                Some((
                    s.unix_of(until),
                    decide_turn_end(&s.turn_end, &r, &opts.policy, until).rule_id(),
                ))
            }
            other => Some((s.now_unix(), other.rule_id())),
        }
    };
    let busy = |s: &mut Session<'_, Mock>, rows: &[String], seq: u64| {
        let reader = s.reader(rows);
        s.end_memory_on_live_turn(reader, rows, seq);
        s.turn_end.took();
    };
    let t = TEST_NOW;
    let mut wrong = Vec::new();
    // (case, the successor's attach after the try, the try's own turn's work;
    // `None`: the window passes, the try is met, a person's turn follows)
    for (n, (case, attach_s, work)) in [
        (
            "1 s after the try, its own 3 h turn",
            1_i64,
            Some(3 * 3600_i64),
        ),
        ("6 s after the try, its own 3 h turn", 6, Some(3 * 3600)),
        (
            "19 s after the try, its first look the try's turn",
            19,
            Some(3 * 3600),
        ),
        (
            "control: 1 s after the try, its own 90 min turn",
            1,
            Some(90 * 60),
        ),
        (
            "control: past the window, the try met, a person's turn",
            45,
            None,
        ),
    ]
    .into_iter()
    .enumerate()
    {
        let (dir, ledger) = ledger_at(&format!("try-in-window-{n}"));
        let books_path = dir.join("books.jsonl");
        let (mut seen, mut books) = (0, Vec::new());
        let mut m = Mock::new(vec![spend.clone()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_zone_lookup(test_zones);
        s.ledger = Ledger::open(Some(&ledger), Some("@s-1"), &mut Vec::new());
        // The default take window, or one the test outlasts.
        let window = if work.is_none() {
            Duration::from_millis(50)
        } else {
            TurnEndTiming::default().take_within
        };
        s.set_turn_end_timing(TurnEndTiming {
            take_within: window,
            ..TurnEndTiming::default()
        });
        s.set_clock(t, PDT);
        let wait = decided(&mut s, &spend, 100, Some(Duration::from_secs(3 * 60)));
        stamp_rows(&ledger, &mut seen, &mut books, t * 1000);
        let try_at = wait.map_or(t, |(until, _)| until);
        s.set_clock(try_at, PDT);
        let p = point_at(&s, spend.clone(), 101);
        let a = s.turn_end_at_point(&p, None, &opts).expect("the try");
        assert_eq!(a.rule_id(), Some(RULE_LIMIT_RESUME), "{case}");
        s.pass_wake_settle();
        s.turn_end_execute(&p, a, &opts, &[], &mut Alone)
            .expect("typed");
        stamp_rows(&ledger, &mut seen, &mut books, try_at * 1000);
        let snapshot = |books: &[String], at: i64| {
            if at == attach_s {
                std::fs::write(&books_path, books.join("\n") + "\n").expect("the books");
            }
        };
        snapshot(&books, 1);
        // The try's screen read again inside its window.
        s.set_clock(try_at + 5, PDT);
        let _ = decided(&mut s, &spend, 102, None);
        stamp_rows(&ledger, &mut seen, &mut books, (try_at + 5) * 1000);
        snapshot(&books, 6);
        snapshot(&books, 19);
        // The successor's events from its attach on: (when, the screen, a
        // busy read or a point, the work it saw).
        let mut events: Vec<(i64, Vec<String>, bool, Option<Duration>)> = Vec::new();
        let (first, end_at) = match work {
            Some(work) => {
                // The try taken; its own turn ends on the limit.
                s.set_clock(try_at + 20, PDT);
                busy(&mut s, &live("keep going"), 103);
                stamp_rows(&ledger, &mut seen, &mut books, (try_at + 20) * 1000);
                let end_at = try_at + 20 + work;
                s.set_clock(end_at, PDT);
                let first = decided(
                    &mut s,
                    &spend,
                    104,
                    Some(Duration::from_secs(work.unsigned_abs())),
                );
                events.push((try_at + 5, spend.clone(), false, None));
                events.push((try_at + 20, live("keep going"), true, None));
                events.push((
                    end_at,
                    spend.clone(),
                    false,
                    Some(Duration::from_secs(work.unsigned_abs())),
                ));
                (first, end_at)
            }
            None => {
                // The window passes on the worker's clock: the try met.
                std::thread::sleep(window * 2);
                s.set_clock(try_at + 40, PDT);
                let _ = decided(&mut s, &spend, 103, None);
                stamp_rows(&ledger, &mut seen, &mut books, (try_at + 40) * 1000);
                snapshot(&books, 45);
                // A person's turn twenty minutes on, twenty minutes long.
                s.set_clock(try_at + 20 * 60, PDT);
                busy(&mut s, &live("please look at the schema"), 104);
                stamp_rows(&ledger, &mut seen, &mut books, (try_at + 20 * 60) * 1000);
                let end_at = try_at + 40 * 60;
                s.set_clock(end_at, PDT);
                let first = decided(&mut s, &spend, 105, Some(Duration::from_secs(20 * 60)));
                events.push((
                    try_at + 20 * 60,
                    live("please look at the schema"),
                    true,
                    None,
                ));
                events.push((
                    end_at,
                    spend.clone(),
                    false,
                    Some(Duration::from_secs(20 * 60)),
                ));
                (first, end_at)
            }
        };
        drop(s);
        // The successor, in `drive_loop`'s order, its own default timing.
        let attach = try_at + attach_s;
        let mut m2 = Mock::new(vec![spend.clone()]);
        let mut s2 = session(&mut m2, Some("@s-1".to_string()));
        s2.set_clock(attach, PDT);
        s2.set_zone_lookup(test_zones);
        s2.ledger = Ledger::open(Some(&books_path), Some("@s-1"), &mut Vec::new());
        seed_usage_act(
            &mut s2.turn_end,
            &books_path,
            s2.setup.sid.as_deref(),
            attach * 1000,
            Instant::now(),
        );
        s2.seed_wall_memory(open_wall(&books_path, Some("@s-1")));
        // Its first look: the screen standing at the attach (the try's own
        // turn, read busy, for the one attached just before it).
        let mut next = None;
        if attach_s != 19 {
            next = decided(&mut s2, &spend, 201, None);
        }
        for (seq, (at, rows, is_busy, worked)) in
            (202..).zip(events.into_iter().filter(|e| e.0 > attach))
        {
            s2.set_clock(at, PDT);
            if is_busy {
                busy(&mut s2, &rows, seq);
            } else {
                next = decided(
                    &mut s2,
                    &rows,
                    seq,
                    worked.map(|w| w.saturating_sub(Duration::from_secs(20))),
                );
            }
        }
        drop(s2);
        let taken = std::fs::read_to_string(&books_path)
            .unwrap_or_default()
            .lines()
            .filter(|l| l.contains(crate::supervise::approvals::WALL_TAKEN))
            .count();
        let _ = std::fs::remove_dir_all(&dir);
        let due = |d: Decided| d.filter(|&(_, rule)| rule == Some(RULE_LIMIT_RESUME));
        let (Some((mine, _)), Some((theirs, _))) = (due(first), due(next)) else {
            wrong.push(format!("{case}: first loop {first:?}, successor {next:?}"));
            continue;
        };
        let ok = if work.is_some() {
            // Thirty minutes from the wall the try's own turn ended on; the
            // successor's busy read wrote the take.
            mine == end_at + 30 * 60 && theirs == mine && taken == 1
        } else {
            // The try's rung, two hours from its answer (the window's end for
            // the first loop, the wall's row for the successor).
            mine == try_at + 40 + 120 * 60 && theirs + 40 >= mine && theirs <= mine
        };
        if !ok {
            wrong.push(format!(
                "{case}: the first loop at try+{}s, the successor at try+{}s, {taken} take row(s)",
                mine - try_at,
                theirs - try_at
            ));
        }
    }
    assert!(wrong.is_empty(), "{wrong:#?}");
}

/// A RESTART OF ANOTHER KIND BEGINS A RUN OF ITS OWN (the verifier of
/// 5b72b1613, R5-3). The critical-memory banner decides a memory restart
/// fifteen minutes before the lab's Sonnet bucket (2.1.300, two days before
/// its reset), and the host answers `wait:held`. Then a person's turn meets
/// the bucket, its notice written five minutes before the decision, and the
/// fallback's relaunch is made at its first ask. The relaunch's row, and the
/// policy, take the fallback's own first ask as when it was made
/// (`made=`): the person's notice, written before it, is the old process's,
/// and the relaunched process's redraw of it is no wall (the short turn's
/// back-off, then `continue@v1`). Measured before: the memory run's count of
/// waits carried its first ask onto the fallback (`made=` fifteen minutes
/// early), the notice read as written after the relaunch, and its redraw as
/// the bucket: its reset waited out, two days on the fallback. So too a run
/// of the fallback's own that another decision ended (`wait:held`, then a
/// turn served): the next fallback is a run of its own. NEGATIVE CONTROL:
/// the fallback with no run before it, the same; the A-2 test keeps a
/// fallback's own run of waits on its first ask
/// ([`a_buckets_notice_the_transcript_wrote_after_the_relaunch_is_the_wall`]).
#[test]
fn a_restart_of_another_kind_begins_a_run_of_its_own() {
    use crate::supervise::approvals::{Ledger, open_model_switch};
    use crate::supervise::policy::turn_end::{RULE_CONTINUE, Restart};
    use aterm_phase::prompt::fixtures as fx;
    const RESET: i64 = 1_792_279_200;
    let now = RESET - 2 * 86_400;
    let armed = fx::screen(fx::WALL_SONNET_BUCKET_AUTO_CONTINUE_ARMED_2_1_300);
    let redrawn: Vec<String> = armed
        .iter()
        .filter(|r| {
            ![
                "Usage limit reached",
                "Continuing automatically",
                "/rate-limit-options",
                "Claude Code will continue automatically",
                "to cancel the wait",
            ]
            .iter()
            .any(|g| r.contains(g))
        })
        .map(|r| r.replace("Sonnet 5.5 · Claude API", "Opus 5.5 · Claude API"))
        .collect();
    let notice = "You've hit your Sonnet limit · resets Oct 17 at 4:20pm (America/Los_Angeles)";
    let tail = |prompt: &str, at: i64| -> String {
        let stamp = crate::harness::usage::rfc3339_utc(at);
        include_str!("fixtures/claude-2.1.294-transcript-session-limit.jsonl")
            .lines()
            .skip(1)
            .filter(|l| !l.contains("\"subtype\":\"informational\""))
            .map(|l| {
                let mut row = l
                    .replace("seventh try", prompt)
                    .replace(
                        "You've hit your session limit · resets 11:33am (America/Los_Angeles)",
                        notice,
                    )
                    .replace("\"five_hour\"", "\"seven_day_sonnet\"");
                for ms in ["921", "951", "952", "953"] {
                    row = row.replace(
                        &format!("\"2026-10-08T16:34:58.{ms}Z\""),
                        &format!("\"{stamp}\""),
                    );
                }
                row
            })
            .collect::<Vec<_>>()
            .join("\n")
            + "\n"
    };
    // The person's turn the bucket answered, five minutes before the fallback.
    let met = tail("please run the integration tests", now - 300);
    // A turn served, its work read, no wall.
    let served = {
        let mut r = rows(&[
            "❯ please run the integration tests",
            "",
            "⏺ Ran them: all green.",
            "",
            "✻ Worked for 4m 0s · done 8:40 AM",
            "",
        ]);
        r.extend(composer("  ? for shortcuts"));
        r
    };
    let mut wrong = Vec::new();
    for (n, before) in [
        "a memory restart's run",
        "a fallback's run another decision ended",
        "none",
    ]
    .into_iter()
    .enumerate()
    {
        let memory_first = before == "a memory restart's run";
        let fallback_first = before.starts_with("a fallback's");
        let answers: &[&'static str] = if before == "none" {
            &["relaunched"]
        } else {
            &["wait:held", "relaunched"]
        };
        let host = AccountHost::scripted(&[None], answers);
        *host.tail.lock().unwrap() = Some(met.clone());
        let opts = SuperviseOpts {
            idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
            policy: owners_policy(),
            ..auto(30)
        };
        let (dir, ledger) = ledger_at(&format!("restart-kinds-{n}"));
        let mut m = Mock::new(vec![armed.clone()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_zone_lookup(test_zones);
        s.ledger = Ledger::open(Some(&ledger), Some("@s-1"), &mut Vec::new());
        s.set_turn_end_timing(TurnEndTiming {
            take_within: Duration::ZERO,
            ..TurnEndTiming::default()
        });
        if memory_first {
            // The critical-memory banner at an idle point, fifteen minutes
            // before; the host cannot restart yet.
            s.set_clock(now - 900, PDT);
            let p = point_at(&s, fx::screen(fx::MEMORY_BANNER_IDLE), 90);
            let a = s
                .turn_end_at_point(&p, None, &opts)
                .expect("the memory restart");
            assert!(
                matches!(
                    &a,
                    TurnEndAction::Restart {
                        why: Restart::Memory,
                        ..
                    }
                ),
                "{a:?}"
            );
            s.pass_wake_settle();
            s.turn_end_execute(&p, a, &opts, &[], &mut Alone)
                .expect("waits");
        }
        if fallback_first {
            // The bucket fifteen minutes before: the fallback waits, then a
            // turn is served (the bucket lifted) and decided on its own.
            s.set_clock(now - 900, PDT);
            let p = point_at(&s, armed.clone(), 90);
            let a = s
                .turn_end_at_point(&p, Some(Duration::from_secs(60)), &opts)
                .expect("the fallback");
            assert!(
                matches!(
                    &a,
                    TurnEndAction::Restart {
                        why: Restart::Model { .. },
                        ..
                    }
                ),
                "{a:?}"
            );
            s.pass_wake_settle();
            s.turn_end_execute(&p, a, &opts, &[], &mut Alone)
                .expect("waits");
            s.set_clock(now - 600, PDT);
            let p = point_at(&s, served.clone(), 91);
            let a = s
                .turn_end_at_point(&p, Some(Duration::from_secs(240)), &opts)
                .expect("the served turn");
            assert!(!matches!(&a, TurnEndAction::Restart { .. }), "{a:?}");
            s.pass_wake_settle();
            s.turn_end_execute(&p, a, &opts, &[], &mut Alone)
                .expect("decided");
        }
        // A person's turn met the bucket: the fallback, made at once.
        s.set_clock(now, PDT);
        let p = point_at(&s, armed.clone(), 100);
        let a = s
            .turn_end_at_point(&p, Some(Duration::from_secs(60)), &opts)
            .expect("the fallback");
        assert!(
            matches!(
                &a,
                TurnEndAction::Restart {
                    why: Restart::Model { .. },
                    ..
                }
            ),
            "{before}: {a:?}"
        );
        s.pass_wake_settle();
        s.turn_end_execute(&p, a, &opts, &[], &mut Alone)
            .expect("relaunched");
        let made = open_model_switch(&ledger, Some("@s-1")).map(|o| o.made_unix);
        // The relaunched process's redraw of that notice.
        s.set_clock(now + 30, PDT);
        s.pass_wake_settle();
        let point = point_at(&s, redrawn.clone(), 102);
        let redraw = s
            .turn_end_at_point(&point, None, &opts)
            .expect("a decision");
        let redraw = match redraw {
            TurnEndAction::WaitUntil { until, .. } => {
                let r = s.turn_end_reading(&point.screen, None, &opts);
                (
                    s.unix_of(until),
                    crate::supervise::policy::turn_end::decide_turn_end(
                        &s.turn_end,
                        &r,
                        &opts.policy,
                        until,
                    )
                    .rule_id(),
                )
            }
            other => (s.now_unix(), other.rule_id()),
        };
        drop(s);
        let _ = std::fs::remove_dir_all(&dir);
        // The continue policy's, within its short back-off: never the
        // bucket's reset.
        if made != Some(now) || redraw.1 != Some(RULE_CONTINUE) || redraw.0 > now + 30 + 120 {
            wrong.push(format!(
                "{before} before: made={:?}, the redraw decides {:?} (now{:+}s)",
                made.map(|m| m - now),
                redraw.1,
                redraw.0 - now
            ));
        }
    }
    assert!(wrong.is_empty(), "{wrong:#?}");
}

/// A FALLBACK'S RELAUNCH IN FLIGHT WHEN ITS LOOP ENDS IS MADE AT THAT RUN'S
/// FIRST ASK FOR A LOOP THAT FOLLOWS (the verifier of 5b72b1613, M7-4). The
/// lab's Sonnet bucket (2.1.300, two days before its reset): the first loop
/// asks the fallback's relaunch, and the host types its line and has not
/// found the new process yet (`wait:resume`). The loop ends there (a
/// seamless update). A person's prompt is answered by the bucket 55 s after
/// the line (the relaunch did not take: the old model's limit), drawn at
/// 60 s. A loop that follows at 61 s, its host carrying the relaunch on
/// (`relaunched` at its first ask), takes up the run the ledger's row names
/// (`approvals::relaunch_waiting`): the relaunch is made at the first loop's
/// first ask, the notice was written after it, and it is the wall — the
/// bucket's reset is waited out. Measured before: no row named the run, the
/// successor's own first ask was taken as when the relaunch was made, the
/// notice read as the relaunched process's redraw, and `continue@v1` went
/// into the standing bucket. NEGATIVE CONTROL: no prompt between, the
/// relaunched process's redraw is the continue policy's as before.
#[test]
fn a_fallbacks_relaunch_in_flight_when_its_loop_ends_is_made_at_its_first_ask() {
    use crate::supervise::approvals::{Ledger, open_model_switch, open_wall, relaunch_waiting};
    use crate::supervise::policy::turn_end::{RULE_CONTINUE, Restart, decide_turn_end};
    use aterm_phase::prompt::fixtures as fx;
    const RESET: i64 = 1_792_279_200;
    let now = RESET - 2 * 86_400;
    let armed = fx::screen(fx::WALL_SONNET_BUCKET_AUTO_CONTINUE_ARMED_2_1_300);
    let redrawn: Vec<String> = armed
        .iter()
        .filter(|r| {
            ![
                "Usage limit reached",
                "Continuing automatically",
                "/rate-limit-options",
                "Claude Code will continue automatically",
                "to cancel the wait",
            ]
            .iter()
            .any(|g| r.contains(g))
        })
        .map(|r| r.replace("Sonnet 5.5 · Claude API", "Opus 5.5 · Claude API"))
        .collect();
    let notice = "You've hit your Sonnet limit · resets Oct 17 at 4:20pm (America/Los_Angeles)";
    let met = {
        let mut rows = redrawn.clone();
        let top = rows
            .iter()
            .position(|r| r.starts_with('─'))
            .expect("the composer's frame");
        rows.splice(
            top..top,
            [
                "❯ please run the integration tests".to_string(),
                format!("  ⎿  {notice}"),
                String::new(),
                "✻ Churned for 0s · done 8:49 AM".to_string(),
                String::new(),
            ],
        );
        rows
    };
    let tail = |prompt: &str, at: i64| -> String {
        let stamp = crate::harness::usage::rfc3339_utc(at);
        include_str!("fixtures/claude-2.1.294-transcript-session-limit.jsonl")
            .lines()
            .skip(1)
            .filter(|l| !l.contains("\"subtype\":\"informational\""))
            .map(|l| {
                let mut row = l
                    .replace("seventh try", prompt)
                    .replace(
                        "You've hit your session limit · resets 11:33am (America/Los_Angeles)",
                        notice,
                    )
                    .replace("\"five_hour\"", "\"seven_day_sonnet\"");
                for ms in ["921", "951", "952", "953"] {
                    row = row.replace(
                        &format!("\"2026-10-08T16:34:58.{ms}Z\""),
                        &format!("\"{stamp}\""),
                    );
                }
                row
            })
            .collect::<Vec<_>>()
            .join("\n")
            + "\n"
    };
    let before = tail("carry on with the task", now - 600);
    let hosted = |transcript: &str, answers: &[&'static str]| {
        let host = AccountHost::scripted(&[None], answers);
        *host.tail.lock().unwrap() = Some(transcript.to_string());
        let opts = SuperviseOpts {
            idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
            policy: owners_policy(),
            ..auto(30)
        };
        (host, opts)
    };
    let mut wrong = Vec::new();
    for (n, answered) in [true, false].into_iter().enumerate() {
        let (dir, ledger) = ledger_at(&format!("relaunch-in-flight-{n}"));
        let (host, opts) = hosted(&before, &["wait:resume"]);
        let mut m = Mock::new(vec![armed.clone()]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_zone_lookup(test_zones);
        s.ledger = Ledger::open(Some(&ledger), Some("@s-1"), &mut Vec::new());
        s.set_turn_end_timing(TurnEndTiming {
            take_within: Duration::ZERO,
            ..TurnEndTiming::default()
        });
        s.set_clock(now, PDT);
        let p = point_at(&s, armed.clone(), 100);
        let a = s.turn_end_at_point(&p, None, &opts).expect("the fallback");
        assert!(
            matches!(
                &a,
                TurnEndAction::Restart {
                    why: Restart::Model { .. },
                    ..
                }
            ),
            "{a:?}"
        );
        s.turn_end_execute(&p, a, &opts, &[], &mut Alone)
            .expect("waits");
        assert_eq!(host.said("restart"), ["restart:model"]);
        // The first loop ends here, its run in the ledger.
        drop(s);
        let run = relaunch_waiting(&ledger, Some("@s-1"));
        // The loop that follows, 61 s on, in `drive_loop`'s order.
        let (screen, transcript) = if answered {
            (
                met.clone(),
                tail("please run the integration tests", now + 55),
            )
        } else {
            (redrawn.clone(), before.clone())
        };
        let (_host2, opts2) = hosted(&transcript, &["relaunched"]);
        let mut m2 = Mock::new(vec![screen.clone()]);
        let mut s2 = session(&mut m2, Some("@s-1".to_string()));
        s2.set_clock(now + 61, PDT);
        s2.set_zone_lookup(test_zones);
        s2.ledger = Ledger::open(Some(&ledger), Some("@s-1"), &mut Vec::new());
        s2.set_turn_end_timing(TurnEndTiming {
            take_within: Duration::ZERO,
            ..TurnEndTiming::default()
        });
        s2.seed_model_switch(&ledger);
        s2.seed_wall_memory(open_wall(&ledger, Some("@s-1")));
        // Its first point asks the relaunch, which its host carries on.
        let p = point_at(&s2, screen.clone(), 101);
        let a = s2
            .turn_end_at_point(&p, None, &opts2)
            .expect("the relaunch");
        let asked = matches!(
            &a,
            TurnEndAction::Restart {
                why: Restart::Model { .. },
                ..
            }
        );
        s2.pass_wake_settle();
        s2.turn_end_execute(&p, a, &opts2, &[], &mut Alone)
            .expect("relaunched");
        let made = open_model_switch(&ledger, Some("@s-1")).map(|o| o.made_unix - now);
        // The relaunch's own row ends the run.
        let ended = relaunch_waiting(&ledger, Some("@s-1")).is_none();
        // Then the screen read again.
        s2.set_clock(now + 70, PDT);
        s2.pass_wake_settle();
        let point = point_at(&s2, screen, 102);
        let decided = match s2
            .turn_end_at_point(&point, None, &opts2)
            .expect("a decision")
        {
            TurnEndAction::WaitUntil { until, .. } => {
                let r = s2.turn_end_reading(&point.screen, None, &opts2);
                (
                    s2.unix_of(until),
                    decide_turn_end(&s2.turn_end, &r, &opts2.policy, until).rule_id(),
                )
            }
            other => (s2.now_unix(), other.rule_id()),
        };
        drop(s2);
        let _ = std::fs::remove_dir_all(&dir);
        let ok = run == Some(now)
            && asked
            && made == Some(0)
            && ended
            && if answered {
                decided.0 >= RESET
            } else {
                decided.1 == Some(RULE_CONTINUE) && decided.0 < RESET
            };
        if !ok {
            wrong.push(format!(
                "{}: the run's row {:?}, the successor asked the relaunch {asked}, made=now{:+?} \
                 (the run ended {ended}), then {:?} at now{:+}s",
                if answered {
                    "a person's prompt answered"
                } else {
                    "control: the redraw"
                },
                run.map(|r| r - now),
                made,
                decided.1,
                decided.0 - now
            ));
        }
    }
    assert!(wrong.is_empty(), "{wrong:#?}");
}

/// A host that withholds the continuations while `on` ([`IdleHost::withholds_turn_end`]).
#[derive(Debug, Default)]
struct Withholds {
    on: AtomicBool,
}

impl IdleHost for Withholds {
    fn wants(&self) -> bool {
        false
    }
    fn at_idle(&self) -> Option<HostStep> {
        None
    }
    fn owns_turn_end(&self) -> bool {
        false
    }
    fn withholds_turn_end(&self) -> bool {
        self.on.load(Ordering::SeqCst)
    }
}

/// A HOST THAT WITHHOLDS THE CONTINUATIONS (a full disk) types nothing at a
/// turn end that would be continued, and is no upgrade: the loop's point is
/// held for it, not escalated. NEGATIVE CONTROL: the same host withholding
/// nothing lets `keep going` through, once.
#[test]
fn a_host_that_withholds_the_continuations_types_nothing() {
    let run = |on: bool| {
        let host = Arc::new(Withholds {
            on: AtomicBool::new(on),
        });
        let mut m = Mock::new(vec![
            busy_screen(),
            ended("Fixed the parser; the suite is green."),
        ]);
        m.vanish_after = Some(2);
        let opts = SuperviseOpts {
            idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
            ..hosted(30)
        };
        let (lines, _) = watch_lines(&mut m, &opts);
        (count(&m, "turn"), lines)
    };
    let (typed, lines) = run(true);
    assert_eq!(typed, 0, "{lines:#?}");
    assert!(
        !lines.iter().any(|l| l.starts_with("CONTINUED")),
        "{lines:#?}"
    );
    let (typed, lines) = run(false);
    assert_eq!(typed, 1, "{lines:#?}");
}

/// The count is the actual scripted host's count at its initial screen,
/// not a default for an omitted wire field: a Claude Code session whose turn
/// ended, then the composer showing `shown` as the read-back.
fn paste_person_run(text: &str, shown: &str, setup: impl FnOnce(&mut Mock)) -> (Mock, Vec<String>) {
    const SAID: &str = "Fixed the parser; the suite is green.";
    let mut m = Mock::new(vec![busy_screen(), ended(SAID), typed_in(SAID, shown)]);
    m.gen_fence = true;
    m.sends_gen = true;
    m.human_seq = Some(0);
    m.human = vec!["null"];
    m.help = FENCED_HELP.to_string();
    m.screen_cols.insert(2, 2 + shown.chars().count());
    m.vanish_after = Some(2);
    m.exit_when = Some(|m| {
        !m.person_skipped.is_empty()
            || m.requests.iter().any(|r| {
                (r.starts_with("key ") && r.ends_with(" enter"))
                    || r.starts_with("meta set attention")
            })
    });
    setup(&mut m);
    let opts = SuperviseOpts {
        policy: SupervisorConfig {
            continue_text: text.to_string(),
            ..owners_policy()
        },
        ..auto(30)
    };
    let (lines, _) = watch_lines_with(&mut m, &opts, |s| {
        s.set_turn_end_timing(TurnEndTiming {
            min_work: Duration::ZERO,
            ..TurnEndTiming::default()
        });
    });
    (m, lines)
}

/// The host's original person count must survive the send, the read-back
/// and Enter. NEGATIVE CONTROLS: the admitted whole write and Enter at a
/// count of 0 and of 7.
#[test]
fn a_fenced_paste_cannot_submit_after_its_original_person_count_is_lost() {
    let long = "carry on";
    for text in ["carry on", "keep going"] {
        for human in [0, 7] {
            let (m, lines) = paste_person_run(text, text, |m| {
                m.human_seq = Some(human);
            });
            assert!(
                m.requests
                    .iter()
                    .any(|r| r.starts_with("send ") && r.ends_with(text)),
                "the admitted whole write, count {human}: {lines:#?}\n{:#?}",
                m.requests
            );
            assert!(
                m.requests
                    .iter()
                    .any(|r| r.starts_with("key ") && r.ends_with(" enter"))
                    && lines.iter().any(|l| l.starts_with("CONTINUED ")),
                "the admitted Enter, count {human}: {lines:#?}\n{:#?}",
                m.requests
            );
            assert_eq!(m.human_seq, Some(human));
            assert_eq!(count(&m, "turn"), 0, "no legacy paste");
        }
    }

    let mut failures = Vec::new();
    fn rejected(
        failures: &mut Vec<String>,
        label: &str,
        m: &Mock,
        lines: &[String],
        no_enter_request: bool,
    ) {
        let entered = m
            .requests
            .iter()
            .any(|r| r.starts_with("key ") && r.ends_with(" enter"));
        let recorded = lines.iter().any(|l| l.starts_with("CONTINUED "));
        if recorded || (no_enter_request && entered) || count(m, "turn") != 0 {
            failures.push(format!("{label}: {lines:#?}\n{:#?}", m.requests));
        }
    }

    let (m, lines) = paste_person_run(long, long, |m| {
        m.human_seq = None;
        m.screens.truncate(2);
    });
    if m.requests.iter().any(|r| r.starts_with("send ")) {
        failures.push(format!(
            "the initial missing count wrote: {lines:#?}\n{:#?}",
            m.requests
        ));
    }
    rejected(&mut failures, "missing initial count", &m, &lines, true);

    let (m, lines) = paste_person_run(long, long, |m| {
        m.human_seq = Some(7);
        m.human_seq_on.insert(2, None);
    });
    assert!(
        m.requests
            .iter()
            .any(|r| r.starts_with("send ") && r.ends_with(long))
    );
    assert!(
        m.reads.iter().any(|(i, _)| *i == 2),
        "the missing-count read-back was reached"
    );
    rejected(
        &mut failures,
        "count omitted from read-back",
        &m,
        &lines,
        true,
    );

    let (m, lines) = paste_person_run(long, long, |m| {
        m.human_seq = Some(7);
        m.person_at_send = 1;
        m.screens.truncate(2);
    });
    assert_eq!(m.person_at_send, 0, "the gesture before send occurred");
    assert_eq!(m.human_seq, Some(8));
    if m.person_skipped.len() != 1 {
        failures.push(format!(
            "the send was not skipped for the person: {lines:#?}\n{:#?}",
            m.requests
        ));
    }
    rejected(&mut failures, "person before send", &m, &lines, true);

    let (m, lines) = paste_person_run(long, long, |m| {
        m.human_seq = Some(7);
        m.person_at_key = 1;
    });
    assert_eq!(m.person_at_key, 0, "the gesture before Enter occurred");
    assert_eq!(m.human_seq, Some(8));
    assert!(
        m.requests
            .iter()
            .any(|r| r.starts_with("key ") && r.ends_with(" enter"))
    );
    if m.person_skipped.len() != 1 {
        failures.push(format!(
            "Enter was not skipped for the person: {lines:#?}\n{:#?}",
            m.requests
        ));
    }
    rejected(&mut failures, "person before Enter", &m, &lines, false);
    assert!(
        failures.is_empty(),
        "original paste person fence: {failures:#?}"
    );
}

/// Post-fix wire custody: both writes name the original known count,
/// including a genuine zero. Generation and row guards remain present.
#[test]
fn a_fenced_paste_names_its_original_person_in_both_writes() {
    for human in [0, 7] {
        let (m, lines) = paste_person_run("carry on", "carry on", |m| {
            m.human_seq = Some(human);
        });
        let writes: Vec<&String> = m
            .requests
            .iter()
            .filter(|r| r.starts_with("send ") || r.starts_with("key "))
            .collect();
        assert_eq!(writes.len(), 2, "{lines:#?}\n{:#?}", m.requests);
        for request in writes {
            let words: Vec<&str> = request.split(' ').collect();
            assert!(
                words.contains(&format!("if-human={human}").as_str()),
                "{request}"
            );
            assert!(words.iter().any(|w| w.starts_with("if-gen=")), "{request}");
            assert!(words.iter().any(|w| w.starts_with("if=")), "{request}");
        }
    }
}

/// A host that advertises generation fences may still refuse if-human.
/// That refusal must not turn its next decision into a legacy unfenced turn.
#[test]
fn a_refused_paste_person_fence_never_becomes_a_legacy_turn() {
    let said = "Fixed the parser; the suite is green.";
    let (m, lines) = paste_person_run("carry on", "carry on", |m| {
        m.human_seq = Some(7);
        m.screens = vec![busy_screen(), ended(said), busy_screen(), ended(said)];
        m.send_replies = VecDeque::from([
            err("usage: send [if-gen=<g>] [if=<re>] [--] <text>"),
            err("usage: send [if-gen=<g>] [if=<re>] [--] <text>"),
        ]);
        m.exit_when = Some(|m| {
            m.requests.iter().filter(|r| r.starts_with("send ")).count() >= 2 || m.turns > 0
        });
    });
    let sends: Vec<&String> = m
        .requests
        .iter()
        .filter(|r| r.starts_with("send "))
        .collect();
    assert_eq!(
        sends.len(),
        2,
        "both decisions reached the strict send: {lines:#?}\n{:#?}",
        m.requests
    );
    assert!(
        sends
            .iter()
            .all(|r| r.starts_with("send if-human=7 if-gen=")),
        "{sends:#?}"
    );
    assert_eq!(count(&m, "turn"), 0, "{lines:#?}\n{:#?}", m.requests);
    assert!(
        !m.requests.iter().any(|r| r.starts_with("key ")),
        "{:#?}",
        m.requests
    );
    assert!(
        !lines.iter().any(|l| l.starts_with("CONTINUED ")),
        "{lines:#?}"
    );
}

/// The login every [`LatchHost`] signs in with: the default stored login.
const LATCH_KEY: &str = "default";

/// A host whose tabs share one login ([`LoginLatches`]), as a window's tabs
/// do: this session is tab `sid`, and everything the loop asked of the latch
/// is kept, in order. `peer`: tab `peer` reads the login's sign-in standing
/// right after this tab takes it (a second tab at the same wall meanwhile).
/// `blind`: the latch is never read before the act, as where another tab
/// took the sign-in between this tab's read and its `/login`.
#[derive(Debug)]
struct LatchHost {
    latches: Arc<LoginLatches>,
    sid: &'static str,
    peer: Option<&'static str>,
    blind: bool,
    /// The login comes back in this tab right after this one takes its
    /// sign-in: the owner signed in elsewhere.
    back_in: Option<&'static str>,
    said: std::sync::Mutex<Vec<String>>,
}

impl LatchHost {
    fn tab(latches: &Arc<LoginLatches>, sid: &'static str) -> Self {
        Self {
            latches: Arc::clone(latches),
            sid,
            peer: None,
            blind: false,
            back_in: None,
            said: std::sync::Mutex::new(Vec::new()),
        }
    }

    fn said(&self) -> Vec<String> {
        self.said.lock().unwrap().clone()
    }
}

impl IdleHost for LatchHost {
    fn wants(&self) -> bool {
        false
    }
    fn at_idle(&self) -> Option<HostStep> {
        None
    }
    fn owns_turn_end(&self) -> bool {
        false
    }
    fn login_shared(&self) -> Option<LoginShared> {
        let shared = (!self.blind)
            .then(|| self.latches.shared(LATCH_KEY, self.sid))
            .flatten();
        self.said.lock().unwrap().push(format!("shared:{shared:?}"));
        shared
    }
    fn login_carry(&self) -> Result<(), String> {
        let carried = self.latches.carry(LATCH_KEY, self.sid);
        self.said.lock().unwrap().push(format!("carry:{carried:?}"));
        if carried.is_ok()
            && let Some(peer) = self.peer
        {
            let read = self.latches.shared(LATCH_KEY, peer);
            self.said.lock().unwrap().push(format!("{peer}:{read:?}"));
        }
        if carried.is_ok()
            && let Some(by) = self.back_in
        {
            self.latches.back(LATCH_KEY, by);
            self.said.lock().unwrap().push(format!("back in {by}"));
        }
        carried
    }
    fn login_abandon(&self) {
        self.said.lock().unwrap().push("abandon".to_string());
        self.latches.gone(self.sid);
    }
    fn login_back(&self) {
        self.said.lock().unwrap().push("back".to_string());
        self.latches.back(LATCH_KEY, self.sid);
    }
}

/// ONE SIGN-IN PER LOGIN, HOWEVER MANY TABS SHARE IT (the review's F7: each
/// tab on a shared login typed its own `/login`, and the owner met as many
/// browser sign-ins). Over one host's latch:
///
/// 1. tab @1 meets the wall, takes the login's sign-in and types `/login`;
///    tab @2, at the same wall meanwhile, reads it carried; the sign-in
///    finishes, @1's turn works on, and its host is told the login is back;
/// 2. tab @2 reads the login back in @1: its turn delivered again
///    (`login-back@v1`), no `/login` of its own, and once that turn works
///    on, nothing is left of the sign-in;
/// 3. a tab that meets the wall while @1's sign-in stands waits on it and
///    types nothing;
/// 4. a tab that read nothing standing but finds the sign-in taken at its
///    act (another tab took it in between) types nothing either.
///
/// NEGATIVE CONTROL: step 1 is the lone tab's `/login` (as
/// `a_lost_login_types_login_and_raises_no_badge`).
#[test]
fn one_sign_in_per_login_however_many_tabs_share_it() {
    let mut lost = rows(&[
        "⏺ Pushing the branch.",
        "  ⎿  Not logged in · Please run /login",
        "",
        "✻ Worked for 3m 2s · done 4:51 PM",
        "",
    ]);
    lost.extend(composer("  ? for shortcuts"));
    let dialog = rows(&[
        " Browser didn't open? Use the url below to sign in (⌘/ctrl + click):",
        " https://claude.ai/oauth/authorize?code=true",
        "",
        " Paste code here if prompted >",
    ]);
    // The run's lines, then its journal's records (`<kind> <summary>`).
    let run = |host: &Arc<LatchHost>, screens: Vec<Vec<String>>| {
        let (dir, path) = journal_file(&format!("te-latch-{}", host.sid.trim_start_matches('@')));
        let mut m = Mock::new(screens);
        m.turn_releases = Some(1);
        m.vanish_after = Some(2);
        let mut opts = SuperviseOpts {
            idle_host: Some(Arc::clone(host) as Arc<dyn IdleHost>),
            journal: Some(path.clone()),
            ..hosted(30)
        };
        // The point after the login is the policy's to continue; quiet.
        opts.policy.continue_policy = false;
        let (lines, _) = watch_lines(&mut m, &opts);
        let (records, _) = journal_records(&path);
        let _ = std::fs::remove_dir_all(&dir);
        let notes: Vec<String> = records
            .into_iter()
            .map(|r| format!("{} {}", r.kind, r.summary))
            .collect();
        (lines, notes)
    };
    // `/login` is a command typed, a turn delivered again a continuation.
    let acts = |lines: &[String]| -> Vec<String> {
        lines
            .iter()
            .filter(|l| l.starts_with("TYPED ") || l.starts_with("CONTINUED "))
            .cloned()
            .collect()
    };
    let typed = |lines: &[String], rule: &str| {
        acts(lines)
            .iter()
            .filter(|l| l.contains(&format!(" rule={rule} ")))
            .count()
    };
    let latches = Arc::new(LoginLatches::default());
    // 1. Tab @1 carries the sign-in; @2 reads it standing.
    let a = Arc::new(LatchHost {
        peer: Some("@2"),
        ..LatchHost::tab(&latches, "@1")
    });
    let (lines, _) = run(
        &a,
        vec![
            busy_screen(),
            lost.clone(),
            dialog.clone(),
            busy_screen(),
            ended("Pushed."),
        ],
    );
    assert_eq!(typed(&lines, RULE_LOGIN), 1, "{lines:#?}");
    assert_eq!(
        typed(&lines, RULE_LOGIN_BACK),
        0,
        "back where it was carried: {lines:#?}"
    );
    let said = a.said();
    let carried_by_1 = Some(LoginShared::Carried {
        by: "@1".to_string(),
    });
    assert_eq!(
        said.iter()
            .filter(|s| s.starts_with("carry:") || s.starts_with("@2:") || *s == "back")
            .cloned()
            .collect::<Vec<_>>(),
        [
            "carry:Ok(())".to_string(),
            format!("@2:{carried_by_1:?}"),
            "back".to_string(),
        ],
        "{said:#?}\n{lines:#?}"
    );
    // 2. Tab @2: the login back in @1, its turn delivered again.
    let b = Arc::new(LatchHost::tab(&latches, "@2"));
    let (lines, _) = run(
        &b,
        vec![busy_screen(), lost.clone(), busy_screen(), ended("Pushed.")],
    );
    assert_eq!(typed(&lines, RULE_LOGIN_BACK), 1, "{lines:#?}");
    assert_eq!(
        typed(&lines, RULE_LOGIN),
        0,
        "no sign-in of its own: {lines:#?}"
    );
    let said = b.said();
    assert!(
        said.iter().all(|s| !s.starts_with("carry:")) && said.last().is_some_and(|s| s == "back"),
        "{said:#?}"
    );
    assert_eq!(
        latches.shared(LATCH_KEY, "@9"),
        None,
        "nothing left of the sign-in"
    );
    // 3. A tab at the wall while @1's sign-in stands: waits on it.
    let latches = Arc::new(LoginLatches::default());
    assert_eq!(latches.carry(LATCH_KEY, "@1"), Ok(()));
    let c = Arc::new(LatchHost::tab(&latches, "@3"));
    let (lines, notes) = run(&c, vec![busy_screen(), lost.clone()]);
    assert!(acts(&lines).is_empty(), "nothing typed: {lines:#?}");
    assert!(
        notes
            .iter()
            .any(|n| n.starts_with("waiting ") && n.contains("@1")),
        "waits on @1's sign-in: {notes:#?}"
    );
    assert!(
        c.said().iter().all(|s| !s.starts_with("carry:")),
        "{:#?}",
        c.said()
    );
    // 4. The sign-in taken between the read and the act.
    let d = Arc::new(LatchHost {
        blind: true,
        ..LatchHost::tab(&latches, "@4")
    });
    let (lines, notes) = run(&d, vec![busy_screen(), lost.clone()]);
    assert!(acts(&lines).is_empty(), "nothing typed: {lines:#?}");
    assert!(
        notes
            .iter()
            .any(|n| n.starts_with("skipped ") && n.contains("@1")),
        "{notes:#?}"
    );
    assert!(
        d.said().iter().any(|s| s == "carry:Err(\"@1\")"),
        "{:#?}",
        d.said()
    );
    // An unacknowledged attempt must not retain its reservation indefinitely.
    // The ordinary full-watch controls above retain a submitted sign-in.
    for lost_reply in [false, true] {
        let latches = Arc::new(LoginLatches::default());
        let host = Arc::new(LatchHost::tab(&latches, "@1"));
        let mut m = fenced(vec![lost.clone()]);
        m.help_send = Some(PROBE_HELP_SEND.to_string());
        if lost_reply {
            m.send_replies.push_back(CtlReply {
                stdout: String::new(),
                stderr: "server closed the connection without responding".to_string(),
                code: 1,
            });
        } else {
            m.human_seq = None;
        }
        let opts = SuperviseOpts {
            idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
            ..hosted(30)
        };
        let mut heard = Heard::default();
        let result = {
            let mut s = session(&mut m, None);
            s.set_clock(TEST_NOW, PDT);
            s.set_zone_lookup(test_zones);
            s.program = Some("claude".to_string());
            let read = s.screen().unwrap();
            let mut point = point_at(&s, read.rows.clone(), read.seq);
            point.screen = read;
            s.turn_end_execute(
                &point,
                TurnEndAction::TypeCommand {
                    command: "/login".to_string(),
                    rule_id: RULE_LOGIN,
                    then: crate::supervise::policy::turn_end::Then::Nothing,
                },
                &opts,
                &[],
                &mut heard,
            )
        };
        assert_eq!(result.is_err(), lost_reply, "{:?}", host.said());
        assert_eq!(
            m.requests.iter().filter(|r| verb_of(r) == "send").count(),
            usize::from(lost_reply),
            "{:#?}",
            m.requests
        );
        assert!(m.requests.iter().all(|r| verb_of(r) != "turn"));
        assert!(host.said().iter().any(|line| line == "carry:Ok(())"));
        assert!(host.said().iter().any(|line| line == "abandon"));
        assert_eq!(latches.shared(LATCH_KEY, "@2"), None);
        assert_eq!(latches.carry(LATCH_KEY, "@2"), Ok(()));
    }
}

/// THE CARRIER'S TURN IS DELIVERED AGAIN WHERE THE LOGIN CAME BACK ELSEWHERE
/// (the review of the login carry, 2026-10-20: the tab whose `/login` was
/// the login's one sign-in never read the login back once the owner signed
/// in in another tab, and its turn stayed stopped under the owner's notice).
/// Tab @1 meets the lost login and types `/login`; the owner signs in in tab
/// @2 meanwhile. While @1's dialog stands the owner is told to close it
/// (`login-back-dialog`, never a sign-in asked of a login that is back: the
/// review's harness-login-misled-dialog), and nothing is typed into it (the
/// dialog takes no keys of the loop's); once that `/login` is left (`Login
/// interrupted`), @1's turn is delivered again, once (`login-back@v1`), with
/// no notice of a sign-in cancelled, and its loss ends as its turn works on.
/// NEGATIVE CONTROL: with the login back nowhere, the dialog is told as the
/// sign-in to finish, its `Login interrupted` as a sign-in cancelled, and
/// nothing is typed into it.
#[test]
fn the_carrier_delivers_its_turn_again_where_the_login_came_back_elsewhere() {
    let wall_row = |r: &String| r.trim_end() == "❯ /login";
    let dialog = handoff();
    let at = dialog.iter().position(wall_row).expect("the /login row");
    let mut lost: Vec<String> = dialog[..at].to_vec();
    while lost.last().is_some_and(|r| r.trim().is_empty()) {
        lost.pop();
    }
    lost.push(String::new());
    lost.extend(composer("  ? for shortcuts"));
    let left = login_left_from(&dialog);
    let run = |back_in: Option<&'static str>| {
        let latches = Arc::new(LoginLatches::default());
        let host = Arc::new(LatchHost {
            back_in,
            ..LatchHost::tab(&latches, "@1")
        });
        let tag = if back_in.is_some() { "back" } else { "none" };
        let (dir, path) = journal_file(&format!("te-carrier-{tag}"));
        let mut m = Mock::new(vec![
            busy_screen(),
            lost.clone(),
            dialog.clone(),
            dialog.clone(),
            left.clone(),
            busy_screen(),
            ended("Pushed."),
        ]);
        m.turn_releases = Some(1);
        m.vanish_after = Some(2);
        let mut opts = SuperviseOpts {
            idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
            journal: Some(path.clone()),
            ..hosted(30)
        };
        opts.policy.continue_policy = false;
        let (lines, _) = watch_lines(&mut m, &opts);
        let (records, _) = journal_records(&path);
        let _ = std::fs::remove_dir_all(&dir);
        let notices: Vec<String> = records
            .iter()
            .filter(|r| r.kind == "exception")
            .filter_map(|r| {
                r.summary
                    .split_whitespace()
                    .find_map(|w| w.strip_prefix("notice="))
                    .map(str::to_string)
            })
            .collect();
        let typed = |rule: &str| {
            lines
                .iter()
                .filter(|l| {
                    (l.starts_with("TYPED ") || l.starts_with("CONTINUED "))
                        && l.contains(&format!(" rule={rule}"))
                })
                .count()
        };
        let counts = (typed(RULE_LOGIN), typed(RULE_LOGIN_BACK));
        let log = format!("{lines:#?}\n{records:#?}\n{:#?}", host.said());
        (notices, counts, host.said(), latches, log)
    };
    let (notices, (logins, backs), said, latches, log) = run(Some("@2"));
    assert_eq!(logins, 1, "`/login` once: {log}");
    assert_eq!(backs, 1, "the turn delivered again, once: {log}");
    assert_eq!(
        notices,
        ["login-back-dialog"],
        "the dialog to close, no sign-in, none cancelled: {log}"
    );
    assert_eq!(said.last().map(String::as_str), Some("back"), "{log}");
    assert_eq!(
        latches.shared(LATCH_KEY, "@1"),
        None,
        "its loss over: {log}"
    );
    // NEGATIVE CONTROL: the login back nowhere.
    let (notices, (logins, backs), _, _, log) = run(None);
    assert_eq!(logins, 1, "{log}");
    assert_eq!(backs, 0, "nothing typed into the left sign-in: {log}");
    assert_eq!(notices, ["login-sign-in", "login-cancelled"], "{log}");
}

/// `rows` up to its `❯ /login` row, then `⎿  Login interrupted` under it and
/// the composer back: Esc out of that `/login`'s dialog.
fn login_left_from(dialog: &[String]) -> Vec<String> {
    let typed = dialog
        .iter()
        .position(|r| r.trim_end() == "❯ /login")
        .expect("the /login row");
    let mut r = dialog[..=typed].to_vec();
    r.push("  ⎿  Login interrupted".to_string());
    r.push(String::new());
    r.extend(composer("  ? for shortcuts"));
    r
}

/// `rows` with the lost login's row above its `/login` made a person's own
/// Esc (`Interrupted · What should Claude do instead?`): the same dialog,
/// typed at no lost login.
fn at_no_wall(rows: &[String]) -> Vec<String> {
    rows.iter()
        .map(|r| {
            if r.contains("Not logged in · Please run /login") {
                "  ⎿  Interrupted · What should Claude do instead?".to_string()
            } else {
                r.clone()
            }
        })
        .collect()
}

/// A LOOP THAT STARTS WHILE A `/login` A LOOP BEFORE IT TYPED STILL STANDS
/// (the login-carry review, 2026-10-20: Off and back over the browser
/// hand-off withdrew the owner's notice, and at `Login interrupted` the new
/// loop typed `keep going` and a second `/login` into the same loss; its
/// first read, before any `status`, took the dialog for no program's, as no
/// composer frame names Claude Code while it stands). The ledger's last
/// act is that `/login`; the new loop never typed one. At each of its
/// dialog's screens — the browser hand-off, the method picker, and Esc out of
/// either (`Login interrupted`) — the notice stands as it does for the loop
/// that typed it (the sign-in; the method left to the owner; the sign-in
/// cancelled), nothing is typed (no continuation, no second `/login`), and
/// where the dialog stands the login's one sign-in is this tab's again
/// (`login_carry`). NEGATIVE CONTROL: the same screens with no lost login
/// above the `/login` (a person's own, after their own Esc) raise no login
/// notice, and take no sign-in.
#[test]
fn a_loop_started_inside_the_login_a_loop_before_typed_carries_it_on() {
    use crate::supervise::approvals::{Outcome, Row};
    use aterm_phase::prompt::fixtures::{LOGIN_PICKER_WARNED, screen};
    let picker = screen(LOGIN_PICKER_WARNED);
    let typed_before = || {
        let now_ms = crate::supervise::journal::unix_ms();
        let point = Row {
            rule_id: crate::supervise::approvals::RULE_POINT,
            outcome: Outcome::Waiting,
            command: "",
            reason: "the turn-end policy judged the point (short turns in a row: 0)",
            box_seq: 90,
        }
        .to_json(now_ms - 61_000, None);
        let login = Row {
            rule_id: RULE_LOGIN,
            outcome: Outcome::Typed,
            command: "/login",
            reason: "the turn-end policy",
            box_seq: 90,
        }
        .to_json(now_ms - 60_000, None);
        point + "\n" + &login + "\n"
    };
    let run = |tag: &str, screens: Vec<Vec<String>>| {
        let (dir, ledger) = ledger_at(tag);
        std::fs::write(&ledger, typed_before()).expect("the ledger");
        let (jdir, journal) = journal_file(&format!("te-{tag}"));
        let latches = Arc::new(LoginLatches::default());
        let host = Arc::new(LatchHost::tab(&latches, "@1"));
        let mut m = Mock::new(screens);
        m.vanish_after = Some(2);
        let opts = SuperviseOpts {
            idle_host: Some(Arc::clone(&host) as Arc<dyn IdleHost>),
            journal: Some(journal.clone()),
            ..hosted(30)
        };
        let (lines, _) = watch_lines_with(&mut m, &opts, |s| {
            s.set_approval_ledger(Some(ledger.clone()));
        });
        let (records, _) = journal_records(&journal);
        let _ = std::fs::remove_dir_all(&dir);
        let _ = std::fs::remove_dir_all(&jdir);
        let notices: Vec<String> = records
            .iter()
            .filter(|r| r.kind == "exception")
            .filter_map(|r| {
                r.summary
                    .split_whitespace()
                    .find_map(|w| w.strip_prefix("notice="))
                    .map(str::to_string)
            })
            .collect();
        let acts: Vec<String> = lines
            .iter()
            .filter(|l| l.starts_with("TYPED ") || l.starts_with("CONTINUED "))
            .cloned()
            .collect();
        let log = format!(
            "{lines:#?}\n{records:#?}\n{:#?}\n{:#?}",
            host.said(),
            m.requests
        );
        (notices, acts, host.said(), log)
    };
    let carried = |said: &[String]| said.iter().any(|s| s == "carry:Ok(())");

    // The browser hand-off, then Esc out of it.
    let (notices, acts, said, log) = run(
        "successor-handoff",
        vec![handoff(), handoff(), login_left_from(&handoff())],
    );
    assert_eq!(notices, ["login-sign-in", "login-cancelled"], "{log}");
    assert!(acts.is_empty(), "nothing typed: {log}");
    assert!(carried(&said), "the sign-in is this tab's again: {log}");
    // The method picker (nothing says the method: the owner's), then Esc.
    let (notices, acts, said, log) = run(
        "successor-picker",
        vec![picker.clone(), picker.clone(), login_left_from(&picker)],
    );
    assert_eq!(notices, ["login-choose", "login-cancelled"], "{log}");
    assert!(acts.is_empty(), "nothing typed: {log}");
    assert!(carried(&said), "{log}");
    // `Login interrupted` already standing as the loop starts.
    let (notices, acts, said, log) = run(
        "successor-left",
        vec![login_left_from(&handoff()), login_left_from(&handoff())],
    );
    assert_eq!(notices, ["login-cancelled"], "{log}");
    assert!(acts.is_empty(), "nothing typed: {log}");
    assert!(!carried(&said), "a sign-in left is nobody's: {log}");

    // NEGATIVE CONTROL: the same screens at no lost login.
    for (tag, screens) in [
        (
            "successor-none-handoff",
            vec![
                at_no_wall(&handoff()),
                at_no_wall(&handoff()),
                at_no_wall(&login_left_from(&handoff())),
            ],
        ),
        (
            "successor-none-picker",
            vec![
                at_no_wall(&picker),
                at_no_wall(&picker),
                at_no_wall(&login_left_from(&picker)),
            ],
        ),
    ] {
        let (notices, acts, said, log) = run(tag, screens);
        assert!(notices.is_empty(), "no login notice: {log}");
        assert!(
            !acts.iter().any(|a| a.ends_with(" /login")),
            "no /login: {log}"
        );
        assert!(!carried(&said), "{log}");
    }
}

/// THE CREDITS HOLD IN THE LOOP (the owner, 2026-10-19: *"for continuing on
/// credits, that's an optional additional feature that's off by default. use
/// subscriptions."*): the notice credits started on (2.1.300, measured:
/// `You're now using usage credits · Your session limit resets 9:43am (…)`),
/// read by the loop's own read before the point, gives the point that shows
/// only the lasting `Now using usage credits` its reset: nothing is typed,
/// and the point waits for 9:43 and the grace. With no start read, no reset
/// is known: the owner is told once, and the next point types and tells
/// nothing, waiting to the hold's bound. NEGATIVE CONTROL: under `[harness]
/// usage_credits = true` the point is continued as before.
#[test]
fn the_loop_holds_its_own_turns_on_usage_credits_until_the_notices_reset() {
    use crate::supervise::policy::turn_end::{CREDITS_HOLD_TOLD, RULE_CREDITS_HOLD};
    use aterm_phase::prompt::fixtures::{CREDITS_IN_USE_2_1_300, CREDITS_STARTED_2_1_300, screen};
    let started = screen(CREDITS_STARTED_2_1_300);
    let lasting = screen(CREDITS_IN_USE_2_1_300);
    let run = |first: Vec<String>, usage_credits: bool, points: u64| {
        let mut m = Mock::new(vec![first]);
        let mut opts = hosted(30);
        opts.policy.usage_credits = usage_credits;
        let mut heard = Heard::default();
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(TEST_NOW, PDT);
        s.set_zone_lookup(test_zones);
        let _ = s.screen().expect("the read before the point");
        let mut actions = Vec::new();
        for seq in 0..points {
            let point = point_at(&s, lasting.clone(), 102 + seq);
            let action = s
                .turn_end_at_point(&point, Some(Duration::from_secs(180)), &opts)
                .expect("a decision");
            s.turn_end_execute(&point, action.clone(), &opts, &[], &mut heard)
                .expect("carried out");
            actions.push(action);
        }
        let kept = s.credits_kept.clone().and_then(|k| k.reset);
        drop(s);
        let typed = count(&m, "@s-1 turn") + count(&m, "@s-1 send");
        (heard_lines(&heard), actions, typed, kept)
    };
    let nine_43 = TEST_NOW + 48 * 60;
    let (lines, actions, typed, kept) = run(started.clone(), false, 1);
    assert_eq!(typed, 0, "{lines:#?}");
    assert_eq!(kept.and_then(|k| k.unix), Some(nine_43));
    assert!(
        matches!(&actions[..], [TurnEndAction::WaitUntil { why, .. }] if why.contains(RULE_CREDITS_HOLD)),
        "{actions:#?}"
    );
    assert!(
        lines
            .iter()
            .any(|l| l.starts_with("WAITING seq=102") && l.contains(RULE_CREDITS_HOLD)),
        "{lines:#?}"
    );
    // No start read: no reset, told once, then the wait to the bound.
    let (lines, actions, typed, _) = run(lasting.clone(), false, 2);
    assert_eq!(typed, 0, "{lines:#?}");
    assert!(
        matches!(&actions[..], [TurnEndAction::Escalate { reason }, TurnEndAction::WaitUntil { why, .. }]
            if reason == CREDITS_HOLD_TOLD && why.contains(RULE_CREDITS_HOLD)),
        "{actions:#?}"
    );
    // NEGATIVE CONTROL: the key on.
    let (lines, _, typed, _) = run(started, true, 1);
    assert!(continued(&lines, RULE_CONTINUE), "{lines:#?}");
    assert_eq!(typed, 1, "{lines:#?}");
}

/// THE LOOP KEEPS WHAT THE SCREEN NO LONGER DRAWS (the review of 2026-10-19,
/// P3 and P1): a reset still ahead — the notice credits started on read,
/// then a screen with no notice (a Team account draws no lasting one) — and a
/// model's credits (`Fable 5.1 is drawing from usage credits`, drawn once a
/// process). The point with no notice is held: the wait to 9:43 and the
/// grace; without a placeable reset it is held to the bound; the model's
/// told once. NEGATIVE CONTROLS: the read with no notice past 9:43 or the
/// no-reset bound is continued; a process the host says started since drops
/// the model episode instead of turning it into an account's hold.
#[test]
fn the_loop_keeps_a_reset_ahead_and_a_models_credits_where_the_screen_draws_none() {
    use crate::supervise::policy::turn_end::{
        CREDITS_HOLD_MODEL_TOLD, CREDITS_HOLD_TOLD, RULE_CREDITS_HOLD,
    };
    use aterm_phase::prompt::fixtures::{CREDITS_IN_USE_2_1_300, CREDITS_STARTED_2_1_300, screen};
    let started = screen(CREDITS_STARTED_2_1_300);
    let lasting = screen(CREDITS_IN_USE_2_1_300);
    let bound = TurnEndTiming::default().credits_bound;
    // The measured screen, its notice another or none, right-aligned where
    // the measured one ends.
    let drawn = |notice: &str| {
        let mut rows = lasting.clone();
        let mode = rows
            .iter()
            .position(|r| r.contains("auto mode on"))
            .expect("the mode row");
        let width = rows[mode].trim_end().chars().count();
        let lead = "  ⏵⏵ auto mode on (shift+tab to cycle) · ← for agents";
        let room = width - lead.chars().count();
        assert!(notice.is_empty() || notice.chars().count() + 2 <= room);
        rows[mode] = format!("{lead}{notice:>room$}");
        rows
    };
    let quiet = drawn("");
    let nine_43 = TEST_NOW + 48 * 60;
    // `passed`: the kept reset placed a minute ago, as a read past 9:43
    // keeps it (the clock left alone: a jump of it reads as a wake).
    let run = |reads: Vec<Vec<String>>, passed: bool, fallback: bool, bound: Duration| {
        let mut m = Mock::new(reads.clone());
        let mut opts = hosted(30);
        if !fallback {
            opts.policy.model_fallback = None;
        }
        let mut heard = Heard::default();
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(TEST_NOW, PDT);
        s.set_zone_lookup(test_zones);
        s.turn_end.timing.credits_bound = bound;
        let _ = s.screen().expect("the first read");
        if passed && let Some(r) = s.credits_kept.as_mut().and_then(|k| k.reset.as_mut()) {
            r.unix = Some(TEST_NOW - 60);
        }
        for _ in 1..reads.len() {
            let _ = s.screen().expect("a read");
        }
        let kept = s.credits_kept.clone();
        let point = point_at(&s, quiet.clone(), 102);
        let action = s
            .turn_end_at_point(&point, Some(Duration::from_secs(180)), &opts)
            .expect("a decision");
        s.turn_end_execute(&point, action.clone(), &opts, &[], &mut heard)
            .expect("carried out");
        drop(s);
        let typed = count(&m, "@s-1 turn") + count(&m, "@s-1 send");
        (heard_lines(&heard), action, typed, kept)
    };
    // The reset ahead, the notice gone.
    let (lines, action, typed, kept) =
        run(vec![started.clone(), quiet.clone()], false, true, bound);
    assert_eq!(typed, 0, "{lines:#?}");
    assert_eq!(
        kept.and_then(|k| k.reset).and_then(|r| r.unix),
        Some(nine_43)
    );
    assert!(
        matches!(&action, TurnEndAction::WaitUntil { why, .. } if why.contains(RULE_CREDITS_HOLD)),
        "{action:#?}"
    );
    // NEGATIVE CONTROL: the read with no notice past the reset.
    let (lines, _, typed, kept) = run(vec![started, quiet.clone()], true, true, bound);
    assert_eq!(kept, None);
    assert!(continued(&lines, RULE_CONTINUE), "{lines:#?}");
    assert_eq!(typed, 1, "{lines:#?}");
    // An account's head-only notice, and a named reset that cannot be
    // placed: neither absence nor an unparseable time proves restoration.
    for (notice, reset_text) in [
        ("You're now using usage credits", None),
        (
            "You're now using usage credits · resets 9am tomorrow",
            Some("9am tomorrow"),
        ),
    ] {
        let rows = drawn(notice);
        let (lines, action, typed, kept) =
            run(vec![rows.clone(), quiet.clone()], false, true, bound);
        assert_eq!(typed, 0, "{notice}: {lines:#?}");
        let kept = kept.expect("the account's known credits");
        assert_eq!(kept.model, None);
        assert_eq!(kept.reset.as_ref().map(|r| r.text.as_str()), reset_text);
        assert_eq!(kept.reset.and_then(|r| r.unix), None);
        assert!(
            matches!(&action, TurnEndAction::Escalate { reason } if reason == CREDITS_HOLD_TOLD),
            "{notice}: {action:#?}"
        );
        // The same producer and policy with an exhausted bound release it;
        // no wall-clock jump or real-time wait is needed for this boundary.
        let (lines, _, typed, kept) = run(vec![rows, quiet.clone()], false, true, Duration::ZERO);
        assert_eq!(kept, None, "{notice}");
        assert!(continued(&lines, RULE_CONTINUE), "{notice}: {lines:#?}");
        assert_eq!(typed, 1, "{notice}: {lines:#?}");
    }
    // A model's credits, drawn once: kept, and told.
    let model = drawn("Fable 5.1 is drawing from usage credits");
    let (lines, action, typed, kept) = run(vec![model.clone(), quiet.clone()], false, false, bound);
    assert_eq!(typed, 0, "{lines:#?}");
    assert_eq!(kept.and_then(|k| k.model).as_deref(), Some("fable"));
    assert!(
        matches!(&action, TurnEndAction::Escalate { reason } if reason == CREDITS_HOLD_MODEL_TOLD),
        "{action:#?}"
    );
    // NEGATIVE CONTROL: the process started since the notice was read.
    let mut m = Mock::new(vec![model, quiet]);
    let mut s = session(&mut m, Some("@s-1".to_string()));
    s.set_clock(TEST_NOW, PDT);
    let _ = s.screen().expect("the notice");
    let host = Arc::new(AccountHost::default());
    *host.started.lock().unwrap() = Some(TEST_NOW + 30);
    s.stall_host = Some(Arc::clone(&host) as Arc<dyn IdleHost>);
    let _ = s.screen().expect("the quiet read");
    assert_eq!(s.credits_kept, None);
}

/// THE HOST'S TURN ON USAGE CREDITS: a break in the agent's own background
/// work, the screen saying credits carry the session, is withheld from the
/// host (`guard=credits`) under the key off — its notice would be billed to
/// them. NEGATIVE CONTROLS: the key on, and no notice, offer it.
#[test]
fn the_hosts_background_step_is_withheld_on_usage_credits() {
    let bg = |credits: bool| {
        let mut r = rows(&[
            "⏺ Waiting for the build.",
            "",
            "✻ Crunched for 9m 27s · done 11:07 AM · 1 shell still running",
            "",
        ]);
        r.extend(composer("  ⏵⏵ auto mode on · 1 shell · ← for agents"));
        if credits {
            let at = r.len() - 1;
            r[at] = format!("{:<95}Now using usage credits", r[at]);
        }
        r
    };
    let run = |credits: bool, usage_credits: bool| {
        let host = Arc::new(BackgroundHost::default());
        let mut m = Mock::new(vec![bg(credits)]);
        let mut s = session(&mut m, Some("@s-1".to_string()));
        s.set_clock(TEST_NOW, PDT);
        s.stall_host = Some(Arc::clone(&host) as Arc<dyn IdleHost>);
        s.setup.background_settle = Duration::ZERO;
        let screen = s.screen().expect("the busy read");
        let cfg = SupervisorConfig {
            usage_credits,
            ..SupervisorConfig::default()
        };
        let mut since = Some(Instant::now());
        s.host_steps_in_background(&screen, &mut since, Some(&cfg), &mut Alone);
        let offered = host.backgrounds.load(Ordering::SeqCst);
        let withheld: Vec<&str> = host
            .withheld
            .lock()
            .unwrap()
            .iter()
            .map(|g| g.word())
            .collect();
        (offered, withheld)
    };
    assert_eq!(run(true, false), (0, vec!["credits"]));
    // NEGATIVE CONTROLS.
    assert_eq!(run(true, true), (1, vec![]));
    assert_eq!(run(false, false), (1, vec![]));
}

/// A NEED SAID EARLY IN A TALL TURN WHOSE LAST WORDS CLAIM NO DONE IS RAISED
/// (`TurnEndState::reads_turn_whole`), on every harness: the turn's start —
/// a `NEEDS YOU:` said there — is above the screen, in the history, and the
/// last words say the worker goes on. The review of b8/residuals found the
/// history read only where the last words claimed done, so the need was
/// never put up, under Cruise and under Land alike: on Claude Code (an
/// earlier message of the turn, or the head of one tall last message) and on
/// Gemini CLI (an earlier reply). NEGATIVE CONTROL: the same turn short
/// enough to fit on the screen raises it too, and the point before it, whose
/// history holds no need, raises none.
#[test]
fn a_need_said_early_in_a_tall_turn_that_claims_no_done_is_raised() {
    let fit = |mut drawn: Vec<String>, rows: usize| {
        if drawn.len() > rows {
            let screen = drawn.split_off(drawn.len() - rows);
            (screen, drawn)
        } else {
            (drawn, Vec::new())
        }
    };
    let claude_turn = |calls: usize| {
        let mut drawn: Vec<String> = vec![
            "❯ Fix the parser and land it.".to_string(),
            String::new(),
            "⏺ Merged the lexer and its suites.".to_string(),
            "  NEEDS YOU: the signing credential".to_string(),
        ];
        for call in 0..calls {
            drawn.extend([
                String::new(),
                format!("⏺ Bash(git log --oneline -1 branch-{call})"),
                format!("  ⎿  {call:04}abc merged branch {call}"),
            ]);
        }
        drawn.extend(rows(&[
            "",
            "⏺ Fixed the parser; pushing it next.",
            "",
            "✻ Worked for 12m 2s · done 4:24 PM",
            "",
        ]));
        drawn.extend(composer("  ⏵⏵ bypass permissions on (shift+tab to cycle)"));
        fit(drawn, 30)
    };
    let claude_message = |lines: usize| {
        let mut drawn: Vec<String> = vec![
            "❯ Fix the parser.".to_string(),
            String::new(),
            "⏺ NEEDS YOU: the signing credential".to_string(),
        ];
        for i in 0..lines {
            drawn.push(format!("  - merged branch {i:02} and ran its suite"));
        }
        drawn.push("  Pushing the parser next.".to_string());
        drawn.extend(rows(&["", "✻ Worked for 12m 2s · done 4:24 PM", ""]));
        drawn.extend(composer("  ⏵⏵ bypass permissions on (shift+tab to cycle)"));
        fit(drawn, 30)
    };
    let gemini_turn = |tall: bool| {
        use aterm_phase::gemini;
        use aterm_phase::prompt::fixtures::screen;
        let end = screen(gemini::fixtures::END_OF_TURN);
        let at = end
            .iter()
            .rposition(|r| r.starts_with("✦ "))
            .expect("the reply");
        let mut drawn = end[..at].to_vec();
        drawn.push("✦ NEEDS YOU: the signing credential".to_string());
        drawn.push("  I will push the branch now.".to_string());
        drawn.push(String::new());
        drawn.push("╭────────────────────────────────────────────╮".to_string());
        for call in 0..(if tall { 60 } else { 1 }) {
            drawn.push(format!(
                "│ ✓  Shell git push origin branch-{call:02}             │"
            ));
        }
        drawn.push("╰────────────────────────────────────────────╯".to_string());
        drawn.push(String::new());
        drawn.push("✦ I will push the next branch now.".to_string());
        drawn.extend(end[at + 1..].iter().cloned());
        if tall {
            fit(drawn, end.len())
        } else {
            (drawn, Vec::new())
        }
    };
    // The loop over [busy, work, busy, the turn]: what it put up, and when.
    let run = |mock: fn(Vec<Vec<String>>) -> Mock,
               busy: Vec<String>,
               work: Vec<String>,
               word: &'static str,
               (screen, above): (Vec<String>, Vec<String>)| {
        let (dir, journal) = journal_file("tall-need");
        let mut m = mock(vec![busy.clone(), work, busy, screen]);
        landing(&mut m);
        m.autopilot = Some(word);
        m.gen_fence = true;
        m.sends_gen = true;
        m.scrollback = Some(above);
        m.scrollback_from = Some(3);
        m.alt_screen = Some(false);
        m.vanish_after = Some(6);
        m.stall_sleep = Some(Duration::from_millis(20));
        let opts = SuperviseOpts {
            policy: owners_policy(),
            journal: Some(journal.clone()),
            ..auto(30)
        };
        let (lines, _) = watch_lines_with(&mut m, &opts, |s| {
            s.set_turn_end_timing(TurnEndTiming {
                min_work: Duration::ZERO,
                short_backoff: Duration::from_millis(30),
                short_backoff_max: Duration::from_millis(60),
                ..TurnEndTiming::default()
            });
        });
        let _ = std::fs::remove_dir_all(&dir);
        let raised = m.needs_calls.iter().any(|c| {
            c.starts_with("set attention owner=needs ") && c.contains("the signing credential")
        });
        // The act at the point before the tall turn (seq 102) names no need.
        let before: Vec<&String> = lines
            .iter()
            .filter(|l| l.starts_with("CONTINUED seq=102 ") && l.contains("NEEDS YOU"))
            .collect();
        (raised, before.is_empty(), lines)
    };
    for word in ["cruise", "land"] {
        for (why, turn) in [
            ("an earlier message", claude_turn(20)),
            ("a tall message's head", claude_message(40)),
            ("control: on the screen", claude_turn(1)),
        ] {
            let tall = !turn.1.is_empty();
            let (raised, clean_before, lines) =
                run(Mock::new, busy_screen(), ended(WORK), word, turn);
            assert!(raised, "{word} {why} (tall={tall}): {lines:#?}");
            assert!(clean_before, "{word} {why}: {lines:#?}");
        }
    }
    for tall in [true, false] {
        use aterm_phase::gemini;
        use aterm_phase::prompt::fixtures::screen;
        let turn = gemini_turn(tall);
        assert_eq!(!turn.1.is_empty(), tall);
        let (raised, clean_before, lines) = run(
            gemini_mock,
            screen(gemini::fixtures::BUSY_THINKING),
            screen(gemini::fixtures::END_OF_TURN),
            "cruise",
            turn,
        );
        assert!(raised, "gemini tall={tall}: {lines:#?}");
        assert!(clean_before, "gemini tall={tall}: {lines:#?}");
    }
}
